\subsubsection{Application to glued spaces}
\label{sec.pushout}

\begin{figure}
    \centering
    \includegraphics[width=0.25\linewidth]{tikz/XZ.png}%
    \qquad\qquad%
    \includegraphics[width=.4\linewidth]{tikz/X_pushout.png}
    \caption{An illustration of a glued space and a corresponding embedding of the type described in Section~\ref{sec.pushout}. \textbf{(left)} We take $Y$ to be the unit disk with the usual metric, and we take $Z$ to be its boundary. \textbf{(right)} The resulting glued space $Y\sqcup_Z Y$ is topologically a sphere, though the metric agrees with the flat metric on $Y$ when restricted to the northern or southern hemispheres. This figure depicts $Y\sqcup_Z Y$ embedded into 3-dimensional space according to the embedding described in \cref{corr.glued space}. That is, for each embedded point, the horizontal coordinates are given by the usual embedding of the unit disk into $\mathbb R^2$, while the vertical coordinate is proportional to its distance in $X$ from the boundary $Z$.}
    \label{fig:pushout}
\end{figure}

Let $(Y,d_Y)$ be a metric space, and let $Z\subseteq Y$ be closed. 
One can construct a new metric space by gluing two copies of $Y$ along $Z$. 
Formally, define $Y\sqcup_Z Y := (Y\times \{\pm 1\})/{\sim_Z}$, where $\sim_Z$ identifies $(z,1)$ with $(z,-1)$ for each $z\in Z$. 
Equip this space with the metric
\begin{align*}
    d_{Y\sqcup_Z Y}\big((y,\delta),(y',\delta')\big) = \left\{\begin{array}{cl}
        d_Y(y,y') & \text{if }\delta = \delta'\\
        \displaystyle\inf_{z\in Z} \big(d_Y(y,z)+d_Y(z,y')\big) & \text{if }\delta = -\delta'.
    \end{array}\right.
\end{align*}
The resulting space $(Y\sqcup_Z Y,d_{Y\sqcup_Z Y})$, true to our notation, is the pushout
\[
\begin{tikzcd}
    Z \ar[r,hook] \ar[d,hook] & Y \ar[d,dashed]\\
    Y \ar[r,dashed] & Y\sqcup_Z Y
\end{tikzcd}
\]
in the category of metric spaces with 1-Lipschitz morphisms. 
In what follows, we present a bilipschitz embedding of all such glued spaces, and we apply \cref{lem.upsilon compute,thm.align preserve} to estimate their Euclidean distortions. 
See Figure~\ref{fig:pushout} for an illustration of a glued space and the proposed embedding.

\begin{corollary}
\label{corr.glued space}
Let $Y$, $Z$, and $X:=Y\sqcup_Z Y$ be as above, let $\phi\colon Y\to H'$ be a map into a Hilbert space, and define $\Psi\colon X\to H'\times \mathbb R$ by
\[
\Psi(y,\delta) 
:= \big(\,\phi(y),\,\delta\inf_{z\in Z}d_Y(y,z)\,\big).
\]
Then $\kappa(\Psi) 
\leq \sqrt 2 \cdot\sqrt{\kappa(\phi)^2 + 1}$.
Moreover, we obtain the two-sided bound:
\[
c_2(Y)
\leq c_2(X)
\leq \sqrt{2}\cdot\sqrt{c_2(Y)^2 + 1}.\]
\end{corollary}
\begin{proof}
The lower bound on $c_2(X)$ follows from observing that $Y$ is a submetric space of $X$.

It remains to prove our upper bound on $\kappa(\Psi)$. Consider the group $G:=\{\operatorname{id},\sigma\}$ with $\sigma$ acting isometrically on $X$ by 
\[\sigma(y,\delta):=(y,-\delta).\]
We first claim that $X/G$ is isomorphic to $Y$ as a metric space.
Indeed, for every $y,y'\in Y$ and $\delta\in\{\pm1\}$, the triangle inequality implies
\[
d_X\big((y,\delta),(y',\delta)\big)
=d_Y(y,y')
\leq \inf_{z\in Z} \big(d_Y(y,z)+d_Y(z,y')\big)
= d_X\big((y,\delta),(y',-\delta)\big),
\]
and so $d_{X/G}([(y,\delta)],[(y',\delta')])=d_Y(y,y')$.
Letting $\sigma$ act on $\mathbb{R}$ by $\sigma v=-v$, then by \cref{thm.align preserve}, it suffices to verify that the map $\psi\colon X\to \mathbb{R}$ defined by
\[
\psi(y,\delta)
:=\delta\inf_{z\in Z}d_Y(y,z)
\]
is $1$-Lipschitz, orbit expanding, and alignment preserving.
In what follows, we write $d_Z(y):=\inf_{z\in Z}d(y,z)$ for convenience.

For $1$-Lipschitz, we aim to show that
\[
|\delta d_Z(y)-\delta' d_Z(y')|
\leq d_X\big((y,\delta),(y',\delta')\big).
\]
On account of the piecewise definition of $d_X$, we proceed in cases.
In the case where $\delta=\delta'$, our task is to show
\begin{equation}
\label{eq.case 1 of lipschitz}
|d_Z(y)-d_Z(y')|
\leq d_Y(y,y').
\end{equation}
Without loss of generality, assume $d_Z(y)\geq d_Z(y')$.
Given any $\varepsilon>0$, we may select $z\in Z$ in such a way that $d_Y(y',z)\leq d_Z(y')+\varepsilon$.
Thus, the triangle inequality gives
\[
|d_Z(y)-d_Z(y')|
=d_Z(y)-d_Z(y')
\leq d_Y(y,z)-d_Y(y',z)+\varepsilon
\leq d_Y(y,y')+\varepsilon.
\]
Since $\varepsilon>0$ was arbitrary, the validity of~\eqref{eq.case 1 of lipschitz} follows.
In the remaining case where $\delta=-\delta'$, our task is to show
\[
|d_Z(y)+d_Z(y')|
\leq \inf_{z\in Z} \big(d_Y(y,z)+d_Y(z,y')\big).
\]
Considering $d_Z(y)+d_Z(y')\geq0$, this is equivalent to the bound
\[
\inf_{z\in Z}d_Y(y,z)+\inf_{z\in Z}d_Y(y',z)
\leq\inf_{z\in Z} \big(d_Y(y,z)+d_Y(y',z)\big),
\]
which immediately follows from the definition of infimum.

For orbit expanding, take any $x:=(y,\delta)\in X$ and $g\in G$.
If $g=\operatorname{id}$, we trivially have $\|\psi(x)-g\cdot\psi(x)\|\geq 0=d_X(x,gx)$.
Otherwise, $g=\sigma$, in which case
\[
\|\psi(x)-g\cdot\psi(x)\|
=2\|\psi(x)\|
=2d_Z(y).
\]
Given any $\varepsilon>0$, we may select $z\in Z$ in such a way that $d_Y(y,z)\leq d_Z(y)+\frac{\varepsilon}{2}$, in which case
\[
\|\psi(x)-g\cdot\psi(x)\|
=2d_Z(y)
\geq 2d_Y(y,z)-\varepsilon
\geq d_X\big((y,\delta),(y,-\delta)\big)-\varepsilon
= d_X(x,gx)-\varepsilon.
\]
Since $\varepsilon>0$ was arbirary, it follows that $\|\psi(x)-g\cdot\psi(x)\|\geq d_X(x,gx)$.

Finally, for alignment preserving, take any $x:=(y,\delta)$ and $x':=(y',\delta')$ in $X$, and for convenience, denote 
\[
A:=\argmin_{g\in G} d_X(x,gx'),
\qquad
B:=\argmin_{g\in G} \|\psi(x)-g\cdot\psi(x')\|.
\]
As a consequence of the triangle inequality, $\delta=\delta'$ implies $\operatorname{id}\in A$ and $\delta=-\delta'$ implies $\sigma\in A$.
Additionally, $\delta=\delta'$ implies that $\psi(x)$ and $\psi(x')$ have the same sign (or at least one is zero), and so $\operatorname{id}\in B$.
On the other hand, $\delta\neq \delta'$ implies that they have opposite sign (or at least one is zero), and so $\sigma\in B$.
Either way, there is a member of $G$ that simultaneously minimizes $d_X(x,gx')$ and $\|\psi(x)-g\cdot\psi(x')\|$.
\end{proof}

