\subsection{Special orthogonal groups}
\label{sec.so}

In this section, we construct a bilipschitz embedding of $\mathbb R^{r\times n}/\SO(r)$.
Considering this space reduces to $\mathbb R^{r\times n}/\O(r)$ when $n<r$, we focus on the setting in which $n\geq r$.
Our bilipschitz map is directly inspired by the classical generating family of polynomial invariants, which, given $X\in\mathbb{R}^{r\times n}$, pairs the $\O(r)$-invariant Gram matrix $X^T X\in\mathbb{R}^{n\times n}$ with the $\SO(r)$-invariant \textbf{Pl\"{u}cker coordinates} $\operatorname{Plu}(X)\in \mathbb{R}^{\binom{n}{r}}$, namely, the determinants of all $r\times r$ submatrices of $X$.
First, we modify the Gram matrix so that it bilipschitzly separates $\O(r)$-orbits.
For this, it suffices to take the positive semidefinite square root of the Gram matrix.
Next, we perform a careful spectral modification of the Pl\"{u}cker coordinates to obtain a Lipschitz map that induces an orbit-expanding and alignment-preserving map $\mathbb{R}^{r\times n}/\SO(r)\to\mathbb{R}^{\binom{n}{r}}$ with respect to the group $\O(r)/\SO(r)$.
By combining these maps, we obtain a quotient--orbit embedding of $\mathbb R^{r\times n}/\SO(r)$ with distortion at most $2\sqrt{2}$. 

% and with distortion bounded above by $2\sqrt 2$. As a consequence, we establish in \cref{corr.so R final} the two-sided inequality
% \[\sqrt 2 \leq c_2(\mathbb R^{r\times n}/\SO(r)) \leq 2\sqrt 2,\]
% valid for all $r,n \geq 2$. Our upper bound is obtained by applying \cref{thm.align preserve} to the natural action of $\O(r)/\operatorname{SO}(r)$ on $\mathbb R^{r\times n}/\SO(r)$. For this, we construct an appropriate alignment preserving orbit expanding map.

%\subsubsection{Setup}

We start by considering the map $\phi\colon \mathbb{R}^{r\times n}\to\mathbb{R}^{n\times n}$ defined by
\[
\phi(X) 
= \sqrt{X^TX}.
\]
It turns out that $\phi_{/\O(r)}$ achieves the Euclidean distortion of $\mathbb R^{r\times n}/\O(r)$.

\begin{proposition}
\label{prop.gram bounds}
Given $X,Y\in \mathbb R^{r\times n}$, it holds that
\[
d_{\O(r)}([X],[Y]) 
\leq \|\phi(X) - \phi(Y)\|_F
\leq \sqrt{2} \cdot d_{\O(r)}([X],[Y]).
\]
The lower Lipschitz bound is tight for all $n\geq 1$, and the upper Lipschitz bound is tight for all $n\geq 2$. 
Moreover, for all $n\geq 2$, we have
\[
c_2(\mathbb R^{r\times n}/\Oname(r)) 
= \kappa(\phi_{/\O(r)}) 
= \sqrt 2.
\]
\end{proposition}

\begin{proof}
The inequality and tightness of bounds follow by adapting the proof of Theorem~3.7(i) in~\cite{BalanD:22}. 
Meanwhile, $c_2$ optimality is implied by the following chain of inequalities:
\[
\sqrt 2
\geq\kappa(\phi_{/\O(r)})
\geq c_2(\mathbb R^{r\times n}/\O(r)) 
\geq c_2(\mathbb R^{1\times n}/\O(1)) 
= \sqrt 2,
\] 
where the final equality follows from Corollary~36 in~\cite{CahillIM:24} (summarized in \cref{prop.known-distortions}), and final inequality holds since the zero-padding map $F\colon \mathbb R^{1\times n}\hookrightarrow \mathbb R^{r\times n}$ induces an isometric embedding of quotient spaces $\mathbb R^{1\times n}/\O(1)\to \mathbb R^{r\times n}/\O(r)$:
\begin{align*}
d_{\O(r)}([F(X)],[F(Y)])^2 
&= \|F(X)\|_F^2 + \|F(Y)\|_F^2 - 2\|F(X)F(Y)^T\|_*\\
&= \|X\|_F^2 + \|Y\|_F^2 - 2 \|XY^T\|_*\\
&= d_{\O(1)}([X],[Y])^2.
\tag*{\qedhere}
\end{align*}
\end{proof}

\begin{remark}
\label{rk.U(r)}
A simple modification of this proof gives $c_2(\mathbb C^{r\times n}/\operatorname{U}(r)) = \sqrt 2$ when $n\geq 2$.
\end{remark}

Now that we can bilipschitzly separate $\O(r)$-orbits, it remains to bilipschitzly separate $\SO(r)$-orbits within $\O(r)$-orbits.
We accomplish this by modifying the Pl\"ucker coordinates.
Given $X\in\mathbb{R}^{r\times n}$, take any thin singular value decomposition $X=U_X\Sigma_XV_X$ with $U_X\in \SO(r)$ and $V_X\in \mathbb R^{r\times n}$ such that $V_XV_X^T=\Id_r$.
Then we define the \textbf{scaled Pl\"ucker invariant} of $X$ to be
\[
\psi(X)
:=\sigma_{\min}(X)\cdot\operatorname{Plu}(V_X),
\]
where $\sigma_{\min}(X)$ is the smallest (i.e., $r$th largest) singular value of $X$.
Note that while $V_X$ is not uniquely determined by $X$, all possible choices of $V_X$ reside in a common $\SO(r)$-orbit, and so $\psi$ is well defined.
It turns out that $\psi$ bilipschitzly separates $\SO(r)$-orbits within $\O(r)$-orbits as intended:

\begin{lemma}
\label{thm.min sing scale upper}
Let $G:=\O(r)/\SO(r)$. 
Then $\psi_{/\SO(r)}$ is a $1$-Lipschitz map that is orbit expanding and alignment preserving with respect to the isometric action of $G$ on $\mathbb R^{r\times n}/\SO(r)$ and the sign representation of $G$ on $\mathbb R^{\binom{n}{r}}$.
\end{lemma}

We defer the proof of \cref{thm.min sing scale upper} to the end of the section.
What follows is the main result of this section.

\begin{theorem}
\label{thm.so psi lower bound}
% this also contains {corr.so R final}
The map $F\colon \mathbb R^{r\times n}/\operatorname{SO}(r)\to \mathbb R^{n\times n}\times \mathbb R^{\binom{n}{r}}$ defined by
\[
F([X]) 
= \big(~\phi(X),~\sqrt 2\cdot\psi(X)~\big)
\]
has distortion $\kappa(F)\leq 2\sqrt{2}$.
Moreover, for all $n\geq r\geq 2$, we have
\[
\sqrt{2}
\leq c_2(\mathbb R^{r\times n}/\SO(r))
\leq 2\sqrt 2.
\]
\end{theorem}

\begin{proof}
We may combine \cref{thm.align preserve,prop.gram bounds,thm.min sing scale upper} to obtain the distortion bound $\kappa(F)\leq 2\sqrt{2}$, which in turn implies the upper bound on $c_2(\mathbb R^{r\times n}/\SO(r))$.
For the lower bound, note that the zero-padding map $\mathbb R^{(r-1)\times n}\hookrightarrow \mathbb R^{r\times n}$ induces an isometric embedding of quotient spaces $\mathbb R^{(r-1)\times n}/\Oname(r-1)\to \mathbb R^{r\times n}/\SO(r)$, and so \cref{prop.gram bounds} gives
\[
c_2(\mathbb R^{r\times n}/\SO(r))
\geq c_2(\mathbb R^{(r-1)\times n}/\Oname(r-1))
= \sqrt{2}.
\tag*{\qedhere}
\]
% observe that
% \[\sqrt{2} = c_2(\mathbb R^{(r-1)\times n}/\Oname(r-1))\]
% by \cref{prop.gram bounds}, and the natural inclusion $\mathbb R^{(r-1)\times n}\hookrightarrow \mathbb R^{r\times n}$ induces an isometric embedding of quotient spaces $\mathbb R^{(r-1)\times n}/\Oname(r-1)\to \mathbb R^{r\times n}/\SO(r)$. Hence,
% \[c_2(\mathbb R^{(r-1)\times n}/\Oname(r-1))\leq c_2(\mathbb R^{r\times n}/\SO(r)).\tag*{\qedhere}\]
\end{proof}

The remainder of this section is dedicated to the proof of \cref{thm.min sing scale upper}.
The Cauchy--Binet formula implies
\begin{equation*}
\langle \psi(X), \psi(Y) \rangle 
= \sigma_{\min}(X)\sigma_{\min}(Y)\det(V_XV_Y^T),
\end{equation*}
and so the squared distance between scaled Pl\"{u}cker invariants is given by
\begin{equation}
\label{eq.plucker real normdiff}
\|\psi(X)-\psi(Y)\|^2 
= \sigma_{\min}(X)^2 + \sigma_{\min}(Y)^2 - 2\,\sigma_{\min}(X)\sigma_{\min}(Y) \det(V_XV_Y^T).
\end{equation}
We will compare this to the squared orbital distance
\begin{equation*}
\label{eq.dist so eq}
d_{\SO(r)}([X],[Y])^2 
= \min_{Q\in \operatorname{SO}(r)}\|QX-Y\|_F^2 
= \|X\|_F^2 + \|Y\|_F^2 - 2\max_{Q\in\operatorname{SO}(r)}\operatorname{Tr}\big(QXY^T\big).
\end{equation*}
Conveniently, the maximum on the right-hand side has a closed-form expression:

\begin{proposition}[Theorem~1 of~\cite{MirandaT:93}]
\label{prop.so max filter}
For every $M\in\mathbb R^{r\times r}$, it holds that
\begin{equation*}
\label{eq.max filter so eq}
\max_{Q\in \operatorname{SO}(r)}\operatorname{Tr}(QM) 
= \|M\|_* - 2\sigma_{\min}(M) \cdot\mathbf{1}_{\{\det(M)<0\}},
% \left\{\begin{array}{cl}
% \|M\|_* &\text{if }\det(M) \geq 0\\
% \|M\|_* - 2\sigma_{\min}(M) &\text{if }\det(M) \leq 0,
% \end{array}\right.
\end{equation*}
where $\|\cdot \|_*$ denotes the nuclear norm.
\end{proposition}

We provide a streamlined proof of \cref{prop.so max filter} in \cref{app.calc proof}.
In what follows, we make continual use of the resulting expression for the squared orbital distance:
\begin{equation}
\label{eq.dist so eq full}
d_{\SO(r)}([X],[Y])^2  
= \|X\|_F^2 + \|Y\|_F^2 - 2\|XY^T\|_* + 4\sigma_{\min}(XY^T) \cdot\mathbf{1}_{\{\det(XY^T)<0\}}.
\end{equation}

\begin{proof}[Proof of \cref{thm.min sing scale upper}]
For orbit expanding, take any $B \in \operatorname{O}(r)$ such that $\det(B)=-1$. 
Then $\det(V_XV_{BX}^T)=-1$, and so \eqref{eq.plucker real normdiff} gives
\[
\|\psi(X)-\psi(BX)\|^2
=\sigma_{\min}(X)^2 + \sigma_{\min}(BX)^2 + 2\sigma_{\min}(X)\sigma_{\min}(BX)
=4\sigma_{\min}(X)^2.
\]
Meanwhile, \eqref{eq.dist so eq full} gives
\[
d_{\SO(r)}([X],[BX])^2 
= \|X\|_F^2 + \|BX\|_F^2 - 2\|X(BX)^T\|_* + 4\sigma_{\min}(X(BX)^T)
=4\sigma_{\min}(X)^2.
\]
Next, for alignment preserving, consider any $B\in\O(r)$.
Then \eqref{eq.dist so eq full} implies
\begin{align*}
d_{\SO(r)}([X],[BY])\leq d_{\SO(r)}([X],[Y])
&\iff \det(XY^T) \leq 0 \\
&\iff \det(V_XV_Y^T)\leq 0 \\
&\iff \|\psi(X) - \psi(BY)\|
\leq \|\psi(X) - \psi(Y)\|,
\end{align*}
where the last step follows from \eqref{eq.plucker real normdiff}.

It remains to show that $\psi_{/\SO(r)}$ is $1$-Lipschitz.
Fix any $X,Y\in\mathbb{R}^{r\times n}$.
Then letting $\sigma_i(Z)$ denote the $i$th largest singular value of a matrix $Z$, \labelcref{eq.plucker real normdiff,eq.dist so eq full} give that it suffices to prove
