\begin{proof}[Proof of \cref{lem.weyl chamber glued space}]
Fix $u,v\in V$. 
If $u,v\in V_+$ or $u,v\in V_-$, then there exist $w,w'\in R$ with $\det(w)=\det(w')$ such that $\phi(u)=wu$ and $\phi(v) = w'v$.
Since $R\cdot x\mapsto\phi(x)$ defines an isometric embedding of $V/R$, it follows that
\[
\begin{aligned}
\min_{g\in R}\|u-gv\| 
= \|\phi(u)-\phi(v)\|
&= \|wu-w'v\| \\
&= \|u - w^{-1}w'v\| 
\geq \min_{g\in R^+}\|u-gv\| 
\geq \min_{g\in R}\|u-gv\|,
\end{aligned}
\]
meaning the inequalities are equalities, i.e.,
\[
d_{C\sqcup_{\partial C}C}\big(F([u]),F([v])\big)
= \|\phi(u)-\phi(v)\| 
= d_{V/R^+}([u],[v]).
\]

Now suppose $u\in V_+\setminus V_-$ and $v\in V_-\setminus V_+$. 
% Then $\phi(u),\phi(v)\in \operatorname{int}(C)$, and we have
% \[
% d_{V/R^+}([u],[v]) 
% = \min_{g\in R\setminus R^+}\|\phi(u) - g\cdot \phi(v)\|.
% \]
Consider the unit vectors $\alpha_1,\ldots,\alpha_m$ that are orthogonal to the facets of $C$ and point into $C$, and let $s_i:=\operatorname{Id}_V-2\langle \cdot,\alpha_i\rangle\alpha_i\in R\setminus R^+$ denote the corresponding fundamental reflections.
Taking $x:= \phi(u)$, $y:= \phi(v)$, then $x,y\in \operatorname{int}(C)$, and it suffices to show the following equalities:
\begin{equation*}
\label{eq.proof alternating}
\underbrace{\min_{g\in R\setminus R^+}\|x - g\cdot y\|}_{d_{V/R^+}([u],[v])}
\overset{\text{(a)}}{=} \min_{i\in [m]}\|x - s_i(y)\| 
\overset{\text{(b)}}{=} \underbrace{\inf_{c\in\partial C}\big(\|x-c\|+\|c-y\|\big)}_{d_{C\sqcup_{\partial C}C}(F([u]),F([v]))}.
\end{equation*}
We will establish (a) and (b) by first reducing to two claims that are perhaps more interpretable.
Given any $z\in V$, consider the index subset 
\[
k(z)
:= \{i\in [m]:\langle z,\alpha_i\rangle < 0\}.
\]
Notably, $k(z)=\varnothing$ if and only if $z\in C$. We claim the following:
\begin{enumerate}[label=(\roman*)]
\item For each $z\in V$, if $i\in k(z)$, then $\|x-s_i(z)\|<\|x-z\|$.
\item For each $i\in [m]$, the set $C\cup s_i(C)$ is convex.
\end{enumerate}
In what follows, we demonstrate (i)$\Rightarrow$(a) and (ii)$\Rightarrow$(b), and then (i) and (ii).

For (i)$\Rightarrow$(a), since $s_i\in R\setminus R^+$ for every $i\in[m]$, we have
\[
\min_{g\in R\setminus R^+}\|x - g\cdot y\| 
\leq \min_{i\in [m]}\|x - s_i(y)\|.
\]
For the reverse inequality, take
\begin{equation}
\label{eq.g star}
g_*
\in \argmin_{g\in R\setminus R^+}\|x - g\cdot y\|.
\end{equation}
Then $g_*y\in \operatorname{int}(g_*C)\subseteq C^c$, and so $k(g_*y) \neq \varnothing$. 
Pick any $i\in k(g_*y)$. 
Then $k(s_i(g_*y))=\varnothing$, since otherwise, assuming $j\in k(s_i(g_*y))$, we use \eqref{eq.g star} followed by two applications of (i) to obtain the contradiction:
\begin{align*}
\|x - g_*\cdot y\|\leq \|x-(s_js_i g_*)\cdot y\|< \|x-(s_i g_*)\cdot y\|< \|x-g_*\cdot y\|.
\end{align*}
Hence, $s_i(g_*y) = y\in \operatorname{int}(C)$, and since $R$ acts freely on $\bigsqcup_{g\in R}\operatorname{int}(gC)$ (e.g., see \cite[Theorem~4.2.4]{GroveB:96}), it follows that $s_ig_* = \Id_V$.
Thus, $g_* = s_i^{-1}=s_i$, as desired.

For (ii)$\Rightarrow$(b), fix $i\in [m]$, and let $H_i:= \operatorname{span}\{\alpha_{i}\}^\perp$ denote the reflection hyperplane of $s_{i}$.
Then $C\cap H_i = s_i(C)\cap H_i =\partial C\cap H_i$, and as a consequence of (ii) and $\langle x,\alpha_i\rangle > 0 > \langle s_i(y),\alpha_i\rangle$, we have
\[
\|x-s_{i}(y)\| 
= \min_{h\in \partial C\cap H_i}\big(\|x-h\|+\|h-s_i(y)\|\big).
\]
%with unique minimizer $h_i:=\frac{1}{2}(x+s_{i}(y))$. 
% By (ii), the set $K_i:= C\cup s_{i}(C)$ is convex, so $h_i \in K_i\cap H_i = \partial C \cap H_i$. Therefore,
Furthermore, $\|h-s_i(y)\|=\|s_i^{-1}(h)-y\|=\|h-y\|$, and so
\[
\min_{i\in[m]}\|x-s_{i}(y)\| 
= \min_{i\in[m]}\min_{h\in \partial C \cap H_i}\big(\|x-h\|+\|h-y\|\big).
\]
Then (b) follows since $\bigcup_{i\in[m]}(\partial C\cap H_i)=\partial C$.

For (i), fix $z\in V$ and $i\in k(z)$. 
Then $s_i(z)-z=-2\langle z,\alpha_i\rangle\alpha_i$, and so
\[
\langle x,s_i(z)\rangle - \langle x,z\rangle 
=\langle x,s_i(z)-z\rangle
= -2\langle z,\alpha_i\rangle\langle x,\alpha_i\rangle 
> 0,
\]
where the last step uses the assumptions that $i\in k(z)$ and $x\in \operatorname{int}(C)$.
Since $\|s_i(z)\|=\|z\|$, it follows that $\|x-s_i(z)\|<\|x-z\|$, as claimed.

For (ii), fix $i\in[m]$, and consider the convex polyhedral cone
\[
K
:= \big\{z\in V:\langle z,\alpha_j\rangle\geq 0 \text{ and } \langle z,s_i(\alpha_j)\rangle \geq 0,~\forall\, j\in [m]\setminus\{i\}\big\}.
\]
It suffices to show that $C\cup s_i(C)=K$.
To this end, recall that
\begin{align*}
C
&=\{z\in V:\langle z,\alpha_j\rangle\geq 0,~\forall\, j\in [m]\},\\
s_i(C) 
&= \{z\in V:\langle z,s_i(\alpha_j)\rangle\geq 0,~\forall \, j\in[m]\}.
\end{align*}
% and define
% \begin{align*}
% L_1
% &:=C\cup s_i(C),\\
% L_2 
% &:= \{z\in V:\langle z,\alpha_j\rangle\geq 0 \text{ and } \langle z,s_i(\alpha_j)\rangle \geq 0\ \forall\, j\in [m]\setminus\{i\}\}.
% \end{align*}
For $K\subseteq C\cup s_i(C)$, note that $s_i(\alpha_i) = -\alpha_i$, and so each $z\in K$ either resides in $C$ or $s_i(C)$, depending on whether $\langle z,\alpha_i\rangle$ is nonnegative or nonpositive.
% Note that $L_2$ is a convex polyhedral cone, and we aim to show $L_1=L_2$. Since $s_i(\alpha_i) = -\alpha_i$, each $z\in L_2$ either satisfies $\langle z,\alpha_i\rangle \geq 0$ (so $z\in C$) or $\langle z,\alpha_i\rangle\leq 0$ (so $z\in s_i(C)$). Thus $L_2\subseteq L_1$.
For $C\cup s_i(C)\subseteq K$, it suffices to show $s_i(C)\subseteq K$ since $K$ is invariant to the action of $s_i$. 
Given $z\in s_i(C)$, we have $\langle z,s_i(\alpha_j)\rangle\geq 0$ for all $j\in[m]$. Moreover, the walls of $C$ meet at acute angles, i.e., $\langle\alpha_i,\alpha_j\rangle\leq 0$ for each $j\in[m]\setminus\{i\}$ (e.g., see~\cite[Proposition~4.1.5]{GroveB:96}). 
Thus, for each $j\in[m]\setminus\{i\}$, we have
\[
0
\leq \langle z,s_i(\alpha_j)\rangle  
= \langle z,\alpha_j\rangle - 2\langle \alpha_i,\alpha_j\rangle \langle z,\alpha_i\rangle,
\]
and so $\langle z,\alpha_j\rangle \geq 2\langle \alpha_i,\alpha_j\rangle \langle z,\alpha_i\rangle=-2\langle \alpha_i,\alpha_j\rangle \langle z,s_i(\alpha_i)\rangle \geq 0$, as desired.
\end{proof}

\subsection{Wallpaper groups}
\label{sec.tran klien}

In this section, we embed quotients of the plane by the wallpaper groups, namely, the discrete subgroups $G\leq \E(2)$ such that $\mathbb R^2/G$ is compact. 
There are several familiar spaces among these quotients, including flat tori, flat Klein bottles, and the M\"obius strip.
To estimate the Euclidean distortions of these spaces, we make frequent use of \cref{lem.upsilon compute,corr.glued space,thm.isotropy}.
While there are multiple notation systems available for describing the wallpaper groups, we use the \textit{orbifold signature notation} introduced by MacBeath \cite{MacBeath:67}, in the form popularized by Conway \cite{Conway:02, Conway:16}.

In any wallpaper group $G$, the set $T_G:=G\cap\mathbb{R}^2$ of translation vectors forms a discrete rank-$2$ lattice in $\mathbb R^2$. 
All but two of the $17$ classes of wallpaper groups exhibit a key structural constraint: the translation lattice of any group in any of these classes is constrained in shape---either having fixed angles (as in rectangular and hexagonal lattices) or generators of equal length (as in rhombic lattices). 
The two exceptional classes are type $o$, in which the group consists of translations by an arbitrary lattice (yielding a flat torus quotient), and type $2222$, which is generated over a group of type $o$ by a $\pi/2$ rotation (producing a quotient of the flat torus by a group of order two).

In \cref{sec.sub flat tori}, we reviewed known results on the Euclidean distortions of quotients by type $o$ wallpaper groups. The best known general upper bound and the only known exact distortion values are summarized in the following proposition.
\begin{proposition}\label{thm:torus-distortion}
Let $G\leq E(2)$ be a wallpaper group of type $o$. Then the following hold:
\begin{itemize}
\item[(a)]
In general, $c_2(\mathbb R^2/G) < 8$.
\item[(b)] 
If $T_G$ is a rectangular lattice, then $c_2(\mathbb R^2/G) = \frac{\pi}{2}$.
\item[(c)] 
If $T_G$ is a hexagonal lattice, then $c_2(\mathbb R^2/G) = \frac{\sqrt{8}\pi}{\sqrt{27}}$.
    \end{itemize}
\end{proposition}

For each of the remaining $16$ wallpaper group types, we either precisely determine or explicitly bound the Euclidean distortions of the corresponding quotient spaces. 
In the case of type $2222$ groups, the underlying translation lattice may be oblique, so we resort to bounding the distortion using \cref{thm:torus-distortion}(a).
For the remaining $15$ types, we obtain sharper bounds or exact values for $c_2(\mathbb R^2/G)$, all of which are at most $\pi$ and expressed in more explicit terms.

Many of our lower bounds for distortion will come from the application of \cref{thm.isotropy} to a rotation center, so we quickly codify this strategy as a lemma.

\begin{lemma}\label{lem.rotation_center}
Let $G$ be a wallpaper group. 
If the action of $G$ has a rotation center of order $r$ that is not on a reflection line (that is, if the orbifold signature of $G$ has an $r$ which is not to the right of any $\ast$), then
\[
c_2(\mathbb R^2/G) 
\geq r\sin(\tfrac{\pi}{2r}).
\]
\end{lemma}

\begin{proof}
Suppose the action of $G$ has a rotation center of order $r$ at $p\in\mathbb R^2$ which is not on any reflection line. 
Then the stabilizer $G_p$ is isomorphic to $C_r$, and it acts on $T_p\mathbb R^2$ by rotations by integer multiples $\pi/r$.
Corollary 36 in \cite{CahillIM:24} (see \cref{prop.known-distortions}) and \cref{thm.isotropy} together give the desired lower bound.
\end{proof}

\begin{theorem}
\label{thm.wallpaper groups}
Let $G\leq \E(2)$ be a wallpaper group.
    \begin{enumerate}[label=(\alph*)]
        \item\label{it:reflections} If $G$ is of type ${\ast}333$, ${\ast}442$, $*632$, or ${\ast}2222$, then $c_2(\mathbb R^2/G) = 1$.
        \item\label{it:cylinder} If $G$ is of type ${\ast}{\ast}$, then $c_2(\mathbb R^2/G) = \frac{\pi}{2}$.
        \item\label{it:half-spin} If $G$ is of type $2{\ast}22$, then $c_2(\mathbb R^2/G) = \sqrt{2}$.
        \item\label{it:quarter-spin} If $G$ is of type $4{\ast}2$, then $c_2(\mathbb R^2/G) = 2\sqrt{2-\sqrt{2}}$.
        \item\label{it:klein} If $G$ is of type ${\times}{\times}$ (that is, if $\mathbb R^2/G$ is a flat Klein bottle), then $\frac{\pi}{2} \leq c_2(\mathbb R^2/G) \leq \frac{\pi}{\sqrt{2}}$.
        \item\label{it:football} If $G$ is of type $22{\times}$, then $\pi/2\leq c_2(\mathbb R^2/G) \leq \pi$.
        \item\label{it:torus-cover} If $G$ is of type $2222$, then $\sqrt{2}\leq c_2(\mathbb R^2/G)\leq \sqrt{2}\cdot c_2(\mathbb R^2/T_G) < 8\sqrt{2}$. %If $T_G$ is a rectangular lattice, then $c_2(\mathbb R^2/G) \leq \frac{\pi}{\sqrt 2}$. If $T_G$ is instead a hexagonal lattice, then $c_2(\mathbb R^2/G) \leq \frac{4\pi}{\sqrt{27}}$. More generally, $c_2(\mathbb R^2/G)\leq \sqrt{2}\cdot c_2(o)$.
        \item\label{it:mobius} If $G$ is of type ${\ast}{\times}$, (that is, if $\mathbb R^2/G$ is a M\"obius strip) then $\frac{\pi}{2}\leq c_2(\mathbb R^2/G)\leq \frac{\pi}{\sqrt{2}}$.
        % \item\label{it:glass} If $G$ is of type $333,442,632,3{\ast}3$, or $22{\ast}$, then $c_2(\mathbb R^2/G)\leq 2$.
        \item\label{it:glass-2} If $G$ is of type $22{\ast}$, then $\sqrt{2}\leq c_2(\mathbb R^2/G)\leq 2$.
        \item\label{it:glass-3} If $G$ is of type $333$ or $3{\ast}3$, then $\frac{3}{2}\leq c_2(\mathbb R^2/G)\leq 2$.
        \item\label{it:glass-4} If $G$ is of type $442$, then $2\sqrt{2-\sqrt{2}}\leq c_2(\mathbb R^2/G)\leq 2$.
        \item\label{it:glass-6} If $G$ is of type $632$, then $3\sqrt{2-\sqrt{3}}\leq c_2(\mathbb R^2/G)\leq 2$.
    \end{enumerate}
\end{theorem}

\begin{proof} \cref{lem.rotation_center} provides the lower bounds for cases~\ref{it:half-spin}, \ref{it:quarter-spin},  \ref{it:torus-cover}, \ref{it:glass-2}, \ref{it:glass-3}, \ref{it:glass-4}, and \ref{it:glass-6}. We tackle the remaining bounds case by case.

\medskip

\noindent\ref{it:reflections}: 
Groups of these types are affine reflection groups, so the quotients $\mathbb R^2/G$ are all isometric to fundamental domains of their actions. 
Hence, they embed isometrically in $\mathbb R^2$.

\medskip
\noindent\ref{it:cylinder}: 
A quotient of this type is a flat cylinder, which means
\[
c_2(\mathbb R^2/G) 
= \max\{c_2([0,1]), c_2(S^1)\} 
= \max\{1,\tfrac{\pi}{2}\} = \tfrac{\pi}{2},
\]
where the first equality uses Lemma~39 in~\cite{CahillIM:24} (see \cref{prop.max-product}) and the second uses Theorem~6.1 in~\cite{HeimendahlLVZ:22} (see \cref{prop.known-distortions}).

\medskip
\noindent\ref{it:half-spin}: 
Note that the reflections in $G$ generate an index-$2$ normal subgroup $N$ that is a wallpaper group of type $*2222$. 
The quotient $\mathbb R^2/N$ is isometric to a rectangle, and $G/N\cong C_2$ acts on the rectangle by a half rotation.
By the second equivariant embedding lemma (\cref{lem:quotient-distortion}), there is an isometric embedding $\mathbb R^2/G \to \mathbb R^2/\{\pm \Id\}$ that descends from the equivariant isometric embedding of the rectangle $\mathbb R^2/N \to \mathbb R^2$, so $c_2(\RR^2/G)$ is at most $c_2(\RR^2/\{\pm \Id\})$. The distortion of the latter space is $\sqrt{2}$ by \cref{thm.root unity}, matching our lower bound of $\sqrt{2}$.

\medskip
\noindent\ref{it:quarter-spin}: 
The same argument that applied in case \ref{it:half-spin} applies here as well; the subgroup of $G$ generated by reflections is an index-$4$ normal subgroup $N$ that is a wallpaper group of type $*2222$. 
Since $G$ is of type $4{\ast}2$, the translation lattice $T_G = T_N$ must be square, and so the quotient $\mathbb R^2/N$ is isometric to a flat square. 
The quotient group $G/N\cong C_4$ acts on $\mathbb R^2/N$ by quarter rotations. 
As in the previous case, the upper bound is obtained by isometrically embedding $\mathbb R^2/G \to \mathbb R^2/C_4$,
the Euclidean distortion of which is $4\sin(\frac{\pi}{8}) = 2\sqrt{2-\sqrt{2}}$ by \cref{thm.root unity}.

\medskip
\noindent\ref{it:klein}:
Note that $T_G$ must be a rectangular lattice. 
The translation subgroup $N$ of $G$ is a normal subgroup of index $2$. 
Since $T_N = T_G$, $N$ is a wallpaper group of type $o$ with a rectangular underlying lattice. 
\cref{lem.upsilon compute,thm:torus-distortion}(b) together imply $c_2(\mathbb R^2/G) \leq \sqrt{2}\cdot c_2(\mathbb R^2/N) = \frac{\pi}{\sqrt{2}}$. 
For the lower bound, let $\pi:\mathbb R^2\to \mathbb R^2/G$ be the quotient map, and let $L\subseteq \mathbb R^2$ be any glide axis of $G$. 
Then $\pi(L)$ is topologically a circle in the quotient, and we claim that the distance on the circle is geodesic\footnote{A \emph{geodesic circle} is any metric space isometric to a circle equipped with the standard arc-length metric, or equivalently, to a quotient space of the form $\mathbb R/c\mathbb Z$ with its induced quotient metric.}. 
Indeed, if $x,y\in L$, then the orbit $G\cdot y$ is a rectangular grid one of whose rows is contained in $L$, and the shortest path from $x$ to a point in $G\cdot y$ remains within $L$. 
The Euclidean distortion of a geodesic circle is $\frac{\pi}{2}$, giving the desired lower bound.

\medskip
\noindent\ref{it:football}:
A group $G$ of this type is generated by a pair of glides $\gamma_1,\gamma_2$ in orthogonal axes. To prove the upper bound, note that $G$ contains an index-$2$ normal subgroup $N$ of type ${\times}{\times}$, generated by $\gamma_1^2$ and $\gamma_2$. (It is generated over $N$ by either the glide $\gamma_1$ or the order-2 rotation $\gamma_1\gamma_2$.) Case~\ref{it:klein}, \cref{thm.upsilon-bound}, and \cref{lem.upsilon compute} together give $c_2(\mathbb R^2/G) \leq \pi$. Meanwhile, for the lower bound, we claim $\RR^2/G$ contains a geodesic circle, so that $c_2(\RR^2/G)\geq \pi/2$. The argument is similar to part \ref{it:klein}. Say the magnitude of the glide $\gamma_i$ is $\alpha_i>0$ for $i=1,2$. We can assume without loss of generality that $\alpha_1 \leq 2\alpha_2$. Then the image in $\RR^2/G$ of the glide axis $L$ of $\gamma_1$ is the desired geodesic circle, as we now argue. If $y\in L$ then $G\cdot y \subseteq G\cdot L = \langle \gamma_2 \rangle \cdot L$, the latter being the union of the glide axes parallel to $L$, which are $\alpha_2$ apart from each other. If $x\in L$ too, then there is an element of $
(G\cdot y)\cap L$ at a distance of at most $\alpha_1 / 2$ from $x$. Since $\alpha_1 / 2 \leq \alpha_2$, there is a representative of $G\cdot y$ of minimum distance to $x$ lying in $L$, so the image of $L$ in $\RR^2/G$ is isometric to $L/\langle \gamma_1\rangle$, a geodesic circle.
% To see the lower bound, note that the action of $G$ has a rotation center $p\in \mathbb R^2$ of order 2. Hence $G_p \cong C_2$ acts on $T_p\mathbb R^2$ by rotations. 
% Corollary 36 in \cite{CahillIM:24} (see Proposition~\ref{prop.known-distortions}) and Theorem~\ref{thm.isotropy} together give a lower bound of $\sqrt{2}$.

\medskip
\noindent\ref{it:torus-cover}:
As in case~\ref{it:klein}, the translation subgroup $N$ of $G$ is normal of index $2$. 
The desired upper bound follows from \cref{thm:torus-distortion}(a) and \cref{lem.upsilon compute}.

\medskip
\noindent\ref{it:mobius}:
A group $G$ of this type contains an index-$2$ normal subgroup $N$ of type ${\ast}{\ast}$, generated by a reflection and the square of a glide of minimal magnitude. 
Case~\ref{it:cylinder} and \cref{lem.upsilon compute} together give $c_2(\mathbb R^2/G) \leq \frac{\pi}{\sqrt{2}}$. 
The lower bound comes from noting that the M\"obius strip contains a geodesic circle, the distortion of which is $\frac{\pi}{2}$.

\medskip
\noindent\ref{it:glass-2}--\ref{it:glass-6}:
For a group $G$ of any of these five types, the quotient $\mathbb R^2/G$ consists of a pair of flat pieces glued together along some portion of the boundary. 
\begin{itemize}
\item If $G$ is of type $333$, $442$, or $632$, then $G$ is the alternating subgroup of an affine reflection group of type $\ast 333$, $\ast 442$, or $\ast 632$ respectively. Thus, the quotient $\mathbb R^2/G$ is isometric to a pair of equilateral, isosceles right, or semi-equilateral triangles respectively, glued together at their boundaries. 

\item If $G$ is of type $3{\ast}3$, then it has a rotation center $p$ not on a reflection line; it is of index $2$ inside a group $\langle G, f\rangle$ of type $\ast 632$ generated by a reflection $f$ in a line through $p$. The quotient $\RR^2/\langle G,f\rangle$ is isometric to a fundamental domain $\Delta$ which is a semi-equilateral triangle; we can take it to have its $\pi/3$-vertex at $p$. Meanwhile, the reflections in $\langle G,f \rangle$ across a line through $p$ all lie in the nontrivial coset $fG$ of $G$ in $\langle G,f\rangle$ (while the reflection in the third edge of $\Delta$ already lies in $G$). Thus, identifying $\RR^2/\langle G,f\rangle$ with $\Delta$, the natural map $\RR^2/G\rightarrow \RR^2/\langle G,f\rangle$ is a degree-2 branched cover, branched along both edges of $\Delta$ that are incident to $p$. Furthermore, $\RR^2/G$ is disconnected by the ramification locus because the axes of the reflections in $Gf$ disconnect a fundamental domain for $G$. Thus, the quotient $\RR^2/G$ is isometric to two copies of $\Delta$ glued along the two sides incident to $p$, i.e., to a pair of semi-equilateral triangles glued along the short leg and the hypotenuse.

\item If $G$ is of type $22{\ast}$, the argument is similar to that for type ${3{\ast}3}$. In this case $G$ has a pair of non-conjugate order-$2$ rotation centers $p,q$ such that the line $\ell$ through $p,q$ is parallel to the reflection axes but not equal to any of them. If $f$ is the reflection in $\ell$, then the group $\langle G,f\rangle$ is of type $\ast 2222$. Its fundamental domain is a rectangle $\Omega$, and if in the first place we choose $p$ and $q$ to be as close to each other as possible, then we can choose $\Omega$ to have $p$ and $q$ as vertices. Meanwhile, all the reflections in $\langle G,f\rangle$ through either $p$ or $q$ lie in the nontrivial coset $fG$ of $G$ in $\langle G,f\rangle$ (while the reflection in the other edge of $\Omega$ lies in $G$). Thus, identifying $\RR^2/\langle G,f\rangle$ with $\Omega$, the natural map $\RR^2/G\rightarrow \RR^2/\langle G,f\rangle$ is a degree-$2$ branched cover of $\Omega$, branched over the edges incident to either $p$ or $q$. By the same reasoning as for type $3{\ast}3$, $\RR^2/G$ is disconnected by the branch locus. Thus, the quotient $\RR^2/G$ is a pair of rectangles glued along three of the four sides.
\end{itemize}
In all cases, the quotient is a pair of identical spaces of distortion $1$ glued together along a closed subset, so \cref{corr.glued space} gives an upper bound of $2$.
% For the lower bounds, we note that if $G$ has a rotation center of order $r$, then by \cref{thm.isotropy}, $c_2(\mathbb R^2/G)\geq c_2(\mathbb R^2/C_r)$, where $C_r$ acts by rotations. 
% By \cref{thm.root unity}, the former distortion is exactly $r\sin(\frac{\pi}{2r})$. 
% The groups in cases \ref{it:glass-2}, \ref{it:glass-3}, \ref{it:glass-4}, and \ref{it:glass-6} have rotation centers of orders $2$, $3$, $4$, and $6$, respectively, thereby producing the lower bounds $2\sin(\frac{\pi}{4}) = \sqrt{2}$, $3\sin(\frac{\pi}{6}) = \frac{3}{2}$, $4\sin(\frac{\pi}{8}) = 2\sqrt{2-\sqrt{2}}$, and $6\sin(\frac{\pi}{12}) = 3\sqrt{2-\sqrt{3}}$, respectively.
\end{proof}


