\section{Previous results in bilipschitz invariant theory}
\label{app.previous results}

We first collect two existing general tools for computing Euclidean distortion. 
The first regards the Euclidean distortion of a product space and is based on Lemma~39 in \cite{CahillIM:24}. 
While \cite{CahillIM:24} states the result in a slightly different setting, the proof is nearly identical. 
Even so, we include a proof.

%Max-product
\begin{proposition}[Euclidean distortion of product spaces]
\label{prop.max-product}
    Given nonempty metric spaces $(X,d_X)$ and $(Y,d_Y)$, if we endow $X\times Y$ with the metric
    \[
    d_{X\times Y}^2\big((x,y),(x',y')\big) 
    := d_X^2(x,x') + d_Y^2(y,y'),
    \]
    then it holds that
    \[
    c_2(X\times Y) 
    = \max\{c_2(X),c_2(Y)\}.
    \]
\end{proposition}

\begin{proof}
    Let $y\in Y$ be arbitrary. Then $X$ is isometric to the subspace $X\times \{y\} \subseteq X\times Y$, so $c_2(X)\leq c_2(X\times Y)$ and similarly for $Y$.

    For the other inequality, we may assume that $c_2(X)$ and $c_2(Y)$ are finite, since otherwise the inequality is trivial. Let $f_X\colon X\to H_X$ and $f_Y\colon Y \to H_Y$ be bilipschitz embeddings into Hilbert spaces. Without loss of generality, we may assume the optimal lower Lipschitz constants for both maps are 1 by rescaling if necessary. Use $\beta_X$ and $\beta_Y$ to denote the respective optimal upper Lipschitz constants. We need only show that the product map
    \[
    f_X \times f_Y
    \colon X\times Y \to H_X\oplus H_Y
    \]
    has optimal upper Lipschitz constant at most $\max\{\beta_1,\beta_2\}$. Indeed,
    \begin{align*}
        \|(f_X\times f_Y)(x,y) - (f_X\times f_Y)(x',y')\|_{H_X\oplus H_Y}^2
        & = \|f_X(x)-f_X(x')\|_{H_X}^2 + \|f_Y(y)-f_Y(y')\|_{H_Y}^2
        \\ & \leq
        \beta_X^2\cdot d_X^2(x,x') + \beta_Y^2\cdot d_Y^2(y,y')
        \\ & \leq \max\{\beta_X^2,\beta_Y^2\} \cdot d_{X\times Y}^2\big((x,y),(x',y')\big),
    \end{align*}
    as desired.
\end{proof}

The second general tool for computing Euclidean distortion allows one to pass from a metric space to the finite subspaces thereof. 
Note that the proof given in \cite{CahillIM:24} uses an ultraproduct construction and hence relies on some nonconstructive axiom such as the axiom of choice.

\begin{proposition}[Euclidean distortion is finitely determined, Proposition~31 \cite{CahillIM:24}]
\label{prop.finitely-determined}
    Let $X$ be a metric space. Then
    \[c_2(X) = \sup_{\substack{B\subseteq X\\|B|<\infty}} c_2(B).\]
\end{proposition}


In addition to the above tools, we also use previously established Euclidean distortions of a few spaces. 
Some of these results are mentioned in Table~\ref{table1}, but we collect them here as well for easy reference.

\begin{proposition}\label{prop.known-distortions}
The following statements hold:
    \begin{enumerate}[label=(\alph*)]
        \item\label{it.known_distortions.pm_identity} \emph{(\cite[Corollary 36]{CahillIM:24})} Let $V$ be a real Hilbert space with $\dim(V)\geq 2$ and set $G:= \{\pm \Id_V\}$. Then $c_2(V/G) = \sqrt{2}$.
        \item\label{it.known_distortions.circle_action} \emph{(\cite[Corollary 37]{CahillIM:24})} Let $V$ be a complex Hilbert space with $\dim(V)\geq 2$ and set $G:= \{z\in\mathbb C:|z|=1\}$. Then $c_2(V/G) = \sqrt{2}$.
        \item\label{it.known_distortions.roots_of_unity} \emph{(\cite[Corollary 38]{CahillIM:24})} Let $G := \langle e^{2\pi i/r}\rangle \leq U(1)$. Then $c_2(\mathbb C/G) = r\sin\left(\frac{\pi}{2r}\right)$.
        \item\label{it.known_distortions.circle}\emph{(\cite[Theorem 6.1]{HeimendahlLVZ:22})} For each $c>0$, $c_2(\mathbb R/c\mathbb Z) = \frac{\pi}{2}$.
    \end{enumerate}
\end{proposition}

\section{Bilipschitz embedding of a compact quotient}
\label{app.finite distortion}
This section presents a streamlined proof of the following result:
\begin{proposition}
    \label{prop.finite distortion}
    Let $M$ be a compact Riemannian manifold equipped with an isometric action by a compact group $G$. Then $c_2(M/G)<\infty$. 
\end{proposition}

In particular, if $V$ is a finite-dimensional real inner product space with unit sphere $S$ and $G\leq \Oname(V)$ is compact, then $c_2(S/G)<\infty$, and so $c_2(V/G)<\infty$ by Section~4 of~\cite{CahillIM:24}.

The first key tool to the proof of \cref{prop.finite distortion} is the following \emph{gluing theorem}, which reduces the embedding problem to local neighborhoods. It is an immediate consequence of Theorem~1.1 in~\cite{MakarychevM:16}.
\begin{proposition}[Gluing theorem]
    \label{prop.gluing theorem}
    Let $X$ be a metric space, and let $A,B\subseteq X$ be subspaces. Then
    \[c_2(A\cup B)\leq 11\cdot c_2(A)\cdot c_2(B).\]
\end{proposition}

We will also use the fact that bilipschitz behavior is preserved under diffeomorphic changes over compact sets:

\begin{proposition}[Diffeomorphisms are bilipschitz over compact sets]
    \label{prop.diff local bilip}
    Let $f\colon N_1\to N_2$ be a diffeomorphism between Riemannian manifolds. Then for every relatively compact subspace $X\subseteq N_1$, the restriction $f|_{X}$ is bilipschitz.
\end{proposition}
\begin{proof}
    Suppose for contradiction that $f|_{X}$ is not bilipschitz for some relatively compact subspace $X\subseteq N_1$. Then there exist sequences $(x_k)_{k=1}^\infty$, $(y_k)_{k=1}^\infty$ in $X$ such that $x_k\neq y_k$ and
    \begin{equation}
    \label{eq.bilip zero}
    \frac{d_{N_2}(f(x_k),f(y_k))}{d_{N_1}(x_k,y_k)}\to 0.
    \end{equation}
    By replacing $X$ with its closure if necessary, we may assume without loss of generality that $X$ is compact. Thus, we may pass to subsequences and assume $x_k\to x$ and $y_k\to y$  for some $x,y\in X$.

    If $x\neq y$, then \eqref{eq.bilip zero} implies $f(x)=f(y)$, contradicting the injectivity of $f$. Meanwhile, if $x=y$, then $f$ fails to be locally bilipschitz at $x$, which contradicts the fact that diffeomorphisms of Riemannian manifolds are locally bilipschitz.
\end{proof}

We will also make essential use of a well-behaved $G$-equivariant diffeomorphism provided by the \emph{slice theorem}. In what follows, recall the notion of an \emph{isotropy representation} introduced at the beginning of \cref{sec.isotropy}. The following result commonly referred to as the \emph{slice theorem} or the \emph{tube theorem} is a reformulation of the main content of Section~3.2 in~\cite{AlexandrinoB:15}, adapted to the setting of an isometric action by a compact Lie group. 
\begin{proposition}[Slice theorem]
    \label{prop.slice theorem}
    Let $M$ be a compact Riemannian manifold equipped with an isometric action by a compact Lie group $G$, where $G$ is endowed with a bi-invariant Riemannian metric. Fix a point $x\in M$, let $G_x$ denote its (compact) pointwise stabilizer, and let $N_x$ denote the orthogonal complement of $T_x(G\cdot x)$ in $T_xM$. Then there exists $R>0$ such that for any open ball $B\subseteq N_x$ of radius less than $R$, it holds that
    \begin{itemize}
        \item[(i)] $B$ is $G_x$-invariant under the isotropy representation,
        \item[(ii)] $G\cdot \exp_x(B)$ is open in $M$,
        \item[(iii)] $G_x$ acts freely and isometrically on the product Riemannian manifold $G\times B$ via the action
        \[h\cdot (g,y):= (gh^{-1},hy),\]
        and
        \item[(iv)] letting $G\times_{G_x} B := (G\times B)/G_x$ denote the corresponding orbit space, equipped with the quotient Riemannian metric, and giving it an isometric left $G$-action via 
        \[k\cdot [(g,y)]:= [(kg,y)],\]
        it holds that the map 
    \[G\times_{G_x} B\to G\cdot \exp_x(B), \quad [(g,y)]\mapsto g\cdot \exp_x(y)\]
    is a $G$-equivariant diffeomorphism.
    \end{itemize}
\end{proposition}

With this setup, we are ready to give a proof of \cref{prop.finite distortion}.

\begin{proof}[Proof of \cref{prop.finite distortion}]
    We proceed by induction on the dimension of $M$. For the base case $\dim(M)=0$, the quotient $M/G$ is a finite metric space, and any injective embedding into a Hilbert space is automatically bilipschitz.

    Now assume that the result holds for all compact Riemannian manifolds of dimension less than $n$, and suppose that $\dim(M) = n$. By replacing $G$ with its compact image in the isometry group of $M$ if necessary, we may assume without loss of generality that $G$ is a compact Lie group, equipped with a bi-invariant Riemannian metric.

    Using the gluing theorem (\cref{prop.gluing theorem}) and the compactness of $M/G$, it suffices to fix $x\in M$ and to find a $G$-stable neighborhood $U$ of $x$ such that $c_2(U/G)<\infty$. Let $B$ be as given in the slice theorem (\cref{prop.slice theorem}). By \cref{prop.diff local bilip}, the slice theorem, and the second equivariant embedding lemma (\cref{lem:quotient-distortion}), it suffices to show that $c_2((G\times_{G_x} B)/G) < \infty$. Note that
    \[
    \begin{aligned}
    &d_{(G\times_{G_x} B)/G}(G\cdot[(g_1,y_1)] ,G\cdot[(g_2,y_2)])^2\\
    &=\min_{k_1,k_2\in G}d_{G\times_{G_x} B}(k_1\cdot[(g_1,y_1)] ,k_2\cdot[(g_2,y_2)])^2 && \text{(def.\ of $d_{(G\times_{G_x}B)/G}$)}\\
    &= \min_{k_1,k_2\in G}d_{G\times_{G_x} B}([(k_1g_1,y_1)] ,[(k_2g_2,y_2)])^2 && \text{(def.\ of $G$-action on $G\times_{G_x}B$)}\\
    &= \min_{k_1,k_2\in G}d_{G\times_{G_x} B}([(k_1,y_1)] ,[(k_2,y_2)])^2 && \text{(change of variables)}\\
    &= \min_{k_1,k_2\in G}\min_{h_1,h_2\in G_x}d_{G\times B}((k_1h_1^{-1},h_1y_1) ,(k_2h_2^{-1},h_2y_2))^2 && \text{(def.\ of $d_{G\times_{G_x}B}$)}\\
    &= \min_{h_1,h_2\in G_x} \min_{k_1,k_2\in G} d_{G\times B}((k_1h_1^{-1},h_1y_1) ,(k_2h_2^{-1},h_2y_2))^2 && \text{(switch minima)}\\
    &= \min_{h_1,h_2\in G_x} \Big(\min_{k_1,k_2\in G} d_G(k_1h_1^{-1},k_2h_2^{-1})^2 + d_B(h_1y_1,h_2y_2)^2\Big) && \text{(product metric)}\\
    &= \min_{h_1,h_2\in G_x} d_B(h_1y_1,h_2y_2)^2 && \text{(inner $\min=0$ via $k_i = h_i$)}\\
    &= d_{B/G_x}(G_x\cdot y_1,G_x\cdot y_2)^2 && \text{(def.\ of $d_{B/G_x}$).}
    \end{aligned}
    \]
    As such, $(G\times_{G_x} B)/G$ is isomorphic, as a metric space, to $B/G_x\subseteq N_x/G_x$, where the isometry is induced by the well-defined $G$-invariant surjection 
    \[G\times_{G_x}B\to B/G_x, \quad [(g,y)]\mapsto G_x\cdot y.\]
    Thus, it suffices to show $c_2(N_x/G_x)<\infty$. By \cite[Section~4]{CahillIM:24}, it further suffices to show that $c_2(S/G_x)<\infty$, where $S$ denotes that unit sphere in $N_x$. The result now follows by applying the induction hypothesis to $S$, whose dimension is at most $\dim(M)-1$.
\end{proof}

\section{Bochner spaces over Radon measures}
\label{app.bochner}

This section is primarily devoted to the proof of \cref{prop.hilbert L2}. 
While the definition of $L^2(G,H)$ given therein appears natural as it extends the familiar space when $H=\mathbb R$, the situation is more nuanced than it first appears.

Given a measure space $(Y,\mathcal A,\mu)$ and a Hilbert space $H$, consider the space of Borel-measurable functions $f\colon Y\to H$ such that $\int_Y\|f(y)\|_H^2\, d\mu(y) < \infty$. 
Identifying functions that agree $\mu$-almost everywhere, one might hope this space forms a vector space. 
Indeed, this identification recovers $L^2(Y,\mathbb R)$ when $H=\mathbb R$. 
However, for general $Y$ and $H$, the space may fail to be closed under addition. 
An explicit example is given in \cref{prop.fail vector} at the end of this section, where $(Y,\mathcal A,\mu)$ is a probability space.

To address this issue, we restrict attention to \textit{strongly measurable} functions. 
For a general Banach space $B$, this yields the well-defined \textit{Bochner space} $L^p(Y,B)$, which is a Banach space under the natural norm. 
Fortunately, when $\mu$ is a Radon measure (e.g., Haar measure on a locally compact group), Borel and strong measurability coincide for $p$-norm-integrable functions, thereby validating the \textit{a priori} natural definition in \cref{prop.hilbert L2}.

This section is divided into four subsections. 
The first two are devoted to the proof of \cref{prop.hilbert L2}, while the latter two offer further context and elaboration on related subtleties. 
In~\ref{app.sub.general def}, we consider a measure space $(Y,\mathcal A,\mu)$ and a Banach space $B$, and formally define key concepts such as strong measurability and the Bochner spaces $L^p(Y,B)$. 
We observe that, in the Radon setting, Borel and strong measurability coincide for $p$-norm-integrable functions, a fact that allows for an immediate proof of \cref{prop.hilbert L2}(a), as Haar measures are Radon. 
In~\ref{app.sub.proof b}, we prove \cref{prop.hilbert L2}(b) by leveraging the density of compactly supported continuous functions in $L^p(Y,B)$, under the assumption that $Y$ is a locally compact Hausdorff space and $\mu$ is a Radon measure. 

In~\ref{app.sub.dimension}, we provide additional insight into the structure of $L^2(G,H)$ by examining its Hilbert space dimension when $G$ is a locally compact group endowed with Haar measure and $H$ is a Hilbert space. 
Finally, in~\ref{app.sub.note noncompact}, we discuss the limitations of elementary set theory in determining whether the distinction between strong and Borel measurability remains necessary in the $\sigma$-finite non-Radon case.

\subsection{General definitions and proof of \cref{prop.hilbert L2}(a)}
\label{app.sub.general def}

In this subsection, we introduce relevant terminology, review foundational results, and then provide a proof of \cref{prop.hilbert L2}(a). 

\begin{definition}
Let $(Y,\mathcal A,\mu)$ be a measure space and $B$ a Banach space. 
A Borel-measurable function $f\colon Y\to B$ is said to be
\begin{itemize}
    \item[(a)] \textbf{$\mu$-simple} if it is of the form
\[
f(x)
=\sum_{i=1}^n x_i\cdot 1_{x\in A_i},
\]
where $x_i \in B$ and $A_i \in \mathcal A$ satisfy $\mu(A_i) < \infty$,
    \item[(b)] \textbf{$\mu$-strongly measurable} if there exists a sequence $(f_n)_{n=1}^\infty$ of $\mu$-simple functions such that $f_n\to f$ pointwise $\mu$-almost everywhere,
    \item[(c)] \textbf{$\mu$-essentially separably valued} if there exists a $\mu$-null set $N\subseteq Y$ such that $f(Y\setminus N)$ is separable, and
    \item[(d)] \textbf{$p$-norm-integrable}, with $p\in [1,\infty)$, if
    \[\int_Y \|f(y)\|_B^p\, d\mu < \infty.\]
\end{itemize}
In addition, we say that $f$ has \textbf{$\sigma$-finite support} if the measurable set $f^{-1}(B\setminus \{0\})$ is $\sigma$-finite with respect to $\mu$.
\end{definition}

Note that every $p$-norm-integrable function $f\colon Y\to B$ has $\sigma$-finite support. 
Indeed, the sets $Y_n:=\{y\in Y:\|f(y)\|_B^p>1/n\}$ form a countable cover of $f^{-1}(B\setminus\{0\})$, and each $Y_n$ has finite measure by Markov's inequality.

Next, we recall the notion of a Radon measure, which plays a central role in what follows.

\begin{definition}
    Let $Y$ be a Hausdorff topological space, and let $\mathcal A$ denote its Borel $\sigma$-algebra. 
    A measure $\mu$ on $(Y,\mathcal A)$ is called a \textbf{Radon measure} if it satisfies the following:
    \begin{itemize}
        \item[(a)] \textit{Locally finite}: For every $y\in Y$, there exists an open neighborhood $U$ of $y$ such that $\mu(U)<\infty$, and
        \item[(b)] \textit{Inner regular}: For all $A\in \mathcal A$,
            \[
            \mu(A) 
            = \sup\big\{\mu(K): K\subseteq A\ \text{compact}\big\}.
            \]
    \end{itemize}
\end{definition}

Note that local finiteness implies that $\mu$ is finite on compact sets. 
The converse holds when $Y$ is additionally locally compact. 
Also, every Haar measure on a locally compact group is a Radon measure; see~\cite[Thm.~8.12]{Salamon:16}. 

The following proposition summarizes several results from~\cite[Chapter~1]{HytonenNVW:16}.
%\cite[Cor.~1.1.7, Cor.~1.1.10, Prop.~1.1.16, Thm.~1.1.20, Sec.~1.2.b]{HytonenNVW:16}.

\begin{proposition}
    \label{prop.banach L2}
    Let $(Y,\mathcal A,\mu)$ be a measure space, $B$ a Banach space, and $f\colon Y\to B$ a Borel-measurable function. 
    Then the following are equivalent:
    \begin{enumerate}[label=(\roman*)]
        \item $f$ is $\mu$-strongly measurable;
        \item $f$ is $\mu$-essentially separably valued and has $\sigma$-finite support.
    \end{enumerate}
    Furthermore, for $p\in[1,\infty)$, let $L^p(Y,B)$ denote the space of all $p$-norm-integrable, $\mu$-strongly measurable functions $f\colon Y\to B$, identified up to $\mu$-almost everywhere equality. 
    Then $L^p(Y,B)$ is a Banach space under the norm
    \[
    \|f\|_{L^p(Y,B)} 
    := \left(\int_Y\big\|f(y)\big\|^p_B\, d\mu(y)\right)^{1/p},
    \]
    and the $\mu$-simple functions form a dense subset.
\end{proposition}

The space $L^p(Y,B)$ is called a \textbf{Bochner space}. 
For $\mu$-strongly measurable functions $f,g\in L^p(Y,B)$, the sum $f+g$ need not be Borel-measurable. 
However, by \cref{prop.banach L2}(ii), it agrees $\mu$-almost everywhere with a Borel-measurable function, which we take to represent the sum in $L^p(Y,B)$; see~\cite[Prop.~2.6]{Folland:99}.

If $Y$ is a locally compact Hausdorff topological space equipped with a Radon measure, then the space $\mathcal C_c(Y,B)$ of compactly supported continuous functions from $Y$ to $B$ is dense in $L^p(Y,B)$. 
This follows from approximating $\mu$-simple functions, which reduces to the familiar case $B=\mathbb R$; see, for example,~\cite[Thm.~4.15]{Salamon:16}.

By definition, every $\mu$-strongly measurable function is Borel-measurable. 
In the special case of functions with $\sigma$-finite support over Radon measure spaces, the converse also holds.

\begin{proposition}
    \label{prop.compact measure}
    Let $(Y,\mathcal A,\mu)$ be a Radon measure space and $B$ a Banach space. 
    Then every Borel-measurable function $f\colon Y\to B$ with $\sigma$-finite support is $\mu$-essentially separably valued.
\end{proposition}

\begin{proof}
    First, observe that the restriction of $\mu$ to the measurable subspace $f^{-1}(B\setminus \{0\})\in\mathcal A$ remains a Radon measure. 
    Indeed, the subspace $f^{-1}(B\setminus \{0\})$ is Hausdorff, the restriction of $\mathcal A$ to this subspace coincides with its Borel $\sigma$-algebra (which remains in $\mathcal A$ by measurability), the restricted measure remains locally finite, and every compact subset of $f^{-1}(B\setminus \{0\})$ is a compact subset of $Y$.
    Thus, we may assume without loss of generality that $Y$ is $\sigma$-finite. 
    Let $(Y,\hat{\mathcal A},\hat\mu)$ denote the completion of $\mu$. 
    Since every $\hat \mu$-null set is contained in a $\mu$-null set, it suffices to show $f$ is $\hat \mu$-essentially separably valued.

    Note that $\hat \mu$ remains locally finite, as $\mathcal A\subseteq \hat {\mathcal A}$. 
    Moreover, $\hat \mu$ is inner regular: each $F\in \hat{\mathcal A}$ has the form $F=E\cup N$ where $E\in\mathcal A$ and $\hat\mu(N)=0$, so it suffices to approximate $\mu(E)$ from below by compact sets. 
    It then follows from~\cite[Prop.~213H(a)]{Fremlin:00} that $\hat \mu$ is a Radon measure in the sense of \cite[Def.~411H(b)]{Fremlin:00} (on $\sigma$-finite spaces, this definition requires a Radon measure to be complete). 
    The conclusion now follows by combining Proposition~416A, Proposition~418G and Theorem~451S from~\cite{Fremlin:00}. 
\end{proof}

With this, \cref{prop.hilbert L2}(a) follows immediately by combining \cref{prop.banach L2,prop.compact measure}, along with the facts that every Haar measure over a locally compact group is Radon and that every $p$-norm-integrable function has $\sigma$-finite support.

\subsection{Proof of \cref{prop.hilbert L2}(b)}
\label{app.sub.proof b}

We now prove \cref{prop.hilbert L2}(b). 
Let $H$ be a Hilbert space, and equip $L^2(G,H)$ with the linear left action of $G$ defined by
\[
(g\cdot f)(h)
= f(hg).
\]
Through this action, each $g\in G$ maps Borel-measurable functions to Borel-measurable functions.
Furthermore, the action is isometric and well defined on $L^2(G,H)$. 
Indeed, for all $g\in G$ and $f\in L^2(G,H)$, the right-invariance of $\mu$ yields
    \begin{align*}
        \|g\cdot f\|_{L^2(G,H)}^2
         =\int_G\|f(hg) \|_H^2\, d\mu(h)
         =\int_G \|f(h)\|_H^2\, d\mu(h) 
         = \|f\|_{L^2(G,H)}^2.
    \end{align*}
To verify strong continuity, observe first that, by \cref{prop.banach L2,prop.compact measure}, the space of $\mu$-simple functions is dense in $L^2(G,H)$. 
Since $G$ is locally compact Hausdorff and its Haar measure is Radon, every such function can be approximated in norm by compactly supported continuous functions; e.g., see~\cite[Thm.~4.15]{Salamon:16}. 
It follows that the space $\mathcal C_c(G,H)$ of compactly supported continuous functions from $G$ to $H$ is dense in $L^2(G,H)$. 
For any $f\in \mathcal C_c(G,H)$ and any sequence $g_n\to g$ in $G$, the dominated convergence theorem yields
    \begin{equation}
        \label{eq.DCT}
        \|g_n\cdot f - g\cdot f\|_{L^2(G,H)}^2 
        = \int_{G} \|f(hg_n)-f(hg)\|_{H}^2\, d\mu(h) 
        \to 0.
    \end{equation}
Now fix any $f\in L^2(G,H)$, $\varepsilon>0$, and a sequence $g_n\to g$ in $G$. 
By density, we may choose $k\in \mathcal C_c(G,H)$ with $\|f-k\|_{L^2(G,H)}<\frac{\varepsilon}{3}$. 
Then by \eqref{eq.DCT}, there exists $N> 0$ such that for all $n\geq N$, we have $\|g_n\cdot k-g\cdot k\|_{L^2(G,H)}<\frac{\varepsilon}{3}$, and so
    \[
    \|g_n\cdot f-g\cdot f\|_{L^2(G,H)}
    \leq 2\|f-k\|_{L^2(G,H)}+\|g_n\cdot k - g\cdot k\|_{L^2(G,H)} 
    < \varepsilon.
    \]
Since $\varepsilon>0$ was arbitrary, it follows that $g_n\cdot f\to g\cdot f$ in norm, as required.

\subsection{Note on dimension of \texorpdfstring{$L^2(G,H)$}{L2(G,H)}}
\label{app.sub.dimension}

We briefly remark on the dimension of $L^2(G,H)$, where $G$ is a locally compact group equipped with Haar measure and $H$ is a Hilbert space. 
If $G$ is finite and $H$ is finite dimensional, then $L^2(G,H)\cong H^{|G|}$ is also finite dimensional. 
Meanwhile, if $G$ is second countable and $H$ is separable, then the Borel $\sigma$-algebra of $G$ is countably generated, and the separability of $L^2(G,H)$ follows from \cite[Prop.~1.2.29]{HytonenNVW:16}.

More generally, using the axiom of choice, let $\mathfrak m(G)$ denote the minimal cardinality of a topological basis for $G$, and let $\dim(H)$ denote the Hilbert space dimension of $H$, i.e., the cardinality of any orthonormal basis. 
Then
\[
\dim(L^2(G,H)) 
= \mathfrak m(G)\cdot \dim(H).
\]
To see this, let $(e_i)_{i\in I}$ be an orthonormal basis for $H$. 
Then $L^2(G,H)$ decomposes as an orthogonal direct sum of strongly continuous unitary representations:
\[
L^2(G,H)
\cong \bigoplus_{i\in I} L^2(G, \mathbb Re_i).
\]
By Theorem~2 in~\cite{Vries:78}, each summand $L^2(G,\mathbb Re_i)$ has dimension $\mathfrak m (G)$, so the claimed formula follows.

\subsection{Note on non-Radon measures and the Banach--Ulam problem}
\label{app.sub.note noncompact}

In light of \cref{prop.hilbert L2,prop.banach L2,prop.compact measure}, and noting that every $p$-norm-integrable function has $\sigma$-finite support, we conclude with a remark on the equivalence between Borel and $\mu$-strong measurability in the setting of $\sigma$-finite measure spaces, which may not be Radon. 
According to \cref{prop.banach L2}, $\mu$-strongly measurability in this context is equivalent to being $\mu$-essentially separably valued. 
With this in mind, consider the following statement:
\begin{itemize}
\item[\textbf{($\mathsf{E}$)}]
For every $\sigma$-finite measure space $(Y,\mathcal A,\mu)$, Banach space $B$, and Borel-measurable function $f\colon Y\to B$, it holds that $f$ is $\mu$-strongly measurable.
\end{itemize}
%We observe that in any consistent formulation of Zermelo--Fraenkel set theory with the Axiom of Choice ($\mathsf{ZFC}$), the failure of \textbf{($\mathsf{E}$)} proves the consistency of $\mathsf{ZFC}$. Therefore, within $\mathsf{ZFC}$, the failure of equivalence between Borel and $\mu$-strong measurability in the $\sigma$-finite case is not provable.
We show this is equivalent to the following deep statement in set-theoretic measure theory:
\begin{itemize}
\item[\textbf{(${\mathsf{BU}}$)}]
There does not exist a discrete probability space $(X,2^X,\mu)$ such that $\mu(\{x\}) = 0$ for every $x\in X$.
\end{itemize}
The presence for a proof of \textbf{(${\mathsf{BU}}$)} in Zermelo--Fraenkel set theory with the Axiom of Choice ($\mathsf{ZFC}$) is commonly referred to as the \emph{Banach--Ulam problem}. 
While it is believed that \textbf{(${\mathsf{BU}}$)} is independent of $\mathsf{ZFC}$ \cite[Sec.~363S]{Fremlin:00}, the following can be stated with certainty: the consistency of $\mathsf{ZFC}$ implies the consistency of $\mathsf{ZFC}+\textbf{(${\mathsf{BU}}$)}$. 
Thus, the failure of $\textbf{(${\mathsf{BU}}$)}$ cannot be proved within $\mathsf{ZFC}$ itself~\cite[Sec.~2.1.6]{Federer:14}. 
The next proposition establishes that \textbf{(${\mathsf{BU}}$)} is equivalent to \textbf{(${\mathsf{E}}$)}. 
Hence, the failure of \textbf{(${\mathsf{E}}$)} is not provable within $\mathsf{ZFC}$, and it is plausible that \textbf{(${\mathsf{E}}$)} is independent of $\mathsf{ZFC}$.

\begin{proposition}
\label{prop.equiv E UC}
    The following equivalence holds:
    \[
    \normalfont \textbf{(${\mathsf{E}}$)} 
    \iff \textbf{(${\mathsf{BU}}$)}.
    \]
\end{proposition}

\begin{proof}
\textbf{(${\mathsf{BU}}$)}$\Rightarrow$\textbf{(${\mathsf{E}}$)} was established in~\cite[Prop.~438D]{Fremlin:00}.
Now suppose the negation of \textbf{(${\mathsf{BU}}$)} holds, that is, there exists a probability space $(X,2^X,\mu)$ such that $\mu(\{x\})=0$ for every $x\in X$. 
Let $(e_i)_{i\in X}$ be the standard orthonormal basis of the Hilbert space $\ell^2(X)$, and define a function $f\colon X\to \ell^2(X)$ by $f(w):= e_w$. 
While $f$ is Borel-measurable, it is not $\mu$-strongly measurable: for any subset $A\subseteq X$, the image $f(A)$ is separable if and only if $A$ is countable, in which case $\mu(A) = 0 < 1$.
\end{proof}

In fact, assuming the {continuum hypothesis} and the negation of {\normalfont\textbf{(${\mathsf{BU}}$)}}, the following proposition demonstrates why strong measurability is required in \cref{prop.banach L2} to ensure that addition in Bochner spaces is well-defined.

\begin{proposition}
\label{prop.fail vector}
    Assuming the continuum hypothesis and the negation of {\normalfont\textbf{(${\mathsf{BU}}$)}}, there exists a probability space $(Y,\mathcal A,\mu)$, a Hilbert space $H$, and Borel-measurable functions $f_1,f_2\colon Y\to H$ such that $\|f_i(y)\|_H = 1$ for each $y\in Y$, but $f_1+f_2$ is not $\mu$-almost everywhere equal to any Borel-measurable function.
\end{proposition}

\begin{proof}
By assumption, there exists a probability space $(X,2^X,\mu)$ such that $\mu(\{x\})=0$ for every $x\in X$. 
By Theorem~438C in~\cite{Fremlin:00} and the continuum hypothesis, we may take $X$ to be an \textit{atom}, that is, $\mu(A)\in\{0,1\}$ for every subset $A\subseteq X$.

Define $(Y, \mathcal A,\mu^{\otimes 2})$ to be the product probability space where $Y:= X\times X$ and $\mathcal A:= 2^X\otimes 2^X$. 
Put $H:=\ell^2(X)$ and denote its Borel $\sigma$-algebra by $\mathcal B$. 
Let $(e_x)_{x\in X}$ be the standard orthonormal basis of $H$, and define
\[
f_1(x,x')
:= e_x
\qquad
\text{and}
\qquad
f_2(x,x')
:= -e_{x'}.
\] 
Then $f_1$ and $f_2$ are $(\mathcal A,\mathcal B)$-measurable functions satisfying $\|f_i(y)\|_H=1$ for each $y\in Y$, and we have $\Delta = (f_1+f_2)^{-1}(0)$. 
If $f_1+f_2$ is $\mu$-almost everywhere equal to an $(\mathcal A,\mathcal B)$-measurable function, then $f_1+f_2$ is $(\mathcal A^*,\mathcal B)$-measurable, where $\mathcal A^*$ is the completion of $\mathcal A$. 
As such, it suffices to show $\Delta$ is not $\mathcal A^*$-measurable, or equivalently, that its inner and outer measures do not coincide.

To state this aim more precisely, recall that a \emph{rectangle} in $Y$ is a set of the form $C\times D$ where $C,D\subseteq X$, and let $\mathcal R_f\subseteq \mathcal A$ (resp.\ $\mathcal R_c\subseteq \mathcal A$) denote the algebra (resp.\ collection) of finite (resp.\ countable) disjoint unions of rectangles in $Y$. 
Then we wish to establish the inequality
\begin{equation}
\label{eq.inner outer}
\sup\Big\{\mu^{\otimes 2}(A): A\in \mathcal R_c, \ A\subseteq \Delta\Big\}
< \inf\left\{\sum_{i=1}^\infty\mu^{\otimes 2}(R_i): R_i\in \mathcal R_f,\, \Delta\subseteq \cup_{i=1}^\infty R_i \right\}.
\end{equation}
Since every rectangle within $\Delta$ is a singleton and $\mu^{\otimes 2}$ is countably additive and vanishing on singletons, the left-hand side of \eqref{eq.inner outer} is zero. 
On the other hand, let $K$ denote its right-hand side. 
The following shows that $K$ is nonzero:
\begin{align*}
    K 
    &= \inf\left\{\sum_{i=1}^\infty\mu(C_i)\mu(D_i): C_i,D_i\subseteq X,\, \Delta\subseteq \cup_{i=1}^\infty \big(C_i\times D_i\big) \right\} 
    &&\text{(definition of $\mathcal R_f$)}\\
    &=\inf\left\{\sum_{i=1}^\infty\mu(C_i)^2: C_i\subseteq X,\, \Delta\subseteq \cup_{i=1}^\infty \big(C_i\times C_i\big) \right\} 
    &&\text{(replace $C_i,D_i$ with $C_i\cap D_i$)}\\
    &=\inf\left\{\sum_{i=1}^\infty\mu(C_i)^2: C_i\subseteq X,\, X= \cup_{i=1}^\infty  C_i \right\} 
    &&\text{(definition of $\Delta$)}\\
    &= 1 
    &&\text{($X$ is an atom).} 
    \tag*{\qedhere}
\end{align*}
\end{proof}

\section{Extensions by subspaces of translations are split}
\label{app.split}

In this appendix, we use group cohomology to prove that in the situation of \cref{thm.euclidean-subgroup}, the extension of groups $0\rightarrow T\rightarrow \Gamma\rightarrow G\rightarrow 1$ is always split. 
Note that $\pi|_{\Gamma}\colon \Gamma \to G$ is a Lie group homomorphism since $\Gamma$ and $G$ are closed embedded Lie subgroups of $\E(V)$ and $\Oname(V)$, respectively.

\begin{proposition}\label{prop.extension-splits}
Under the hypotheses of \cref{thm.euclidean-subgroup}, the following short exact sequence of Lie group homomorphisms splits:
\[
0
\rightarrow T
\hookrightarrow \Gamma
\xrightarrow{\pi|_\Gamma} G
\rightarrow 1.
\]
In other words, there exists a Lie group homomorphism $\varphi\colon G\to \Gamma$ such that $\pi|_\Gamma\circ \varphi = \mathrm{id}_G$, whereupon it follows that $\Gamma = T\rtimes \varphi(G)$ is an internal semidirect product. 
Furthermore, there exists $p\in V$ such that $\varphi(g)\cdot p = p$, for each $g\in G$.
\end{proposition}

We provide two proofs for this proposition. 
The first is group cohomology--based while the second avoids group cohomology, at least explicitly. 
Recall that for a topological group $G$, a continuous $G$-module $M$ is a topological abelian group equipped with an action of $G$ such that the action map $G\times M\rightarrow M$ is continuous. 
Following \cite[Section~3]{Hu:52}, the continuous group cohomology of $G$ with coefficients in $M$ is defined as the cohomology $H_c^\bullet(G,M)$ of the cochain complex $\{\operatorname{C}(G^n,M)\}_{n=0}^\infty$, where $\operatorname{C}(G^n,M)$ is the $\mathbb Z$-module comprised of continuous maps from $G^n$ to $M$ and the coboundary map $d \colon \operatorname{C}(G^n,M)\to \operatorname{C}(G^{n+1},M)$ is defined by the usual formula
\[
\begin{aligned}
(d\varphi)(g_1,\dots,g_{n+1}) 
:= g_1\cdot \varphi(g_2,\dots,g_{n+1})
+\sum_{i=1}^n (-1)^i \varphi(g_1,&\dots,g_ig_{i+1},\dots,g_{n+1})\\
&+ (-1)^{n+1}\varphi(g_1,\dots,g_{n}).
\end{aligned}
\]
Specializing to $n\in\{0,1\}$, one sees that the $1$-cocycles are the \textit{continuous crossed homomorphisms}, i.e., continuous maps $b\colon G\to M$ that satisfy $b(gh) = b(g) + g\cdot b(h)$ for all $g,h\in G$, and that the $1$-coboundaries are the \textit{principal crossed homomorphisms}, i.e., $1$-cocycles of the form $g\mapsto gm-m$ for some $m\in M$. 
As such, $H_c^1(G,M)$ vanishes if and only if every continuous crossed homomorphism is principal. 
Meanwhile, by \cite[(5.3)]{Hu:52}, the group $H_c^2(G,M)$ classifies isomorphism classes of extensions in the category of topological groups 
\[
0
\to M
\hookrightarrow \Gamma 
\xrightarrow{\pi} G
\to 1
\]
with conjugation by $\Gamma$ inducing the given action of $G$ on $M$, such that there exists a continuous (but not necessarily homomorphic) section $\varphi\colon G\rightarrow\Gamma$ that splits $\pi$ (i.e., such that $\pi\varphi=1_G$). 
The class of the split extension $\Gamma:= M\rtimes G$ corresponds to $0\in H_c^2(G,M)$, so if $H_c^2(G,M)=0$, then every extension with a continuous section has a homomorphic section.

With this recap, we give an almost immediate group cohomology--based proof of \cref{prop.extension-splits}.

\begin{proof}[Cohomology-based proof]
The hypothesis of \cref{prop.extension-splits} states that $T$ is a real vector space, and also immediately implies that $G$ is compact. 
Let $W$ be any finite-dimensional real $G$-representation. 
By \cite[Theorem~2.8]{Hu:52}, $H_c^i(G,W) = 0$ for each $i\geq 1$. 
In particular, $H_c^2(G,T) = 0$ and $H_c^1(G,V) = 0$.

The Lie group surjection $\pi|_\Gamma\colon\Gamma \rightarrow G$ defines a fiber bundle with fiber $T$. 
Since $T$ is a real vector space, thus solid (see \cite[Section~12.1]{Steenrod:99}), and $G$ is compact Hausdorff, the bundle has a continuous section by \cite[Theorem~12.2]{Steenrod:99}. 
Then by the above discussion, $H_c^2(G,T) = 0$ implies the existence of the desired continuous homomorphic section $\varphi\colon G\to \Gamma$. 

Next, one can check that the map $k\colon G\to V$ defined by $k(g) := \varphi(g)(0)$ is a continuous crossed homomorphism with respect to the action of $G$ on $V$. 
Since $H_c^1(G,V) = 0$, it follows that $k$ is principal, so it has the form $k(g)=g\cdot q - q$ for some $q\in V$. 
It follows that $\varphi(g)(x) = g\cdot x + k(g) = g\cdot (x+q)-q$ for each $g\in G$ and $x\in V$, so $p:=-q$ is a fixed point of $\varphi(G)$.
\end{proof}

The following is an alternative proof of \cref{prop.extension-splits} that avoids group cohomology, at least explicitly. 
(The map $b\colon G\rightarrow T^\perp$ constructed in the proof turns out to be a $1$-cocycle, so cohomology lurks beneath the surface.)

\begin{proof}[Prima facie cohomology-free proof]
For $c\in V$, let $t_c\in \E(V)$ denote translation by $c$. 
For each $h\in \Gamma$, we have a unique expression $h(x)= \pi(h)\cdot x+h(0)$ for $x\in V$, where $\pi(h)\in G\leq \O(V)$ and $h(0)\in V$. 
We claim that there exists a unique function $b\colon G \to T^\perp$ such that for each $A\in G$, it holds that
\[
\{h(0):h \in \pi^{-1}(A)\} 
= b(A)+T.
\]
To see this, note that the left-hand side is a nonempty union of $T$-cosets since $\pi(T\circ h) = \pi(h)$ and $T\circ h(0) = h(0)+T$ for each $h\in \Gamma$. 
It is a unique coset since if $\pi(h_1)=\pi(h_2)=A$, then $h_1\circ h_2^{-1} = t_{h_1(0)-h_2(0)}$, and so $h_1(0)\in h_2(0)+T$. 
This proves the claim.

Now consider the map $\varphi\colon G\to \Gamma$, given by $\varphi(A)(x) := Ax+b(A)$. 
Then $\pi\circ \varphi(A) = A$ for each $A\in G$, that is, $\varphi$ is a (set-map) section of $\pi$. 
Moreover, we have that
\[
\varphi(A)\circ \varphi(B)(x) 
= ABx + b(A)+A\cdot b(B) 
= ABx+b(AB) 
= \varphi(AB)(x),
\]
where the middle equality follows from the $A$-invariance of $T^\perp$ (noted at the beginning of the section) and the uniqueness of $b(AB)$ in $T^\perp$ as established in the aforementioned claim. 
So $b(A)+A\cdot b(B)=b(AB)$, i.e., $b$ is a crossed homomorphism, and $\varphi$ is a homomorphism. 

We are done once we show that $\varphi$ is smooth and that $\varphi(G)$ has a fixed point. 
Assuming smoothness, the latter follows by taking $v\in V$ any vector and defining
\[
p
:= \int_G \varphi(g)v d\mu_G(g),
\]
where the integral is with respect to the normalized (left-invariant) Haar measure $\mu_G$ on the compact Lie group $G$. 
This point is evidently fixed by every element of $\varphi(G)\leq \Gamma$ (in particular, $b(A) = p-Ap$ for each $A\in G$). 

We are left to prove smoothness. 
Since $H$ is a closed Lie subgroup of $\Gamma$, and $\pi|_\Gamma$ is a surjective Lie group homomorphism with kernel $H$, Noether's first isomorphism theorem for Lie groups entails that $\pi|_\Gamma$ is a submersion, so it possesses smooth local sections. 
Take an arbitrary $g\in G$, and let $\varphi_0\colon U\to \Gamma$ denote a smooth local section of $\pi|_\Gamma$ over an open neighborhood $U\subseteq G$ of $g$. 
Let $P\colon V\to T^\perp$ denote the linear orthogonal projection of $V$ onto $T^\perp$. 
Then the map $\Psi\colon \Gamma\to \Gamma$ given by $\Psi(h)(x):= \pi(h)\cdot x + P(h(0))$ is smooth and satisfies $\pi|_\Gamma\circ \Psi = \pi|_\Gamma$, as well as $\Psi(h)(0) = b(\pi(h))$ by the definition of $b$. 
This entails that $\varphi|_U = \Psi\circ \varphi_0$, and so $\varphi|_U$ is smooth. 
Overall, it follows that $\varphi$ is smooth, as desired.
\end{proof}

\section{Proof of Proposition~\ref{prop.so max filter}}
\label{app.calc proof}
Since $\SO(r)$ is compact, the function $M\mapsto \max_{Q\in \SO(r)}\operatorname{Tr}(QM)$ is continuous over $M \in \mathbb R^{r\times r}$. 
By continuity, we may pass to the open and dense subset where $M$ has distinct singular values. 
We proceed under this assumption for the rest of the proof.

Let $M = U_0\Sigma V_0$ be a singular value decomposition with $U_0,V_0\in \O(r)$. 
By the cyclic property of the trace, 
\[
\max_{Q\in \SO(r)}\operatorname{Tr}(QM)
= \max_{Q\in \SO(r)}\operatorname{Tr}(Q\Sigma_{\varepsilon}),
\]
where $\varepsilon = \mathbf{1}_{\{\det(M) < 0\}}$, $\Sigma_{0} = \Sigma$, and $\Sigma_{1} = J\Sigma = \Sigma J$, with $J$ denoting the identity matrix with its last diagonal entry negated.

If $\varepsilon = 0$, then the maximum is achieved at $Q = \Id_r$, since $|q_{ii}|\leq 1$ for all $Q\in \SO(r)$ and all $i\in [r]$. 
So we now assume $\varepsilon = 1$.

Let $U\in \arg\max_{Q\in \SO(r)}\operatorname{Tr}(Q\Sigma J)$. 
Then $U$ is a critical point of the map $Q\mapsto \operatorname{Tr}(Q\Sigma J)$, defined on $\SO(r)$. 
Taking directional derivatives along the tangent space
\[
T_{U}\SO(r) 
= \{A^TU:A^T = -A \in \mathbb R^{n\times n}\},
\]
we obtain $\operatorname{Tr}(A^TU\Sigma J) = 0$ for all skew-symmetric matrices $A \in \operatorname{Skew}^{r\times r}$. 
In other words, $U\Sigma J \in (\operatorname{Skew}^{r\times r})^\perp = \operatorname{Sym}^{r\times r}$, i.e., $U\Sigma J$ is symmetric.

This implies that both $U\Sigma J = J \Sigma U^T$ are valid singular value decompositions of the same matrix. 
Since $\Sigma$ has distinct diagonal entries, it follows that $U$ is diagonal.  
Considering we also have $U\in \SO(r)$, the diagonal entries of $U$ are necessarily $\pm 1$, with an even number of $-1$s. 
Thus,
\[
\Tr(U\Sigma J) 
= \max_{\substack{\varepsilon \in \{-1,1\}^r\\ \prod_{i=1}^r \varepsilon_i = -1}} \sum_{i=1}^r \varepsilon_i\sigma_i(M),
\]
which yields the desired formula.


