    \includegraphics[width=0.6\textwidth]{figures/tight_bounds.pdf} 
    \caption{Example that Theorems~\ref{theorem:l-best} and \ref{theorem:l-best-bipartite} are tight in terms of the number of fixed edges. Dashed edges have a weight of $1$ and solid edges have a weight of 0.}
