\end{figure}


\subsection{Proof of Theorem~\ref{theorem:l-best}}
\label{subsection:general_graphs}

The goal of this section is to prove Theorem~\ref{theorem:l-best}. We start by recalling some useful facts about the perfect matching polytope from Chapter~11 of the standard textbook by Korte and Vygen~\cite{korteCombinatorialOptimizationTheory2018}.
For this, it will be convenient to use the notation $\delta(v)$ to denote the set of edges incident to a vertex $v \in V$. Similarly, for all $A \subseteq V$, we use $\delta(A)$ to denote the set of edges with one endpoint in $A$ and the other in $V \setminus A$. Moreover, we denote by $\A$ the set of all odd-cardinality sets $A \subseteq V$, i.e.\ $\A \coloneqq \{ A \subseteq V : |A| \equiv_2 1\}$.

For the remainder of this section, let $G = (V, E)$ be a graph with edge-weights $w : E \rightarrow \Z$. 
The integer linear program 
\begin{align*}
    &\min \sum_{e \in E} x_e w(e) \\
    \text{ s.t.\ } &\sum_{e \in \delta(v)} x_e = 1 &\forall v \in V\\
    \text{ and } &x_e \in \{0, 1\} &\forall e \in E
\end{align*}
with variables $\{x_e \mid e \in E \}$ captures the problem of finding a minimum-weight perfect matching in $G$. Now consider the following LP relaxation
\begin{align*}
    &\min \sum_{e \in E} x_e w(e) \\
    \text{ s.t.\ } &\sum_{e \in \delta(v)} x_e = 1 &\forall v \in V\\
    &\sum_{e \in \delta(A)} x_e \geq 1 &\forall A \in \A \text{ with } |A| > 1 \\
     &x_e \geq 0 &\forall e \in E
\end{align*}
where additional odd-set constraints were added. By the famous result of Edmonds~\cite{edmonds1965maximum}, adding these additional odd-set constraints is necessary and sufficient to make the LP integral.
In other words, the basic feasible solutions to the LP are exactly the perfect matchings of $G$. The dual LP is now given by \begin{align*}
    &\max \sum_{A \in \A} z_A \\
    \text{ s.t.\ } &\sum_{A \in \A \, : \,  e \in \delta(A)} z_A \leq w(e) &\forall e \in E\\
     & z_A \geq 0 &\forall A \in \A \text{ with } |A| > 1\\
\end{align*}
where we introduced a variable $z_A$ for all $A \in \A$. By strong duality, the optimal value of the primal and the dual coincide.

\begin{definition}[Residual Graph]
    Let $G = (V, E)$ be a graph with edge-weights $w : E \rightarrow \Z$. 
    Let $z$ be an optimal solution to the dual LP associated with $G$.
    The graph $G_z \coloneqq (V, E_z)$ with 
    \[
        e \in E_z \iff w(e) = \sum_{A \in \A \, : \, e \in \delta(A)} z_A
    \]
    is called residual graph with respect to $z$.
\end{definition}
Unsurprisingly, it turns out that all minimum-weight perfect matchings are contained in the residual graph with respect to a given optimal solution $z$.
However, there might exist perfect matchings in the residual graph that are not minimum-weight perfect matchings of $G$. Hence, we need an extra condition to exactly characterize which perfect matchings in the residual graph are minimum-weight in $G$. 
Eppstein \cite{eppstein1995representing} shows such a result for bipartite graphs.
We present here the natural generalization to all graphs. This essentially follows from the complementary slackness theorem \cite{korteCombinatorialOptimizationTheory2018}. 


\begin{lemma}
\label{lemma:general_residual_graph}
    Let $G = (V, E)$ be a graph with edge-weights $w : E \rightarrow \Z$. 
    Let $z$ be an optimal solution to the dual LP associated with $G$, and let $G_z = (V, E_z)$ be its residual graph.
    A perfect matching $M$ of $G$ has minimum weight if and only if $M \subseteq E_z$ and $|M \cap \delta(A) | = 1$ holds for all $A \in \A$ with $z_A > 0$.
\end{lemma}
\begin{proof}
For the sake of clarity, we prove both directions individually.
\begin{itemize}
    \item[($\Rightarrow$)] We provide an indirect proof. Assume first that there exists $f \in M$ such that 
    \[
        \sum_{A \in \A \, : \,  f \in \delta(A)} z_A < w(f)
    \]
    holds and hence $f \notin E_z$. Observe that, by feasibility of $z$, we have 
    \[
        \sum_{A \in \A \, : \,  e \in \delta(A)} z_A \leq w(e)
    \]
    for all $e \in E$. Moreover, we have $z_A \geq 0$ for all $A \in \A$ with $|A| > 1$. Thus, we get 
    \[       
        w(M) - \sum_{A \in \A} z_A \geq \sum_{e \in M} \left( w(e) - \sum_{A \in \A \, : \, e \in \delta(A)} z_A \right) > 0
    \]
    since every set $A \in \A$ with $|A| = 1$ is associated with exactly one edge in $M$, and every other set $A \in \A$ (with $|A| > 1$) satisfies $z_A \geq 0$. In other words, we have 
    \[
        w(M) > \sum_{A \in \A} z_A
    \]
    which, by strong duality, implies that $M$ does not have minimum weight. Thus, assume now that $M \subseteq E_z$, but there exists $A \in \A$ such that $z_A > 0$ and $|M \cap A| > 1$. Again, we calculate 
    \[       
        w(M) - \sum_{A \in \A} z_A > \sum_{e \in M} \left( w(e) - \sum_{A \in \A \, : \, e \in \delta(A)} z_A \right) = 0
    \]
    where the strict inequality now comes from the fact that we needed to duplicate the variable $z_A$ in the first step. Again, by strong duality, we conclude that $M$ does not have minimum weight.

    \item[($\Leftarrow$)] Assume now that we have $M \subseteq E_z$ and $|M \cap A| = 1$ for all $A \in \A$ with $z_A > 0$. In this case, we get
    \[
        w(M) - \sum_{A \in \A} z_A = \sum_{e \in M} \left( w(e) - \sum_{A \in \A \, : \, e \in \delta(A)} z_A \right) = 0
    \]
    as every set $A \in \A$ with $z_A > 0$ is associated with exactly one edge in $M$. By strong duality, we can use the fact that $z$ is optimal to conclude that $M$ has minimum weight.
\end{itemize}
\end{proof}
Using Lemma~\ref{lemma:general_residual_graph}, we can prove the following lemma, which captures the special case $\ell = 2$ of Theorem~\ref{theorem:l-best}.

\begin{lemma}
\label{lemma:fixing_two_edges}
    Let $G = (V, E)$ be a graph with edge-weights $w : E \rightarrow \Z$. Assume that $G$ contains a $2$nd-smallest perfect matching $M$. Then there exist edges $e, f \in E$ such that 
    \begin{displaymath}
        w(M) =  \min\limits_{M' \in \PMs_G \, : \, \{e, f\} \subseteq M'} w(M').
    \end{displaymath}
\end{lemma}
\begin{proof}
    Let $z$ be a fixed optimal dual solution. Since $M$ is not a minimum-weight perfect matching, by Lemma~\ref{lemma:general_residual_graph}, there are two cases: Either there exists an edge $e \in M$ with $e \not\in E_z$ (in this case, take as $f$ any edge from $M$ and we are done), or there exists some odd set $A \in \mathcal{A}$ with $z_A > 0$, distinct edges $e, f \in M$, and both $e,f \in \delta(A)$. In the latter case, by the same lemma, no minimum-weight perfect matching contains both $e$ and $f$. Hence, we get
    \begin{displaymath}
        \text{OPT} < \min\limits_{M' \in \PMs_G \, : \, \{e, f\} \subseteq M'} w(M') = w(M)
    \end{displaymath}
    where OPT denotes the weight of a minimum-weight perfect matching in $G$.
\end{proof}
It remains to use Lemma~\ref{lemma:fixing_two_edges} repeatedly to obtain Theorem~\ref{theorem:l-best}.

\begin{proof}[Proof of Theorem~\ref{theorem:l-best}]
    We proceed by induction over $\ell$. The case $\ell = 1$ is trivial and Lemma~\ref{lemma:fixing_two_edges} already proves the case $\ell = 2$. Thus, let now $\ell \geq 3$ be arbitrary, and assume as induction hypothesis that the statement holds for all $\ell' < \ell$. Recall that $M$ is an $\ell$-th smallest perfect matching. We want to prove that there is a subset $F \subseteq E$ of edges of size at most $2(\ell - 1)$ such that 
    \begin{displaymath}
        w(M) =  \min\limits_{M' \in \PMs_G \, : \, F \subseteq M'} w(M').
    \end{displaymath}
    Let $M_{\min} $ be an arbitrary minimum-weight perfect matching of $G$. From the argument in Lemma~\ref{lemma:fixing_two_edges}, we know that there exist edges $e, f \in M$ such that 
    \begin{displaymath}
        w(M_{\min}) < \min\limits_{M' \in \PMs_G \, : \, \{e, f\} \subseteq M'} w(M') \leq w(M).
    \end{displaymath}
    Consider now the graph $G'$ obtained from $G$ by removing $e$ and $f$, their incident vertices, and all their incident edges. 
    Observe that $M \setminus \{e, f\}$ is an $\ell'$-th smallest perfect matching in $G'$ for some $\ell' < \ell$. By the induction hypothesis, this means that there is a set $F' \subseteq E \setminus \{e, f\}$ of size at most $2(\ell' - 1)$ such that 
    \begin{displaymath}
        w(M \setminus \{e, f\}) =  \min\limits_{M' \in \PMs_{G'} \, : \, F' \subseteq M'} w(M').
    \end{displaymath}
    Define $F \coloneqq F' \cup \{e, f\}$ and observe that 
    \begin{displaymath}
        w(M) = w(\{e, f\}) + \min\limits_{M' \in \PMs_{G'} \, : \, F' \subseteq M'} w(M') = \min\limits_{M' \in \PMs_{G} \, : \, F \subseteq M'} w(M')
    \end{displaymath}
    and that the set $F$ has size at most $2(\ell - 1)$.
\end{proof}

\section{Related Cycle Problems}
\label{sec:related_cycle_problems}

In this section, we present the ideas behind Theorem~\ref{theorem:cycles_equiv_matchings} below. The full proof of Theorem~\ref{theorem:cycles_equiv_matchings} and the involved lemmata can be found in Appendix~\ref{appendix:cycles_equiv_matchings}. % TODO: of the full version

\begin{restatable}[\EWPM\ $\equiv_p$ \ECS\ \& \BCPM\ $\equiv_p$ \SOC]{theorem}{theoremcyclesequivmatchings}
\label{theorem:cycles_equiv_matchings}
    \EWPM\ is polynomial-time equivalent to \ECS. 
    \BCPM\ is polynomial-time equivalent to \SOC. 
\end{restatable}

As we will see, both equivalences use the same base construction and only differ in some minor configurations. The encoding of the weights is preserved in all reductions and hence \ECS\ is equivalent to \EM\ for weights encoded in unary, and \NP-complete for weights encoded in binary. 



\paragraph*{From Matchings to Cycles}

We start with the direction of \EWPM\ $\leq_p$ \ECS\ and \BCPM\ $\leq_p$ {\SOC}, i.e.\ we give reductions starting from matching-type problems going to cycle-type problems.
We use roughly the same construction for both reductions. We remark that in the case of matching-type problems in \emph{bipartite graphs}, a similar reduction already exists, and it goes to cycle-type problems in \emph{directed} graphs \cite{papadimitriouComplexityRestrictedSpanning1982, elmaaloulyExactMatchingCorrect2023}. 
In these existing reductions,
the bipartition of the graph was used to define some edge orientation, which in turn ensured that cycles in the new graph would correspond to $M$-alternating cycles (where $M$ is an arbitrary minimum-weight perfect matching) in the old graph (see \cite{papadimitriouComplexityRestrictedSpanning1982} and \cite{elmaaloulyExactMatchingCorrect2023} for more details). 
The same trick does not apply in general graphs, which is why we need to reduce to undirected cycle problems instead. In particular, the new trick will be to manipulate
the weights such that the weight of any non-alternating cycle exceeds some threshold. 
The following lemma captures the key properties of this construction. 

\begin{restatable}{lemma}{lemmamatchingstocycles}
\label{lemma:matchings_to_cycles}
    Let $G = (V, E)$ be a graph with non-negative edge-weights 
    $w : E \rightarrow \N$ that admits a minimum-weight perfect matching $M$. 
    Consider the new edge-weights $w' : E \rightarrow \Z$ defined as
    \[
        w'(e) \coloneqq \begin{cases}
                            - w(e) - r - 1, & e \in M \\
                            w(e) + r + 1, & e \notin M
                        \end{cases}  
    \]
    for some integer $r \geq w(M)$. 
    Then every cycle $C$ with $w'(C) \leq r - w(M)$ is $M$-alternating
    and $w'$ is conservative.
\end{restatable}

Using Lemma~\ref{lemma:matchings_to_cycles}, we can now informally describe the reductions: Assume first that we are given an \EWPM-instance $I$ consisting of $G = (V, E)$, $w : E \rightarrow \Z$, and $k \in \Z$. 
Without loss of 
generality, we can assume that the weights $w$ are non-negative. We first compute 
a minimum-weight perfect matching $M$ in $G$. Note that if no such 
matching exists or its weight exceeds $k$, $I$ is a NO-instance and we can produce a 
simple NO-instance of \ECS. Otherwise, we construct $w'$ as in 
Lemma~\ref{lemma:matchings_to_cycles} (setting $r = k$) and return the \ECS-instance 
$I'$ consisting of $G$, $w'$ and $k' \coloneqq k - w(M)$. By Lemma~\ref{lemma:matchings_to_cycles}, $w'$ is 
conservative. Setting $r = k$ crucially guarantees that solutions to the \ECS-instance can be translated back to solutions to the \EWPM-instance $I$. 

The only difference in the reduction from \BCPM\ to \SOC\ is that we need to manually check the parity of $M$ and use a trivial construction if it already has correct parity.

\paragraph*{From Cycles to Matchings}
We will now turn our attention to the reverse reductions \ECS\ $\leq_p$ \EWPM\ and \SOC\ $\leq_p$ \BCPM. The general idea is again inspired by the existing reductions between bipartite matching and directed cycle problems (\cite{papadimitriouComplexityRestrictedSpanning1982, elmaaloulyExactMatchingCorrect2023}):
We want to 
duplicate every vertex and add edges between duplicates in order to ensure the existence of a canonical perfect matching $M$.
Additionally, we want to ensure that the existence of any other perfect matching $M'$ in the new graph implies existence of cycles in the original 
graph by looking at the symmetric difference $M \Delta M'$. Unfortunately, since our original graph
is not directed anymore, we cannot use the ideas from~\cite{papadimitriouComplexityRestrictedSpanning1982, elmaaloulyExactMatchingCorrect2023} to achieve this. Instead, we use the construction described in Lemma~\ref{lemma:cycles_to_matchings} and Figure~\ref{figure:cycle_to_matching}. 

\begin{figure}[htb]
    \centering
    \includegraphics[width=0.7\textwidth]{figures/cycle_to_matching} 
    \caption{This figure shows the construction from Lemma~\ref{lemma:cycles_to_matchings}
    for a single edge $e = \{u, v\}$. Solid edges indicate the perfect matching 
    $M$ from Lemma~\ref{lemma:cycles_to_matchings}. The edge $\{e_{uv}, e_{vu}\}$
    receives the weight of $e$ while all other edges get a weight of zero.}
    \label{figure:cycle_to_matching}
\end{figure}

\begin{restatable}{lemma}{lemmacyclestomatchings}
\label{lemma:cycles_to_matchings}
    Let $G = (V, E)$ be a graph with conservative edge-weights $w : E \rightarrow \Z$.
    We define
    \begin{align*}
        V' \coloneqq &\{v_1, v_2 \, | \, v \in V\} \cup \{e_u, e_{uv}, e_{vu}, e_v \, | \, e = \{u, v\} \in E\} \\
        E' \coloneqq &\{ \{v_1, v_2\} \, | \, v \in V\} \\
        &\cup \{\{u_1, e_u\}, \{u_2, e_u\}, \{e_u, e_{uv}\},  \{e_{uv}, e_{vu}\}, \\ 
        &\qquad \{e_{vu}, e_v\}, \{e_v, v_1\}, \{e_v, v_2\} \, | \, e = \{u, v\} \in E\} \\
        w' \coloneqq &e' \in E' \mapsto \begin{cases}
            w(e) & \text{if } e' = \{e_{uv}, e_{vu}\} \text{ for some } e = \{u, v\} \in E \\
            0 & \text{otherwise}
            \end{cases}  \\
        M \coloneqq &\{ \{v_1, v_2\} \, | \, v \in V\} \cup \{\{e_u, e_{uv}\}, \{e_{vu}, e_v\} \, | \, e = \{u, v\} \in E\}
    \end{align*}
    and consider the graph $G' = (V', E')$ with edge-weights $w'$ and perfect matching 
    $M$. Then there exist vertex-disjoint cycles $C_1, \dots, C_p$ of total weight 
    $k$ (w.r.t.\ $w$) in $G$ if and only if there exist vertex-disjoint $M$-alternating 
    cycles $C'_1, \dots, C'_p$ of total weight $k$ (w.r.t.\ $w'$) in $G'$.
\end{restatable}

Let us now briefly explain how this yields the desired reductions. Assume that we are given an \ECS-instance $I$ consisting of $G = (V, E)$, $w : E \rightarrow \Z$, and $k \in \Z$. We use the construction from Lemma~\ref{lemma:cycles_to_matchings} to obtain a graph $G'$ with edge-weights $w'$ and return the \EWPM-instance $I'$ consisting of $G' = (V', E')$, $w'$, and $k' \coloneqq k$. The symmetric difference $M \Delta M'$ of $M$ with any perfect matching $M'$ in $G'$ yields a set of vertex disjoint cycles that can be translated back to $G$ using Lemma~\ref{lemma:cycles_to_matchings}. The reduction from \SOC\ to \BCPM\ uses the same construction, but we need to additionally observe that we can get a single odd-weight cycle that translates through Lemma~\ref{lemma:cycles_to_matchings}.


\section{Final Remarks}
\label{sec:final_remarks}

In Section~3, we proved that we can deterministically find an $\ell$-th smallest perfect matching in time $n^{\bigO(\ell)}$. This also allows us to solve certain instances of \EWPM\ efficiently: Assume e.g.\ that we are given an \EWPM\ instance with $k$ such that $k_1 < k_2 <  \dots < k_\ell = k$ are all the distinct weights up to $k$ that perfect matchings in $G$ can take. Then our algorithm can find a perfect matching of weight $k = k_\ell$ efficiently if $\ell$ is small. 

Clearly, this also works in the case of \BCPM. Moreover, our reductions from Section~\ref{sec:related_cycle_problems} also allow us to get similar guarantees for \ECS\ and \SOC, respectively. Indeed, assume that we are given an instance of \ECS\ or \SOC\ with $k$ such that $k_1 < k_2 <  \dots < k_\ell = k$ are all the distinct weights up to $k$ that cycle sums in $G$ can take. We apply our reduction to build a corresponding \EWPM\ or \BCPM\ instance. By Lemma~\ref{lemma:cycles_to_matchings}, our reductions have a one-to-one correspondence between $\ell$-th smallest perfect matchings and $\ell$-th smallest cycle sums. Hence, the parameterized runtime guarantees of the \lBPM-algorithm carry through the reduction. 
\begin{corollary}
\label{corollary:parametrized_algo_+_reduction}
    \BCPM\ can be solved in time $n^{\bigO(\ell)}$ if $k_1 < k_2 <  \dots < k_\ell = k$ are all the distinct weights up to $k$ that perfect matchings in $G$ can take. \ECS\ and \SOC\ can be solved in time $n^{\bigO(\ell)}$ if $k_1 < k_2 <  \dots < k_\ell = k$ are all the distinct weights up to $k$ that cycle sums in $G$ can take.
\end{corollary}

