Here we calculate the effective Hamiltonian by considering all the $J_1$ and $J_2$ coupling as the perturbative terms, and the rest of the terms as the unperturbed part. Using the third-order perturbative calculation, the effective Hamiltonian is given by,
\begin{eqnarray}
        \hat{H}_{eff}^{(3)} &=& \frac{-J_1}{J_z}\left(-2J_2+\frac{J_1^2}{J_z}+\frac{4J_2^2}{J_z}\right)\sum_{i=1}^{L-3}(\hat{B}_i^\dagger\hat{B}_{i+1}+\text{H.c.}) \nonumber\\
        &+& \frac{J_2^3}{J_z^2}\sum_{i=1}^{L-4}(\hat{B}_i^\dagger\hat{B}_{i+2}+\text{H.c.})\nonumber\\
        &+& \left(\frac{2J_1^2}{J_z}+\frac{4J_2^2}{J_z}-\frac{6J_1^2J_2}{J_z^2}\right)\sum_{i=1}^{L-2}\hat{B}_i^\dagger\hat{B}_{i},
        \label{eq:3part_eff_ham}
\end{eqnarray}
where $B_i=\hat{\sigma}_{i-1}^-\hat{\sigma}_i^-\hat{\sigma}_{i+1}^-$. The bound state exhibits motion with an effective coupling strength given by $-\frac{J1}{J_z}(-2J_2+\frac{J_1^2}{J_z})$ at the leading order in $J_1$ and $J_2$. If the parameters are tuned such that $-2J_2+\frac{J_1^2}{J_z}=0$, the bound state is expected to undergo a critical slowdown. This suggests that the effective Hamiltonian agrees well with our numerical results shown in Fig.~\ref{fig:den_evo_3_part}.


\section{Perturbative calculation}
In the main text, we show that in the limit $J_z\gg J_1,~J_2$, two spin excitation forms a bound pair and behave as a single composite particle and move in the lattice with a reduced effective mass. In this limit, we can use the perturbative approach following the prescription given in Refs.~\cite{Takahashi_1977,Cai2021}, to study the behavior of the composite particle. By treating $J_z$ as the unperturbed part and the rest of the terms perturbatively we can  write the Hamiltonian as,
\begin{equation}
    \hat{H} = \hat{H}_0 + \hat{H}_1,
\end{equation}
where
\begin{equation}
    \hat{H}_0 = \frac{J_z}{4}\sum_{j=0}^{L-2} (1+\hat{\sigma}_j^z)(1+\hat{\sigma}_{j+1}^z)
\end{equation}
\begin{equation}
    \hat{H}_1 = -\frac{J_{1}}{2}\sum_{\langle i, j\rangle} (\hat{\sigma}_{i}^x \hat{\sigma}_{j}^x+\hat{\sigma}_{i}^y \hat{\sigma}_{j}^y)
    -\frac{J_{2}}{2}\sum_{\langle\langle i, j\rangle\rangle} (\hat{\sigma}_{i}^x \hat{\sigma}_{j}^x+\hat{\sigma}_{i}^y \hat{\sigma}_{j}^y)
    \label{eq:pert_ham}
\end{equation}
We consider two excitations in the system for which the unperturbed Hamiltonian has two possible energies. When two excitations stay at adjacent sites, the system has $L-1$ fold degeneracy with eigenenergy $E_0 = J_z$, and we denote the corresponding eigenstates by $\{|E_0^{(j)}\rangle = |j, j+1\rangle\}$. The other possible eigenenrgy is $E_1=0$, for which the eigenstate is $\{ |E_1^{(j_1j_2)}\rangle = |j_1, j_2\rangle\}$, where $j_1\neq j_2\pm1$.

The projection operator to the bound state subspace can be written as,
\begin{equation}
    P_0 = \sum_j |E_0^{(j)}\rangle\langle E_0^{(j)}|,
    \label{eq:proj0}
\end{equation}
and the projection operator to the orthogonal subspace of $P_0$ is
\begin{equation}
    P_1 = \sum_{j_1,J_2}\frac{1}{E_0-E_1}|E_1^{(j_1j_2)}\rangle\langle E_1^{(j_1j_2)}|.
    \label{eq:proj1}
\end{equation}
The second-order effective Hamiltonian can be expressed as 
\begin{equation}
    \hat{H}_{eff}^{(2)} = E_0P_0 + P_0\hat{H}_1P_0+P_0\hat{H}_1P_1\hat{H}_1P_0.
    \label{eq:pur_exp}
\end{equation}
Substituting Eq.~\ref{eq:pert_ham}, ~\ref{eq:proj0}, and \ref{eq:proj1} into Eq.~\ref{eq:pur_exp} we get the effective Hamiltonian as
\begin{align}
        &\hat{H}_{eff}^{(2)} = \left(-J_2+\frac{J_1^2}{J_z}\right)\sum_{i=0}^{L-2}(\hat{B}_i^\dagger\hat{B}_{i+1}+\text{H.c.}) \nonumber\\
        &+ \frac{J_2^2}{J_z}\sum_{i=0}^{L-3}(\hat{B}_i^\dagger\hat{B}_{i+2}+\text{H.c.})+\left(\frac{2J_1^2}{J_z}+\frac{2J_2^2}{J_z}\right)\sum_{i=0}^{L-2}\hat{B}_i^\dagger\hat{B}_{i},   
\end{align}
where $B_i=\hat{\sigma}_i^-\hat{\sigma}_{i+1}^-$. This effective Hamiltonian agrees well with our numerical results for the dynamics with two excitations as the initial state.

Now, if we consider three excitations, then three possible energies corresponding to the unperturbed Hamiltonian are

\begin{enumerate}
    \item $E_0 = 2J_z$, possible only when three excitations reside at adjacent sites, and therefore correspond to the eigenstate $|E_0^{(j)}\rangle=|j,~j+1,~j+2\rangle$.
    \item $E_1 = J_z$, only two excitations at adjacent sites are possible. Therefore, corresponding states are $|E_1^{(j_1j_2)}\rangle=|j_1,~j_1+1,~j_2\rangle$, where $j_2\neq j_1-1$, $j_2\neq j_1+2$.
    \item $E_2=0$, existaions at NN sites are prohabited. Therefore the eigenstates are $|E_2^{(j_1j_2j_3)}\rangle = |j_1, j_2, j_3\rangle$, where $j_1 \neq j_2\pm 1$, $j_1\neq j_3\pm1$ and $j_3\neq j_2\pm1$.
\end{enumerate}


The projection operator to the three-excitation bound state subspace,
\begin{equation}
    P_0 = \sum_j |E_0^{(j)}\rangle\langle E_0^{(j)}|,
    \label{eq:3_part_proj0}
\end{equation}
and the projection operator to the orthogonal subspace
\begin{align}
    P_1 &= \sum_{j_1,J_2}\frac{1}{E_0-E_1}|E_1^{(j_1j_2)}\rangle\langle E_1^{(j_1j_2)}| \nonumber\\
    &+\sum_{j_1,J_2,j_3}\frac{1}{E_0-E_2}|E_2^{(j_1j_2j_3)}\rangle\langle E_2^{(j_1j_2j_3)}|.
    \label{eq:3_part_proj1}
\end{align}
The third-order effective Hamiltonian in terms of projection operators and perturbative Hamiltonian is given by,
\begin{align}
    \hat{H}_{eff}^{(3)} &= E_0P_0 + P_0\hat{H}_1P_0+P_0\hat{H}_1P_1\hat{H}_1P_0 \nonumber\\
    &+P_0\hat{H}_1P_1\hat{H}P_1\hat{H}_1P_0 \nonumber\\
    &-\frac{1}{2}(P_0\hat{H}_1P_0\hat{H}_1P_1^2\hat{H}_1P_0+P_0\hat{H}_1P_1^2\hat{H}_1P_0\hat{H}_1P_0).
    \label{eq:3_part_pur_exp}
\end{align}
Substituting Eq.~\ref{eq:pert_ham}, ~\ref{eq:3_part_proj0} and \ref{eq:3_part_proj1} into Eq.~\ref{eq:3_part_pur_exp} we get the following effective Hamiltonian
\begin{eqnarray}
        \hat{H}_{eff}^{(3)} &=& \frac{-J_1}{J_z}\left(-2J_2+\frac{J_1^2}{J_z}+\frac{4J_2^2}{J_z}\right)\sum_{i=1}^{L-3}(\hat{B}_i^\dagger\hat{B}_{i+1}+\text{H.c.}) \nonumber\\
        &+& \frac{J_2^3}{J_z^2}\sum_{i=1}^{L-4}(\hat{B}_i^\dagger\hat{B}_{i+2}+\text{H.c.})\nonumber\\
        &+& \left(\frac{2J_1^2}{J_z}+\frac{4J_2^2}{J_z}-\frac{6J_1^2J_2}{J_z^2}\right)\sum_{i=1}^{L-2}\hat{B}_i^\dagger\hat{B}_{i},
        \label{eq:3part_eff_ham}
\end{eqnarray}
where $B_i=\hat{\sigma}_{i-1}^-\hat{\sigma}_i^-\hat{\sigma}_{i+1}^-$. This effective Hamiltonian shows a good agreement with our numerical results.

