\section{Kinematics of Point Particles \label{SecKinPunkt}}
%------------------------------------------------------------------------------
A relativistic description of the motion of point particles requires that from the knowledge of the kinematic quantities in one inertial system, their values can be calculated in other inertial systems. It is therefore useful to formulate kinematic quantities as scalars, vectors and tensors. This allows for a simple transformation of these quantities between the reference systems and an easy check of whether the principle of relativity is fulfilled, i.e., whether the same physical laws apply in all reference systems.

The transformation
\begin{eqnarray}\label{ViererTrafo}
x^{\mu\prime}:={\Lambda^{\mu\prime}}_\nu x^\nu\quad
\Leftrightarrow\quad x^\prime:=\Lambda x,
\end{eqnarray}
of the coordinates $x^\mu\ist{DefRaumZeit}(ct,\vec x)$ defines a Lorentz transformation from the laboratory system $\Sigma$ to the moving system $\Sigma^\prime$. The condition
\begin{eqnarray}\label{DefLambdaTrafo}
\Lambda^T\eta\Lambda\muss\eta\quad\textrm{with}\quad
\eta:=\mathrm{diag}(1,-1,-1,-1)
\end{eqnarray}
on the Lorentz transformations $\Lambda$ guarantees the invariance
\begin{eqnarray}
x^\mu x_\mu\iist{ViererTrafo}{DefLambdaTrafo}x^{\mu\prime}x_{\mu\prime}\quad\textrm{with}\quad x_\mu=\eta_{\mu\nu}x^\nu
\end{eqnarray}
and the invariance of the proper time $\tau$ by the differential
\begin{eqnarray}\label{tauDiff}
\mathrm d\tau:=
\frac{1}{c}\sqrt{\mathrm dx_\mu\mathrm dx^\mu}\ist{DefRaumZeit}
\mathrm dt\sqrt{1-\Big(\frac{\mathrm d\vec x}{\mathrm dt}\Big)^2}.
\end{eqnarray}
The gradients transform ``contragrediently'' with the matrix $\bar\Lambda$
\begin{eqnarray}
\partial_{\mu\prime}\ist{ViererTrafo}\bar\Lambda_{\mu\prime}^{\ \ \nu}\partial_\nu
\quad\Leftrightarrow\quad\partial^\prime=\bar\Lambda\partial
\quad\textrm{with}\quad\bar\Lambda:=\eta\Lambda\eta
\ist{DefLambdaTrafo}{\Lambda^T}^{-1}.
\end{eqnarray}

Using the non-relativistic definitions of velocity and acceleration
\begin{eqnarray}\label{DreiGroess}
\vec v:=\frac{\mathrm d\vec x}{\mathrm dt},\quad
\vec a:=\frac{\mathrm d\vec v}{\mathrm dt},
\end{eqnarray}
and the abbreviations
\begin{eqnarray}\label{betagammatau}
\vec\beta:=\frac{\vec v}{c_0},\quad
\gamma:=\frac{1}{\sqrt{1-\beta^2}},\quad
\mathrm dt\iist{tauDiff}{DreiGroess}\gamma\,\mathrm d\tau,
\end{eqnarray}
we obtain the four-velocity 
\begin{eqnarray}\label{UVonbeta}
u:=(u^0,\vec u):=\frac{\mathrm dx}{\mathrm d\tau}=
\frac{\mathrm dx}{\mathrm dt}\frac{\mathrm dt}{\mathrm d\tau}
\iist{DefRaumZeit}{betagammatau}\gamma(c_0,\vec v)
\ist{betagammatau}c_0\gamma(1,\vec\beta),
\end{eqnarray}
and the four-acceleration, \footnote{
\begin{eqnarray}\label{gammaAbl}
\frac{\mathrm d\gamma}{\mathrm dv_i}\ist{betagammatau}
\frac{1}{c_0}\frac{\mathrm d\gamma}{\mathrm d\beta_i},\quad
\frac{\mathrm d\gamma}{\mathrm d\beta_i}
\ist{betagammatau}\frac{\beta_i}{(1-\beta^2)^{3/2}}=\beta_i\gamma^3,
\end{eqnarray}}
\begin{eqnarray}\begin{aligned}\label{bVona}
b&=(b^0,\vec b):=\frac{\mathrm du}{\mathrm d\tau}\ist{betagammatau}
\frac{\mathrm du}{\mathrm dv_i}\frac{\mathrm dv_i}{\mathrm dt}\gamma
\iist{UVonbeta}{DreiGroess}\frac{\mathrm d}{\mathrm dv_i}
\left[\gamma(c_0,\vec v)\right]a_i\gamma=\\
&\ist{gammaAbl}\left(\gamma^4\vec a
\vec\beta,\gamma^2\vec a+\gamma^4(\vec a\vec\beta)\vec\beta\right),
\end{aligned}\end{eqnarray}
which for rectilinear motion is simplified to the space-like four-vector
\begin{eqnarray}\label{bgerade}b\iist{bVona}{betagammatau}
\gamma^4a\left(\beta,\vec1\right)
\end{eqnarray}

Including the invariant rest mass $m_0$, we define the four-vectors for the momentum $p^\mu$ and the force vector $K^\mu$
\begin{eqnarray}\label{pUndK}
p:=(\frac{E}{c_0},\vec p):=m_0u,\quad
K:=(K^0,\vec K):=\frac{\mathrm dp}{\mathrm d\tau}\ist{bVona}m_0b.
\end{eqnarray}
The following applies to the four-momentum
\begin{eqnarray}\label{pvonbeta}
&&p\ist{pUndK}m_0u\ist{UVonbeta}\gamma m_0(c_0,\vec v)=:m(\beta)(c_0,\vec v)
\end{eqnarray}
and the four-force
\begin{eqnarray}\label{defK}
K\ist{pUndK}m_0b\ist{bVona}m_0\left(\gamma^4\vec a
\vec\beta,\gamma^2\vec a+\gamma^4(\vec a\vec\beta)\vec\beta\right).
\end{eqnarray}

It is noteworthy that for the derivation of the relations of the relativistic to the non-relativistic quantities of particle kinematics, in addition to the four-vector (\ref{DefRaumZeit}) of the coordinates $x^\mu$, we have also identified the four-momentum $p^\mu$ directly with the non-relativistic quantities, energy $E$ and momentum $\vec p$, see Equations~(\ref{pVierer}) and (\ref{pUndK}). We will elaborate on this after Equation~(\ref{minimalerWeg}).

From expression~(\ref{pvonbeta}) for the four-momentum $p$, it follows that the mass contributing to energy and momentum increases proportionally to $\gamma$,
\begin{eqnarray}\label{pundgamma}
E\iist{pUndK}{pvonbeta}\gamma m_0c_0^2,\quad
\vec p\iist{pUndK}{pvonbeta}\gamma m_0\vec v.
\end{eqnarray}

Since we retain the definitions for the power $P$ and the force $\vec F$
\begin{eqnarray}\label{FundP}
P:=\frac{\mathrm dE}{\mathrm dt},\quad
\vec F:=\frac{\mathrm d\vec p}{\mathrm dt}
\end{eqnarray}
known from non-relativistic mechanics, it follows that 
\begin{eqnarray}\label{3und4}
K\ist{pUndK}m_0b\ist{bVona}m_0\left(\gamma^4\vec a
\vec\beta,\gamma^2\vec a+\gamma^4(\vec a\vec\beta)\vec\beta\right)
\iist{pUndK}{betagammatau}\gamma
\left(\frac{1}{c_0}P,\vec F\right),
\end{eqnarray}
i.e.,
\begin{eqnarray}\label{Funda}
\vec F\ist{3und4}m_0[\gamma\vec a+\gamma^3(\vec a\vec\beta)\vec\beta]
\quad\textrm{und}\quad P=\vec v\vec F.
\end{eqnarray}
{For} rectilinear motion, it follows that the inertial mass that must be accelerated increases with $\gamma^3$
\begin{eqnarray}\label{m0mita}
\vec F\ist{Funda}\gamma^3m_0\vec a.
\end{eqnarray}

We will now calculate invariants and draw conclusions from them. Vectors $x^\mu$ are denoted by
\begin{eqnarray}
x^\mu x_\mu=\begin{cases}\rho^2>0\;&\textrm{timelike vectors},\\
0\;&\textrm{lightlike vectors},\\
-\rho^2<0\;&\textrm{spacelike vectors}.
\end{cases}
\end{eqnarray}
$x^\mu x_\mu$ is a Lorentz invariant but not an invariant of motion. In contrast, however,
\begin{eqnarray}
&&u_\mu u^\mu\ist{UVonbeta}c_0^2\gamma^2(1-\vec\beta^2)
\ist{betagammatau}c_0^2\label{uuInv}\\
&&p_\mu p^\mu\iist{pUndK}{uuInv}m_0^2c_0^2\label{ppInv}
\end{eqnarray}
are also invariants of motion. From the vanishing of the differential of
these invariants follows the relativistic energy conservation law~\footnote{
\begin{eqnarray}\label{ortVA}
u^0\mathrm du^0\ist{uuInv}\vec u\,\mathrm d\vec u\quad\gleichw{UVonbeta}\quad
c_0^2\mathrm d\gamma=\vec v\,\mathrm d(\gamma\vec v)\ist{DreiGroess}
\frac{\mathrm d\vec x}{\mathrm dt}\,\mathrm d(\gamma\vec v)
=\mathrm d\vec x\,\frac{\mathrm d(\gamma\vec v)}{\mathrm dt}
\end{eqnarray}}
\begin{eqnarray}\label{EnErh0}
\mathrm dE\ist{pundgamma}\mathrm d\gamma m_0c_0^2\ist{ortVA}
\mathrm d\vec x\,\frac{\mathrm d(\gamma m_0\vec v)}{\mathrm dt}\ist{pvonbeta}
\mathrm d\vec x\,\frac{\mathrm d\vec p}{\mathrm dt}\ist{FundP}
\vec F\mathrm d\vec x,
\end{eqnarray}
which expresses that mechanical work $\int\vec F\mathrm d\vec x$ contributes to the energy. If Equation~(\ref{EnErh0}) is divided by $\mathrm dt$, it turns out that energy conservation was already included in Equation~(\ref{Funda})
\begin{eqnarray}\label{MechLeist}
P\ist{FundP}\frac{\mathrm dE}{\mathrm dt}\iist{EnErh0}{DreiGroess}\vec v\vec F.
\end{eqnarray}

The two Equations (\ref{pUndK}) and (\ref{ppInv})  show that the energy of a
moving mass, in addition to the kinetic energy and its relativistic
corrections, also contains an additional contribution, the rest energy $m_0c_0^2$
\begin{eqnarray}\begin{aligned}\label{relEnergieBez}
&(p^0)^2-\vec p^{\,2}\ist{ppInv}m_0^2c_0^2\quad\Leftrightarrow\quad
E^2\ist{pUndK}m_0^2c_0^4+\vec p^{\,2}c_0^2,\\
&E\ist{pundgamma}\gamma m_0c_0^2\ist{betagammatau}\frac{1}{\sqrt{1-\beta^2}}m_0c_0^2
\approx m_0c_0^2+\frac{m_0\vec v^{\,2}}{2}+\mathcal O(\beta^4).
\end{aligned}\end{eqnarray}

Interestingly, by transferring the law of conservation of energy from classical mechanics to relativity theory, it has emerged naturally that for the two canonically conjugated quantities $x$ and $p$, the spatial components coincide with the three-quantities. However, for their derivatives $u$, $b$ and $K$, we had to introduce separate letters to prevent confusion between their spatial components and the non-relativistic quantities $\vec v$, $\vec a$ and $\vec F$.

We will now show that it is sufficient to define the relationship~(\ref{DefRaumZeit}) between three- and four-quantities. The relationship~(\ref{pVierer}) between the momenta follows from a suitably chosen Lagrange density and the energy--momentum tensor derived from it, see Equation~(\ref{ImpulsAbgeleitet}).

Free particles move on geodesics, on extremal paths between events. It is therefore obvious that paths with extreme (minimal) proper time
\begin{equation}\label{minimalerWeg}
\int_0^1\frac{\mathrm d\tau(\lambda)}{\mathrm d\lambda}\,\mathrm d\lambda
=\int_{\tau_1}^{\tau_2}\mathrm d\tau
\end{equation}
are proportional to a suitable action function for free particles. The proper time decreases as the speed of the particles increases. The proportionality factor between extreme time and extreme action has the dimension of energy, obviously the rest energy of the free particle
\begin{equation}\label{freieWirkung}
S:=-m_0c_0^2\int_{\tau_1}^{\tau_2}\mathrm d\tau\ist{minimalerWeg}
-m_0c_0^2\int_{t_1}^{t_2}\frac{\mathrm d\tau(t)}{\mathrm dt}\,\mathrm dt
\end{equation}
{The} sign was chosen negative so that the Lagrange function
\begin{equation}\label{freieLagrange}
L:=-m_0c_0^2\frac{\mathrm d\tau(t)}{\mathrm dt}
\ist{betagammatau}-\frac{m_0c_0^2}{\gamma}
\ist{betagammatau}-m_0c_0^2\sqrt{1-\beta^2}
=-m_0\gamma c_0^2(1-\beta^2)
\end{equation}
increases with increasing momentum of the particle. The components of the canonically conjugated momentum follow in the Lagrange description to
\begin{equation}\label{freieImpulse}
p_i:=\frac{\partial L}{\partial v_i}\ist{freieLagrange}m_0\gamma\,v_i.
\end{equation}
{The} Hamiltonian results in
\begin{equation}\label{freieHamilton}
H:=\vec p\,\vec v-L\iist{freieImpulse}{freieLagrange}m_0\gamma c_0^2.
\end{equation}
{For} point-like electrons with the world line $\vec x_e(t)$, the Lagrange density $\mathcal L$, energy density $\mathcal E$ and momentum density $\vec\pi$ are
\begin{equation}\begin{aligned}\label{freieDichten}
&\mathcal L(x)\ist{freieLagrange}
-\frac{m_0c_0^2}{\gamma}\delta^3(\vec x-\vec x_e(t)),\\
&\mathcal E(x)\ist{freieHamilton}m_0\gamma\,c_0^2\delta^3(\vec x-\vec x_e(t)),\\
&\vec\pi(x)\ist{freieImpulse}m_0\gamma\,\vec v\,\delta^3(\vec x-\vec x_e(t))
\end{aligned}\end{equation}

The energy--momentum tensor, which contains the energy density $\mathcal E:=\Theta^{00}(x)$ and momentum density $\vec\pi:=\frac{1}{c_0}\Theta^{0i}(x)$, is
\begin{equation}\label{freieSpannung}
\Theta^{\mu\nu}(x)\iist{freieDichten}{UVonbeta}
\frac{m_0}{\gamma}\,u^\mu(x)u^\nu(x)\,\delta^3(\vec x-\vec x_e(t)).
\end{equation}
{The} momentum of the particle consequently results as a spatial integral over the space--time components of $\Theta^{\mu0}(x)=\Theta^{0\mu}(x)$
\begin{equation}\label{ImpulsAbgeleitet}
p^\mu\iist{freieSpannung}{freieDichten}\frac{1}{c_0}\int_\Sigma\Theta^{\mu0}(x)\,
\mathrm d^3\sigma.
\end{equation}
{As} can be seen from the transition from the integrated quantities in Equations~(\ref{freieLagrange})--(\ref{freieHamilton}) to the densities (\ref{freieDichten}), the integration takes place over the three-dimensional space $\Sigma$ in which the velocities $\vec v$ are determined, i.e., in principle, over any three-dimensional space-like volume $\Sigma$. Precisely this arbitrariness is obviously one of the characteristics of a~particle.


%-------------------------------------------------------------------------------
\section{Electrons in Maxwell's Field Model}\label{SecElektronMaxw}
%-------------------------------------------------------------------------------
We calculate energy and momentum for an extended classical electron of charge $e=-e_0$ and describe it from different reference systems, in a reference system $\stackrel{\circ}{\Sigma}$ in which the electron is at rest and in a reference system $\Sigma$ in which the electron moves with a velocity $\vec v=c\vec\beta$, see Figure~\ref{mitbewegt}.

Like Abraham~\cite{Abraham1903}, we start from the idea that the mass of the
electron is purely electromagnetic in nature. The electron at rest is described solely by an electric field $\vec E$, which is measured in V/m, and a moving electron additionally by a magnetic field $\vec B$ in T~=~Vs/m$^2$. In relativistic notation, electric and magnetic fields can be combined to form the field strength tensor in SI notation
\begin{equation}\label{FaradayTensor}
F^{\mu\nu}=\begin{pmatrix}
0&-\frac{E_x}{c_0}&-\frac{E_y}{c_0}&-\frac{E_z}{c_0}\\
\frac{E_x}{c_0}&0&-B_z&B_y\\
\frac{E_y}{c_0}&B_z&0&-B_x\\
\frac{E_z}{c_0}&-B_y&B_x&0\end{pmatrix}
\end{equation}
where $c_0$ is the speed of light in the vacuum, which results from the dielectric constant $\varepsilon_0$ and the permeability constant $\mu_0$ of the vacuum by $c_0^2\,\varepsilon_0\,\mu_0=1$. We therefore use the usual Lagrangian density of electrodynamics
\begin{equation}\label{LagrEdyn}
\mathcal L:=-\frac{1}{4\mu_0}F_{\mu\nu}F^{\mu\nu}\ist{FaradayTensor}
\frac{1}{2}\Big(\varepsilon_0\vec E^2-\frac{1}{\mu_0}\vec B^2\Big)
\end{equation}
and the metric tensor $\eta_{\mu\nu}=\mathrm{diag}(1,-1,-1,-1)$. Due to the translation symmetry and after adding a four-divergence term, this leads to the symmetric energy--momentum {tensor} %MDPI: Ref citation is not allowed in the equations. Please revise. pdf cannot be complied, if there is ``\cite{}'' in equations, so we removed the ``\cite{}''.
%Faber: Citation in the equation is removed. Another citation {Chaichian2016} is inserted instead of Jackson1999.
\begin{equation}\label{symmEITEdyn}
\Theta^{\mu\nu}=-\frac{1}{\mu_0}\eta^{\mu\kappa}F_{\kappa\lambda}F^{\nu\lambda}
+\frac{1}{4\mu_0}\eta^{\mu\nu}F_{\kappa\lambda}F^{\kappa\lambda},
\end{equation}
see Equation (8.185) of Ref.~\cite{Chaichian2016}. Its elements are in detail
\begin{equation}\label{EneDicht}
\Theta^{00}=:\mathcal E\ist{symmEITEdyn}
\frac{\varepsilon_0}{2}(\vec E^2+c_0^2\vec B^2),
\end{equation}
\begin{equation}\label{ImpDicht}
\Theta^{0i}=\Theta^{i0}\ist{symmEITEdyn}c_0\varepsilon_0\,\vec E\times\vec B,
\end{equation}
\begin{equation}\label{SpannungsDicht}
\Theta^{ij}\ist{symmEITEdyn}-\varepsilon_0\,(E_iE_j+c_0^2B_iB_j)
+\delta_{ij}\frac{\varepsilon_0}{2}(\vec E^2+c_0^2\vec B^2).
\end{equation}

The four-momentum of a field distribution generally depends on the reference system $\Sigma$ in which the field strengths are determined. A reference system can be defined in a Lorentz covariant manner as the three-dimensional Euclidean space that is orthogonal to a velocity vector $u^\mu$ and is usually written as
\begin{equation}\label{3DRaum}
\mathrm d\sigma^\mu:=\frac{u^\mu}{c_0}\,\mathrm d^3\sigma
\end{equation}
{A} Lorentz covariant definition of the four-momentum is obtained by
\begin{equation}\label{DefViererimp}
P^\mu:=\frac{1}{c_0}\int_\Sigma\Theta^{\mu\nu}\,\mathrm d\sigma_\nu.
\end{equation}

In his 1903 paper, Abraham describes electrons on a purely electromagnetic basis with a homogeneous spherically symmetrical charge distribution $\rho(r)$ for electrons at rest. He poses the question: Can the inertia of the electron be completely described by the dynamic effect of its electromagnetic field? It turns out through the 4/3 problem that this question must ultimately be answered in the negative. We will draw conclusions from this failure.


%-------------------------------------------------------------------------------
\subsection{Self-Energy of the Classical Electron}
%-------------------------------------------------------------------------------
The electric field of a point charge $e$ at rest at the origin results in the SI according to Gauss's law to
\begin{equation}\label{EPunkt}
\vec E_\infty=\frac{e}{4\pi\varepsilon_0}\frac{\vec e_r}{r^2}.
\end{equation}
{As} Equation~(\ref{Eruhend}) will show for the limiting case $r_0\to0$, such a field strength is unrealistic, since it leads to an infinite self-energy $E_e(0)$ of the charge $e$ at rest, i.e., an energy that is infinitely greater than the electron mass requires. The more realistic assumption that the electron charge is distributed on a homogeneously charged sphere of radius $r_0$ or the surface charge of a conducting sphere, as used by Abraham in 1902 on page 147 of Ref.~\cite{Abraham1903}, leads to a finite self-energy. In the following, we prefer a regularized form of the electric field strength $\vec E(0)$ for a resting classical electron, which does not result in a kink or jump in the density of an extended charge distribution,
\begin{equation}\label{Ereg}
\vec E(0):=\frac{e}{4\pi\varepsilon_0}\frac{\vec e_r}{r^2+r_0^2},
\end{equation}
as proposed by Schwinger in Ref.~\cite{Schwinger1983}. In Equation~(\ref{Ereg}) it may be irritating that the field strength at the origin has no defined direction. However, this only shows that the electric field strength is defined as the electric flux density on space--time surfaces, which can have different directions starting from the origin. As required, expression~(\ref{Ereg}) results in a finite energy density everywhere in the system at rest
\begin{equation}\label{enedicht}
\mathcal E_0(\vec r)\ist{EneDicht}
\frac{\varepsilon_0}{2}\vec E^2(0)\ist{Ereg}
\frac{\alpha_f\hbar c_0}{8\pi r_0^4}\frac{1}{(1+\rho^2)^2}\quad\textrm{with}
\quad\alpha_f:=\frac{e_0^2}{4\pi\varepsilon_0\hbar c_0},\quad\rho:=\frac{r}{r_0}.
\end{equation}
with a total energy, the so-called self-energy, of the charge $e$ that results from integration over the three-dimenional space,
\begin{equation}\label{Eruhend}
E_e(0)\ist{DefViererimp}4\pi \int_0^\infty r^2\mathcal E_0(\vec r)\mathrm dr\ist{enedicht}
\frac{\alpha_f\hbar c_0}{r_0}\int_0^\infty\frac{\rho^2}{2(1+\rho^2)^2}\mathrm d\rho
=\frac{\alpha_f\hbar c_0}{r_0}\frac{\pi}{8}=:m_sc_0^2,
\end{equation}
and gives the self-energy $m_sc_0^2$ of the classical electron as a function of $r_0$. Adjusting this self-energy to the physical value leads to $r_0=1.1066$\,fm.

From Equation (\ref{Eruhend}), the known instability of the classical electron can be seen. Its mass decreases with $1/r_0$, it dissolves, its radius parameter $r_0$ increases indefinitely. The reason for this expansion of the core region is easy to detect. Because of the four Lorentz indices in $F_{\mu\nu}F^{\mu\nu}$, the energy density is proportional to $r_0^{-4}$, the spatial integral only grows with $r_0^3$, so overall the $r_0^{-1}$ behavior of Equation~(\ref{Eruhend}) results.


%-------------------------------------------------------------------------------
\subsection{Energy of the Moving Electron}
%-------------------------------------------------------------------------------
To describe an electron moving in $\Sigma$, we start from the transformation of
the coordinates $\stackrel{\circ}{x}:=(c_0\!\!\stackrel{\circ}{t},\stackrel{\circ}{\vec r)}$ in the comoving frame $\stackrel{\circ}{\Sigma}$ and transform to $\Sigma$ in which the electron moves with $\vec\beta$
\begin{eqnarray}\begin{aligned}\label{txbewegt}
c_0\!\stackrel{\circ}{t} &=\gamma c_0t-\gamma\vec\beta\vec r,\\
\stackrel{\circ}{\vec r}&=\gamma\vec r_\parallel+\vec r_\perp
-\gamma\vec\beta c_0t,
\end{aligned}\end{eqnarray}
{The} Lorentz transformation of the field strength tensor $F^{\mu\nu}$ is
\begin{eqnarray}\begin{aligned}\label{EBbewegt}
&\vec E(\vec\beta)=\vec E_\parallel(0)+\gamma\vec E_\perp(0)\quad
\textrm{with}\quad\vec E_\parallel:=\frac{\vec\beta(\vec\beta\vec E)}{\beta^2},
\quad\vec E_\perp:=\vec E-\vec E_\parallel,\\
&c_0\vec B(\vec\beta)=\gamma\vec\beta\times\vec E(0).
\end{aligned}\end{eqnarray}
{We} can interpret the evaluation of the energy in Equation~(\ref{Eruhend}) in such a way that the energy of the electron at rest regularized according to Equation~(\ref{Ereg}) takes place in the 3D space $\stackrel{\circ}{\Sigma}$, which is orthogonal to the velocity vector $u=\gamma(c,\vec\beta)$, see Figure~\ref{mitbewegt}. We note for further calculations that in $\stackrel{\circ}{\Sigma}$, each of the three electric field components contributes to the energy density~(\ref{EneDicht}) with one-third of $\mathcal E_0(\vec r)$, which is due to the spherical symmetry of the field. Now, however, we consider the energy densities $\mathcal E_{\vec\beta}(\vec r)$ in the 3D space $\Sigma$, which is orthogonal to $(1,\vec 0)$ and contains other space--time points than $\stackrel{\circ}{\Sigma}$, see Figure~\ref{mitbewegt}. We list the contributions of the field components $\vec E_\parallel ,\vec E_\perp, \vec B_\parallel, \vec B_\perp$ according to Equation (\ref{EBbewegt}) in order \footnote{We point out that this calculation, which was carried out in analogy to Abraham~\cite{Abraham1903}, is an exact calculation according to  definition~(\ref{DefViererimp}) of the four-momentum and not, as Rohrlich~\cite{rohrlich2007} writes before his Equation~(16): ``We can summarize this discussion by saying that  definition (5) is incorrect''. With  definition (5), Rohrlich refers to the Abraham-Lorentz definition of the energy of a moving electron, which corresponds to Equation~(\ref{eneBewSigma})}.
\begin{equation}\label{eneBewSigma}
E_e(\beta)\ist{DefViererimp}\int_\Sigma\mathrm d^3\sigma\Theta^{00}(\beta)
\ist{EneDicht}\int_\Sigma\mathrm d^3\sigma\mathcal E_{\vec\beta}(\vec r)
\iist{EneDicht}{EBbewegt}\int_{\Sigma}\mathrm d^3\sigma\frac
{\mathcal E_0(\stackrel{\circ}{\vec r})}{3}(1+2\gamma^2+0+2\gamma^2\beta^2).
\end{equation}
{In} this calculation, we have used that $\vec E_\parallel$ contributes unchanged with one third of the energy density of the electron at rest. The contributions of the two orthogonal electric field components are given a factor $\gamma^2$. $\vec B_\parallel$ and consequently its contribution vanishes. The two orthogonal magnetic field components are proportional $\beta^2\gamma^2$ according to Equation~(\ref{EBbewegt}). From an expansion up to the order $\beta^2$, i.e., $\gamma^2\approx1+\beta^2$, Abraham read in Equation~(15e) of Ref.~\cite{Abraham1903} that the ``kinetic'' magnetic energy contributions proportional to $\beta^2$, $W_\mathrm{m}\propto2\gamma^2\beta^2\approx2\beta^2$, is related to the ``static'' electrical energy contributions of a Lorentz-contracted electron $W_\mathrm{e}\propto1+2\gamma^2\approx3+2\beta^2$ by
\begin{equation}\label{AbrahamBez}
W_\mathrm{m}\ist{eneBewSigma}\approx\frac{2\beta^2}{3+2\beta^2}\,W_\mathrm{e}
\approx\frac{2\beta^2}{3}\,W_\mathrm{e}
\approx\frac{4}{3}\frac{\beta^2}{2}\,W_\mathrm{e},
\end{equation}
and thus the factor $4/3$ appeared for the first time.

Due to the time independence of the electric field strength in the comoving system, it was possible in Equation~(\ref{eneBewSigma}) to read off the field values in the comoving reference system $\stackrel{\circ}{\Sigma}$ instead of in $\Sigma$, see Figure~\ref{mitbewegt}. Since we have already integrated in Equation~(\ref{Eruhend}) over the energy density in the comoving system $\stackrel{\circ}{\Sigma}$, it makes sense to carry out the integration in Equation~(\ref{eneBewSigma}) via $\stackrel{\circ}{\Sigma}$, whereby we take into account the Lorentz contraction of the moving electron according to Equation~(\ref{txbewegt}). The total energy of the moving classical electron thus results in
\begin{equation}\label{eneBew0}
E_e(\beta)\iist{eneBewSigma}{txbewegt}\frac{1}{\gamma}\int_{\stackrel{\circ}{\Sigma}}
\mathrm d^3\stackrel{\circ}{\sigma}\frac{\mathcal E_0(\stackrel{\circ}{\vec r)}}
{3}(1+2\gamma^2+0+2\underbrace{\gamma^2\beta^2}_{\gamma^2-1})
\ist{Eruhend}\frac{E_e(0)}{3\gamma}(4\gamma^2-1),
\end{equation}
which does not have the form~(\ref{pvonbeta}) expected for particles. For $\gamma=1$ the expression is correct, but for $\gamma\to\infty$ the energy increases to $4/3$ of the expected value.


%-------------------------------------------------------------------------------
\subsection{Momentum of the Moving Electron}
%-------------------------------------------------------------------------------
According to the particle interpretation, the momentum of the uniformly moving classical electron results from the $\Sigma$ integration via the stress tensor or the Poynting vector
\begin{equation}\begin{aligned}\label{ImpBew}
\vec P_e(\vec\beta)&:=\frac{1}{c_0}\int_\Sigma\mathrm d^3\sigma\,\Theta^{0i}
(\vec\beta)\ist{ImpDicht}\varepsilon_0\int_\Sigma\mathrm d^3\sigma\vec E
(\vec\beta)\times\vec B(\vec\beta)=\\
&\ist{EBbewegt}\frac{\varepsilon_0}{c_0}\gamma
\int_\Sigma\mathrm d^3\sigma\left[\vec E_\parallel(0)+\gamma\vec E_\perp(0)\right]
\times\left[\vec\beta\times\vec E_\perp(0)\right].
\end{aligned}\end{equation}
In the transformation to $\stackrel{\circ}{\Sigma}$, we again take into account the Lorentz contraction
\begin{equation}\begin{aligned}\label{ImpBew0}
\vec P_e(\vec\beta)&\iist{ImpBew}{txbewegt}
\frac{\varepsilon_0}{c_0}\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}
{\sigma}\left[\vec E_\parallel(0)+\gamma\vec E_\perp(0)\right]\times
\left[\vec\beta\times\vec E_\perp(0)\right]=\\&=\frac{\varepsilon_0}{c_0}
\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}
\left[-\vec E_\perp(0)\left(\vec E_\parallel(0)\vec\beta\right)
+\gamma\vec\beta\vec E_\perp^2(0)\right].
\end{aligned}\end{equation}
The first summand in the integrand of the last expression shows momentum densities normal to the velocity and thus internal stresses in the classical electron. At points that are mirror-symmetrical to the velocity vector $\vec\beta$, $E_\perp(0)$ points in the opposite directions, so their contributions cancel each other out and do not contribute to the total momentum $\vec P_e(\vec\beta)$. Since the two orthogonal field components $\vec E_\perp(0)$ in the resting electron each contribute one-third of the field energy, the second contribution provides the 4/3 factor already known from Equation~(\ref{AbrahamBez})
\begin{equation}\label{ImpBew1}
\vec P_e(\vec\beta)\ist{ImpBew0}\vec\beta\gamma\frac{4}{3}
\frac{\varepsilon_0}{c_0}\int_{\stackrel{\circ}{\Sigma}}
\mathrm d^3\stackrel{\circ}{\sigma}\frac{\vec E^2(0)}{2}\ist{Eruhend}\vec\beta
\gamma\frac{4}{3}\frac{E_e(0)}{c_0}\ist{Eruhend}\vec v\gamma\frac{4}{3}m_s.
\end{equation}
{Both} calculations, (\ref{AbrahamBez}) and (\ref{ImpBew1}), thus show that the mass of the electron contributing to the momentum and the kinetic energy is greater by a factor of 4/3 than results from the electrical field energy $E_e(0)$ for the electron at rest in Equation~(\ref{eneBew0}). This would mean a discrepancy between inertial and gravitational mass. To eliminate this contradiction, Poincaré introduced a negative pressure~\cite{poincare1905}, which has to balance the exploding tendency of the electron.


%-------------------------------------------------------------------------------
\subsection{Lorentz Transformed Four-Momentum of the Electron at Rest}
%-------------------------------------------------------------------------------
The situation is different for the four-momentum of the electron at rest in $\stackrel{\circ}{\Sigma}$ when its four-momentum $P^\mu(\vec\beta)$ is expressed in coordinates of $\Sigma$. As Rohrlich~\cite{rohrlich1960} has clearly shown, the correct expression results due to the consistency of special relativity
\begin{equation}\label{ViererSigma0}
P^\mu(\vec\beta)\iist{DefViererimp}{3DRaum}\frac{1}{c_0}\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}\Theta^{\mu\nu}_\Sigma\beta_\nu
\iist{eneRuhSigma0}{ImpRuhSigma0b}\frac{E_e(0)}{c_0}(\gamma,\vec\beta\gamma),
\end{equation}
whereby it should be noted that the field values calculated in the laboratory system $\Sigma$ are integrated over the comoving world volume $\stackrel{\circ}{\Sigma}$.

In detail, this results in
\begin{equation}\begin{aligned}\label{eneRuhSigma0}
P^0(\vec\beta)&\ist{ViererSigma0}\frac{\gamma}{c_0}\int_{\stackrel{\circ}{\Sigma}}
\mathrm d^3\stackrel{\circ}{\sigma}(\Theta^{00}_\Sigma-\beta_i\Theta^{0i}_\Sigma)
\ist{txbewegt}\frac{\gamma^2}{c_0}\int_\Sigma
\mathrm d^3\sigma(\Theta^{00}_\Sigma-\beta_i\Theta^{0i}_\Sigma)=\\
&\iist{eneBewSigma}{ImpBew}\gamma^2\frac{E_e(\beta)}{c_0}-\gamma^2\vec\beta
\vec P_e(\vec\beta)\iist{eneBew0}{ImpBew1}\gamma(4\gamma^2-1)\frac{E_e(0)}{3c_0}
-\beta^2\gamma^3\frac{4E_e(0)}{3c_0}=\gamma E_e(0)
\end{aligned}\end{equation}
\begin{equation}\begin{aligned}\label{ImpRuhSigma0}
P^i(\vec\beta)&\ist{ViererSigma0}\frac{\gamma}{c_0}\int_{\stackrel{\circ}{\Sigma}}
\mathrm d^3\stackrel{\circ}{\sigma}(\Theta^{i0}_\Sigma-\beta_j\Theta^{ij}_\Sigma)=\\
&\iist{SpannungsDicht}{ImpBew}\gamma^2P_e^i(\vec\beta)-\frac{\gamma}{c_0}\beta_j
\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}
\{-\varepsilon_0\,[E_i(0)E_j(0)+c_0^2B_i(0)B_j(0)]+\\&\hspace{20mm}
+\delta_{ij}\frac{\varepsilon_0}{2}[\vec E^2(0)+c_0^2\vec B^2(0)]\}\\
&\ist{EBbewegt}\gamma^2P_e^i(\vec\beta)+\frac{\gamma}{c_0}\beta\varepsilon_0\,
\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}
[E_i(0)E_\parallel(0)+c_0^2B_i(0)\underbrace{B_\parallel(0)}_{0}]-\\&\hspace{20mm}
-\frac{\gamma}{c_0}\beta_i\frac{\varepsilon_0}{2}\int_{\stackrel{\circ}{\Sigma}}
\mathrm d^3\stackrel{\circ}{\sigma}[\vec E^2(0)+c_0^2\vec B^2(0)]
\end{aligned}\end{equation}
i.e.,
\begin{equation}\begin{aligned}\label{ImpRuhSigma0b}
P_\parallel(\vec\beta)&\ist{ImpRuhSigma0}\gamma^2P_e^\parallel(\vec\beta)
+\frac{\gamma}{c_0}\beta\frac{\varepsilon_0}{2}\,
\int_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}[E_\parallel^2(0)
-2E_\perp^2(0)-2c_0^2\vec B^2_\perp(0)]=\\
&\iist{ImpBew1}{EBbewegt}\beta\gamma^3\frac{4}{3}\frac{E_e(0)}{c_0}
+\frac{\gamma}{c_0}\beta\,\frac{E_e(0)}{3}
[1-2\gamma^2-2\beta^2\gamma^2]=\beta\gamma\frac{E_e(0)}{c_0}.
\end{aligned}\end{equation}
and
\begin{equation}\begin{aligned}\label{ImpRuhSigma0c}
P_\perp(\vec\beta)&\ist{ImpRuhSigma0}\frac{\gamma}{c_0}\beta\varepsilon_0\,\int
_{\stackrel{\circ}{\Sigma}}\mathrm d^3\stackrel{\circ}{\sigma}E_\parallel(0)E_\perp(0)=0.
\end{aligned}\end{equation}
{The} result~(\ref{ViererSigma0}) has nothing to do with the 4/3 problem. It only shows that the four-vector $(1,\vec0)\,E_e(0)/c_0$ in $\stackrel{\circ}{\Sigma}$ can be transformed by a Lorentz transformation to $(\gamma,\vec\beta\gamma)\,E_e(0)/c_0$ in $\Sigma$. It is important that the space-like volume that is integrated is also correctly transformed.


