\vert \xi\vert ^{\lambda}\vert \ln \vert \xi\vert \vert  & =\begin{cases}
\left(\vert \xi\vert ^{\lambda+\mu}\right)\left(\vert \xi\vert ^{-\mu}\vert \ln \vert \xi\vert \vert \right) & \text{if $\vert \xi\vert \geq 1$},
\\
