Let $a,b\in C^{0}(\overline{Q}_T)$. Introduce the quantities

\[
\begin{split}
& \mathcal{N}(\nabla w)=\int_{Q_T}\left(a(z)|\nabla w|^{p(z)}+b(z)|\nabla w|^{q(z)}\right)\,dz,
\\
& \mathcal{G}_\epsilon(\nabla u,\nabla v)=\int_{Q_T}\left(\mathcal{F}_{\epsilon}(z,\nabla u)\nabla u- \mathcal{F}_{\epsilon}(z,\nabla v)\nabla v\right)\cdot \nabla (u-v)\,dz.
\end{split}
\]

\begin{proposition}[\cite{RACSAM-2023}, Proposition 3.2]
\label{pro:racsam-prop-3.2}
For every $u,v\in \mathbb{W}_{\overline{s}(\cdot)}(Q_T)$ and any $\epsilon\in (0,1)$

\[
\mathcal{N}(\nabla (u-v))\leq C\left(\mathcal{G}_\epsilon^{\frac{\overline{s}^+}{2}}(\nabla u,\nabla v)+ \mathcal{G}_\epsilon^{\frac{\underline{s}^-}{2}}(\nabla u,\nabla v)+\mathcal{G}_\epsilon(\nabla u,\nabla v)\right)
\]
with a constant C depending on $p^\pm$, $q^\pm$, $a^+$, $b^+$, $\|\nabla u\|_{\overline{s}(\cdot),Q_T }$, $\|\nabla v\|_{\overline{s}(\cdot),Q_T }$.
\end{proposition}

\begin{corollary}[\cite{RACSAM-2023}, Lemma 3.1]
\label{cor:cont-embed}
There is the continuous embedding

\[
\{u:Q_T\mapsto \mathbb{R}:\,u\in L^{2}(Q_T),\,\mathcal{N}(\nabla u)<\infty\}\subset \mathbb{W}_{\underline{s}(\cdot)}(Q_T).
\]
\end{corollary}

\begin{proposition}[\cite{RACSAM-2023}, Lemma 3.2]
\label{pro:conv-W}
If $u,v\in \mathbb{W}_{\overline{s}(\cdot)}(Q_T)$ and $\epsilon\in (0,1)$, then

\[
\int_{Q_T}|\nabla (u-v)|^{\underline{s}(z)}\,dz\to 0\quad \text{when $\mathcal{G}_\epsilon(\nabla u,\nabla v)\to 0$}.
\]
\end{proposition}


\begin{corollary}
\label{cor:conv-1}
If a sequence $\{u_m\}$ is uniformly bounded in $\mathbb{W}_{\overline{s}(\cdot)}(Q_T)$ and $\mathcal{G}_\epsilon(\nabla u_m,\nabla u_k)\to 0$ as $m,k\to \infty$, then

\[
\text{$|\nabla (u_m-u_k)|\to 0$ a.e. in $Q_T$}.
\]
\end{corollary}

