\section{Some important  representations}\label{app:prelim}

We recall the following notation from Section \ref{secgenset}. \begin{eqnarray*}
	A(u,T)= \int_u^T \alpha(u,s)\mathrm{d}s, \ \ \ \Sigma_1(u,T)= \int_u^T \sigma_1(u,s)\mathrm{d}s,\ \ \
	\Sigma_2(u,T) = \int_u^T \beta(u,s)\mathrm{d}s. 
\end{eqnarray*}
We have the following  representation.
\begin{lemma}\label{lemm1a} Let $f(t,s)$ be the quantity defined in \eqref{forward rate}. For any $0\leq t\leq T$, we have \label{lem:HJM}
	$$
	-\int_{t}^T f(t,s)\mathrm{d}s = \int_0^{t}r(s)\mathrm{d}s -\int_0^T f(0,s)\mathrm{d}s - \int_0^{t}A(u,T)\mathrm{d}u + \int_0^{t}\Sigma_1(u,T)\mathrm{d}L^1_u - \int_0^{t}\Sigma_2(u,T)\mathrm{d}L^2_u.
	$$
\end{lemma}

\begin{proof}

	Applying the Fubini's theorem for stochastic integrals, we obtain
	\begin{align*}
	& -\int_{t}^T f(t,s)\mathrm{d}s \\
	 =& \int_0^{t}r(s)\mathrm{d}s -\int_0^{t} r(s)\mathrm{d}s - \int_{t}^T f(0,s)\mathrm{d}s - \int_{t}^T \int_0^{t}\alpha(u,s)\mathrm{d}u\, \mathrm{d}s\\
		& +\int_{t}^T\int_0^{t}\sigma_1(u,s)\mathrm{d}L^1_u\mathrm{d}s -\int_{t}^T\int_0^{t}\beta(u,s)\mathrm{d}L^2_u\mathrm{d}s \\
		=& \int_0^{t}r(s)\mathrm{d}s -\Big[\int_0^{t}f(0,s)\mathrm{d}s + \int_0^{t}(\int_0^s \alpha(u,s)\mathrm{d}u)\mathrm{d}s - \int_0^{t}(\int_0^s \sigma_1(u,s)\mathrm{d}L^1_u)\mathrm{d}s  \\
		&+ \int_0^{t}(\int_0^s \beta(u,s)\mathrm{d}L^2_u)\mathrm{d}s\Big] - \int_{t}^T f(0,s)\mathrm{d}s - \int_0^{t}\int_{t}^T \alpha(u,s)\mathrm{d}s\, \mathrm{d}u +\int_0^{t}\int_{t}^T\sigma_1(u,s) \mathrm{d}s\,\mathrm{d}L^1_u\\
		& - \int_0^{t}\int_{t}^T\beta(u,s) \mathrm{d}s\,\mathrm{d}L^2_u\\
		=& \int_0^{t}r(s)\mathrm{d}s  -\Big[\int_0^{t}f(0,s)\mathrm{d}s + \int_0^{t}\int_u^{t} \alpha(u,s)\mathrm{d}s\,\mathrm{d}u - \int_0^{t}\int_u^{t} \sigma_1(u,s)\mathrm{d}s\,\mathrm{d}L^1_u + \int_0^{t}\int_u^{t} \beta(u,s)\mathrm{d}s\,\mathrm{d}L^2_u\Big] \\
		& - \int_{t}^T f(0,s)\mathrm{d}s - \int_0^{t}\int_{t}^T \alpha(u,s)\mathrm{d}s\mathrm{d}u +\int_0^{t}\int_{t}^T\sigma_1(u,s) \mathrm{d}s\,\mathrm{d}L^1_u - \int_0^{t}\int_{t}^T\beta(u,s) \mathrm{d}s\mathrm{d}L^2_u\\
		=& \int_0^{t}r(s)\mathrm{d}s - \int_{0}^T f(0,s)\mathrm{d}s - \int_0^{t}\int_{u}^T \alpha(u,s)\mathrm{d}s\mathrm{d}u +\int_0^{t}\int_{u}^T\sigma_1(u,s) \mathrm{d} s\mathrm{d}L^1_u - \int_0^{t}\int_{u}^T\beta(u,s) \mathrm{d} s\mathrm{d}L^2_u.
	\end{align*}
The result follows from the definition of $A(u,T), \Sigma_1(u,T)$ and $\Sigma_2(u,T)$.

\end{proof}

Using the previous lemma, we get  the following representation of $D(t)$ defined in \eqref{Dt}.
\begin{align}
	D(t)=& \int_0^t r(s)\mathrm{d}s+\int_0^t \sigma_2(s)\mathrm{d}L^2_s -\omega(t)  -p(t) + \int_{t}^Tf(t,s)\mathrm{d}s - \delta T  \notag \\
	=&  -p(t) - \delta T+\int_0^t r(s)\mathrm{d}s+\int_0^t \sigma_2(s)\mathrm{d}L^2_s -\omega(t)- \int_0^{t}r(s)\mathrm{d}s +\int_0^T f(0,s)\mathrm{d}s  \notag\\
	&+ \int_0^{t}A(u,T)\mathrm{d}u - \int_0^{t}\Sigma_1(u,T)\mathrm{d}L^1_u + \int_0^{t}\Sigma_2(u,T)\mathrm{d}L^2_u \notag\\
	=& -p(t) - \delta T+\int_0^t \sigma_2(s)\mathrm{d}L^2_s -\omega(t)+\int_0^T f(0,s)\mathrm{d}s + \int_0^{t}A(u,T)\mathrm{d}u  \notag\\
	&- \int_0^{t}\Sigma_1(u,T)\mathrm{d}L^1_u+ \int_0^{t}\Sigma_2(u,T)\mathrm{d}L^2_u. \label{D:appendix}
\end{align}
By setting $t=T$ in the previous lemma, we get 
\begin{equation}
	0 = \int_0^{t}r(s)\mathrm{d}s -\int_0^t f(0,s)\mathrm{d}s - \int_0^{t}A(s,t)\mathrm{d}s + \int_0^{t}\Sigma_1(s,t)\mathrm{d}L^1_s - \int_0^{t}\Sigma_2(s,t)\mathrm{d}L^2_s, \label{interest}
\end{equation}
therefore, we deduce the following representation for the bank account (see (49) in \cite{Eberlein-R}),
\begin{equation}
	B(t) = \frac{1}{B(0,t)}\exp\Big( \int_0^t A(s,t)\mathrm{d}s - \int_0^t \Sigma_1(s,t)\mathrm{d}L^1_s +\int_0^t \Sigma_2(s,t)\mathrm{d}L^2_s \Big). \label{Bank ac}
\end{equation} 



