\section{Osculating functions}\label{sec: osculating}

{\bf Notation.} Let $V$ be an $(n+1)$-dimensional vector space over $\C$, or more generally an algebraically closed field. We denote by $\P^n$ the projective space $\P(V)$, while $(\P^n)^\vee$ denotes the dual projective space of hyperplanes in $\P^n$. Given a multi-index $\alpha=(\alpha_1,\ldots,\alpha_m)\in\N^m$, we define $|\alpha|\coloneqq \alpha_1+\cdots+\alpha_m$, and for any vector $x=(x_1,\ldots,x_m)$, we call $x^\alpha=x_1^{\alpha_1}\cdots x_m^{\alpha_m}$.

Let  $f\colon X\to\P^n$ be an algebraic morphism.
We may assume that it is defined by the global sections of the line bundle $\OO_X(1)=f^*(\OO_{\P^n}(1)),$ in particular $f(p)=(\sigma_0(p),\ldots,\sigma_n(p))$ for a given basis $(\sigma_0,\ldots,\sigma_n)$ of $H^0(X,\OO_X(1)).$ Because $f$ is a morphism, at each $p\in X$ there is at least one nonvanishing global section. 
This allows us to identify $V$ with $H^0(X,\OO_X(1))$.
Let $p\in X$ and $\sigma\in H^0(X,\OO_X(1))$. Recall that any $\sigma\in H^0(X,\OO_X(1))$ can be represented in a neighborhood of $p$ as a polynomial in local coordinates $(x_1,\ldots,x_m)$.
The {\em $k$th jet} of $\sigma$ at $p$ is the $\binom{m+k}{k}$-tuple
\[
j_{k,p}(\sigma)\coloneqq\left(\frac{\partial^{|\alpha|}\sigma}{\partial x^\alpha}(p)\right)_{\substack{\alpha\in\N^m\\0\le|\alpha|\le k}}\in \JJ_{k,p}(f)\coloneqq H^0\left(X,\OO_X(1)\otimes\frac{\OO_{X,p}}{\mathfrak{m}_{p}^{k+1}}\right)\cong\C^{\binom{m+k}{k}}\,,
\]
where $\mathfrak{m}_p$ denotes the maximal ideal at $p$. The vector space $\JJ_{k,p}(f)$ is the fiber at $p$ of a vector bundle $\JJ_k(f)$ of rank $\binom{m+k}{k}$, called the {\em $k$th jet bundle} of the morphism $f$ or the principal part bundle.
Gluing together the maps $j_{k,p}$ yields a morphism of vector bundles on $X$:
\begin{equation}\label{eq: morphism jk}
j_k\colon H^0(X,\OO_X(1))\otimes\OO_X\to \JJ_k(f)\,.
\end{equation}

Jet bundles, also called bundles of principal parts, were first introduced in \cite{pohl1962differential, PienePrincipalBundles}, where an algebraic definition is given.
\begin{definition}\label{def: osculating space}
For every point $p\in X$, the {\em $k$th osculating space of $f$ at $f(p)\in f(X)$} is
\[
\T_p^k(f) \coloneqq \P(\image j_{k,p})\,.
\]
\end{definition}
If $f$ is a closed embedding, by convention we identify $X$ with its image $f(X)$ and write $p$ instead of $f(p)$. Moreover, when $f$ is a closed embedding, the first osculating space of $X$ at the point $p$ coincides with the projective tangent space of $f$ at $p$:
\[
\T_p^1(f) = \T_p(f)\,.
\]
Furthermore, osculating spaces form an ascending sequence of inclusions:
\begin{equation}\label{eq: osc seq}
    \{p\} \subseteq \T_p(f)  = \T_p^1(f) \subseteq \cdots \subseteq \T_p^k(f) \subseteq \cdots \subseteq \P^n\,.
\end{equation}

For a generic $p\in X$, the rank of $j_{k,p}$ is constant. This motivates the following definition.

\begin{definition}\label{def: globally k-osculating}
Given $f\colon X\to\P^n$, let $X_k^{\circ}\subseteq X$ be the dense open subset of $X$ of points $p$ such that $\rank j_{k,p}$ is constant. We define the {\em generic $k$-osculating dimension} of $f$ as $m_k\coloneqq\rank j_{k,p}-1$ for any $p\in X_k^{\circ}$.
We say that the morphism $f$ is {\em globally $k$-osculating} if $X_k^{\circ}=X$. In this case, $m_k$ is referred to as the {\em $k$-osculating dimension} of $f$.
\end{definition}
\begin{remark}
The generic $1$-osculating dimension of a morphism $f\colon X\to\P^n$ is $m_1=m$. Indeed, the open dense subset $X_1^\circ\subseteq X$ coincides with the nonsingular locus of $X$, and $\T_p^1(f)=\T_p(f)=\P^m$ for every $p\in X_1^\circ$. Furthermore, the morphism $f$ is globally $1$-osculating if and only if it is a closed embedding.
\end{remark}

Let $(x_1,\ldots,x_m)$ be a system of local coordinates around the point $p=(0,\ldots,0)$. After choosing a basis $(\sigma_0,\ldots,\sigma_n)$ of $V=H^0(X,\OO_X(1))$ one can define the $\binom{m+k}{k}\times (n+1)$ matrix
\begin{equation}\label{eq: matrix A}
A^{(k)}_p(f)\coloneqq \left(\frac{\partial^{|\alpha|}\sigma_\beta}{\partial x^\alpha}(p)\right)_{\substack{\alpha\in\N^m\\\ 0\le|\alpha|\le k\\0\le\beta\le n}} =
\left(
\begin{array}{c|c|c|c}
j_{k,p}(\sigma_0)^\mT & j_{k,p}(\sigma_1)^\mT & \cdots & j_{k,p}(\sigma_n)^\mT 
\end{array}
\right)
\end{equation}
obtained by concatenating horizontally the $n+1$ column vectors $j_{k,p}(\sigma_\beta)^\mT$ of length $\binom{m+k}{k}$ for every $\beta\in\{0,\ldots,k\}$.
A basis of $\image j_{k,p}$ is given by $m_k+1$ linearly independent vectors in the column span of $A^{(k)}_p(f)$.
Notice that $X_k^{\circ}=\{p\in X\mid \rank A_p^{(k)}(f)=m_k+1\}$ and that this identity is independent of the choice of a basis of $V.$

\begin{definition}\label{def: k-regular}
The morphism  $f\colon X \to\P^n$ is {\em $k$-regular} if $X_k^{\circ}=X$ and if the vector bundle morphism $j_k$ in \eqref{eq: morphism jk} is surjective, equivalently $m_k+1=\binom{m+k}{k}$.
\end{definition}

\begin{proposition}
Let $f\colon X\to\P^n$ be a globally $k$-osculating morphism for some $k\ge 1$. Then it is $\ell$-osculating for all $\ell\le k.$
Similarly, if $f$ is $k$-regular, then it is $\ell$-regular for all $\ell\le k$.
\end{proposition}
\begin{proof}
Assume that $f\colon X\to\P^n$ is a globally $k$-osculating morphism for some $k\ge 1$, and let $\ell\le k$. Notice that   
\[
A_p^{(k)}(f) = 
\begin{pmatrix}
A_p^{(\ell)}(f) \\ B_p(f)
\end{pmatrix}
\]
where $B_p(f)$ is an $\left(\binom{m+k}{k}-\binom{m+t}{t}\right)\times n$ matrix for every $p\in X$. Assuming that there exists a special point $p$ where $A_p^{(t)}$ does not have the maximal generic rank while $A_p^{(k)}$ has the maximal generic rank is impossible.
Moreover, if $A_p^{(k)}(f)$ has maximal rank, then $A_p^{(\ell)}(f)$ will also have maximal rank.
\end{proof}

\begin{remark}
A globally $1$-osculating morphism is always $1$-regular. For $k\ge 2$, this is no longer the case. See Example \ref{ex: blowup P1xP1 one point} below.
\end{remark}





\subsection{A gallery of toric examples}\label{subsec: gallery of toric examples}

For varieties endowed with a maximal dimensional torus action, i.e., toric varieties, the torus action leads to remarkably simple criteria dictated by the size of the associated polytope.

Let $f\colon X\to\P^n$ be a nonsingular, globally $k$-osculating, torus-equivariant embedding of a toric variety $X$ of dimension $m$. 
Then $f$ is defined by an integer matrix
\[
A = \begin{pmatrix}a_1 & a_2 & \cdots & a_{n+1}\end{pmatrix} \in \Z^{(m+1)\times(n+1)}
\]
of full rank, containing in its row span the vector $\bone=(1,\ldots,1)$. We also denote by $A$ the subset $\{a_1,\ldots,a_{n+1}\}\subseteq\Z^m$. Let $P(f)=\conv(A)$ be the associated polytope and $\vertices P(f)$ the set of vertices of $P(f)$. When $f$ is defined by an ample divisor, the polytope $P(f)$ is of maximal dimension and every $v\in\vertices P(f)$ corresponds to a fixed point $p_v\in X.$ The variety has an affine cover $X=\bigcup_{v\in\vertices P(f)} U_v$ where $U_v\subseteq\C^m$ is a Zariski open subset containing $p_v$ for every $v\in\vertices P(f)$. Moreover, assuming $X$ nonsingular, we can choose a lattice basis where $v=0$ and consequently local coordinates $(x_1,\ldots,x_m)$ around $p_v=0.$ It follows that the first lattice vectors on the $m$ edges through $v$ correspond to a generating set for the dual lattice and $f|_{U_v}(x)=(x^\alpha)_{\alpha\in A}.$
Let $p=\bone$ be the generic point in the torus.
For every $k\ge 1$, we denote by $A^{(k)}$ the matrix $A_{\bone}^{(k)}(f)$ defined in \eqref{eq: matrix A}. The construction of the matrices is explained in detail in \cite[Section 5.2]{Higher_duality_and_toric}. In particular $A^{(1)}$ is obtained adding the row $\bone$ on top of $A$. The augmented matrix $A^{(k)}$ determines the generic $k$-osculating rank. More generally, for every fixed point $p_v\in X$, we denote by $A_v^{(k)}$ the matrix $A_{p_v}^{(k)}(f)$. The following result characterizes globally $k$-osculating toric embeddings. 

\begin{proposition}\label{prop: characterization of globally osculating toric varieties}
A nonsingular toric embedding $f$ is globally $k$-osculating of osculating dimension $m_k$ if and only if $\dim\T_{p_v}^k(f)=\rank A_v^{(k)}-1=\rank A^{(k)}-1$ for every fixed point $p_v$.
\end{proposition}
\begin{proof}
From the description above, it is clear that $m_k+1=\rank A^{(k)}.$ Note that if the locus of points where the $k$th osculating space has a lower dimension than $m_k$ is nonempty, the torus action ensures that it contains fixed points. It follows that to ensure global $k$th osculation is enough that the $k$th osculation dimension at each fixed point is $m_k.$
\end{proof}  

\begin{example}\label{ex: blowup P2 three points}
Consider $\pi\colon X\to\P^2,$ the blow-up of $\P^2$ at the three points and the embedding $f_1\colon X\to \P^6$, a Del Pezzo surface of degree six defined by the global sections of the line bundle $\OO_X(1)=\pi^*\OO_{\P^2}(3)-E_1-E_2-E_3$, where $E_i$ are the exceptional divisors. On an affine patch around the fixed point $p_v$, where $v$ is indicated in Figure \ref{fig: blowup P2 three points}, the monomial map is:
\[
(x_1,x_2) \mapsto (1,x_1,x_2,x_1x_2,x_1x_2^2,x_1^2x_2,x_1^2x_2^2)\,.
\]
Consider $k=2$. In this case $\rank A^{(2)}=6$, and thus the generic $2$-osculating dimension of $f_1$ is $m_2=5$, but $f_1$ is not globally $2$-osculating since $\dim\T_{p_v}^2(f_1)=3$ for every fixed point $p_v\in X$.
\hfill$\diamondsuit$

