\section{Preliminaries}
The following definitions are presented in Bohner et al.  \cite{Peterson} and Agarwal et al. \cite{Agarwal}. A time scale $\mathbb{T}$ is defined as any closed subset of $\mathbb{R}$. The forward and backward jump operators $\sigma, \rho: \mathbb{T}\to\mathbb{T}$  are defined as follows:
$$\sigma(t)=\inf\{s\in\mathbb{T}: s > t\}\,\,\,\text{and}\,\,\,\rho(t)=\sup\{s\in\mathbb{T} : s < t\}$$
(supplemented by $\inf\emptyset:=\sup\mathbb{T}$ and $\sup\emptyset:=\inf\mathbb{T}$). A point $t\in\mathbb{T}$ is
called left-dense if $t>\inf\mathbb{T}$ and $\rho(t)=t$, left-scattered if $\rho(t)<t$, right-dense if $t<\sup\mathbb{T}$
and $\sigma(t)=t$, right-scattered if $\sigma(t)>t$. If $\mathbb{T}$ has a right-scattered minimum $m$, then define
$\mathbb{T}_{\kappa}:=\mathbb{T}-\{m\}$; otherwise, set $\mathbb{T}_{\kappa}:=\mathbb{T}$. The backward graininess $\nu:\mathbb{T}_{\kappa}\to[0,\infty)$
is defined by
$$\nu(t)=t-\rho(t)$$
and it represents the difference between
$t$ and its backward jump 
$\rho(t).$
For $f:\mathbb{T}\to\mathbb{R}$ and $t\in\mathbb{T}_{\kappa}$,  the nabla derivative  of $f$ at $t$, denoted 
$\nabla f(t)$,  is defined as the number (provided it exists) with the property that for any $\varepsilon>0$, there exists a neighborhood $U$ of $t$ such that
$$|[f(\rho(t))-f(s)]-\nabla f(t)[\rho(t) - s]| \leq \epsilon |\rho(t)-s|$$
for all \( s \in U \) \cite{Guseinov}.
\begin{theorem}\label{nabladerrule}\cite{Peterson, Guseinov}
Let \( f: \mathbb{T} \to \mathbb{R} \) be a function, and let \( t \in \mathbb{T}_\kappa \). Then the following results hold:
\begin{enumerate}[label=(\roman*)]
\item  If f is $\nabla$-differentiable at $t$, then $f$ is continuous at  $t.$
\item  If $f$ is continuous at $t$ and $t$ is left-scattered, then $f$ is $\nabla$-differentiable at $t$ with
\begin{equation*}
\label{rrrsder}
\nabla f(t)=\frac{f(t)-
f(\rho(t))}{\nu(t)}.
\end{equation*}
\item If $t$ is  left-dense, then $f$ is $\nabla$-differentiable at $t$ iff the limit
$$\lim_{s\to t}\frac{f(s)-f(t)}{s-t}$$
exists. Then we have
$$\nabla f(t)=\lim_{s\to t}\frac{f(s)-f(t)}{s-t}.$$
\item If $f$ is $\nabla$-differentiable at $t$, then
\begin{equation}
\label{derrho}
f(\rho(t))=f(t)-\nabla f(t)\nu(t).
\end{equation}
\end{enumerate}
\end{theorem}
We will now present the intermediate value theorem for a continuous function on a time scale.
\begin{theorem}\label{IVT}\cite{Peterson}
Assume \( f: \mathbb{T} \to \mathbb{R} \) is continuous,  \( a < b \) are points in \( \mathbb{T} \), and
$
f(a)f(b) < 0.
$
Then, there exists \( c \in [a, b)\cap\mathbb{T}\) such that either \( f(c) = 0 \) or \(f(c)  f(\sigma(c))< 0.\)
\end{theorem}





\begin{definition}\cite{Zadeh} \label{def7}
	A fuzzy set \( u \) in a universe of discourse \( U \) is represented by a function $u:U\rightarrow [0,1]$, where \( u(x) \) indicates the membership degree of \( x \) to the fuzzy set \( u \).
\end{definition}

\begin{definition}\cite{Negoita}\label{def8}
	Let $u:U\rightarrow \lbrack 0,1]$ be a fuzzy set. The $\alpha$-level sets of $u$
	are defined as
	\[
	u_{\alpha}=\left\{ x\in U:u(x)\geq \alpha\right\}
	\]%
	for $0<\alpha\leq 1$. The $0$-level set of $u$ 
	\[
	u_{0}=cl\left\{ x\in U:u(x)>0\right\} 
	\]%
	is called the support of the fuzzy set $u$. Here $cl$ denotes the closure
	of the set $u.$
\end{definition}

\begin{definition}\cite{Negoita}\label{def9}
	Let \( u: \mathbb{R} \rightarrow [0,1] \) be a fuzzy subset of the real numbers. Then \( u \) is said to be a fuzzy number if it fulfills the following criteria:


    \begin{enumerate}[label=(\roman*)]
		\item \( u \) is normal, i.e., there exists an \( x_{0} \in \mathbb{R} \) such that \( u(x_{0}) = 1 \).

		\item  \( u \) is quasi-concave, i.e., for all \( \lambda \in [0,1] \), $x, y\in\mathbb{R}$, \( u(\lambda x + (1-\lambda)y) \geq \min\{u(x), u(y)\} \).

		\item  \( u \) is upper semicontinuous on \( \mathbb{R} \), i.e., for any given \( \varepsilon > 0 \), there exists a \( \delta > 0 \) such that \( u(x) - u(x_{0}) < \varepsilon \) whenever \( |x - x_{0}| < \delta \).

	\item  \( u \) is compactly supported, i.e., the set \( \text{cl}\{ x \in \mathbb{R} : u(x) > 0 \} \) is compact.
    \end{enumerate}
\end{definition}
Henceforth, we will use  $\mathbb{R}_{\cal{F}}$ to denote the the space of fuzzy numbers.

\begin{definition}\label{def10**}\cite{Bedebook}
	Let $a\leq b\leq c$ be real numbers. A fuzzy number $u:%
	%TCIMACRO{\U{211d} }%
	%BeginExpansion
	\mathbb{R}
	%EndExpansion
	\rightarrow \lbrack 0,1]$ is called a triangular fuzzy number if%
	\[
	u(x)=\left\{ 
	\begin{array}{cc}
		\frac{x-a}{b-a}; & a\leq x\leq b, \\ 
		\frac{c-x}{c-b}; & b\leq x\leq c, \\ 
		0; & otherwise.%
	\end{array}%
	\right. 
	\]%
	Such a fuzzy number is denoted by  $u=(a,b,c)$.
\end{definition}

If $\ u=(a,b,c)$ is a triangular fuzzy number, then its $\alpha$-level sets are given by
\[
[u]_{\alpha}=[a+\alpha(b-a),c+\alpha(b-c)].
\]

\begin{theorem}\label{Bede1}\cite{Bede}
Let us consider the functions $u^{-}, u^{+}: [0,1]\to\mathbb{R}$, that satisfy the following conditions:

(i) $u^{-}(\alpha)=u^{-}_{\alpha}\in \mathbb{R}$
 is a bounded, non-decreasing, left-continuous function
in $(0,1]$ and it is right-continuous at $0.$

(ii) $u^{+}(\alpha)=u^{+}_{\alpha}\in \mathbb{R}$ is a bounded, non-increasing, left-continuous function
in $(0,1]$ and it is right-continuous at $0.$

(iii) $u^{-}_{1}\leq u^{+}_{1}.$

Then there is a fuzzy number $u\in \mathbb{R}_{\cal{F}}$ that has $u^{-}_{\alpha}, u^{+}_{\alpha}$ as endpoints of its
$\alpha$-level sets, $[u]_{\alpha}$.

\end{theorem}

\begin{definition}\cite{Stefanini}\label{def11}
	Let $u,v\in $ $\mathbb{R}_{\mathcal{F}}$. The generalized Hukuhara difference ($gH$-difference) is the fuzzy number $w$, if it exists, such that%
	$$
	u\ominus _{gH}v=w\Longleftrightarrow u=v+w \text{   or   } v=u+(-1)w. $$
 \end{definition}   

\begin{remark}\label{remark1}\cite{Stefanini}
    The conditions for the existence of \( w = u \ominus_{g_H} v \) are as follows:

\textbf{Case (i):}  
    \begin{itemize}
