\begin{definition}\label{defder}\cite{you}
Let $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ be a fuzzy function, and let $t\in\mathbb{T}_{\kappa}.$ We define  the generalized Hukuhara $\nabla$-derivative of $f$ at \(t\), denoted by $\nabla_{gH} f(t),$ to be the element of $\mathbb{R}_{\cal{F}}$ (if it exists) with the property that  given any \( \varepsilon > 0\), there exists a neighborhood \( U_{\mathbb{T}}= (t- \delta, t+\delta) \cap \mathbb{T} \) of  $t$  for some \( \delta > 0 \) such that the following inequalities hold:
\begin{equation*}
D( f(t+h)\ominus
_{gH}f(\rho(t)),\nabla_{gH} f(t)(h+\nu(t)))  \leq \varepsilon |h+\nu(t)|,
\end{equation*}
\begin{equation*}
D( f(\rho(t))\ominus
_{gH}f(t-h),\nabla_{gH} f(t)(h-\nu(t))) \leq \varepsilon |h-\nu(t)|
\end{equation*}
	for all \( t-h, t+h \in U_{\mathbb{T}} \) with $0\leq h<\delta.$ 

     We say that $f$ is  \(\nabla_{gH} \)-differentiable at $t$ if its \(\nabla_{gH}\)-derivative exists at \(t\). Moreover, we say that $f$ is  \(\nabla_{gH} \)-differentiable on $\mathbb{T}_{\kappa}$ if its \(\nabla_{gH}\)-derivative exists at  each \(t\in\mathbb{T}_{\kappa}\).  The fuzzy function $\nabla_{gH} f:\mathbb{T}_{\kappa}\to\mathbb{R}_{\cal{F}}$ is then called the \(\nabla_{gH}\)-derivative of $f$ on $\mathbb{T}_{\kappa}.$
   \end{definition}

The definition of the  generalized Hukuhara $\nabla$-derivative can alternatively be expressed through the concept of limit as follows.
\begin{definition}
A fuzzy function $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ is  said to be \(\nabla_{gH} \)-differentiable at
$t\in\mathbb{T}_{\kappa}$ if there exists an element  $\nabla_{gH} f(t)\in \mathbb{R}_{\cal{F}}$ such that
$$\nabla_{gH} f(t)=\lim_{h\to 0}\frac{1}{h+\nu(t)}[f(t+h)\ominus
_{gH}f(\rho(t))].$$
\end{definition}

The following theorem was presented in \cite{you} without a proof; however, we will provide the proof here.
%   The following theorem was given in \cite{you} without proof, but we will provide its proof here.
   \begin{theorem}\cite{you}
   If the \(\nabla_{gH}\)-derivative of $f$ at $t\in\mathbb{T}_{\kappa}$  exists, then it is unique. Hence, the \(\nabla_{gH}\)-derivative is well defined.
   \end{theorem}

   \begin{proof}
   Let $^{1}\nabla_{gH} f(t)$ and $^{2}\nabla_{gH} f(t)$  both be the  $\nabla_{gH}$-derivative of $f$ at $t.$ Then
\begin{equation*} 
\begin{split}
   D&(^{1}\nabla_{gH} f(t),^{2}\nabla_{gH} f(t))\\&=\frac{1}{|h-\nu(t)|}D(^{1}\nabla_{gH} f(t)(h-\nu(t)),^{2}\nabla_{gH} f(t)(h-\nu(t)))\\
   &\leq \frac{1}{|h-\nu(t)|}D(^{1}\nabla_{gH} f(t)(h-\nu(t)),f(\rho(t))\ominus
_{gH}f(t-h))\\
&\,\,\,+ \frac{1}{|h-\nu(t)|} D(f(\rho(t))\ominus
_{gH}f(t-h),^{2}\nabla_{gH} f(t)(h-\nu(t)))\\
&\leq \varepsilon+\varepsilon=2\varepsilon
  \end{split}
\end{equation*}
 for all $|h-\nu(t)|\neq 0.$  Since $\varepsilon>0$ is arbitrary, we have $ D(^{1}\nabla_{gH} f(t),^{2}\nabla_{gH}f(t))=0$ and hence $^{1}\nabla_{gH} f(t)=^{2}\nabla_{gH} f(t).$
 \end{proof}
\begin{theorem}\label{derivative}\cite{you}
Assume $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ is a  function, and let $t\in\mathbb{T}_{\kappa}$. Then, we have the followings:
\begin{enumerate}[label=(\roman*)]


\item  If $f$ is continuous at $t$ and $t$ is left-scattered, then $f$ is $\nabla_{gH}$-differentiable at $t$ with
\begin{equation}
\label{rsder}
\nabla_{gH} f(t)=\frac{f(t)\ominus
_{gH}f(\rho(t))}{\nu(t)}.
\end{equation}
\item If $t$ is  left-dense, then $f$ is $\nabla_{gH}$-differentiable at $t$ if and only if  the following two limits exist:
$$\lim_{h\to 0^+}\frac{f(t+h)\ominus
_{gH}f(t)}{h}\quad\text{and} \quad \lim_{h\to 0^+}\frac{f(t)\ominus
_{gH}f(t-h)}{h},$$
and the equality
\begin{equation}
\label{rdderlim}
\lim_{h\to 0^+}\frac{f(t+h)\ominus
_{gH}f(t)}{h}= \lim_{h\to 0^+}\frac{f(t)\ominus
_{gH}f(t-h)}{h}=\nabla_{gH} f(t)
\end{equation}
holds.
\end{enumerate}
\end{theorem}

Let $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ be a fuzzy function. For each $\alpha\in[0,1],$ associated to $f,$
we define the family of interval valued functions $f_{\alpha}:\mathbb{T}\to{\cal K}_C$ given by
$f_{\alpha}(t)=[f(t)]_{\alpha},$ where ${\cal K}_C$ is  the family of all bounded closed intervals in $\mathbb{R}.$ For any $\alpha\in[0,1],$  we denote
$f_{\alpha}(t)=[f_{\alpha }^{-}(t), f_{\alpha }^{+}(t)],$ $t\in\mathbb{T}.$ Here, for each $\alpha\in[0,1],$  the endpoint functions $f_{\alpha }^{-},f_{\alpha }^{+}:\mathbb{T}\to\mathbb{R}$ are called the lower and upper  functions of $f,$ respectively.

In the following theorem, we focus on examining the relationship between the $\nabla_{gH}$-differentiability of a fuzzy function $f$ and the $\nabla_{gH}$-differentiability of the family of interval valued functions $f_{\alpha}.$


\begin{theorem}\label{Thmlevel}
If $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$  is $\nabla_{gH}$-differentiable at $t\in\mathbb{T}_{\kappa},$  then the family of interval valued functions $f_{\alpha}:\mathbb{T}\to{\cal K}_C$ is 
$\nabla_{gH}$-differentiable at $t$ uniformly in $\alpha\in[0,1]$. Furthermore, the $\nabla_{gH}$-derivative of $f_{\alpha}$ at $t$ is given by
$$\nabla_{gH} f_{\alpha}(t)=[\nabla_{gH} f(t)]_{\alpha }$$
for all $\alpha\in[0,1].$
\end{theorem}

\begin{proof}
Assume that $f$ is $\nabla_{gH}$-differentiable at $t.$ Let $\varepsilon>0$ be given.  Since $f$ is $\nabla_{gH}$-differentiable at $t$, there is a neighborhood $U_{\mathbb{T}}$ of $t$ such that
\begin{equation*}
\begin{split}
&D\left(\frac{1}{h+\nu(t)}[f(t+h)\ominus
_{gH}f(\rho(t))],\nabla_{gH} f(t)\right)\\
&=\underset{\alpha\in[0,1]}{\sup} D_H\left(\frac{1}{h+\nu(t)}\{[f(t+h)]_{\alpha}\ominus
_{gH}[f(\rho(t))]_{\alpha}\},[\nabla_{gH} f(t)]_{\alpha}\right)\leq\varepsilon\\
\end{split}
\end{equation*}
for all $t+h\in U_{\mathbb{T}}$ with $|h|>0.$ In view of the definition of the metric $D,$ this implies that $f_{\alpha}$ is $\nabla_{gH}$-differentiable at $t$  uniformly in $\alpha\in[0,1]$, and $$\nabla_{gH} f_{\alpha}(t)=[\nabla_{gH} f(t)]_{\alpha }$$ for all $\alpha\in[0,1].$
\end{proof}



\begin{theorem}\label{derivativeleftscattered}
Let $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ be a function that is $\nabla_{gH}$-differentiable at a point $t\in \mathbb{T}_{\kappa}$, where $t$ is both left-scattered and right-dense. Additionally, assume that for every   \( \delta > 0 \), there exist \( h, k\in\mathbb{R}\) such that \( 0 < h, k < \delta \) and \( t + h, t+k \in \mathbb{T} \), and that the Hukuhara differences 
$$f(t+h)\ominus_H f(\rho(t))\quad\text{and}\quad
f(\rho(t))\ominus_H f(t+k)$$  are both defined. Then, $\nabla_{gH}f(t)$ is a crisp number.
%every neighborhood $U_{\mathbb{T}}=(t- \delta, t+\delta) \cap \mathbb{T}$ of $t$ for some \( \delta > 0 \), of $t,$ contains points $t+h_1$ and  such that the Hukuhara differences $f(t+h)\ominus_H f(t)$ 
\end{theorem}
\begin{proof}
Suppose the function $f$ is $\nabla_{gH}$-differentiable at a point $t\in\mathbb{T}_{\kappa},$ where $t$ is both left-scattered and right-dense.  Assuming the relevant Hukuhara differences are well-defined, then for each  \( n \in \mathbb{N} \), there exist \( h_n, h_n^{\prime} \in \mathbb{R} \) satisfying $0 < h_n<1/n,$ $ 0<h_n^{\prime}< 1/n, 
$ and such that $t+h_n, t+h_n^{\prime}\in\mathbb{T}.$  For these choices of $h_n$ and  $h_n^{\prime}$, the following inequalities hold for all \( \alpha \in [0,1] \):
\begin{equation}\label{EQ113}
\text{len}([f(t+h_n)]_{\alpha})\geq \text{len}([f(\rho(t))]_{\alpha}),
\end{equation}
\begin{equation}\label{EQ213}
\text{len}([f(t+h_h^{\prime})]_{\alpha})\leq \text{len}([f(\rho(t))]_{\alpha}).
\end{equation}

Based on this, define two sequences $\{w_n\}$ and  $\{w_n^{\prime}\}$  as:
\begin{equation*}
\begin{split}
 w_n&=\frac{1}{h_n+\nu(t)}[f(t+h_n)\ominus_{gH}f(\rho(t))],\\
 w_n^{\prime}&=\frac{1}{h_n^{\prime}+\nu(t)}[f(t+h_n^{\prime})\ominus_{gH}f(\rho(t))].
 \end{split}
 \end{equation*}

Using the inequalities   \eqref{EQ113} and \eqref{EQ213}, we can express the  $\alpha $-level sets of $w_n$ and $w_n^{\prime}$ for all \( \alpha \in [0,1] \) as:
\begin{equation}\label{EQ31}
[w_n]_{\alpha}=\frac{1}{h_n+\nu(t)}[f_{\alpha }^{-}(t+h_n)-f_{\alpha }^{-}(\rho(t)),f_{\alpha }^{+}(t+h_n)-f_{\alpha }^{+}(\rho(t))],
\end{equation}
\begin{equation}\label{EQ41}
[w_n^{\prime}]_{\alpha}=\frac{1}{h_n^{\prime}+\nu(t)}[f_{\alpha }^{+}(t+h_n^{\prime})-f_{\alpha }^{+}(\rho(t)),f_{\alpha }^{-}(t+h_n^{\prime})-f_{\alpha }^{-}(\rho(t))].
\end{equation}
By combining  the expressions \eqref{EQ31} and \eqref{EQ41} with Theorem \ref{Thmlevel},  it follows that the right-sided nabla derivatives 
 \( \nabla_+f_{\alpha}^{-}(t) \) and \(\nabla_+ f_{\alpha}^{+}(t) \) exist  for all $\alpha \in [0,1],$ and the convergence with respect to
$\alpha$  is uniform.  Furthermore, the derivatives are equal for all $\alpha \in [0,1],$  i.e.,  \(\nabla_{+} f_{\alpha}^{-}(t) = \nabla_{+}f_{\alpha}^{+}(t) \). 
 This implies that the generalized Hukuhara nabla derivative $\nabla_{gH} f(t)$ is a crisp number.
\end{proof}
In \cite{you}, the proof of the following theorem is  incomplete. Hence, we have reproven it using the result we have obtained in Theorem \ref{derivativeleftscattered}.
\begin{theorem}
Let $f:\mathbb{T}\to\mathbb{R}_{\cal{F}}$ be a  function, and let $t\in\mathbb{T}_{\kappa}$. 
 If $f$  is $\nabla_{gH}$-differentiable at $t,$ then $f$ is continuous at $t.$ 
\end{theorem}
\begin{proof}
Firstly, if $f$ is $\nabla_{gH}$-differentiable at 
 $t$ and $t$ is isolated, then it is clear that $f$ is continuous at $t.$
Now, assume that  $f$ is $\nabla_{gH}$-differentiable at 
 $t$ and $t$ is left-dense. Let $\varepsilon\in(0,1)$ be given. Define $\varepsilon^{*}=\varepsilon[1+||\nabla_{gH} f(t)||_F]^{-1}.$  Then,  $\varepsilon^{*}\in(0,1).$ Here, for $u\in\mathbb{R}_{\cal{F}},  ||u||_{F}=D(u,\tilde{0})$, where $\tilde{0}$ is the zero element of $\mathbb{R}_{\cal{F}}.$ By Definition \ref{defder},  there exists a neighborhood $U_{\mathbb{T}}$  of  $t$ such that 
\begin{equation*}
D( f(t+h)\ominus
_{gH}f(t),h\nabla_{gH} f(t))  \leq \varepsilon^* h
\end{equation*}
and
\begin{equation*}
D( f(t)\ominus
_{gH}f(t-h),h\nabla_{gH} f(t))  \leq \varepsilon^* h 
\end{equation*}
for all \( t-h, t+h \in U_{\mathbb{T}} \) with $h\geq 0.$ Hence, for all  \( t-h, t+h \in U_{\mathbb{T}}\cap(t-\varepsilon^*,t+\varepsilon^*)\) with $0\leq h<\varepsilon^*$, we have 
\begin{equation*}
\begin{split}
D(f(t-h),f(t))
&=D(f(t-h)\ominus
_{gH}f(t),\tilde{0})\\
%&=D(f(t+h)\ominus
%_{gH}f(\rho(t)),0)+D(f(t)\ominus_{gH}f(\rho(t)),0)\\
&\leq D(f(t-h)\ominus
_{gH}f(t),(-1)h\nabla_{gH} f(t))+D((-1)h\nabla_{gH} f(t),\tilde{0})\\
&=D(f(t)\ominus
_{gH}f(t-h),h\nabla_{gH} f(t))+h D(\nabla_{gH} f(t),\tilde{0})\\
&=D(f(t)\ominus
_{gH}f(t-h),h\nabla_{gH} f(t))+h||\nabla_{gH} f(t)||_F\\
&\leq \varepsilon^* h+h||\nabla_{gH} f(t)||_F\\
&<\varepsilon^* h+\varepsilon^* ||\nabla_{gH} f(t)||_F\\
&<(1+||\nabla_{gH} f(t)||_F)\varepsilon^* \\
&=\varepsilon.
\end{split}
\end{equation*} 
Thus, we conclude that
$$\lim_{h\to 0^+}f(t-h)=f(t).$$
 If $t$ is right-scattered, then it is clear that f is right-continuous at $t.$ Otherwise, it is similarly straightforward to show that
$$\lim_{h\to 0^+}f(t+h)=f(t).$$
Therefore, $f$ is continuous at $t.$
