\section{Restriction Kernels for $C_p\times C_p$}\label{sec:restker2}

We have already determined a basis for the restriction kernel $\mathcal{K}\kerlin(E_2)$ for $E_2 = C_p\times C_p$ in Corollary \ref{cor:resker2}:
\[
\mathcal B = \{F_1\}\cup \bigcup_{1<\langle t\rangle < E_2} \{ F_{t, \phi}\mid 1\not =\phi\in\widehat{\Aut(\langle t\rangle)} \}
\]
In this section we determine its $\mathbb C[\Aut(E_2)]$-module structure. It is clear that the basis vector $F_1$ generates a trivial $\mathbb C[\Aut(E_2)]$-submodule and a complement of the submodule is generated by the rest
\[
\mathcal B':= \bigcup_{1<\langle t\rangle < E_2} \{ F_{t, \phi}\mid 1\not =\phi\in\widehat{\Aut(\langle t\rangle)}\}
\]
of the basis vectors. Hence we concentrate on the span of $\mathcal{B}'$. We begin by describing the structure of $\Aut(E_2)$.


\begin{nothing} {\textbf{Automorphism group of $E_2$.}} It is known that the group $\Aut(E_2)$ is isomorphic to the general linear group $\gl$ of $2\times 2$-matrices with entries in the finite field $\mathbb F_p$ of $p$-elements. We fix an isomorphism. Write $E_2 = \langle x\rangle \times \langle y\rangle$. We may regard $E_2$ as the space of column vectors of length 2 with basis $x = \begin{pmatrix}
    1\\ 0
\end{pmatrix}$ and $y = \begin{pmatrix}
    0 \\ 1
\end{pmatrix}$ and hence any automorphism $\alpha : E_2\to E_2$ can be represented by a matrix where the columns are $\alpha(x)$ and $\alpha(y)$, that is, 
\[
\alpha = \begin{pmatrix}
    a & b\\
    c & d
\end{pmatrix}
\]
if $\alpha(x) = x^ay^c$ and $\alpha(y) = x^by^d$. With this isomorphism, we make the  identification $\Aut(E_2) = \gl$.

Let $1\not = T < E_2$. Then $T$ is cyclic of order $p$ and hence is generated by any of its non-identity elements. To determine the explicit action of the automorphism group, we index these subgroups as follows. Let $\mathfrak C = \{ x, y, xy, x^2y, \ldots, x^{p-1}y\}$. Then clearly there is a bijective correspondence between the subgroups $T$ of order $p$ in $E_2$ and the elements of $\mathfrak C$ given by $T\longleftrightarrow g$ if and only if $T= \langle g\rangle$. We denote the subgroup generated by $g$ by $T_g$. Hence the set of subgroups of order $p$ of $E_2$ is
\[
\mathfrak S = \{ T_g\mid g\in\mathfrak C \} = \{ T_x, T_y, T_{xy}, T_{x^2y}, \ldots, T_{x^{p-1}y} \}
\]
For any $g\in \mathfrak C$, we denote the automorphism group of $T_g$ by $\Gamma_g$. We fix primitive root $s$ modulo $p$ and define a generator $\gamma_g\in\Gamma_g$ as the $s$-th power map. We also write $\hat\Gamma_g$ for the group of irreducible characters of $\Gamma_g$.

The generator $\gamma_g\in\Gamma_g$ is canonical in the following sense. First it is the restriction of the automorphism $\gamma = \begin{pmatrix}
    s & 0 \\ 0&s
\end{pmatrix}$ to $T_g$ for any $g$. Moreover, since $\gamma$ is diagonal, it commutes with all the elements in $\gl$. Therefore for any $\alpha\in\gl$ we have 
\[
\alpha\circ\gamma_g = \gamma_{\alpha(g)}\circ \alpha.
\]
In particular, we get that the isomorphisms 
\[
\tilde\alpha:\Gamma_g\to \Gamma_{\alpha(g)},\, \gamma\mapsto {}^\alpha\gamma
\]
induced by $\alpha$ is actually given by mapping $\gamma_{g}$ to $\gamma_{\alpha(g)}$. Since $\gamma_g$ is independent of the choice of the generator of $T_g$, we conclude that $\tilde\alpha$ is independent of $\alpha$, in the sense that if $T_{\alpha(g)} = T_{\beta(g)}$ for some $\beta\in\gl$, then $\tilde\alpha=\tilde\beta$. 

The isomorphism $\tilde\alpha$ induces an isomorphism between the corresponding groups of characters:
\[
\hat\alpha: \hat\Gamma_g\to \hat\Gamma_{\alpha(g)},\, \phi\mapsto {}^\alpha\phi
\]
where ${}^\alpha\phi({}^\alpha\gamma) = \phi(\gamma)$. Notice that, as in the previous case, the induced map $\hat\alpha$ depends only on the group $T_{\alpha(x)}$ and not on the particular $\beta\in\gl$ such that $T_{\beta(x)} = T_{\alpha(x)}$, that is, we have ${}^\alpha\phi = {}^\beta\phi$ for any $\alpha, \beta\in\gl$ with $T_{\beta(x)} = T_{\alpha(x)}$.

Finally one may consider the $\gl$-action on the set $\mathfrak S$ via automorphisms, that is, for any $\alpha\in\gl$ and $g\in \mathfrak C$, $\alpha\cdot T_g = T_{\alpha(g)}$. In general, $\alpha(g)$ is not an element of $\mathfrak C$. To determine the corresponding element of $\mathfrak C$, write $\alpha =\begin{pmatrix}
    a & b \\ c & d
\end{pmatrix}$ and $x^iy\in E_2$. Then
\[
\alpha(x^iy) = \begin{pmatrix}
    a & b \\ c & d
\end{pmatrix} \cdot \begin{pmatrix}
    i \\ 1
\end{pmatrix} = \begin{pmatrix}
    ai + b  \\ ci + d
\end{pmatrix} = x^{ai + b}y^{ci+d}
\]
Writing $f$ for the multiplicative inverse of $ci+d$, we get
\[
\alpha\cdot T_{x^iy} = T_{x^{(ai+b)f}y}
\]
Similarly we have
\[
\alpha\cdot T_x = \begin{cases}
              T_{x^{ac^{-1}}y} & \text{if } c\not = 0,\\
              T_x & \text{ otherwise.}
          \end{cases}  
          \]
From this equality it is clear that the $\gl$-action on $\mathfrak S$ is transitive. Moreover the stabilizer of $T_x$ in $\gl$ is the subgroup of upper triangular matrices, the so-called Borel subgroup of $\gl$.
\end{nothing}
\begin{nothing}
Now we are ready to determine $\mathcal{K}\kerlin(E_2)$ as a $\mathbb C[\gl]$-module. We write
\[
\mathbb C[\mathcal B]:= \{ \mathbb C[F_{g, \phi}]\mid F_{g, \phi}\in \mathcal B\}
\]
for the set of lines in $\kerlin(G)$ parameterized by the set $\mathcal{B}$.
\end{nothing}
\begin{theorem}\label{thm:cpcpfinal}
    Assume the above notation.

    {\rm (a)} The set $\mathbb C[\mathcal{B}]$ is a monomial $\gl$-set via the action induced from the action of $\gl$ on $\kerlin(G)$.

    \smallskip
    {\rm (b)} There is a unique fixed point in $\mathcal B$, namely $F_1$.

    \smallskip
    {\rm (c)} The $\gl$-orbits in $\mathbb C[\mathcal B]$ of size $\ge 2$ are in one-to-one correspondence with the non-trivial irreducible characters of $\Gamma_x$.

    \smallskip
    {\rm (d)} The stabilizer in $\gl$ of any of these orbits is conjugate to the Borel subgroup $B$ of $\gl$.

    \smallskip
    {\rm (e)} The $B$-action on the line $\mathbb C[F_{x, \phi}]$ is given by the linear character $$\tilde\phi: B\to \mathbb C^\times, \begin{pmatrix}
        a & b\\ 0 & d
    \end{pmatrix}\mapsto \phi(a)$$ of $B$. 
\end{theorem}
\begin{proof} We first note that part Part {\rm (b)} is trivial. For the rest of the theorem, we begin by proving that the action of $\gl$ on $\kerlin(E_2)$ induces a permutation action on $\mathbb C[\mathcal B]$. For simplicity, we consider the $\gl$-action on $F_{x, \phi}$ for a fixed character $\phi\in\hat\Gamma_x$. Let $\alpha\in\gl$. Then
\begin{eqnarray*}
    \alpha\cdot F_{x,\phi} &=& \sum_{\sigma\in\Aut(T_x)}\overline{\phi(\sigma)} \alpha(e_{G, \sigma(x)}^G)\\
    &=& \sum_{\sigma\in\Aut(T_x)}\overline{\phi(\sigma)} e_{G, \alpha\sigma(x)}^G\\
    &=& \sum_{\delta\in\Aut(T_{\alpha(x)})}\overline{\phi(\alpha\delta\alpha^{-1})} e_{G, \delta\alpha(x)}^G\\
    &=& \sum_{\delta\in\Aut(T_{\alpha(x)})}\overline{{}^\alpha\phi(\delta)} e_{G, \delta\alpha(x)}^G
\end{eqnarray*}
We divide the rest of the calculation into two cases. First suppose $\alpha = \begin{pmatrix}
    a & b\\ 0 & d
\end{pmatrix}$ is an element in the Borel subgroup. Then $\alpha(x) = x^a$ and hence $\alpha' :=\alpha\mid_{T_x}\in\Gamma_x$. In particular $T_{\alpha(x)} = T_x$ and $\delta':= \delta\alpha'\in\Gamma_x$ for any $\delta\in\Gamma_x$. The above sum becomes
\begin{eqnarray*}
  \alpha\cdot F_{x,\phi} &=&\sum_{\delta'\in\Aut(T_{x})}\overline{\phi(\delta'(\alpha')^{-1})} e_{G, \delta'(x)}^G\\
&=&\phi(\alpha')\sum_{\delta'\in\Aut(T_{x})}\overline{\phi(\delta'} e_{G, \delta'(x)}^G\\
&=& \phi(\alpha') F_{x, \phi}.
\end{eqnarray*}
This calculation also shows that the Borel subgroup stabilizes the line $\mathbb C[F_{x, \phi}]$. Since it is the stabilizer of $T_x$, we conclude that 
\[
B = \text{Stab}_{\gl}(\mathbb C[F_{x, \phi}])
\]
Moreover we obtain that if $\phi\not = \psi$, then the lines $\mathbb C[F_{x, \phi}]$ and $\mathbb C[F_{x, \psi}]$ are not in the same $\gl$-orbit.

Next suppose $\alpha = \begin{pmatrix}
    a&b\\c&d
\end{pmatrix}$ with $c\not = 0$. Then $T_{\alpha(x)} = T_{x^{ac^{-1}}y}$. Also let $\delta_c: T_{\alpha(x)}\to T_{\alpha(x)}, g\mapsto g^c$. Then 
\begin{eqnarray*}
  \alpha\cdot F_{x,\phi} &=& 
\sum_{\delta\in\Aut(T_{\alpha(x)})}\overline{{}^\alpha\phi(\delta)} e_{G, \delta\alpha(x)}^G\\
&=& \sum_{\delta'\in\Aut(T_{\alpha(x)})}\overline{{}^\alpha\phi(\delta'\delta_c^{-1})} e_{G, \delta'(x^{ac^{-1}}y)}^G\\
&=& {}^\alpha\phi(\delta_c)\sum_{\delta'\in\Aut(T_{\alpha(x)})}\overline{{}^\alpha\phi(\delta')} e_{G, \delta'(x^{ac^{-1}}y)}^G\\
&=& {}^\alpha\phi(\delta_c)F_{x^{ac^{-1}y}, {}^\alpha\phi}
\end{eqnarray*}
It is now clear that the group $\gl$ acts on $\mathbb C[\mathcal{B}]$ by permutations. By the previous case, we already know that there are at least $p-2$-orbits in $\mathbb C[\mathcal{B}]$ and each orbit is isomorphic to the coset space $\gl/B$. Hence these orbits cover at least $(p+1)(p-2)$ elements. But the total number of elements is $1+(p+1)(p-2)$. The additional orbit comes from the fixed line $\mathbb C[F_1]$. 

\end{proof}

\begin{nothing}
    By the above theorem for each non-trivial irreducible character $\phi$ of $\Gamma_x$, there is a direct summand of $\mathcal{K}\kerlin(E_2)$ isomorphic to the induced $\mathbb C[\gl]$-module $\ind_B^{\gl}\phi_1$ where $\phi_1: B\to \mathbb C^\times$ is given by 
    \[
    \phi_1\begin{pmatrix}
        a & b\\ 0& d
    \end{pmatrix} = \phi(a).
    \]
    By the classification of irreducible characters of $\gl$, given in Theorem 8.12 in \cite{Shapiro}, this module is irreducible. He we obtain the following result from which Theorem \ref{thm:main}(c) follows.
\end{nothing}
\begin{theorem}%[Structure of \( \mathcal{K}\kerlin(G) \) for \( G \cong C_p \times C_p \)]
\label{thm:cpcpfinal2}
    Assume the above notation. 
    The restriction kernel \( \mathcal{K}\kerlin(G) \) decomposes as:
\[
\mathcal{K}\kerlin(G) \cong \begin{cases}
\mathbb{C} \oplus \bigoplus_{1\neq \phi\in \hat\Gamma_x} \ind_B^{\gl}\phi_1, & \text{if } p > 2, \\
\mathbb{C}, & \text{if } p = 2,
\end{cases}
\]
Moreover the right-hand side is a direct sum of irreducible $\mathbb C[\gl]$-modules.
\end{theorem}

