\section{Restriction Kernels for $C_{2^m}\times C_2$}\label{sec:restker3}

This section is devoted to the determination of the irreducible constituents of $\mathcal K\kerlint(C_{2^m}\times C_2)$ as a $\mathbb C\Gamma$-module where we put $\Gamma := \Aut(C_{2^m}\times C_2)$. We collect necessary results about the group $\Gamma$ in the Appendix. For the rest of this section, we assume the notation from the appendix, whenever needed.


\begin{nothing} {\bf The case $G= C_4\times C_2$.} To begin with, we separate this case 
because the automorphism group of $G$ is an exception.  We have $\Gamma  \cong D_8$, the dihedral group of order 8 and this is not a special case of the presentation given in \cite{BC} (and also in the appendix). Put $C_4\times C_2 = \langle x,  y\mid x^4 = y^2 = 1, xy = yx\rangle$ and $\Gamma = \langle a, b\mid a^4 = b^2 = 1, bab = a^3\rangle$. Here we identify $a$ by the automorphism $x\mapsto xy, y\mapsto x^2y$ and $b$ as the automorphism $x\mapsto x^3, y\mapsto y$. The following theorem settles this case and proves a special case of Part (d) of Theorem \ref{thm:main}.
\end{nothing}

\begin{theorem}
    Assume the above notation. Then
    \begin{enumerate}
        \item[(i)] The set $\mathcal{B}_2$ is a transitive monomial basis for the $\mathbb C[\Gamma]$-module $\mathcal{K}\kerlint(G)$.
        \item[(ii)] We have \[\Sigma:= \text{Stab}_\Gamma(\mathbb C[E_x]) = \langle a^2, b\rangle\cong C_2\times C_2\] and for any $\sigma\in\Sigma$, the equality
        \[\sigma\cdot E_x = \phi(\sigma)\cdot E_x\]
        holds. Here $\phi = \infl_{\Sigma/\langle a^2b\rangle}^\Sigma (-1)$ where $(-1)$ is the non-trivial irreducible character of $\Sigma/\langle a^2b\rangle$.
        \item[(iii)] The $\mathbb C[\Gamma]$-module $\mathcal{K}\kerlint(G)$ is isomorphic to the unique 2-dimensional irreducible $\mathbb C[\Gamma]$-module. More precisely
        \[
        \mathcal{K}\kerlint(C_4\times C_2) \cong \ind_\Sigma^\Gamma\infl_{\Sigma/\langle a^2b\rangle}^\Sigma (-1).
        \]
    \end{enumerate}
\end{theorem}
\begin{proof}
With the above notation, the set $\mathcal M/Z$ of $Z$-orbits of $\mathcal{M}$ becomes
\[
\mathcal M = \big\{ \{x, x^3\}, \{xy, x^3y\}\big\}
\]
Hence the basis $\mathcal B_2$ consists of the two elements $E_x$ and $E_{xy}$ where 
\[
E_x = e_{G, x}^G - e_{G, x^3}^G \text{ and } E_{xy} = e_{G, xy}^G - e_{G, x^3y}^G
\]
The action of $\Gamma$ on $\mathcal{B}_2$ can be evaluated using the following table.
\begin{center}
    \begin{tabular}{c|cc}
         & $a$ & $b$  \\ \hline
         $E_x$ & $E_{xy}$ & $-E_{x}$  \\
         $E_{xy}$ & $-E_{x}$ & $-E_{xy}$  \\
           \end{tabular}
\end{center}
It is now clear that $\mathcal B_2$ is a monomial basis for $\mathcal{K}\kerlint(G)$ and the stabilizer $\Sigma$ of 
the line $\mathbb C[E_x]$ is the subgroup generated by $a^2$ and $b$. Moreover the action of $\Sigma$ on 
$\mathbb C[E_x]$ is given by the following homomorphism $\Sigma\to \mathbb C^\times$.
\begin{center}
    \begin{tabular}{c|cccc}
         & 1 & $a^2$ & $b$ & $a^2b$  \\ \midrule 
         $\phi:= \infl_{\Sigma/\langle a^2b\rangle}^\Sigma (-1)$ & $1$ & $-1$ & $-1$ & $1$  \\
           \end{tabular}
\end{center}
Here by $(-1)$ (and below by $\mathbb C_{(-1)}$) we denote the non-trivial irreducible character (module) of the group $\Sigma/\langle a^2b\rangle$. Therefore we obtain 
\[
\mathcal{K}\kerlint(G)\cong \ind_\Sigma^\Gamma \infl_{\Sigma/\langle a^2b\rangle}^\Sigma \mathbb C_{(-1)}= \ind_\Sigma^\Gamma C_\phi
\]
as $\mathbb C\Gamma$-modules. In particular $\mathcal{K}\kerlint(G)$ is isomorphic to the unique irreducible $\mathbb C\Gamma$-module of dimension 2.
\end{proof}

\begin{nothing} {\bf The case $m>2$.}
Now we assume $m>2$. In this case, the set $\mathcal B_2$ simplifies again since there are only 2 subgroups of order $2^m$ and the subgroup $Z=\langle z\rangle$ has order 2. Writing $G = \langle x, y\mid x^{2^m} = y^2 = 1, xy = yx\rangle$, we have $z= x^{2^{m-1}}$. With this notation, the list of elements of order $2^m$ is
\[
\mathcal M= \{ x^iy^j\mid 0<i< m, i\equiv 1 (\text{mod }2), j= 0,1 \}
\]
Also for any element $g\in\mathcal M$, we clearly have $E_g = -E_{gz}$. Therefore the line $\mathcal K_{gZ}$ can be represented as $\mathbb C[E_g]$ and a basis for $\mathcal K\kerlint(G)$ is given by 
\[
\mathcal B_2= \{ E_{x^iy^j}\mid 0<i<m/2 , i\equiv 1 (\text{mod }2), j= 0,1 \}
\]
\end{nothing}
\begin{lemma}
The set \(\mathbb{C}[\mathcal{B}_2]\) forms a transitive monomial \(\Gamma\)-set, with the action of \(\Gamma\) defined via the isomorphism biset \(\operatorname{Iso}_G^a\) for each automorphism \(a \in \Gamma\). Moreover:
\begin{enumerate}
    \item[\textbf{(a)}] The stabilizer subgroup of \(\Gamma\) at \(\mathbb{C}[E_x]\) is \[\Sigma := \operatorname{Stab}_\Gamma(\mathbb{C}[E_x]) = \langle a_2^{2^{m-3}}, b \rangle \unlhd \Gamma.\]
    \item[\textbf{(b)}] The subgroup \(\Sigma\) acts on \(\mathbb{C}[E_x]\) via the character \(\phi_x := \operatorname{Inf}_{\Sigma / \langle b \rangle}^\Sigma(-1)\), where \(-1\) denotes the non-trivial character of \(\Sigma / \langle b \rangle\).
\end{enumerate}
\end{lemma}

\begin{proof}
First, we verify that the \(\Gamma\)-action is monomial. Observe that the element \(z\) is fixed under any automorphism \(a \in \Gamma\). For a given \(a \in \Gamma\), we compute:
\[
\iso_G^a(E_g) = \iso_G^a(e_{G, g}^G - e_{G, gz}^G) 
= e_{G, a(g)}^G - e_{G, a(g)z}^G = \pm E_h,
\]
where \(h = a(g)\) or \(h = a(g)z\), depending on the action of \(a\). This shows that \(\iso_G^a(E_g)\) lies in the same orbit under \(\Gamma\), confirming that the action is monomial. Transitivity follows from the fact that \(\Gamma\) acts transitively on the set of generators.

Next, we determine the stabilizer subgroup \(\Sigma = \operatorname{Stab}_\Gamma(\mathbb{C} [E_x])\). From Appendix~\ref{app:evenp}, \(\Gamma\) is generated by the elements \(a_1\), \(a_2\), \(b\), and \(c\). Using the table in the appendix, we compute the action of these elements on \(E_x\):
\[
\begin{array}{c|cccc}
 & a_1 & a_2 & b & c \\ \hline
E_x & E_{x^{-1}} & E_{x^5} & E_x & E_{xy}.
\end{array}
\]

Note that, since \(m > 2\), the inverse \(x^{-1}\) is distinct from both \(x\) and \(xz\). Thus, \(E_{x^{-1}} \neq \pm E_x\). Similarly, it is evident that \(E_{xy} \neq \pm E_x\). Therefore, \(\langle a_1, c \rangle \not\subseteq \Sigma\).

On the other hand, since \(a_2\) has order \(2^{m-2}\), the element \(\tilde{a}_2 := a_2^{2^{m-3}}\) is in \(\Sigma\). Furthermore, for \(i \notin \{0, 2^{m-3}\}\), \(a_2^i \notin \Sigma\). The action of \(\tilde{a}_2\) on \(E_x\) is given by:
\[
\tilde{a}_2(E_x) = -E_x,
\]
because \(5^{2^{m-3}} = 1 + 2^{m-1}\).

Additionally, \(b \in \Sigma\) trivially, as \(b(E_x) = E_x\). Combining these, we conclude:
\[
\Sigma = \langle \tilde{a}_2, b \rangle.
\]

Finally, we describe the action of \(\Sigma\) on \(\mathbb{C} [E_x]\). The subgroup \(\Sigma\) acts via the homomorphism:
\[
\phi_x: \Sigma \to \mathbb{C}^\times,
\]
where \(\phi_x(\tilde{a}_2) = -1\) and \(\phi_x(b) = 1\). This gives the following isomorphism of \(\mathbb{C}\Gamma\)-modules:
\[
\mathcal{K}\kerlint(G) \cong \operatorname{Ind}_\Sigma^\Gamma \phi_x.
\]
\end{proof}



The final step is to determine the irreducible summands of this monomial module. We have the following theorem which is Part (d) of Theorem \ref{thm:main}.
\begin{theorem}
    The $\mathbb C[\Gamma]$-module $\mathcal{K}\kerlint(G)$ contains each irreducible $\mathbb C[\Gamma]$-module of dimension 2 as a direct summand exactly once and has no other irreducible summands. 
\end{theorem}
\begin{proof}
By the previous lemma, we already know that $\mathcal{K}\kerlint(G)$ is induced from the 1-dimensional $\mathbb C[\Sigma]$-module $\phi_x$. To determine the irreducible summands, we first consider the inertia subgroup of $\phi_x$. Note that $\phi_x$ is not $\Gamma$-invariant. Indeed since $b^c = \tilde a_2b$, we have 
\[
({}^c\phi_x)(b) = \phi_x(b^c)\neq \phi_x(b).
\]
Its $\Gamma$-orbit consists of two elements, namely $\phi_x$ and ${}^c\phi_x$. In particular we also have
\[
\mathcal K\kerlint(G) \cong \ind_\Sigma^\Gamma {}^c\phi_x.
\]

Although it will not be used immediately, we determine ${}^c\phi_x$ more explicitly to refer to it later. It is straightforward to see that, following the above notation, the stabilizer of the line $\mathbb C[E_{xy}]$ is also equal to $\Sigma$. The action of generators of $\Gamma$ on $E_{xy}$ is given in the following table.
\begin{center}
    \begin{tabular}{c|cccc}
         & $a_1$ & $a_2$ & $b$ & $c$ \\ \hline
         $E_{xy}$ & $E_{x^{-1}y}$ & $E_{x^5y}$ & $E_{xzy}$ & $E_{x}$\\
           \end{tabular}
\end{center}
The character $\phi_{xy}$ of this action is given by 
\[
\phi_{xy}(\tilde a_2) = -1, \ \phi_{xy}(b)= -1
\]
It is clear that we have ${}^c\phi_x = \phi_{xy}$. 

Returning back to the inertia subgroup $I$ of $\phi_x$ in $\Gamma$, since $a_1, a_2$ are central and $b\in\Sigma=Z(\Sigma)$, the inertia subgroup $I$ of $\phi_x$ in $\Gamma$ contains $\langle a_1, a_2, b\rangle$.
But this is a maximal subgroup and $\phi_x$ is not $\Gamma$-invariant. Hence we must have equality.
\[
I = \langle a_1, a_2, b\rangle \cong C_2\times C_2\times C_{2^{m-2}}.
\]
 Since $I$ is abelian, the character $\phi_x$ extends to $I$ and by Clifford's Theory, $\ind_\Sigma^I\phi_x$ is the sum of distinct extensions of $\phi_x$ to $I$. More precisely, if $\tilde\phi_x$ is such an extension, then by the Gallagher Correspondence, the set of extensions, and  
hence the set of  irreducible characters of $I$ lying over $\phi_x$ is
\[
\text{Irr}(I\mid \phi_x) = \{ \lambda\cdot\tilde\phi_x \mid \lambda\in\widehat{I/\Sigma} \}.
\]
Here as usual, $(\lambda\cdot \tilde\phi_x)(g) = \lambda(g\Sigma)\tilde\phi_x(g)$.
Furthermore none of these extensions is $\Gamma$-invariant and hence by the Mackey Formula we get
\[
\res^\Gamma_I\ind_I^\Gamma \tilde\phi_x = \tilde\phi_x \oplus {}^c\tilde\phi_x
\]
Therefore by the Frobenius Reciprocity,
\begin{eqnarray*}
    \big\langle \ind_I^\Gamma\tilde\phi_x, \ind_I^\Gamma\tilde\phi_x\big\rangle_\Gamma &=&     \big\langle \tilde\phi_x, \res^\Gamma_I\ind_I^\Gamma\tilde\phi_x\big\rangle_I\\
    &=&     \big\langle \tilde\phi_x, \tilde\phi_x \oplus {}^c\tilde\phi_x\big\rangle_I = 1
\end{eqnarray*}
In particular, $\ind_I^\Gamma\tilde\phi_x$ is an irreducible $\mathbb C\Gamma$-module. Furthermore by the Clifford's Correspondence, the irreducible summands of $\ind_\Sigma^\Gamma\phi_x$ are in bijective correspondence with $\text{Irr}(I\mid \phi_x)$ and hence we get
\[
\mathcal K\kerlint(G) \cong \ind_\Sigma^\Gamma\phi_x \cong \bigoplus_{\chi\in\text{Irr}(I\mid \phi_x)}\ind_I^\Gamma \chi
\]
where the summands are pairwise non-isomorphic irreducible $\mathbb C\Gamma$-modules of dimension 2. Since the number of summands on the right hand side is equal to $|\Gamma|/8$. By Theorem \ref{thm:chars}, it is also the number of irreducible $\mathbb C\Gamma$-modules of dimension 2. Hence we conclude that irreducible constituents of $\ind_\Sigma^\Gamma\phi_x$ are exactly the ones of dimension 2 and each appears with multiplicity 1. 
\end{proof}

\begin{nothing}
Finally we determine bases for the irreducible summands of $\mathcal K\kerlint(G)$. For each $\chi\in\text{Irr}(I\mid \phi_x)$, let $e_\chi$ be the primitive idempotent of the group algebra $\mathbb CI$ corresponding to $\chi$. It is given by
\[
e_\chi = \frac{1}{|I|}\sum_{\iota\in I}\chi(\iota^{-1})\iota
\]
Recall that $\{ e_\chi\mid \chi\in \hat{I} \}$ is the set of pairwise orthonormal primitive idempotents summing up to 1. Hence the summand of $\ind_\Sigma^I\phi_x$ with character $\chi$ is equal to $e_\chi\cdot \ind_\Sigma^I\phi_x$. By Frobenius Reciprocity, the multiplicity of $\chi$ in $\ind_\Sigma^I\phi_x$ is 1, and hence it is generated by any nonzero vector it contains. To distinguish one, consider the product
\[
e_\chi\cdot E_x = \frac{1}{|I|}\sum_{\iota\in I}\chi(\iota^{-1})\iota(E_x)
\]
Here we regard $E_x$ as an element in $\ind_\Sigma^I\phi_x$ via the identification of $\mathbb C[E_x] = \phi_x$. Since $b$ fixes $E_x$ and $\chi(b) = 1$, the terms of the above sum corresponding to $b$ and $b\iota$ for any $\iota\in I$ are the same. Similarly, since $\tilde a_2\cdot E_x = -E_x$ and $\chi(\tilde a_2)= -1$, the terms corresponding to $\tilde a_2$ and $\tilde a_2\iota$, for any $\iota\in I$ are equal. Hence we may sum over the cosets of $\Sigma =\langle \tilde a_2, b\rangle$. After removing the terms with coefficient zero, we obtain the following nonzero vector
\[
F_{x, \chi} = \sum_{\iota\in [I/\Sigma]} \chi(\iota^{-1})E_{\iota(x)}.
\]
and hence get
\[
\ind_\Sigma^I \phi_x \cong \bigoplus_{\chi\in\text{Irr}(I\mid \phi_x)}\mathbb C[F_{x, \chi}].
\]
With this notation, we also have
\[
\res^\Gamma_I\ind_I^\Gamma \mathbb C[F_{x, \chi}] \cong \mathbb C[F_{x, \chi}] \oplus {}^c\big( \mathbb C[F_{x, \chi}]\big)
\]
where 
\[
{}^c\big( \mathbb C[F_{x, \chi}]\big) = \mathbb C[F_{xy, {}^c\chi}]
\]
One can easily check that both $F_{x, \chi} + F_{xy, {}^c\chi}$ and $F_{x, \chi} - F_{xy, {}^c\chi}$ are $\Gamma$-invariant and hence form a basis for $\ind_I^\Gamma \mathbb C[F_{x, \chi}]$. 
\end{nothing}
