\section{Real Infinitesimal Free Cumulants \\ and the Moment-cumulant formula}\label{section:real infinitesimal cumulants}

When we pass from complex infinitesimal freeness to real infinitesimal freeness we need to use the symmetric non-crossing annular permutations introduced in \cite{mvb}. 
\begin{figure}
\includegraphics[width=10em]{fig1}
\caption{\small\label{fig:non-crossing_annular} A non crossing permutation of a $(6, 4)$-annulus.}
\end{figure}


Let us recall that $S_{NC}(p, q)$ denotes the set of non-crossing permutations of a $(p, q)$-annulus. These are permutations of $[p+q]$ such that the cycles can be drawn in an annulus, with $p$ points on the outer circle and $q$ points on the inner circle, in such a way that the cycles do not cross, see Figure \ref{fig:non-crossing_annular}. See \cite[\S5.1]{ms} for a full definition and examples. The simplest characterization of these permutations is through Euler's formula for the genus of a triangulated surface, but now transferred into the symmetric group: $\pi \in S_\NC(p, q)$ if  and only if
\[
\pi \vee \gamma_{p,q} = 1_{p+q} \qquad \mbox{and}\qquad
\#(\pi) + \#(\pi^{-1} \gamma_{p,q})  = p + q,
\]
where $\pi \vee \gamma_{p,q} = 1_{p+q}$ means that at least one cycle of $\pi$ meets both cycles of $\gamma_{p, q}$, and $\gamma_{p,q} \in S_{p+q}$ is the permutation with two cycles $(1, 2, 3, \dots, p)(p+1, \dots, p+q)$, and $\#(\pi)$ is the number of cycles in the cycle decomposition of $\pi$, counting cycles of length $1$. 

\subsection{Symmetric annular non-crossing permutations}

In \cite[\S2]{mvb} a subset of non-crossing annular permutations was identified. These are the \textit{symmetric} non-crossing annular permutations.  We denote this subset by $S_\NC^\delta(n, -n)$, the definition is recalled in the next paragraph. 

Let $n \geq 2$ be an integer. By $S_{\pm n}$ we mean the permutations of $[\pm n] = \{ \pm 1, \dots,\ab  \pm n\}$. We let $\delta \in S_{\pm n}$ be the permutation with $n$ cycles each of size $2$ given by $\delta(k) = - k$. Next we let $\gamma_n \in S_n$ be the permutation with the long cycle $(1, 2, 3, \dots, n)$. Throughout the paper we shall observe the following convention. If $\pi \in S_n$ then we consider $\pi$ to also be the permutation of $[\pm n]$ which acts trivially on $\{ -1, \dots, -n\}$. With this convention we have that given a $\pi \in S_n$, $\delta \pi \delta$ is a permutation on $[\pm n]$ which acts trivially on $[n] = \{1, \dots, n\}$.  Thus with $\gamma_n = (1, \dots, n)$ we have that 
\[
\gamma_n \delta \gamma_n^{-1} \delta = (1, \dots, n)(-n, \dots, -1). 
\]
We shall say that a permutation, $\pi$,  is a \textit{pairing} if all cycles have length $2$. This is equivalent to saying that $\pi^2$ is the identity and $\pi$ has no fixed points.
\begin{figure}
\begin{center}
\includegraphics{fig2}
\end{center}
\caption{\label{fig:symmetric annular}\small A \textit{symmetric} non-crossing annular permutation on a $(6, -6)$-annulus. Note that the orientation of the points on the two circles is the same. This is the opposite convention used in Figure \ref{fig:non-crossing_annular}. }
\end{figure}

\begin{notation}
Let $S_\NC^\delta(n, -n)$ be the permutations $\sigma \in S_{\pm n}$ such that
\begin{itemize}
\item
$\sigma \vee \gamma_n \delta \gamma_n^{-1} \delta = 1_{\pm n} $, and

\smallskip

\item
$\#(\sigma) + \#(\sigma^{-1} \gamma_n \delta \gamma_n^{-1} \delta) = 2 n$, and

\smallskip

\item
$\sigma \delta$ is a pairing.
\end{itemize} 
The first two assumptions mean that $\sigma$ is non-crossing annular on a $(n, -n)$-annulus, the third is a symmetry condition explained below. See Figure \ref{fig:symmetric annular}.
\end{notation}

\begin{remark}\label{remark:conjugate pairs}
It was noted in \cite[Remark 17]{mvb} that if we set $p = \sigma \delta$ with $\sigma \in S_\NC^\delta (n, -n)$ then $\sigma = p \delta$ and thus $\sigma$ is the product of two pairings and hence the cycles of $\sigma$ appear in conjugate pairs: $c$ and $c'$ with $c' = \delta c^{-1} \delta$ (see \cite[Lemma 2]{mp}). Thus the cycle decomposition of $\sigma$ can always be written $c_1 c_1' \cdots c_k c_k'$ with $c_i' = \delta c_i^{-1} \delta$. We call  the pair $\{ c_i, c_i'\}$ a \textit{conjugate pair}. The blocks of $\sigma\delta \vee \delta$ are exactly $c_i \cup c_i'$ (again, see \cite[Lemma 2]{mp}).
\end{remark}


\begin{notation}
Let $(\cA, \tau, \tau')$ be a tracial real non-commutative probability space and $\sigma \in S_\NC^\delta(n, -n)$. We define
$ 
\kappa_{\sigma/2}(a_1, \dots, a_n)
$
as follows. For each pair of conjugate cycles $\{ c, c'\}$ of $\sigma$, we write $c = (i_1, \dots, i_k, -j_l, \dots, -j_1)$ with $i_1, i_2,  \dots, i_k$ and $j_1, j_2, \dots,  < j_l$ in cyclic order\footnote{We say that $i_1 , i_2 \dots, i_k$ are in \textit{cyclic order} if they are in  the same order as in the orbit of $i_1$ under $\gamma_n$.}, we have the contribution of the pair $\{c, c'\}$ is 
\[
\kappa_{k+l}(a_{i_1}, \dots, a_{i_k}, a_{-j_l}^t, \dots, a_{-j_1}^t).
\]
By taking the product over all conjugate pairs $\{c, c'\}$ we get $\kappa_{\sigma/2}$: 
\[
\kappa_{\sigma/2}(a_1, \dots, a_n)
= \kern-2em
\mathop{\prod_{\{c, c'\} \in \sigma}}_{c = (i_1, \dots, i_k, -j_{l}, \dots, -j_1)}
\kern-2em
\kappa_{k+l}(a_{i_1}, \dots, a_{i_k}, a_{-j_l}^t, \dots, a_{-j_1}^t).
\]
The $\sigma/2$ in the notation is meant to signal that we only take one member of each conjugate pair. Since $\tau$ is tracial and invariant under the transpose the contributions of $c$ and $c'$ are the same. 
\end{notation}

\begin{definition}\label{definition:real infinitesimal cumulants}
Let $(\cA, \tau, \tau')$ be a tracial real infinitesimal probability space. For $a_1, \dots, a_n \in \cA$ we set for $n = 1$
\[
\kappa_1'(a_1) = \tau'(a_1)\ \mbox{and}
\]
and for $n \geq 2$
\begin{equation}\label{eq:real infinitesimal moment cumulant}
\tau'(a_1 \cdots a_n) =
\sum_{\pi \in \NC(n)} \partial \kappa_\pi(a_1, \dots, a_n)
+
\sum_{\sigma \in S_\NC^\delta (n, -n)} \kappa_{\sigma/2}(a_1, \dots, a_n).
\end{equation}
\end{definition}

\subsection{Spatial Derivatives}
As in the usual moment-cumulant formula (\ref{eq:moment_cumulant}), the equation above inductively defines the infinitesimal cumulants. For example
\[
\kappa_2'(a_1, a_2) = \tau'(a_1 a_2) -[ \tau'(a_1) \tau(a_2)  + \tau(a_1) \tau'(a_2)  + \tau(a_1a_2^t) - \tau(a_1) \tau(a_2^t)],
\]
\[
= \sum_{\pi \in \NC(2)} \mu(\pi, 1_2) \partial \tau_\pi(a_1, a_2) - \tau(a_1a_2^t) + \tau(a_1) \tau(a_2^t)
\]
where $\mu$ is the M\"obius function of $\NC(n)$. In order to make this fit into a convenient moment-cumulant relation we introduce the \textit{spatial} derivative, $\dot\kappa_n$. In this example, this will amount to rewriting the equation above as 
\[
\nabla \kappa_2(a_1, a_2) := 
\kappa_2'(a_1, a_2)  + \dot{\kappa}_2(a_1, a_2) =
\sum_{\pi \in \NC(2)} \mu(\pi, 1_2) \partial \tau_\pi(a_1, a_2),
\]
where $\dot{\kappa}_2(a_1, a_2) = \tau(a_1a_2^t) - \tau(a_1) \tau(a_2^t) = \kappa_2(a_1, a_2^t)$. This example is meant to illustrate the name spatial derivative, in that we do not consider the infinitesimal distributions of $a_1$ and $a_2$, but the first order joint distribution of $a_1$ and $a_2^t$.  

When $n = 3$ we can start with equation (\ref{eq:real infinitesimal moment cumulant}) and use the equation above to write $\kappa_3'$ in terms of $\tau$ and $\tau'$. The right hand side of (\ref{eq:real infinitesimal moment cumulant}) will have nine terms containing a $\kappa_i'$ (for some $i$) and six terms not containing a $\kappa_i'$, this will be the spatial part. The terms containing a $\kappa_i'$ can be grouped (after some calculation) into $\sum_{\pi \in \NC(3)} \mu(\pi, 1_3)
\partial\tau_\pi(a_1, a_2, a_3)$. The terms six not containing a $\kappa_i'$:
\begin{align*} 
\kappa_3(a_1, a_2, a_3^t) &+ \kappa_3(a_2, a_3, a_1^t) + \kappa_3(a_3, a_1, a_2^t)
+ \kappa_1(a_1) \kappa_2(a_2, a_3^t)  \\
& + 
\kappa_2(a_1, a_3^t) \kappa_1(a_2) + \kappa_2(a_1, a_2^t) \kappa_1(a_3),
\end{align*}
can be expanded into 21 terms with a $\tau$ but no $\tau'$. So we  write these remaining six as 
\[
\dot{\kappa}_3(a_1, a_2, a_3) + \kappa_1(a_1) \dot\kappa_2(a_2, a_3) + \kappa_1(a_2) \dot\kappa_2(a_3, a_1) + \kappa_1(a_3) \dot\kappa_2(a_1, a_2),
\]
where $\dot\kappa_2$ is as above and
\[
\dot\kappa_3(a_1, a_2, a_3) =
\kappa_3(a_1, a_2, a_3^t) + \kappa_3(a_2, a_3, a_1^t) + \kappa_3(a_3, a_1, a_2^t).
\]
The three terms in $\dot\kappa_3$ are the sum of $\kappa_{\sigma/2}$ as $\sigma$ runs over the three permutations in Figure \ref{fig:all through blocks}. 

Thus
\[
\kappa_3'(a_1, a_2, a_3) + \dot{\kappa}_3(a_1, a_2, a_3) = \sum_{\pi \in \NC(3)} \mu(\pi, 1_3)
\partial\tau_\pi(a_1, a_2, a_3), \quad\mbox{and}
\]
\[
\tau'(a_1a_2a_3)
=
\sum_{\pi \in \NC(3)} \{\partial\kappa_\pi(a_1, a_2, a_3) + \delta\kappa_\pi(a_1, a_2, a_3)\}, \quad\mbox{where}
\]
$ \delta\kappa_\pi = \sum_{V \in \pi} \dot\kappa_{{\scriptscriptstyle |V|}} \prod_{W \not= V} \kappa_{{\scriptscriptstyle |W|}}$.

To give a general definition for $\dot{\kappa}_n$ we need the set $S_\NC^{\delta, a}(n, -n)$ given in Definition \ref{def:all through cycles} below. 



\begin{definition}\label{def:all through cycles}
We let $S_\NC^{\delta, a}(n, -n) \subseteq S_\NC^\delta(n, -n)$ be those annular permutations for which every cycle meets both cycles of $\gamma_n \delta \gamma_n^{-1} \delta$. The superscript `$a$' means that \textit{all} cycles meet both cycles of $\gamma_n \delta \gamma_n^{-1} \delta$. These permutations, arising in earlier work on second order freeness \cite[Prop. 6.1]{cmss}, will play a prominent role in  constructing the real infinitesimal cumulants below. 
\end{definition}

\begin{notation}\label{notation:spatial derivative}
For $n \geq 2$, let $\dot{\kappa}_n(a_1, \dots, a_n) = \kern-1em\ds\sum_{\sigma \in S_\NC^{\delta, a}(n, -n) } \kern-1em \kappa_{\sigma/2}(a_1, \dots, a_n)$. If $\pi \in \NC(n)$ we let
\[
\delta\kappa_\pi(a_1, \dots, a_n) =
\sum_{V \in \pi} \dot{\kappa}_{{\scriptscriptstyle |V|}}(a_1, \dots, a_n | V) \prod_{W \not= V}
\kappa_{{\scriptscriptstyle |W|}}(a_1, \dots, a_n| W), 
\]
where the product is over all blocks $W$ not equal to $V$. Then we set $\nabla = \partial + \delta$. 
\end{notation}


