\begin{notation}
Let $S_\NC^{\delta, a}(n, -n)$ be the subset of $S_\NC^{\delta}(n, -n)$ where all cycles are through cycles. Given $\pi \in \NC(n)$ and $V \in \pi$ we let $S_\NC^{\delta}(n, -n)_{\pi, V} $
\[
=
\left\{ \sigma \in S_\NC^{\delta}(n, -n) \ \vrule height 3em depth 2.5 em width 0.4pt\quad 
\vcenter{\hsize=15.1em\noindent$\mbox{every cycle of\ } \sigma \mbox{\ is either a cycle of}\\ 
\pi\delta\pi^{-1}\delta \mbox{\ or contained in\ } V \cup \delta(V)$, \\
moreover any cycle of $\sigma$ contained in $V \cup \delta(V)$ must be a through cycle}\quad
\right\}.
\]
\end{notation}



\begin{lemma}\label{lemma:annular reduction}
\[
S_\NC^\delta (n, -n)
=
\bigcup_{\pi \in \NC(n)}
\bigcup_{V \in \pi}
S_\NC^{\delta}(n, -n)_{\pi, V},
\]
and the union is disjoint.
\end{lemma}

\begin{proof}
For each $\pi$ and $V$ we have $S_\NC^{\delta}(n, -n)_{\pi, V} \subseteq S_\NC^{\delta}(n, -n)$. If 
\[
\sigma \in 
S_\NC^{\delta}(n, -n)_{\pi_1, V_1}
\bigcap
S_\NC^{\delta}(n, -n)_{\pi_2, V_2}
\]
then $V_1 \cup \delta(V_1)$ and $V_2 \cup \delta(V_2)$ are both the union of the through cycles of $\sigma$; so $V_1 = V_2$. All the non-through cycles of $\sigma$ are cycles of $\pi_1 \delta\pi_1^{-1}\delta$ and of $\pi_2 \delta\pi_2^{-1}\delta$. So we also have $\pi_1 = \pi_2$. This proves disjointness. 

Given $\sigma \in S_\NC^\delta(n, -n)$ we let $V \subset [n]$ be such that $V \cup \delta(V)$ is the union of through cycles of $\sigma$. Let the remaining blocks of $\pi$ be the cycles of $\sigma$ contained in $[n]$. Then $\pi$ is non-crossing,  \cite[Def. 8 and Thm. 13]{kms}. See also the proof of Proposition 19 and Figure 6 in  \cite{mvb}.
\end{proof}




