\subsection{The Moment-Cumulant Formula}
\begin{theorem}\label{thm:moment cumulant}


\begin{align}\label{eq:infinitesimal moment cumulant}\lefteqn{
\tau'(a_1 \cdots a_n)}\\
& =
\sum_{\pi \in \NC(n)} \partial \kappa_\pi(a_1, \dots, a_n) +
\sum_{\sigma \in S_\NC^\delta(n, -n)} \kappa_{\sigma/2}(a_1, \dots, a_n). \notag \\
& =
\sum_{\pi \in \NC(n)} \nabla \kappa_\pi(a_1, \dots, a_n)  \notag
\end{align}
\begin{align}\label{eq:infinitesimal cumulant moment}
\nabla \kappa_n(a_1, \dots, a_n) & =  \kappa_n'(a_1, \dots, a_n) + \dot \kappa_n(a_1, \dots, a_n) \\
& =
\sum_{\pi \in \NC(n)} \mu(\pi, 1_n) \partial \tau_\pi (a_1, \dots, a_n). \notag
\end{align}
\end{theorem}

\begin{proof}
Equation (\ref{eq:infinitesimal moment cumulant}) is a definition; equation (\ref{eq:infinitesimal cumulant moment}) follows from Möbius inversion (see \cite[Lect. 11]{ns}). 
\end{proof}


\begin{remark}
As observed above, $\dot\kappa_n(a_1, \dots, a_n)$ depends only on the joint distribution of $\{a_1, a_1^t, \dots, a_n, a_n^t\}$. This leads to the question as to how do we write $\{\dot\kappa_n\}_n$ in terms of the joint distribution of $\{a_1, a_1^t, \dots, a_n, a_n^t\}$? There is an answer to question this when $a_1 = \cdots =a_n$ and $a_i = a_i^t$ for $1 \leq i \leq n$. 


Using Equation (\ref{eq:infinitesimal moment cumulant}), we solve for $\dot\kappa_n$ in terms of moments.
