Now turning to equation (\ref{eq:product rule}) we have to evaluate
\[
\mathop{\sum_{\sigma \in S_\NC^\delta(6, -6)}}_%
{K^\delta(\sigma) \sep \{\pm 2, \pm 4, \pm 6\}}
\kappa_{\sigma/2}(s, s, s, s, s, s, s).
\]
Since $s$ is semi-circular, the only $\sigma$'s that appear are pairings and their contribution is the same for all pairings $\sigma$. In \cite[Lemma 23]{m} we found that  the number of pairings is 22. If one examines these 22 annular pairings\footnote{The details are not provided here, but it is instructive to examine this case.} one finds that only the following 4 satisfy the condition that $K^\delta(\sigma)$ separates the points of $\{ \pm 2, \pm 4, \pm 6\}$
\[
(1, -4)(2, -5)(3, -6)(-1, 4)(-2, 5)(-3, 6),
\]
\[
(1, -6)(2, 3)(4, 5)(-1, 6)(-2, -3)(-4, -5),
\]
\[
(1, 6)(2, 3)(4, -5)(-1, -6)(-2, -3)(-4, 5),
\]
\[
(1, 6)(2, -3)(4, 5)(-1, -6)(-2, 3)(-4, -5).
\]
Thus using equation (\ref{eq:product rule}) we also get the conclusion that $\kappa_3'(x, x, x) = 4$.


Let $y$ have the limit distribution of a real Wishart matrix with $c = 1$ and $c' = 0$ (see \cite[Corollary 18]{mvb}). Then the base distribution of $x$ and $y$ are both Marchenko-Pastur with parameter $1$ (see \cite[Def.~2.11]{ms}). However we have $\kappa_2'(y, y) = 1$, see \cite[Cor.~18]{mvb}. So the infinitesimal laws of $x$ and $y$ are different even though the base distributions are the same. 









\section{The proof of Theorem \ref{thm:product rule}: $r=1$}
\label{sec:product rule r = 1}

The proof will be induction on $r$. In this section we will consider the case $r = 1$. To get started let us recall some earlier results.

\begin{lemma}[{\cite[Lemma 14]{mst}}]
Suppose $\rho \in \NC(m)$. Then $\rho \vee \gamma_\vm = \pi_\vm$ if and only if $\rho^{-1}\pi_\vm$ separates the points of $M$.
\end{lemma}

\begin{lemma}[{\cite[Prop. 11.12]{ns}}]\label{lemma:zeroth order product}
For $\pi \in \NC(r)$ we have 
\begin{equation}\label{eq:product rule}
\kappa_\pi(A_1, \dots, A_r)
=
\sum_{\rho \in \NC(m)} \kappa_\rho(a_1, \dots, a_m)
\end{equation}
where the sum is over all $\rho$ such that $\rho \vee \gamma_\vm = \pi_\vm$. 
\end{lemma}

\noindent
To set up the proof we shall set the following notation. Let 



\begin{itemize}\itemsep1em
\item
$N_1 = \{ \pi \in \NC(m) \mid K(\pi) \sep M \}$ and  

\item
$N_2 = \{ \pi \in \NC(m) \mid K(\pi)|_M \not= \textit{id}_M\}$.
\end{itemize} 

\medskip\noindent
Then $\NC(m) = N_1 \cup N_2$. 

For $\sigma \in S_\NC^\delta(m, -m)$ let $K^\delta(\sigma) = \delta \gamma_m^{-1} \delta \sigma^{-1} \gamma_m$.  Let
\begin{itemize}\itemsep1em

\item
$S_1 = \{ \sigma \in S_\NC^\delta(m, -m) \mid K^\delta(\sigma) \sep \pm M\}$, 

\item
$S_2 = \{ \sigma \in S_\NC^\delta(m, -m) \mid K^\delta(\sigma)|_{\pm M} \not= \id_{\pm M}$ but $K^\delta(\sigma)|_{\pm M}$ has no through cycles$\}$

\item
$S_3 = \{ \sigma \in S_\NC^\delta(m, -m) \mid K^\delta(\sigma)|_{\pm M}$ has through cycles$\}$

\end{itemize}\medskip

\noindent
Then $S_1 \cup S_2 \cup S_3 = S_\NC^\delta(m, -m)$. 



First we check (\ref{eq:the product rule}) when $r = 1$. Then, using induction on $r$, we may, for each $\pi \in \NC(r) \setminus \{ 1_r \}$ expand $\partial \kappa_\pi(A_1, \dots, A_r)$ using (\ref{thm:product rule}) and use this to prove the theorem for $\pi = 1_r$. The main idea is to expand
\[
\phi'(A_1 \cdots A_m)
=
\phi'(a_1 \cdots a_m)
\]
using the moment-cumulant formula (\ref{eq:infinitesimal moment cumulant}) in two ways and compare the result.

First we expand $\phi'(A_1 \cdots A_m)$ using the moment-cumulant formula:
\begin{equation}\label{eq:infinitesimal moment cumulant products}
\phi'(A_1 \cdots A_m)
=
\sum_{\pi \in \NC(r)} \partial \kappa_\pi(A_1, \dots, A_r)
\end{equation}
\[
\mbox{} + 
\sum_{\sigma \in S_\NC^\delta(r, -r)} \kappa_{\sigma/2}(A_1, \dots, A_r)
\]
We write the first term on the right-hand side of (\ref{eq:infinitesimal moment cumulant products}) as
\begin{equation}\label{eq:induction term one}
\kappa'_r(A_1, \dots, A_r)
+
\mathop{\sum_{\pi \in\NC(r)}}_{\pi \not= 1_r}
\partial\kappa_\pi(A_1, \dots, A_r).
\end{equation}
Now applying (\ref{eq:infinitesimal moment cumulant})  to (\ref{eq:product rule}) we will show that the second term on the right-hand side of (\ref{eq:induction term one}) is
\[
\sum_{\rho \in N_2} \partial \kappa_\rho(a_1, \dots, a_m)
+
\sum_{\tau \in S_2} \kappa_{\tau/2}(a_1, \dots, a_m)
\]
Then we will show that the second term on the right-hand side of (\ref{eq:infinitesimal moment cumulant products}) equals
\[
\sum_{\tau \in S_3}
\kappa_{\tau/2}(a_1, \dots, a_m)
\]
Let us put these two results together. 
\begin{align*}
& 
\kappa'_r(A_1, \dots, A_r) +
\sum_{\rho \in N_2} \partial \kappa_\rho(a_1, \dots, a_m) 
+
\sum_{\tau \in S_2} \partial \kappa_{\tau/2}(a_1, \dots, a_m) \\
& \mbox{} +
\sum_{\tau \in S_3} \kappa_{\tau/2}(a_1, \dots, a_m) 
= \phi'(A_1 \cdots A_r) = \phi'(a_1 \cdots a_m) \\
& \mbox{} =
\sum_{\rho \in \NC(r)} \partial \kappa_\rho(a_1, \dots, a_m)
 + 
\sum_{\tau \in S_\NC^\delta(r, -r)} \kappa_{\tau/2}(A_1, \dots, A_r).
\end{align*}
Thus
\begin{multline*}
\kappa'_r(A_1, \dots, A_r) =
\sum_{\rho \in \NC(m) \setminus N_2} \partial \kappa_\rho(a_1, \dots, a_m) \\
 \mbox{} +
\sum_{\tau \in S_\NC^\delta(m, -m) \setminus (S_2 \cup S_3)} \partial \kappa_{\tau/2}(a_1, \dots, a_m) \\
 \mbox{} =
\sum_{\rho \in N_1} \partial \kappa_\rho(a_1, \dots, a_m)
+
\sum_{\tau \in S_1} \partial \kappa_{\tau/2}(a_1, \dots, a_m)
\end{multline*}
which is exactly the claim of Theorem \ref{thm:product rule}.


\section{First Step: Proposition \ref{prop:first}}
\label{sec:product formula first step}

Since in Proposition \ref{prop:first} we exclude the case $\pi = 1_r$ we may use induction on $r$ and thus  we may use (\ref{eq:the product rule}) for $n < r$, provided that we start the induction by proving  (\ref{eq:the product rule}) when $n = 1$. However in this case (\ref{eq:the product rule}) reduces to the moment cumulant formula (\ref{eq:infinitesimal moment cumulant}). Let us recall the definition of $N_2$ and $S_2$:


\[
N_2 = \{ \pi \in \NC(m) \mid K(\pi)|_M \not= \textit{id}_M\} \mbox{\ and}
\]
\begin{multline*}
S_2 = \{ \sigma \in S_\NC^\delta(m, -m) \mid K^\delta(\sigma)|_{\pm M} \not= \id_{\pm M} \mbox{\ but\ } \\ K^\delta(\sigma)|_{\pm M} \mbox{\ has no through cycles\ }\}.
\end{multline*}




\begin{proposition}\label{prop:first}
\[
\mathop{\sum_{\pi \in\NC(r)}}_{\pi \not= 1_r}
\partial\kappa_\pi(A_1, \dots, A_r)
=
\sum_{\rho \in N_2} \partial \kappa_\rho(a_1, \dots, a_m)
+
\sum_{\tau \in S_2} \kappa_{\tau/2}(a_1, \dots, a_m)
\]
\end{proposition}
