The idea is that for each $\rho \in N_2$ we can associate a unique $\pi(\rho) \in \NC(r) \setminus \{1_r\}$ and for each $\tau \in S_2$ we can associate a unique $\pi(\tau) \in \NC(r) \setminus \{1_r\}$ such that 
\[
\partial\kappa_\pi(A_1, \dots, A_r)
=
\mathop{\sum_{\rho \in N_2}}_{\pi(\rho) = \pi}
 \partial \kappa_\rho(a_1, \dots, a_m)
+
\mathop{\sum_{\tau \in S_2}}
_{\pi(\rho) = \pi}
\kappa_{\tau/2}(a_1, \dots, a_m).
\]

For $\pi \in \NC(r)$, recall that $K(\pi) = \pi^{-1}\gamma_r$, and for $\rho \in \NC(m)$, $K(\rho) = \rho^{-1}\gamma_m$, and $\psi: [r] \rightarrow M$ is given by $\psi(k) = m_1 + \cdots + m_k$.

\begin{lemma}\label{lemma:first restriction}
For $\rho \leq \pi_\vm$ with $\rho \vee \gamma_\vm = \pi_\vm$, we have ${K(\rho)}|_\sM \psi = \psi K(\pi)$. 
\end{lemma}

Before reading the proof one can inspect the example on Figure \ref{fig:first term}.


\begin{proof}
Since $K(\pi_\vm)|_{\sM} = \psi K(\pi) \psi^{-1}$ we just have to show that $K(\rho)|_\sM = K(\pi_\vm)|_\sM$. However we have $K(\rho) = \rho^{-1}\pi_\vm \, K(\pi_\vm)$ and $\pi_\vm^{-1}\gamma_m$ acts trivially on $M^c$. We have that $K(\rho)|_\sM = (\rho^{-1}\pi_\vm)|_\sM K(\pi_\vm)|_\sM$, by \cite[Lemma 6]{mst} . By assumption $\rho^{-1}\pi_\vm|_\sM = \id_\sM$, so we have 
$K(\rho)|_\sM = K(\pi_\vm)|_\sM$. 
\end{proof}


\begin{lemma}\label{lemma:first bijection}
Let 
\begin{multline}
\tilde{N}_2 =
\{ \rho \in \NC(m) \mid \exists\,
1_r \not =\pi \in \NC(r) \mbox{\ such that\ } \\
\rho \leq \pi_\vm 
\mbox{\ and\ }
\rho^{-1}\pi_\vm \sep M\}.
\end{multline}
Then $N_2 = \tilde{N}_2$.
\end{lemma}


\begin{proof}
Let $\rho \in \tilde{N}_2$. By Lemma \ref{lemma:first restriction}, $K(\rho)|_\sM \psi = \psi K(\pi)$. By assumption $\pi \not = 1_r$ so $K(\pi) \not= 0_r$. Hence as a permutation $K(\pi)$ is not the identity, thus $K(\rho)|_\sM \not= \id_\sM$. 

Conversely, suppose $\rho \in N_2$. We obtain $\pi$ as follows.  Start with $\rho$, take its Kreweras  complement, restrict to $M$, then take the inverse Kreweras complement. This produces a permutation on $M$. Finally use $\psi$ to turn this into a permutation on $[r]$.

Let $\gamma_\sM = (m_1, m_1 + m_2, \dots, m_1 + \cdots + m_r) \in S(M)$ be the permutation with one cycle and let $\tilde\pi$ be the inverse Kreweras complement of $K(\rho)|_\sM$, namely $\tilde\pi = \gamma_\sM (K(\rho)|_\sM)^{-1}$, and finally let $\pi \in S_r$ be given by $\tilde\pi\psi = \psi\pi$. In \cite[Notation 4]{mst} it was shown that $K(\rho)|_\sM \in \NC(M)$, thus $\pi \in \NC(r)$, as $\psi$ is order preserving. As $K(\pi_\vm)$ acts trivially on $M^c$, we have $K(\pi_\vm)|_\sM = \psi K(\pi) \psi^{-1}$ and so $K(\rho)|_\sM = K(\pi_\vm)|_\sM$.

Note that 
\[
K(\rho)|_\sM = (\rho^{-1} \gamma_m )|_\sM = 
(\rho^{-1} \pi_\vm \pi_\vm^{-1} \gamma_m)|_\sM
=
(\rho^{-1} \pi_\vm K(\pi_\vm)|_\sM
\]
Again as $K(\pi_\vm)$ acts trivially on $M^c$, we have  by \cite[Lemma 6]{mst} that
\[
(\rho^{-1} \pi_\vm K(\pi_\vm)|_\sM
=
(\rho^{-1} \pi_\vm)|_\sM (K(\pi_\vm)|_\sM.
\]
Thus $K(\rho)|_\sM = (\rho^{-1}\pi_\vm)|_\sM K(\pi_\vm )|_\sM = (\rho^{-1}\pi_\vm)|_\sM K(\rho )|_\sM$. By cancelling $K(\rho)|_\sM$ we have $\rho^{-1}\pi_\vm|_\sM = \id_\sM$. 

Finally note that the actions of $K(\rho)$ and $K(\pi_\vm )$ on $M$ are the same and $K(\pi_\vm)$ acts trivially on $M^c$, so $K(\pi_\vm) \leq K(\rho)$. Hence $\rho \leq \pi_\vm$. This shows that $\rho \in N_2$. In addition our formula for $\pi$ shows that $\pi$ is unique.
\end{proof}

Let us fix $\pi \in \NC(r)$ with $\pi \not= 1_r$. For $V \in \pi$, $V_\vm \subseteq [m]$ is defined in \S\ref{section:product formula}.
\[
\partial\kappa_\pi(A_1, \dots, A_r) = \sum_{V \in \pi} 
\Big\{
\kappa_{|V|}'(A_1, \dots, A_r \mid V)
\prod_{W \not=V} \kappa_{|W|}(A_1, \dots, A_r | W) \Big\} 
\]
\[
 \stackrel{(*)}{=}
\sum_{V \in \pi} \Big\{
\kappa_{|V|}'(A_1, \dots, A_r \mid V)
\prod_{W \not=V}
\mathop{\sum_{\rho \in \NC(W_{\vv m})}}_{K(\rho) \sep M \cap W_{\vv m}}
\kern-1em
\kappa_\rho(a_1, \dots, a_m \mid W_{\vv m}) 
\]
\begin{multline}\label{eq:parts one and two}
\stackrel{(**)}{=}
\sum_{V \in \pi} \Bigg\{
\prod_{W \not=V} \kern-1em
\mathop{\sum_{\rho \in \NC(W_{\vv m})}}_{K(\rho) \sep M \cap W_{\vv m}}
\kern-1em
\kappa_\rho(a_1, \dots, a_m \mid W_{\vv m}) \\
\mbox{} \times
\bigg\{ \kern-1em
\mathop{\sum_{\rho \in \NC(V_{\vv m})}}_{K(\rho) \sep M \cap V_{\vv m}}
\partial \kappa_\rho(a_1, \dots, a_m \mid V_{\vv m})   \\
\mbox{} + \kern-2em
\mathop{\sum_{\tau \in S_\NC^\delta(V_{\vv m}, -V_{\vv m})}}
_{K^\delta(\tau) \sep \pm (M \cap V_{\vv m})}
\kappa_{\tau/ 2}(a_1, \dots, a_m | V_{\vv m}) \bigg\}\Bigg\}
\end{multline}
where $(*)$ holds by the product formula in the disc and $(**)$ holds by the induction hypothesis. 

\subsection{\normalsize The First Part of Equation (\ref{eq:parts one and two})}

Next break the last expression into two parts and consider the first part. 
\[
\sum_{V \in \pi}\Bigg\{
\prod_{W \not=V} \kern-1.0em
\mathop{\sum_{\rho \in \NC(W_{\vv m})}}_{K(\rho) \sep M \cap W_{\vv m}}
\kern-2em
\kappa_\rho(a_1, \dots, a_m \mid W_{\vv m})
\Bigg\}  \kern-1.5em
\mathop{\sum_{\rho \in \NC(V_{\vv m})}}_{K(\rho) \sep M \cap V_{\vv m}} \kern-1.5em
\partial \kappa_\rho(a_1, \dots, a_m \mid V_{\vv m})
\]
\[
\mbox{} \stackrel{(***)}{=} \kern-1.5em
\mathop{\sum_{\rho \in \NC(m),\, \rho \leq \pi_\vm}}_{\rho^{-1}\pi_\vm \sep M} \kern-1.5em
\partial \kappa_\rho(a_1, \dots, a_m)
\]
where in $(*\!*\!*)$ we combined all the $\rho$'s into a single $\rho$. To justify this notice that when we have for each $W \in \pi$, a $\rho_\sW \in \NC(W_{\vv m})$ such that $\rho_\sW \vee  \gamma_{\sW_{\vv m}} = 1_{\sM \cap \sW_{\vv m}}$, we get that $\prod_{W \in \pi} \rho_\sW^{-1} \gamma_{\sW_{\vv m}}$ separates the points of $M$. Then $\rho^{-1} \pi_{\vv m} = \prod_{\sW \in \pi} \rho_\sW^{-1} \gamma_{\sW_{\vv m}}$ separates the points of $M$. 

By Lemma \ref{lemma:first bijection}, this first part equals
\[
\sum_{\rho \in N_2} \partial \kappa_\rho(a_1, \dots, a_m).
\]

\subsection{\normalsize The Second Part of Equation (\ref{eq:parts one and two})}

Now let us consider the second part of the expression (\ref{eq:parts one and two}) above: 
\begin{equation}\label{eq:second term}
\sum_{V \in \pi}
\prod_{W \not=V} \kern-1.0em
\mathop{\sum_{\rho \in \NC(W_{\vv m})}}_{K(\rho) \sep M \cap W_{\vv m}}
\kern-2em
\kappa_\rho(a_1, \dots, a_m \mid W_{\vv m}) \kern-2em
\mathop{\sum_{\tau \in S_\NC^\delta(V_{\vv m}, -V_{\vv m})}}
_{K^\delta(\tau) \sep \pm(M \cap V_\vm)} 
\kern-2em
\kappa_{\tau}(a_1, \dots, a_m | V_{\vv m}). 
\end{equation}


We need to combine all the $\rho$'s for each $W$ and the $\tau$ for $V$ to obtain a single $\tau$ as follows. If $\tau_\sW \in \NC(W_\vm)$, then we double this to obtain $\delta\tau_\sW^{-1}\delta \tau_\sW \in  \NC(W_\vm) \times \NC(-W_\vm)$. For the $\tau_\sV \in S_\NC^\delta(V_\vm, -V_\vm)$ we let it stand unchanged. The $\tau$ we want is then the product of all these parts
\begin{equation}\label{eq:tau construction}
\tau = \tau_\sV \prod_{W \not= V} \delta \rho_\sW^{-1} \delta \rho_\sW.
\end{equation}  We want to show that the $\tau$'s obtained this way are such that $K^\delta(\tau)$ does not separate the points of $\pm M$ but does separate $M$ from $-M$. For this we shall need some additional notation. As before we start with $\pi \in \NC(r)$ and construct $\pi_\vm \in \NC(m)$. Then $\delta \pi_\vm^{-1} \delta \pi_\vm \in \NC(m) \times \NC(-m)$. For each $V \in \pi$ we get a block $V_\vm$ of $\pi_\vm$. If we fix $V \in \pi$ we let $\cU_\sV$ be the partition of $[ \pm m]$ obtained from $\delta \pi_\vm^{-1} \delta \pi_\vm$ by joining $V_\vm$ with $\delta(V_\vm)$.  Then each cycle of $\pi_\vm$ is contained in a block of $\cU_\sV$, and thus $(\cU_\sV, \pi_\vm)$  is a partitioned permutation in the sense of \cite[\S1]{mst}, see page 4754. The crucial part is that now for the $\tau$ constructed above (\ref{eq:tau construction}), $(0_\tau, \tau)$ is non-crossing with respect to $(\cU_\sV, \delta\pi_\vm^{-1} \delta \pi_\vm)$, or equivalently $(0_\tau, \tau) \leq (\cU_\sV, \delta\pi_\vm^{-1} \delta \pi_\vm)$ in the sense of \cite[Cor. 38 $(iii)$]{mst}. 


Thus we may write the second term as
\[
\sum_{V \in \pi}
\prod_{W \not=V} \kern-1.0em
\mathop{\sum_{\rho \in \NC(W_{\vv m})}}_{K(\rho) \sep M \cap W_{\vv m}}
\kern-2em
\kappa_\rho(a_1, \dots, a_m \mid W_{\vv m}) \kern-2em
\mathop{\sum_{\tau \in S_\NC^\delta(V_{\vv m}, -V_{\vv m})}}
_{K^\delta(\tau) \sep \pm(M \cap V_\vm)} 
\kern-2em
\kappa_{\tau}(a_1, \dots, a_m | V_{\vv m})
\] 
\[
\mbox{}\stackrel{(*)}{=}
\mathop{\mathop{\sum_{\tau \in S_\NC^\delta(m, -m)}}_
{(0_\tau, \tau) \leq (\cU_\sV, \delta\pi_\vm^{-1} \delta \pi_\vm)}}_
{K^\delta_{\pi_{\vv m}}(\tau) \sep \pm M}
\kappa_{\tau/2}(a_1, \dots, a_m),
\]
where $K^\delta_{\pi_\vm}(\tau) := \delta \pi_\vm^{-1} \delta \tau^{-1} \pi_\vm$ is the \textit{relative} Kreweras complement of $\tau$ with respect to $\pi_\vm$. The justification for this last equality $(*)$ is the same as above: all of the separation conditions are local; so when we put the cycles together to form $\tau$ we get that $K^\delta_{\pi_\vm}(\tau)$ separates the points of $M$. Since the non-crossing condition is characterized by a metric property, \cite[Notation 4]{mst}, non-crossing on each piece, plus that the pieces don't cross give us that $\tau \in S_\NC^\delta(m, -m)$. See Figure \ref{fig:two}  for a simple example.

\medskip\noindent
Let
\begin{multline*}
\tilde{S}_2 = 
\{ \tau \in S_\NC^\delta(m, -m) \mid \exists!\,
1_r \not =\pi \in \NC(r) \mbox{\ and\ } V \in \pi
\mbox{\ such that\ } \\
(0_\tau, \tau) \leq (\cU_\sV, \delta\pi_\vm^{-1} \delta \pi_\vm)  
 \mbox{\ and\ } 
K_{\pi_\vm}^\delta(\tau) \sep \pm M\}.
\end{multline*}




\begin{lemma}\label{lemma:annular restrictions}
Suppose that $\tau \in S_\NC^\delta(m, -m)$, $\pi \in \NC(r)$, $V \in \pi$ with $(0_\tau, \tau) \leq (\cU_\sV, \pi_\vm)$ and $K_{\pi_\vm}^\delta(\tau)|_{\pm \sM} = \id_{\pm \sM}$. Then \[ K^\delta(\tau)|_{\pm \sM} = \ab K^\delta(\pi_\vm) |_{\pm \sM}.\] 
\end{lemma}


\begin{proof}
First note that $\pi_\vm^{-1} \gamma_m|_{[m] \setminus M} = \id_{[m] \setminus M}$. So by \cite[Lemma 6]{mst}, 
\begin{multline*}
\pi_\vm^{-1} \gamma_m |_{\pm \sM} = K^\delta_{\pi_\vm}(\tau) |_{\pm \sM} \pi_\vm^{-1} \gamma_m |_{\pm \sM} \\
\mbox{}= \delta \pi_\vm^{-1} \delta \tau^{-1} \pi_\vm \cdot \pi_\vm^{-1} \gamma_m |_{\pm \sM} =
\delta \pi_\vm^{-1} \delta \tau^{-1} \gamma_m|_{\pm \sM}.
\end{multline*}
Likewise, $\delta \gamma_m^{-1}\pi_\vm \delta|_{[-m] \setminus -M} = \id_{[-m] \setminus -M}$. So by \cite[Lemma 6]{mst},
\[
\delta \gamma_m^{-1} \pi_\vm \delta|_{\pm\sM} \delta \pi_\vm^{-1} \delta \tau^{-1} \gamma_m|_{\pm \sM}
= \delta \gamma_m^{-1} \delta \tau^{-1} \gamma_m |_{\pm \sM} = K^\delta(\tau)|_{\pm \sM}.
\]
Combining these two identities we have 
\[
K^\delta(\pi_\vm)|_{\pm \sM} = \delta \gamma_m^{-1} \delta \tau \gamma_m |_{\pm \sM} = K^\delta(\tau)|_{\pm \sM}.
\]
\end{proof}

\begin{lemma}\label{lemma:second bijection}
$S_2 = \tilde{S}_2$.
\end{lemma}

\begin{proof}
Let $\tau \in \tilde S_2$, then by Lemma \ref{lemma:annular restrictions} we have $K^\delta(\tau)|_{\pm \sM} = K^\delta(\pi_\vm)|_{\pm \sM}$. Since $\pi \not = 1_r$ we cannot have that $K(\pi)$ is trivial. Thus $K^\delta(\tau)|_{\pm \sM} \not = \id_{\pm\sM}$. In addition, as $K^\delta(\pi_\vm)|_{\pm \sM}$ has no through cycles, we have that $K^\delta(\tau)|_{\pm \sM}$ has no through cycles. Thus $\tau \in S_2$. 


Now let $\tau \in S_2$. Let us recall some notation from Lemma \ref{lemma:first bijection}. By assumption $K^\delta(\tau)|_{\pm M}$ leaves $M$ invariant\footnote{Note similarity to \cite[Lemma 20]{mst}}. Let $\gamma_\sM = (m_1, m_1 + m_2, \dots,\ab m_1 + \cdots + m_r) \in S(M)$ be the permutation with one cycle and let $\tilde\pi$ be the inverse Kreweras complement of $K^\delta(\tau)|_\sM$, namely $\tilde\pi = \gamma_\sM (K^\delta(\tau)|_\sM)^{-1}$, and finally let $\pi \in S_r$ be given by $\tilde\pi\psi = \psi\pi$. In \cite[Notation 4]{mst} it was shown that $K(\tilde\pi)|_\sM \in \NC(M)$, thus $\pi \in \NC(r)$, as $\psi$ is order preserving. As $K(\pi_\vm)$ acts trivially on $M^c$, we have $K(\pi_\vm)|_\sM = \psi K(\pi) \psi^{-1}$ and so $K^\delta(\tau)|_\sM = K(\pi_\vm)|_\sM$. By the symmetry of $\tau$ we also have $K^\delta(\tau)|_{-\sM} = K^\delta(\delta\pi_\vm^{-1}\delta)|_{-\sM}$. Combining this with the result on $M$ we have $K^\delta(\tau)|_{\pm\sM} = K^\delta(\delta\pi_\vm^{-1}\delta \pi_\vm)|_{\pm \sM}$. Since $K^\delta(\delta\pi_\vm^{-1}\delta \pi_\vm) = \delta \gamma_m^{-1} \pi_\vm \delta \pi_\vm^{-1} \gamma_m$ acts trivially on $(\pm M)^c$, we have $K^\delta(\delta \pi_\vm^{-1} \delta \pi_\vm) \leq K^\delta(\tau)$ in the sense of \cite[Notation 4]{mst}. This then implies that
\begin{equation*}\label{eq:relative complement}
|K^\delta(\delta \pi_\vm^{-1}\delta\pi_\vm)| + |K^\delta_{\pi_\vm}(\tau)| = |K^\delta(\tau)|.
\end{equation*}
The fact that $\tau \in S_\NC^\delta(m, -m)$ means
\begin{equation*}\label{eq:non-crossing tau}
|\tau| + |K^\delta(\tau)| = |\delta \gamma_m^{-1}\delta \gamma_m| + 2.
\end{equation*}
Finally as $\pi_\vm \in \NC(m)$ we have
\begin{equation*}\label{eq:non-crossing pi}
|\delta \pi_\vm^{-1} \delta \pi_\vm| + |K^\delta( \delta \pi_\vm^{-1} \delta \pi_\vm) | = |\delta \gamma_m^{-1} \delta \gamma_m|.
\end{equation*}
Putting the last three equations together we have
\begin{align}
|\tau| &   + |K^\delta_{\pi_\vm}(\tau)| = \big(2 + |\delta \gamma_m^{-1} \delta \gamma_m|  - |K^\delta(\tau)|\big) \\
&\qquad\mbox{} + \big(
|K^\delta(\tau)| - |K^\delta(\delta \pi_\vm^{-1} \delta \pi_\vm)| \big)\notag \\ 
& \mbox{} =
2 + |\delta \gamma_m^{-1} \delta \gamma_m| -  |K^\delta(\delta \pi_\vm^{-1} \delta \pi_\vm)| = |\delta \pi_\vm^{-1}\delta \pi_\vm| + 2. \notag
\end{align}

So now we show that $\exists V \in \pi$ such that
\begin{enumerate}
\item[$(a)$]
$\#(\cU_\sV) = 2 \#(\pi_\vm) - 1$, and

\item[$(b)$]
$\tau \vee K^\delta_{\pi_\vm}(\tau) = \cU_\sV$. 
\end{enumerate}
Property $(a)$ will show that 
\[
|(\cU_\sV, K^\delta(\delta\pi_\vm^{-1} \delta \pi_\vm))| = |\delta \pi_\vm^{-1}\delta \pi_\vm| + 2
= | \tau| + |K^\delta_{\pi_\vm}(\tau)|. 
\]
Combining this with property $(b)$ we will have $(0_\tau, \tau) \leq (\cU_\sV, \delta \pi^{-1}_\vm \delta \pi_\vm)$; which implies that $\tau \in \tilde{S}_2$. So let us prove $(a)$ and $(b)$. 

First note that $\tau \vee K^\delta_{\pi_\vm}(\tau) = \tau \vee \delta\pi_\vm^{-1}\delta\pi_\vm$.

Suppose that $V$ and $V'$ are distinct blocks of $\pi_\vm$ that meet through cycles of $\tau$. As there two such blocks we may let $x$ and $y$ be the first and last elements of $V$. Then $\gamma_m^{-1}(x)$ and $y$ are in the same cycle of $K^\delta(\tau)$; the same also holds for $-\gamma_m^{-1}(x)$ and $-y$ . Thus, considering $\tau$ as a partition, either
\[
\tau \leq 
\{(1, \dots, \gamma_m^{-1}(x), \gamma_m(y), \dots, m, -1, \dots, -m),
(x, \dots, y)\}, \mbox{\ or}
\]
\[
\tau \leq
\{(1, \dots, \gamma_m^{-1}(x), \gamma_m(y), \dots, m), 
(x, \dots, y, -1, \dots, -m)\}.
\]
Since we assumed that $V$ meets a through cycle of $\tau$ we must have 
\[
\tau \leq
\{(1, \dots, \gamma_m^{-1}(x), \gamma_m(y), \dots, m), 
(x, \dots, y, -1, \dots, -m)\}.
\]
As $V' \subseteq (1, \dots, \gamma_m^{-1}(x), \gamma_m(y), \dots, m)$, we see that $V'$ cannot meet a through cycle of $\tau$. Moreover, $\tau$ has a through cycle, so it must meet some block of $\pi_\vm$ thus there is exactly one block, $V$, of $\pi_\vm$ that meets the through cycles of $\tau$. Then $\tau$ connects $V$ to $-V$, so $\tau \vee \delta\pi_\vm^{-1} \delta \pi_\vm = \cU_\sV$ and $\#(\cU_\sV) = \#(\delta \pi_\vm^{-1} \delta \pi_\vm -1$. This proves the claims $(a)$ and $(b)$. Hence $\tau \in \tilde S_2$
\end{proof}

\subsection{\normalsize The two parts combined}

Combining these two terms we have

\begin{multline}
\partial\kappa_\pi(A_1, \dots, A_r)
=
\sum_{\rho \in N_2}
\partial \kappa_\rho(a_1, \dots, a_m) \\
+
\sum_{\tau \in S_2}
\kappa_{\tau/2}(a_1, \dots, a_m).
\end{multline}
This completes the proof of Proposition \ref{prop:first}.


