\section{The second step: Proposition \ref{prop:third bijection}}
\label{sec:product formula second step}

We will conclude the proof of Theorem \ref{thm:product rule} with Proposition \ref{prop:third bijection}. Let us recall the definition of $S_3$:

\[
S_3 = \{ \sigma \in S_\NC^\delta(m, -m) \mid K^\delta(\sigma)|_{\pm M} 
\mbox{\ has through cycles\ } \}. 
\]

\begin{proposition}\label{prop:third bijection}
\begin{equation}\label{eq:s three}
\sum_{\sigma \in S_\NC^\delta(r, -r)} \kappa_{\sigma/2}(A_1, \dots, A_r)
=
\sum_{\tau \in S_3}
\kappa_{\tau/2}(a_1, \dots, a_m)
\end{equation}
\end{proposition}


\begin{proof}

Recall from \cite[Lemma 24]{mvb} that for every $\sigma \in S_\NC^\delta(r, -r)$ there are $1 \leq j < k \leq r$ such that $\sigma$ is non-crossing with respect to $\gamma_\sz$ where
\[
\gamma_\sz
= (1, \dots, j-1, -(k-1), \dots, -j, k, k+1, \dots, r)
\]
\[
\qquad\mbox{}\times
(-r, \dots, -k, j, j+1, \dots, k-1, -(j-1), \dots, -1).
\]
If we let $\hat\gamma = (1, \dots, j-1, -(k-1), \dots, -j, k, k+1, \dots, r)$, then $\gamma_\sz = \delta \hat\gamma^{-1} \delta \hat\gamma$. 
We let $\hat\sigma$ be the permutation consisting of the cycles of $\sigma$ contained in $\hat\gamma$. Then 
\[
\kappa_{\sigma/2}(A_1, \dots, A_r) = 
\kappa_{\hat\sigma}(A_1, \dots, A_{j-1}, A_{k-1}^t, \dots, A_j^t, A_k, \dots, A_r). 
\]

Next we let $\sigma_\vm$ be the permutation of $[\pm m]$ defined as follows. For $k \in [m] \setminus M$ we set $\sigma_\vm(k) = \gamma_m(k)$. For $k \in M$ with $k = m_1 + \cdots + m_l$ we define \[
\sigma_\vm(k) =
\begin{cases} 
m_1 + \cdots + m_{\sigma(l) -1 } + 1 & \mbox{if\ } \sigma(l) \in [r] \\
-(m_1 + \cdots + m_{-\sigma(l)}) & \mbox{if\ }  \sigma(l) =\in [-r].
\end{cases}
\]
Next for $k \in [-m]\setminus -\gamma_m(M)$ we set $\sigma_\vm(k) = \delta\gamma_m^{-1}\delta(k)$. If $k \in -\gamma_m(M)$ with $k = -(m_1 + \cdots + m_{l-1} +1)$ we set 
\[
\sigma_\vm(k) =
\begin{cases} 
-(m_1 + \cdots + m_{\sigma(-l)}) & \mbox{if\ } \sigma(-l) \in [-r] \\
m_1 + \cdots + m_{\sigma(-l)-1}+ 1 & \mbox{if\ }  \sigma(-l) \in [r].
\end{cases}
\]
Note that if $l \in [r]$ and $\sigma(l) \in [-r]$ then $\sigma_\vm(m_1 + \cdots + m_l) =$ $-(m_1 + \cdots + m_{-\sigma(l)})$ and thus $K^\delta(\sigma_\vm)(-(m_1 + \cdots + m_{-\sigma(l)})) = m_1 + \cdots + m_l$. So $K^\delta(\sigma_\vm)|_{\pm M}$ always has a through cycle. Also $\sigma_\vm = \delta \hat \sigma_\vm^{-1} \delta \hat\sigma_\vm$. 

Let $I_l = \{ m_1 + \cdots + m_{l-1} +1, \dots, m_1 + \cdots + m_l\}$ and $J_l = \{ -(m_1\ab + \cdots +m_l), \dots, -(m_1 + \cdots + m_{l-1}+1)\}$ (note the reversal of order). 
We let
$ [\hat m] =
I_1 \cup \cdots \cup I_{j-1}
\cup
J_{k-1} \cup \cdots \cup J_j \cup I_k \cup \cdots \cup I_r$ and
\begin{multline*}
\widehat{M}
= \{ m_1, \dots, m_1 + \cdots + m_{j-1}, -(m_1 + \cdots + m_{k-2}+1), 
\dots, \\
-(m_1 + \cdots + m_{j-1} + 1), m_1 + \cdots + m_k, \dots, m_1 + \cdots + m_r\}.
\end{multline*}
Note that
$\widehat{M} \subseteq [\hat m]$. We let $\hat\sigma_\vm$ be the restriction of $\sigma_\vm$ to $[\hat m]$. 

Since we reversed the order of elements in the $J$-intervals, we can just say that $\widehat{M}$ consists of the right hand endpoints of the intervals $\{I_1, \dots,  I_{j-1},\ab J_{k-1}, \dots, J_j, I_k, \dots,  I_r\}$. 

Thus when we expand $\kappa_{\hat\sigma}(A_1, \dots, A_{j-1}, A_{k-1}^t, \dots, A_j^t, A_k, \dots, A_r)$ we get by \cite[Thm.~15]{mst}
\begin{multline}\label{eq:local product expansion} 
\mathop{\sum_{\tau_\sz \in \NC([\hat m])}}_
{\tau_\sz^{-1} \hat\sigma_\vm \sep \widehat M}
\kappa_{\tau_\sz}(a_1, \dots, a_{m_1 + \cdots + m_{j-1}},
a_{m_1 + \cdots + m_{k-1}}^t, \dots, \\ 
a_{m_1 + \cdots + m_{j-1}+1}^t,
a_{m+1 + \cdots + m_{k-1}+1}, \dots, a_{m+1 + \cdots + m_r}).
\end{multline}
Now for $\tau_\sz \in \NC([\hat m])$ with $\tau_\sz^{-1}\hat \sigma_\vm |_{\widehat M}  = \id_{\widehat M}$, we let $\tau = \delta \tau_\sz^{-1} \delta \tau_\sz$. We claim that $K^\delta(\tau)|_{\pm M} = K^\delta(\sigma_\vm)|_{\pm M}$. This will prove that $\tau \in S_3$. 

Note that 
\[
K^\delta(\sigma_\vm)  = \delta \gamma_m^{-1} \hat\sigma_\vm  \delta \cdot \hat\sigma_\vm^{-1} \gamma_m
\mbox{\ and\ } 
K^\delta(\tau)  = \delta \gamma_m^{-1} \tau_\sz \delta \cdot \tau_\sz^{-1}\gamma_m 
\]

\noindent
Now let 
\hfill$
\hathat M = \{
m_1 + \cdots + m_j, \dots, m_1 + \cdots + m_{k-1} \} \ \cup
$\hfill\hbox{}
\[ \{ 
-(m_1 + \cdots + m_{k-1} + 1), \dots, -1, -(m_1 + 1), 
\dots, -(m_1 + \cdots + m_{j-2} + 1)\}
\]
Then $\delta\gamma_m\delta(\pm M) = \widehat{M} \cup \hathat M$. Let $\rho = \tau_\sz^{-1} \hat\sigma_\vm \delta \tau_\sz \hat\sigma_\vm^{-1} \delta$. Then $\rho|_{\widehat{M} \cup \hathat M} = \id_{\widehat{M} \cup \hathat M}$. So we let $\tilde\rho = \delta \gamma_m^{-1} \delta \rho \delta \gamma_m \delta$. Then   $\tilde\rho|_{\pm M} = \id_{\pm M}$. Next we observe that $\tilde K^\delta(\hat \sigma_\vm) = K^\delta(\tau)$. Indeed
\begin{align*}
\tilde \rho  K^\delta(\hat \sigma_\vm) 
& =
\delta \gamma_m^{-1} \delta \rho \delta \gamma_m \delta \cdot \delta \gamma_m^{-1}
\hat \sigma_\vm \delta \hat \sigma_\vm^{-1} \gamma_m \\
& =
\delta \gamma_m^{-1} \delta \big[ \tau_\sz^{-1} \hat\sigma_\vm \delta \tau_\sz \hat \sigma_\vm^{-1} \delta \big] \delta \gamma_m \delta \cdot \delta \gamma_m^{-1} \hat\sigma_\vm \delta \hat\sigma_\vm^{-1} \gamma_m \\
& =
\delta \gamma_m^{-1} \delta  \cdot \tau_\sz^{-1} \hat \sigma_\vm \cdot \delta \tau_\sz \hat \sigma_\vm^{-1} \delta \cdot \delta \hat\sigma_\vm \delta \cdot \hat\sigma_\vm^{-1} \gamma_m  \\
& =
\delta \gamma_m^{-1} \delta  \cdot \underbrace{\tau_\sz^{-1} \hat \sigma_\vm} \cdot 
 \underbrace{\delta \tau_\sz  \delta} \cdot \hat\sigma_\vm^{-1} \gamma_m \\
& \stackrel{(*)}{=}
\delta \gamma_m^{-1} \delta  \cdot  \underbrace{\delta \tau_\sz  \delta} \cdot 
\underbrace{\tau_\sz^{-1} \hat \sigma_\vm} \cdot  \hat\sigma_\vm^{-1} \gamma_m = K^\delta(\tau),\\
\end{align*}
where the equality $(*)$ holds because $\tau_\sz^{-1} \hat\sigma_\vm$ and $\delta \tau_\sz \delta$ commute as they act on disjoint subsets of $[\pm m]$. As 
$K^\delta(\hat \sigma_\vm)$ acts trivially on $(\pm M)^c$ (the complement of $\pm M$) we have by \cite[Lemma 6]{mst} that
\[
 K^\delta(\hat \sigma_\vm) |_{\pm M} = \tilde \rho|_{\pm M}  K^\delta(\hat \sigma_\vm) |_{\pm M} = ( \tilde \rho  K^\delta(\hat \sigma_\vm)) |_{\pm M}
= K^\delta(\tau)|_{\pm M}
\]
as claimed. Since $K^\delta(\sigma_\vm)|_{\pm M}$ has a through cycle (as observed above) we see that $K^\delta(\tau)|_{\pm M}$ has a through cycle and thus $\tau \in S_3$. 

So now we have shown that the left hand side of (\ref{eq:s three}) can be written as a sum over $\tau$'s with each $\tau$ in $S_3$. We must further show that each $\tau \in S_3$ occurs once and only once in the expansion  (\ref{eq:local product expansion}). To achieve this we must show how to recover $\sigma$ from $\tau$, exactly as in the second part of the proof of Lemma \ref{lemma:second bijection}. We will take $\sigma \in S(\pm r)$ to be the inverse Kreweras complement of the restriction of the Kreweras complement of $\tau$ to $\pm M$. 

Indeed, we consider $K^\delta(\tau)|_{\pm M}$; this is a permutation of $\pm M$. Then we conjugate by $\psi:[\pm r] \rightarrow \pm M$, where $\psi$ is the map $\psi(k) = m_1 + \cdots + m_k$ and $\psi(-k) = -(m_1 + \cdots + m_k)$ for $k > 0$. Then $\psi^{-1} (K^\delta(\tau)|_{\pm M}) \psi$ is a permutation of $[\pm r]$. We seek $\sigma$ such that $K^\delta(\sigma) = \psi^{-1} (K^\delta(\tau)|_{\pm M}) \psi$. To this end we let 
\[
\sigma =  \gamma_r (\psi^{-1} (K^\delta(\tau)|_{\pm M}) \psi)^{-1} \delta \gamma_r^{-1}\delta.  
\]
Then $K^\delta(\sigma) = \psi^{-1} (K^\delta(\tau)|_{\pm M})
\psi$. Thus $K^\delta(\sigma_\vm) |_{\pm M} =
K^\delta(\tau)|_{\pm M}$.  This shows that every term
appears once and only once and this completes the proof of
Proposition \ref{prop:third bijection}. \end{proof}





