		\title{\textbf{A quantile-based bivariate distribution}}		\author{Shifna. P. R.\corref{cor1}}
		\ead{shifnarazack92@gmail.com}
		\author{N. Unnikrishnan Nair}
		\ead{unnikrishnannair4@gmail.com}
		\author{S. M. Sunoj}
