    \subsection{Notations}
    In this paper, we will use the following notations. We use $f\le g$ to denote $f\leq C g$. 
        For the norm of Sobolev spaces in $x$-variable, we denote
$$
||f||_m :=||f||_{H^m},\quad
||f|| :=||f||_0,\quad
|||f|||:=||f||_{L^\infty}.
$$
    Also, we use the abbreviation $B=B(0,1)$, and $\p_{R_i}$, $\divr$ and $\gr$ denote the derivative, divergence and gradient in $R$-variable, respectively.
    We define the following Hilbert spaces in $R$-variable
    $$
    \begin{aligned}
    \h L^2 &= L^2({\dr/\pin })=\left\{
    \psi \ \Big| \ |\psi|^2_{\h L^2}=\intr |\psi|^2\dri<\infty
    \right\},\\
    \hd &= \left\{
    \psi \ \Big| \ 
   |\psi|_\hd^2 = \intr \pin \Big | \gr\frac{\psi}{\pin} \Big |^2 \dr < \infty
\right\},
    \end{aligned}
    $$

Also, for $\alpha\in \mathbb N^N$, $\g^\alpha$  denotes  $\alpha_1$ derivatives in $x_1$, $\cdots$, $\alpha_N$ derivatives in $x_N$.
With the above notations, we are able to 
 define the norms involving $x$ and $R$. For $s\geq 0$,
$$
\begin{aligned}
||\psi||_\hsltt&=\sum\limits_{|\alpha|\leq s}\ixr \left|\g^\alpha \psi\right|^2\dri\dx,\\
||\psi||_\hshot&=\sum\limits_{|\alpha|\leq s} \ixr \pin \left |\g^\alpha \gr \frac{\psi}{\pin}\right|^2\dr\dx.
\end{aligned}
$$
Also, we set
$$
||f||_\ler:=||f||_{0,\ler},\quad
||f||_\hyi:=||f||_{0,\hyi}.
$$

