\subsection{inequalities in $R$-variable}
The first Lemma is the \poin inequality in $R$-variable.
  \begin{lemma}[\cite{masmoudi-cpam}]\label{le-poincare-r}
      Assume that $\psi \in \hyi$ and $\intr \psi=0$, then
      \begin{equation*}
          \intr \frac{\psi^2}{\pin} \dr
          \le \int \pin \left| \gr  \frac{\psi}{\pin}\right|^2 \dr.
      \end{equation*}      
  \end{lemma}

 To deal with the singular term $\div \tau$, the main tool is the following Hardy-type inequality. 

  \begin{lemma}[\cite{masmoudi-cpam}]\label{le-tau}
      Assume that $\psi \in \ler\cap \hyi$ and $\intr \psi=0$, then
\begin{equation*}
          \left(\intr \frac{|\psi|}{1-|R|}\dr \right)^2
      \le \intr \pin 
      \left |
      \gr\frac{\psi}{\pin}
      \right|^2 \dr.
\end{equation*}
  \end{lemma}


    The following Hardy inequality is restricted in the case that $k>1$, and it can deal with stronger singularity.
  \begin{lemma}[\cite{masmoudi-cpam}] \label{le-hardy}
      Assume that $k>1$, $\psi\in \h H ^1$, and $\intr \psi=0$, then
            \begin{equation*} \label{ineq-hardy}
          \intr \frac{\psi^2}{\pin (1-|R|)^2} \dr
          \le |\psi|_{\h {\dot H}^1}^2.
      \end{equation*}
  \end{lemma}

   \section{Global Existence}\label{sec-global existence}

  In this section, we Investigate the small data global existence and stability of the N-dimensional FENE dumbbell without velocity dissipation. Thanks to the enhanced dissipation of (\ref{fene}), we can discover the additional time integrability of $u$. Recall that we define  the energy functionals as follows
  \begin{equation*}\label{nde1}
      \ey (t)=\sup\limits_{0\leq s\leq t}||u(s)||_{s}^2
      +\sup\limits_{0\leq s\leq t}||\psi(s)||_\hsltt
     +\nu \int_0^t \bbl||\nabla\psi(s)||_\hsltt
     + ||\psi(s)||_\hshot \bbr \d s,
 \end{equation*}
 \begin{equation*}\label{nde2}
      \ee(t)=\int_0^t ||\nabla u(s)||_{s-1}^2 \d s.
 \end{equation*}

 \begin{proof}[proof of Theorem \ref{thm-exist}]
    By the bootstrap argument (see e.g. P.21 of \cite{tao}), it suffices to prove the following two inequalities:
     \begin{equation}\label{nde1-inequ}
          \ey (t) \leq  \ey (0) + C  \ey^{\frac{3}{2}} (t) + C  \ee^{\frac{3}{2}}(t),
     \end{equation}
     and
     \begin{equation}\label{nde2-inequ}
          \ee(t) \leq C  \ey (0) +  C\ey (t) + C  \ey ^{\frac{3}{2}}(t) + C \ee^{\frac{3}{2}}(t).
     \end{equation}

     We begin with (\ref{nde1-inequ}). By standard $L^2$ energy method, we deduce from integrating by parts that
    $$
    \begin{aligned}
          &\frac{1}{2}\dt (||u||^2 +||\psi||_\ler ^2)
          + \nu ||\nabla \psi||_\lerer+||\psi||_\hyier
          \\
          =& \ixr \nabla u\cdot R \psi\cdot \gr \frac{\psi}{\pin}  \dr\d x\nonumber\\
          \le & ||\nabla u||\,|||
          \psi|||_\ler ||\psi||_\hyi \nonumber\\
          \leq & ||\psi||_{s,\ler}
          \bl ||\nabla u||^2+||\psi||_\hyier\brr.
    \end{aligned}
    $$
         Here we use the fact that, by integrating by parts and $-\dfrac{\p_{R_i}\pin}{\pin}=\p_{R_i} \h U$, 
     \begin{equation*}\label{linearpart-equal}
     \begin{aligned}
         &\ixr \divr (-\g u\cdot R \pin)\psi \dri\dx\\
         =& -\ixr \div u\pin\psi  \dr \dx 
         +\sum\limits_{i,j=1}^N \ixr \p_j u_i R_j\p_{R_i}\h U  \psi \dr \dx\\
         = & - \ix \div\tau\cdot u \dx.
     \end{aligned}
    \end{equation*}

     Now we consider the $\dot s$ estimate. Direct computation shows
      \begin{equation}\label{nde1-estimate}
                \frac{1}{2}  \dt (||\ls u||^2 
                +||\ls \psi||_\lerer)
          +  \nu ||\ls \nabla  \psi||_\lerer
          +  ||\ls\psi||_\hyier =\sum\limits_{i=1}^3 I_i, 
      \end{equation}
      where
      \begin{align*}
          I_1:= & -\intnx \ls(u\cdot\nabla u)\ls u \d x,\\
          I_2:= & -\ixr \ls((u\cdot\nabla\psi)\ls \psi \dri \d x,\\
          I_3:= & \ixr \ls \divr ( -\nabla u \cdot R \psi)\ls \psi \dri \d x.  
      \end{align*}

 Notice that by Sobolev embedding and $s>1+\frac{N}{2}$, we have 
 $$|||\nabla u|||
 \le ||\nabla u||_{s-1} 
\quad\text{and}\quad
 |||\nabla \psi|||_\ler
 \le ||\psi||_{s,\ler}.$$
 Together with divergence free condition $\div u=0$, we can bound $I_1$ and $I_2$ as follows
 \begin{equation*}
      \begin{aligned}
     |I_1|&=
     \left |
     \,\intnx  (\ls(u\cdot\nabla u)-u\cdot\nabla \ls u)\ls u\d x
     \right|\\
     & \le ||\nabla u||_{s-1}^2 ||\ls u||,\\
     |I_2|&=
     \left |
    \, \ixr  (\ls(u\cdot\nabla \psi)-u\cdot\nabla \ls \psi)\ls \psi \dri\d x
     \right|\\
     &  \le ||u||_s ||\psi||_\hshot.
     \end{aligned}
 \end{equation*}
 Finally, we deduce from integrating by parts, $\div u=0$ and Lemma \ref{le-hardy} that
 \begin{equation*}
 \begin{aligned}
     |I_3|
     =& \left |
     \, \ixr  \lsm\left[ \nabla u\cdot R\gr
     \left(\frac{\psi}{\pin}\pin\right)
     \right]\lsp \psi
     \dri \d x
     \right|\\
     \le & 
     \left |
     \, \ixr  \lsm\left[ \nabla u\cdot R
     \left(\pin^{\frac{1}{2}}\gr
     \frac{\psi}{\pin}\right)
     \right]\pin^{-\frac{1}{2}}\lsp \psi
     \dr \d x
     \right| \\
     & + 
     \left |
     \, \ixr  \lsm\left[ \nabla u\cdot R
     \left(\pin^{-\frac{1}{2}}
     \frac{\psi}{1-|R|}\right)
     \right]\pin^{-\frac{1}{2}}\lsp \psi
     \dr \d x
     \right|  \\
     \leq & 
     ||\g u||_{s-1} || \psi ||_{s,\hyi}
     ||\lsp \psi||_\ltlt\\
     \leq &||u||_\hs
     \bl
     ||\psi||_\hshot + ||\nabla\psi||_{s,\ler}^2
     \brr.
 \end{aligned}
 \end{equation*}
     Plugging the upper bounds of $I_1$, $I_2$ and $I_3$ into (\ref{nde1-estimate}), integrating in time and invoking  the norm equivalence, we find
\begin{align*}
    &||u||_\hser+||\psi||_\hsltt
    +\nu \int_0^t \bbl ||\nabla \psi(s)||_\hsltt +||\psi(s)||_\hshot \bbr \d s\\
    \leq  & ||u_0||_\hser+||\psi_0||_\hsltt
    + C \sup\limits_{0\leq s\leq t} ||u||_\hs 
    \int_0^t ||\nabla \psi(s)||_\hsltt +||\psi(s)||_\hshot \d s\\
    &+ C \sup\limits_{0\leq s\leq t} ||u||_\hs 
    \int_0^t ||\nabla u(s)||_{s-1}^2 \d s\\
    \leq & \ey (0) + C  \ey (t)^{\frac{3}{2}} + C  \ee(t)^{\frac{3}{2}},
\end{align*}
and (\ref{nde1-inequ}) is proved.

 Now we turn to take advantage of wave structure and prove (\ref{nde2-inequ}). 
 We deduce from the equation of $\D u$ in (\ref{du}) that
      \begin{equation}\label{Du-define-nd}
      \begin{aligned}
         ||\D u||_{s-1}^2 
         = & (\D u,\D u)+ \serl(\lsm\D u,\lsm\D u)
        = \sum\limits_{i=1}^5 J_i,
        \end{aligned}
        \end{equation}
    where
    $$
    \begin{aligned}
        J_1:=&\serjkn \ixr \dt \psi R_j R_k [\D u]_{j,k}\dr \d x\\
       & + \serjkn \ixr \dt \lsm \psi R_j R_k \lsm[\D u]_{j,k}\dr \d x,\\
        J_2 :=& \serjkn \ixr u\cdot \nabla \psi \rjk [\D u]_{j,k}\dr \d x\\
        &+ \serjkn \ixr \lsm( u\cdot \nabla \psi \rjk) \lsm [\D u]_{j,k}\dr \d x,  
    \end{aligned}
    $$
    $$
    \begin{aligned}
            J_3:= &\serjkn \ixr \Delta \psi \rjk [\D u]_{j,k}\dr \d x\\
        &+ \serjkn \ixr \Delta \lsm \psi \rjk \lsm [\D u]_{j,k}\dr \d x,  \\
        J_4:=& \serjkn \ixr \divr(-\nabla u \cdot R \psi)\rjk [\D u]_{j,k}\dr \d x\\
        &   +\serjkn\ixr \lsm\divr (-\nabla u \cdot R \psi)\rjk \lsm [\D u]_{j,k}\dr \d x \\
        J_5:=& \serjkn  \ixr \divr \Big( \pin \gr \frac{\psi}{\pin}\Big )\rjk[\D u]_{j,k}\dr \d x\\
        & +\serjkn \ixr \lsm\divr \Big( \pin \gr \frac{\psi}{\pin}\Big )\rjk\lsm[\D u]_{j,k}\dr \d x.
    \end{aligned}
    $$

    To estimate $J_1$, we split it into four terms $J_1=J_{1,1}+J_{1,2}+J_{1,3}+J_{1,4}$, where
    \begin{align*}
    J_{1,1}&:=\serjkn \dt \ixr \psi \rjk [\D \P u]_{j,k} \dr \d x ,\\
    J_{1,2}&:=- \serjkn \ixr \psi\rjk \dt [\D \P u]_{j,k} \dr \d x,\\
    J_{1,3}&:=\serjkn \dt \ixr  \lsm \psi \rjk \lsm [\D \P u]_{j,k} \dr \d x, \\
    J_{1,4}&:=- \serjkn \ixr \lsm \psi\rjk \dt \lsm [\D\P u]_{j,k} \dr \d x.
     \end{align*}

       By integrating in time, we have
     \begin{align*}
         \left |\int_0^t J_{1,1} \d s \right | 
         &\leq  \serjkn \left| \ixr \psi \rjk [\D \P u]_{j,k} \dr \d x  \right |
         +||\psi_0||_\ltlt||u_0||_\hyi\\
         &\leq ||u||_1^2 + ||\psi||_\ltltt  
         + ||u_0||_1^2 +  ||\psi_0||_\ltltt ,\\
        \left |\int_0^t J_{1,3} \d s \right | 
         &\leq  \serjkn \left| \ixr  \lsm \psi \rjk \lsm  [\D \P u]_{j,k} \dr \d x  \right |
         +||\lsm\psi_0||_\ltlt||\ls u_0|| \\
         &\leq ||\ls u||^2 + ||\lsm \psi||_\ltltt
         +||\ls u_0||^2 + ||\lsm \psi_0||_\ltltt,
     \end{align*}   
     By substituting the second equation of (\ref{fene}) into $J_{1,2}$ and using Lemma \ref{le-poincare-r}, we obtain
     \begin{align*}
         J_{1,2}
         = & \serjkn \ixr \psi \rjk 
         \left[
         \D (u\cdot \nabla u) -\D \P \div \tau 
         \right ]_{j,k} \dr\d x \\
         \le & 
         ||\psi||_\ltlt ||\g (u\cdot \nabla u)|| 
         +||\psi||_\ltlt ||\psi||_{2,\hyi}\\
         \le &    ||\psi||_\ltlt||| u|||\, ||\g u||_1 
         +||\psi||_\hyi||\psi||_{2,\hyi}\\
         \leq & ||\psi||_\ltlt ||\nabla u||_{s-1}^2
         +||\psi||_{2,\hyi}^2.
     \end{align*}
     Using integration by part, $J_{1,4}$ can be treated similar to $J_{1,2} $:     
     \begin{align*}
         J_{1,4}
         = & \serjkn \ixr \lsm  \psi \rjk 
          \lsm \left[
         \D (u\cdot \nabla u) -\D \P \div \tau 
         \right ]_{j,k} \dr\d x \\
         \leq & ||\ls \psi||_\ltlt 
         ||\lsm(u\cdot \nabla u)||  
         +||\lsp \psi||_\ltlt||\ls \tau|| \\
         \leq & ||\psi||_{s,\ler} ||\nabla u||_{s-1}^2
         +||\lsp \psi||_\ltltt + ||\ls \psi||_\lthot.
     \end{align*}
     Summing up $N_{1,i}(i=1,2,3,4)$ and integrating in $t$ yields
     \begin{equation}
     \begin{aligned}\label{n1}
        \int_0^t J_1(s) \d s
         \le & ||u_0||_\hser + ||\psi_0||_\hsltt
        +  \sup\limits_{0\leq s\leq t}\bl  || u(s)||_\hser 
        +  ||\psi(s)||_\hsltt\brr \\
         &+ \int_0^t 
           \bbl ||\nabla \psi||_\hsltt  + ||\psi||_\hshot \bbr \d s\\
         &+  \sup\limits_{0\leq s\leq t} ||\psi||_{s,\ler} 
         \int_0^t 
         ||\nabla u||_{s-1}^2 \d s.
     \end{aligned}
     \end{equation}
     $J_2$ and $J_3$ are bounded by
     \begin{equation}
         \begin{aligned}
             J_2\le & |||u|||\,||\nabla \psi||_\ltlt||\nabla u|| 
             + ||\lsm (u\cdot \nabla \psi)||_\ltlt ||\ls u|| \\
             \le & ||u||_\hs 
             ( ||\nabla u||_{s-1}^2 + ||\psi||_\hshot ),\\
             J_3\leq &  C||\Delta\psi||_\ler ||\nabla u||  
             + C||\lsp \psi||_\ltlt ||\nabla u||_{s-1}\\
             \leq &  C ||\psi||_\hsltt + \frac{1}{4}||\nabla u||_{s-1}^2.
         \end{aligned}
     \end{equation}

     Finally, using integrating by parts in $R$, we obtain
     \begin{equation}
         \begin{aligned}
             J_4=&\ixr \pin\gr\frac{\psi}{\pin}\gr(R_jR_k)[\D u]_{j,k} \dr \d x\\
             &+\ixr \pin\gr\frac{\ls\psi}{\pin}\gr(R_jR_k)[\D \ls u]_{j,k} \dr \d x\\
             \leq & C ||\psi||_\ltho ||\nabla u|| 
             + C ||\lsm \psi||_\ltho ||\ls u|| \\
             \leq & C ||\psi||_\hshot + \frac{1}{4}||\nabla u||_{s-1}^2,
         \end{aligned}
     \end{equation}

     \begin{equation}\label{n5}
         \begin{aligned}
             J_5=&-\ixr \nabla u\cdot R\psi \gr (R_jR_k)[\D u]_{j,k}\dr \d x\\
             &-\ixr \lsm (\nabla u\cdot R\psi) \gr (R_jR_k)[\D \lsm u]_{j,k} \dr \d x\\
             \leq & 
             |||\psi |||_\ler
             ||\nabla u||^2              
             + ||\psi||_{s-1,\ler} 
             ||\g u||_{s-1}^2 \\
             \le & ||\psi||_\hslt ||\nabla u||_{s-1}^2.
         \end{aligned}
     \end{equation}

  By integrating (\ref{Du-define-nd}) in time and substituting the estimates (\ref{n1})-(\ref{n5}) into it, we find
  \begin{equation}
      \begin{aligned}
          \ee(t)
          \leq & C ||u_0||_\hser + C ||\psi_0||_\hsltt
        +  C \sup\limits_{0\leq s\leq t} \bl ||u(s)||_s^2
        +  ||\psi(s)||_{s,\ler}^2 \brr \\
        & + C \int_0^t  
        \bbl ||\psi||_\hsho^2 + ||\nabla \psi||_\hsltt \bbr
        \d s\\
        & + C\sup\limits_{0\leq s\leq t} 
        \bl
        ||u(s)||_s
        + ||\psi(s)||_{s,\ler}\brr
         \int_0^t \bbl 
         ||\nabla u||_{s-1}^2 
         + ||\psi||_{s,\hyi}^2
         \bbr \d s\\
         \leq & C\ey (0) + C\ey (t) + C \ey ^\frac{3}{2}(t) + C \ee^\frac{3}{2}(t),
      \end{aligned}
  \end{equation}
  and (\ref{nde2-inequ}) is proved.
 \end{proof}

\section{Decay estimates}\label{sec-decay}
In this section, we take advantage of the enhanced dissipation of the velocity and explore the decay rates of (\ref{fene}).
By combining this enhanced dissipation and the Fourier splitting method, we derive the velocity decay rate which matches that of the heat equation, and this is also identical to the FENE dumbbell model with velocity dissipation.
\begin{proof}[Proof of Theorem \ref{thm-decay}]
    By basic $L^2$ and $\hdyi$ energy estimates, we find
    $$
    \begin{aligned}
    &\frac{1}{2}\dt \bl ||u||_1^2 + ||\psi||_{1,\ler}^2 \brr 
    + \nu ||\g\psi||_{1,\ler}^2
        + ||\psi||_{1,\hyi}^2\\
        =& 
         - \ix \g(u\cdot \g u) : \g u\dx
            -\ixr \g (u\cdot\g\psi)\cdot\g\psi\dri\dx\\
        &+\sum\limits_{k=0,1}
        \ixr \g^k \divr (\-\g u\cdot R\psi) \g^k \psi\dri\dx.
    \end{aligned}
    $$
    Also, we integrate (\ref{du}) with $\D u$ to obtain
    $$
    \begin{aligned}     
        \h C ||\D u||^2 = &
        \p_t\ixr ( \psi R\otimes R):\D u\dr\dx 
        -\ixr ( \psi R\otimes R)\cdot\D\P(u\cdot\g u) \dr\dx \\
        &+\ixr ( \psi R\otimes R)\cdot\D\P \div \tau \dr\dx 
        +\ixr (u\cdot\g\psi R\otimes R):\D u\dr \dx\\
        &-\nu\ixr (\Delta\psi R\otimes R):\D u\dr \dx
        -\ixr (\h L \psi R\otimes R):\D u\dr\dx\\
        &+\ixr(\divr (-\g u\cdot R\psi)R\otimes R):\D u\dr\dx.
    \end{aligned}
    $$

    Gathering the above equations together, we find
    \begin{equation}\label{equ-decay}
        \begin{aligned}
            &\frac{1}{2}\dt
            \bbl 
            ||u||_1^2 + ||\psi||_{1,\ler}^2
            -2 a \ixr (\psi R\otimes R ):\D u \dr \dx
            \bbr\\
            & + \nu ||\g\psi||_{1,\ler}^2
            + ||\psi||_{1,\hyi}^2
            +2 a \cal C  ||\D u||^2
            = \cal L + \cal{NL},
        \end{aligned}
    \end{equation}
    where $a$ is a small positive constant that will be determined later, and
    $$\begin{aligned}
    &\begin{aligned}
        \cal L:= &
        2a\ixr ( \psi R\otimes R)\cdot\D\P \div \tau \dr\dx\\
        &-2a \nu\ixr (\Delta\psi R\otimes R):\D u\dr \dx\\
        &-2a\ixr (\h L \psi R\otimes R):\D u\dr\dx,
    \end{aligned}\\
   & \begin{aligned}
        \cal{NL}:= & 
        \ix \g(u\cdot \g u) : \g u\dx
        -\ixr \g (u\cdot\g\psi)\cdot\g\psi\dri\dx\\
        &+\sum\limits_{k=0,1}
        \ixr \divr (-\g^k u\cdot R\psi)\g^k\psi\dri\dx\\
        &-2a\ixr ( \psi R\otimes R)\cdot\D\P(u\cdot\g u) \dr\dx\\
        &+2a\ixr (u\cdot\g\psi R\otimes R):\D u\dr \dx\\
        &+2a\ixr(\divr (-\g u\cdot R\psi)R\otimes R):\D u\dr\dx.        
    \end{aligned}
    \end{aligned}
    $$
Using integrating by parts, Lemma \ref{le-tau}, and setting $a$ small enough, we can estimate $\cal L$ by
 $$
 \begin{aligned}
 \cal L\leq & C a\ixr \pin^{\frac{1}{2}}|\gr\frac{\psi}{\pin}|\,|\g u| \dr\dx
 + 2a \ix |\g\psi|\,|\g\tau| \dx\\
 &+ C a\nu \ixr |\Delta\psi|\,|\g u| \dri\dx\\
 \leq & \frac{\nu}{4}||\g^2 \psi||_\lerer
 + \frac{1}{4}||\psi||_{1,\hyi}^2
 +\frac{1}{2} a \cal C  ||\D u||^2.
 \end{aligned}
 $$
 Also, by the Theorem \ref{thm-exist} and the smallness of $\ep$, it is direct to deduce
 $$
 \cal {NL}\leq \frac{\nu}{4}||\g^2 \psi||_\lerer
 + \frac{1}{4}||\psi||_{1,\hyi}^2
 +\frac{1}{2} a \cal C  ||\D u||^2.
 $$

 Substituting the above estimates into (\ref{equ-decay}) yields that
 $$
 \dt f(t) + g(t) \leq 0,
 $$
 where
 $$
 \begin{aligned}
 f:= & ||u||_1^2 + ||\psi||_{1,\ler}^2
            -2 a \ixr (\psi R\otimes R ):\D u \dr \dx,\\
g:= & \nu ||\g\psi||_{1,\ler}^2
            + ||\psi||_{1,\hyi}^2
            +2 a\cal C  ||\D u||^2.
 \end{aligned}
 $$

 To characterize the decay rate, we define
 $$
 d(t)= (\eta+ t)^s,\quad s > 0.
 $$
 By choosing $\eta$ large enough, we have
 $$
 \begin{aligned}
     & d'(t)\bbl  ||\psi||_\lerer 
     + ||\g\psi||_\lerer + ||\g u||^2
     -2a \ixr (\psi R\otimes R):\D u \dr \dx\bbr \\
     \leq &d (t)\bl \frac{1}{2}  ||\psi||_{1,\hyi}^2
     +  a \cal C   ||\D u||^2\brr.
 \end{aligned}
 $$
 Hence, we obtain that 
 $$
 \dt \bl  d(t) f (t) \brr + \frac{1}{2}d(t) g(t)  \leq d'(t) ||u||^2.
 $$
 By setting 
 $$
 S(t):=\left\{\xi: \xier\leq \frac{2}{a \cal C } \frac{d'(t)}{d(t)}\right\},
 $$
 we have
  \begin{equation}\label{equ-df}
       \dt \bl  d(t) f (t) \brr 
       + \frac{1}{2}a\cal C  d(t) ||\D u||^2
       = \leq d'(t) \is | \hu(\xi)|^2 \d \xi .
  \end{equation}

 To estimate $\is | \hu|^2 \d \xi$, we consider (\ref{fene}) in frequency space:
 \begin{equation}\label{equ-fene-f}
  \begin{cases}
      \p_t \hu + \F(u\cdot \g u) 
      + i\xi \hat P 
      = i\xi \cdot\hat \tau ,\\
      \p_t\hp  + \F(u\cdot \g \psi) 
      +\nu \xier \hp + \h L \hp
      = \divr [-\F (\g u\cdot R(\psi+ \pin)) ],\\
      i\xi\cdot\hu = 0.
  \end{cases}   
 \end{equation}
 By integrating (\ref{equ-fene-f}) with $(\hbu,\hbp)$ and subtracting the real parts, we get
 $$
 \begin{aligned}
 &\frac{1}{2} \dt\bl |\hu|^2 + |\hp|_\lerer\brr
 +\nu \xier|\hp|_\lerer + |\hp|_\hyier\\
 = & -\re [ \F (u\cdot\g u)\cdot\hbu ]
 - \re  \intr \F(u\cdot\g \psi ) \hbp\dri 
  - \re \intr  \divr \F ( \g u\cdot R \psi )\hbp \dri.
 \end{aligned}
 $$
 By \holder inequality,
 $$
 \begin{aligned}
 &- \re  \intr \F(u\cdot\g \psi ) \hbp\dri 
  - \re \intr  \divr \F ( \g u\cdot R \psi )\hbp \dri\\
  \leq &\frac{1}{2} |\hp|_\hyier
  + C \intr |\F (u\cdot \g \psi)|^2 \dri
  + C \intr |\F (\g u\cdot R \psi)|^2 \dri,
 \end{aligned}
 $$
 which implies 
 $$
\begin{aligned}
 &\frac{1}{2} \dt\bl |\hu|^2 + |\hp|_\lerer\brr\\
 \leq &|\re ( \F (u\cdot\g u)\cdot\hbu)|
  + C \intr |\F (u\cdot \g \psi)|^2 \dri
  + C \intr |\F (\g u\cdot R \psi)|^2 \dri.
\end{aligned}
 $$
 Integrating the above inequality in $S(t)$ and in time yields
 \begin{equation}\label{equ-f-up}
     \begin{aligned}
         &\is |\hu (t)|^2\d\xi
         + \is |\hp(t)|^2 \d \xi\\
         \leq &\is |\hu (0)|^2\d\xi
         + \is |\hp(0)|^2 \d \xi
         + K_1+K_2+K_3,
     \end{aligned}
 \end{equation}
 where
 $$
\begin{aligned}
 K_1:= &C \it\is \intr |\F (u\cdot \g \psi)|^2 \dri \d\xi\d s,\\
 K_2:=& C \it\is\intr |\F (\g u\cdot R \psi)|^2 \dri\d\xi\d s,\\
  K_3:=&2\it \is |\re ( \F (u\cdot\g u)\cdot\hbu)|\d\xi\d s.
\end{aligned}
 $$

 For the initial data, we take advantage of the definition of $S(t)$ to obtain
 $$
 \begin{aligned}
 &\is |\hu (0)|^2\d\xi
  + \is |\hp(0)|^2 \d \xi\\
    \leq & \is \d\xi 
    \bl ||u(0)||_{L^1}^2
    + ||\psi(0)||_{L^1(\ler)}^2\brr\\
    \le & \int_0^{\sqrt{\frac{2s}{a \cal C }(\eta + t)} }
    r^{N-1}\d r 
    \bl ||u(0)||_{L^1}^2
    + ||\psi(0)||_{L^1(\ler)}^2\brr\\
    \le & (\eta+ t)^{-\frac{N}{2}}
    \bl ||u(0)||_{L^1}^2
    + ||\psi(0)||_{L^1(\ler)}^2\brr.
 \end{aligned}
 $$
 For $K_1$ and $K_2$, we use Theorem \ref{thm-exist} to obtain
 $$
 \begin{aligned}
     K_1\leq & \is \d\xi \it ||u\cdot\g\psi||_{L^1}\dri\d s\\
     \le & \is \d\xi \it 
     ||u||^2 ||\g\psi||_\lerer \d s
     \le \varepsilon^4 (\eta + t)^{-\frac{N}{2}},\\
     K_2\leq & \is \d\xi 
     \it ||\g u\cdot R\psi||_{L^1}\dri\d s\\
     \le & \is \d\xi \it 
     ||\g u||^2 ||\psi||_\lerer \d s
     \le \varepsilon^4 (\eta + t)^{-\frac{N}{2}}.
 \end{aligned}
 $$
 For $K_3$, we use Hardy-Littlewood-Sobolev inequality and Theorem \ref{thm-exist} to obtain
 $$
 \begin{aligned}
     K_3 \leq 2 \it ||\Lambda^{-1}(u\cdot\g u)||\,||\g u|| \d s
     \leq  C \it ||u\cdot\g u||_{L^{6/5}}||\g u|| \d s
     \leq \ep C t ||\g u||^2.
 \end{aligned}
 $$
 By substituting the above estimates into (\ref{equ-f-up}), we find
 $$
 \is |\hu (t)|^2\d\xi
         + \is |\hp(t)|^2 \d \xi
         \leq C\varepsilon^4 (\eta+t)^{-\frac{N}{2}} 
         + \varepsilon Ct||\g u||^2.
 $$
  Plugging the above inequality into (\ref{equ-df}) and choosing $\ep \leq \frac{a \cal C }{2 C}$ yields
  $$
  \dt\bl d(t) f(t)\brr \leq \varepsilon^4 Cd'(t)(\eta+t)^{-\frac{N}{2}}.
  $$
  Since 
  $
  f \sim ||u||_1^2 + ||\psi||_{1,
  \ler}^2
  $,
  by integrating the above inequality in time, we obtain that
  $$
  ||u||_1^2 + ||\psi||_{1,
  \ler}^2\leq \varepsilon^2 C (\eta+t)^{-\frac{N}{2}}.
  $$

  Next, we take advantage of the higher-order decay to improve the decay rate of $||\psi||_\ler $.
  By the argument parallel to the $L^2$ case, it is not difficult to deduce that
  $$
  \begin{aligned}
  &\dt\bbl d(t) \bbl ||\g u||_1^2 + ||\g \psi||_{1,\ler}^2
            -2 a \ixr \g(\psi R\otimes R ):\g\D u \dr \dx \bbr \bbr \\
            \le & d'(t) \is \xier |\hu|^2 \d \xi
            \le \ep^2 d'(t)  (\eta + t)^{-1} (\eta+t)^{-\frac{N}{2}}. 
  \end{aligned}
  $$
  Integrating the above inequality yields that
  \begin{equation}\label{est-gup}
  ||\g u||_1^2 + ||\g \psi||_{1,\ler}^2
  \le \ep^2 (\eta+ t)^{-\frac{N}{2}-1}.
  \end{equation}
 By the standard $L^2$-estimate of $\psi$, we obtain
  $$
  \begin{aligned}
  &\frac{1}{2}\dt ||\psi||_\lerer
  +\nu ||\g\psi||_\lerer
  + ||\psi||_\hyier\\
  =&\ixr \divr( -\g u\cdot R\psi )\psi\dri\dx
  + \ixr \divr( -\g u\cdot R\pin )\psi\dri\dx\\
  \leq & |||\g u|||\,||\psi||_\hyier
  + C||\g u ||^2 + \frac{1}{4}||\psi||_\hyier.
  \end{aligned}
  $$
  Combining the above estimates with Theorem \ref{thm-exist} and (\ref{est-gup}) yields that
  $$
  \dt ||\psi||_\lerer + ||\psi||_\hyier 
  \le \ep^2 (\eta + t)^{-\frac{N}{2}-1},
  $$
  which implies 
  $$
  ||\psi||_\lerer
  \leq \ep^2 C(\eta + t)^{-\frac{N}{2}-1}.
  $$
\end{proof}
