\section{Tight-Binding model of topological superconductor leads}

\noindent 

 It has been shown that, the general Hamiltonian, near $\pm K$ points and in the basis ${\left(c_{e\uparrow },c_{e\downarrow }\right)}^{\dagger }$ which $c_{e\uparrow (\downarrow )}$ is the annihilation operator of $4d^2_z$ electrons with spin-up (down), reads [34]:
\begin{equation*} \label{GrindEQ__20_} 
H\left(\overrightarrow{k}+\tau \overrightarrow{K}\right)=\left(\frac{{\left|\overrightarrow{k}\right|}^2}{2m^*_e}-\mu \right)I_z+\tau \lambda {\sigma }_z+
\end{equation*}
\begin{equation}
{\gamma }_R(k_y\hat{x}-k_x\hat{y})\cdot \left({\sigma }_x\hat{x}+{\sigma }_y\hat{y}+{\sigma }_z\hat{z}\right) 
\end{equation} 
where, $I_z$ and ${\sigma }_i$ are unit and Pauli matrix, respectively and $\tau $ is the valley degree of freedom. The intrinsic and Rashba SOC parameter are $\lambda $ and ${\gamma }_R$, respectively.

\noindent        The different possible superconducting pairing phases in MoS${}_{2}$ has been studied, before [34]. It has been shown that, if $A_1$  be the trivial  representation of $C_{3h}$ point group symmetry of the monolayer of MoS${}_{2}$, the singlet pairing component of the superconducting pairing matrix dominates and , in the basis ${\left(c_{e\uparrow },c_{e\downarrow }\right)}^{\dagger }$, can be written as ${{\Delta }_s=\Delta }_0\sum^3_{j=1}{{\omega }^{j-1}{\mathrm{cos} (\overrightarrow{k}\ }.{\overrightarrow{R}}_j)}\left(i{\sigma }_y\right)$ i.e., [34]:
\begin{equation*} \label{GrindEQ__21_} 
{\Delta }_s=\left( \begin{array}{cc}
0 & {\Delta }_0\sum^3_{j=1}{{\omega }^{j-1}{\mathrm{cos} (\overrightarrow{k}\ }.{\overrightarrow{R}}_j)} \\ 
-{\Delta }_0\sum^3_{j=1}{{\omega }^{j-1}{\mathrm{cos} (\overrightarrow{k}\ }.{\overrightarrow{R}}_j)} & 0 \end{array}
\right)=
\end{equation*}
\begin{equation}
\left( \begin{array}{cc}
0 & {\Delta }_{sc} \\ 
-{\Delta }_{sc} & 0 \end{array}
\right) 
\end{equation} 
 Here, ${\Delta }_0$ and ${\sigma }_y$ are the spin-singlet pairing strength and the Pauli matrix, respectively and $\omega =e^{2\pi i/3}$  [34].  It can be shown that only this phase is characterized by the Chern numbers (CN) and supports Majorana edge states (MES) [34].

\noindent       By choosing ${\left({\psi }^e_{A,\uparrow },{\psi }^h_{A,\uparrow },{\psi }^e_{A,\downarrow },{\psi }^h_{A,\downarrow },{\psi }^e_{B,\uparrow },{\psi }^h_{B,\uparrow },{\psi }^e_{B,\downarrow },{\psi }^h_{B,\downarrow }\right)}^{\dagger }$ as the basis functions and using Eqs.(1), Eq.(20), and Eq.(21), the Hamiltonian of topological superconductor lead reads (in $k$-space):
\begin{equation} \label{GrindEQ__22_} 
H_{SC}=\left( \begin{array}{cc}
E11 & T11 \\ 
{T11}^{\dagger } & E22 \end{array}
\right) 
\end{equation} 
where
\begin{equation} \label{GrindEQ__23_} 
E11=\left( \begin{array}{cc}
 \begin{array}{cc}
\frac{k^2}{2m^*_e}-\mu  & {\Delta }_{sc} \\ 
{\Delta }^{\dagger }_{sc} & -\frac{k^2}{2m^*_h}+\mu  \end{array}
 &  \begin{array}{cc}
0 & 0 \\ 
0 & 0 \end{array}
 \\ 
 \begin{array}{cc}
0 & 0 \\ 
0 & 0 \end{array}
 &  \begin{array}{cc}
\frac{k^2}{2m^*_e}-\mu  & -{\Delta }_{sc} \\ 
-{\Delta }^{\dagger }_{sc} & -\frac{k^2}{2m^*_h}+\mu  \end{array}
 \end{array}
\right) 
\end{equation} 
\begin{equation} \label{GrindEQ__24_} 
E22=\left( \begin{array}{cc}
 \begin{array}{cc}
