0 & \ \ \ \ \cdots \ \ \ \  & 0 \end{array}
 \\ 
{\beta }^{\dagger } & {\alpha }_{N(SC)} &  \begin{array}{ccc}
\beta \ \ \ \ \  & 0 & \ \ \ \ \ 0 \end{array}
 \\ 
 \begin{array}{c}
0 \\ 
\vdots  \\ 
0 \end{array}
 &  \begin{array}{c}
{\beta }^{\dagger } \\ 
0 \\ 
\cdots  \end{array}
 &  \begin{array}{ccc}
 \begin{array}{c}
{\alpha }_{N(SC)} \\ 
\ddots  \\ 
\cdots  \end{array}
 &  \begin{array}{c}
\beta  \\ 
\ddots  \\ 
{\beta }^{\dagger } \end{array}
 &  \begin{array}{c}
\vdots  \\ 
\beta  \\ 
{\alpha }_{N(SC)} \end{array}
 \end{array}
 \end{array}
\right)                                       
\end{equation}
\noindent 

\noindent which,  ${\alpha }_N=\left( \begin{array}{cc}
2t-\mu  & 0 \\ 
0 & -2t+\mu  \end{array}
\right)$, ${\alpha }_{SC}=\left( \begin{array}{cc}
2t-\mu  & {\Delta }_{SC} \\ 
{\Delta }^{\dagger }_{SC} & -2t+\mu  \end{array}
\right)$, $\beta =\left( \begin{array}{cc}
-t & 0 \\ 
0 & t \end{array}
\right)$ , and $t=\frac{{\hslash }^2}{2m^*a^2}$ [51]. Here,$\ \ \mu $ is the chemical potential,$\ \ t$ is the hopping constant, $\ m^*$ is the effective mass of electron, $a$ is the lattice constant, and  ${\Delta }_{SC}={\Delta }_0e^{i\varphi }$ is the superconductor pairing potential which $\varphi $ is the applied phase to the lead. It should be noted that this is an effective discrete lattice description of the junction and is not an atomic model [51]. The basis set is $\psi ={\left(c_{i,\uparrow },c^{\dagger }_{i+1,\downarrow }\right)}^{\dagger }\ $ which $c^{\dagger }_{i,\uparrow }$ and $c_{i+1,\downarrow }$ are the creation operator of spin-up electron and spin-up hole, respectively. It should be noted that the annihilation operator of spin-down electron is the creation operator of spin-up hole. 

\noindent       By using the Sancho's method [56], the retarded surface Green function of the left ($g_{sL}$) and right ($g_{sL}$) leads can be calculated. For doing that, one should consider ${\alpha }_{SC}$ as the Hamiltonian of the central cell and $\beta $ as the hopping term between the central cell and its left and right neighbor cells. In this effective discrete lattice, the retarded self-energies of leads are [51]:
\begin{equation}
{\mathrm{\Sigma }}^r_L=\left( \begin{array}{cc}
{(\beta }^{\dagger }g_{sL}\beta )\times {10}^{-3} & 0_{2\times (N-2)} \\ 
0_{(N-2)\times 2} & 0_{(N-2)\times (N-2)} \end{array}
\right)                                                                      
\end{equation}
\begin{equation}
{\mathrm{\Sigma }}^r_R=\left( \begin{array}{cc}
0_{(N-2)\times (N-2)} & 0_{(N-2)\times 2} \\ 
0_{2\times (N-2)} & (\beta g_{sR}{\beta }^{\dagger })\times {10}^{-3} \end{array}
\right)
\end{equation}                                                                       

\noindent      It should be noted that, for observing the Andreev bound states, we should consider the potential barrier between the superconductor leads and the transport channel. This is modeled by decreasing the hopping parameter, t,  i.e., by multiplying the ${\mathrm{\Sigma }}^r_{L(R)}$-matrix in the factor ${10}^{-3}$.

\noindent In coherent regime, the retarded Green function of the transport channel is (i.e., normal region) is equal to [46-51]:

\begin{equation}
G^r\left(E\right)={\left(\left(E+i\eta \right)\mathrm{l}-H_N-{\mathrm{\Sigma }}^r_L-{\mathrm{\Sigma }}^r_R\right)}^{-1}                                                                        
\end{equation}

\noindent where, $\mathrm{l}$ is $\left(N\times N\right)\ $unit matrix ($N$ is the dimension of $H_N$), ${\mathrm{\Sigma }}^r_{L(R)}$ is The self-energy of left (right) lead, and $\eta $ is an infinitesimal constant (e.g. $1.5\times {10}^{-3}$). The advanced Green function is $G^a\left(E\right)=G^{r\dagger }(E)$. Also, the lesser self-energy or in-scattering function (matrix) of either contact is:

\begin{equation}
{\mathrm{\Sigma }}^<_{L\left(R\right)}\left(E\right)=-\left({\mathrm{\Sigma }}^r_{L\left(R\right)}-{\mathrm{\Sigma }}^a_{L\left(R\right)}\right)f_{L\left(R\right)}(E)=i{\mathrm{\Gamma }}_{L\left(R\right)}f_{L\left(R\right)}(E)                                                  
\end{equation}

\noindent where, ${\mathrm{\Sigma }}^a_{L(R)}={\mathrm{\Sigma }}^{r\dagger }_{L(R)}$ is advanced self-energy and $f_{L(R)}=1/(1+{\mathrm{exp} \left(\frac{E-\mu }{K_BT}\right)\ })$ represents the Fermi-Dirac distribution function at left (right) contact. The broadening matrix of the left (right) lead is ${\mathrm{\Gamma }}_{L\left(R\right)}$. It can be shown that the current operator for left (right) contact is [47-52]:

\begin{equation}
I^{op}_{L(R)}=\frac{e}{h}\left[G^r\left(E\right){\mathrm{\Sigma }}^<_{L\left(R\right)}-{\mathrm{\Sigma }}^<_{L\left(R\right)}G^a\left(E\right)+G^<\left(E\right){\mathrm{\Sigma }}^a_{L\left(R\right)}-{\mathrm{\Sigma }}^r_{L\left(R\right)}G^<(E)\right]                                
\end{equation}

\noindent Where, $G^<\left(E\right)=G^r(E)\left({\mathrm{\Sigma }}^<_L+{\mathrm{\Sigma }}^<_R\right)G^a(E)$ is the lesser Green function. Since both contacts are superconductors, the net current through left(right) contact is equal to the difference between electron and hole current. Therefore, the fledged current operator is:

\begin{equation}
I^{op}_{L(R)}=\frac{e}{h}\left[G^r\left(E\right){\mathrm{\Sigma }}^<_{L\left(R\right)}-{\mathrm{\Sigma }}^<_{L\left(R\right)}G^a\left(E\right)+G^<\left(E\right){\mathrm{\Sigma }}^a_{L\left(R\right)}-{\mathrm{\Sigma }}^r_{L\left(R\right)}G^<(E)\right]{\tau }_z                     
\end{equation}       

\noindent 

\noindent where, by attention to the basis set which has been used for writing $H_{SC}$

\begin{equation}
{\tau }_z={\mathrm{l}}_{N\times N}\otimes {\sigma }_z={\left( \begin{array}{ccc}
1 & 0 &  \begin{array}{cc}
\cdots  & 0 \end{array}
 \\ 
0 & -1 &  \begin{array}{cc}
\cdots  & 0 \end{array}
 \\ 
 \begin{array}{c}
\vdots  \\ 
0 \end{array}
 &  \begin{array}{c}
0 \\ 
0 \end{array}
 &  \begin{array}{cc}
 \begin{array}{c}
\ddots  \\ 
\cdots  \end{array}
 &  \begin{array}{c}
\vdots  \\ 
-1 \end{array}
 \end{array}
 \end{array}
\right)}_{2N\times 2N}
\end{equation}                                                 

\noindent Now, the total current reads:

\begin{equation}
I^{\varphi }_{L(R)}=\int{dE\ real\left(trace\left(I^{op}_{L\left(R\right)}(E,\varphi )\right)\right)}                                                        
\end{equation}
\noindent By changing  the applied phase to left (right) lead at range $\left(-\pi -\pi \right)$ and integrating  $I^{\varphi }_{L(R)}$ over the phase differences , it is possible to obtain the variation of current against the variation of the applied phase differences, i.e.,

\begin{equation}
I_{L(R)}=\int{d\varphi }\ I^{\varphi }_{L(R)}                                                                             \end{equation}

\noindent       It should be noted that, when we deal with the superconducting leads (or even superconductor transport channel), we cannot write the lesser Green function as, $G^<=iG^r\left({\mathrm{\Gamma }}_LF_L+{\mathrm{\Gamma }}_RF_R\right)G^a$, where ${\mathrm{\Gamma }}_{L(R)}=i\left({\mathrm{\Sigma }}^r_{L(R)}-{\mathrm{\Sigma }}^a_{L(R)}\right)$ and $F_{L(R)}=\left( \begin{array}{cc}
f(E,\mu ) & 0 \\ 
0 & f(E,-\mu ) \end{array}
\right)$, because it misses a term in the current proportional to $\left(G^rG^a\right)$ , the trace of which increases with the number of Andreev bound states (which depends on the length of the nanowire) [47-52]. In consequence, we can write the current operator as below [47-52]:

\begin{equation}
I^{op}_{L(R)}=\frac{e}{h}real\left(trace\left(\left(G^a{\mathrm{\Sigma }}^a_{L(R)}-G^r{\mathrm{\Sigma }}^r_{L(R)}\right){\tau }_z\right)\right)                                         
\end{equation}

\noindent    Also, for each $\Delta \varphi $, the density of states (DOS) can be computed as the trace of the spectral Green function i.e., [51]:

\begin{equation}
DOS=\sum_E{DOS\left(E\right)}=\sum_E{\left(\frac{1}{2\pi }trace\left[A\left(E\right)\right]=\frac{1}{2\pi }trace(i\left\{G^r-G^a\right\})\mathrm{\ }\right)}                       
\end{equation}

\noindent 

\noindent The real-valued singularities of the density of states are the Andreev bound state (ABS) energies and are computed as a function of the phase difference of the order parameter of the leads [51]. 

\noindent       However, for observing the Andreev bound states in a typical experiment, one should set $\mu \gg {\Delta }_0$ and $E\ll {\Delta }_0$, where $E$ is the excitation energy of electrons [48,56]. Also, the parabolic dispersion relations, in normal region, correspond to the condition $t\gg \mu $ [48,56].  In consequence, the choice of the effective lattice parameter $a$ is bounded by the condition $t\gg \mu \gg {\Delta }_0$. Otherwise, Andreev bound states will not be observed [48,56]. We choose $t=1.2$ eV, $\mu =0.4$ eV and ${\Delta }_0$=0.01 eV, such that $\frac{t}{\mu }=30$ and $\frac{\mu }{{\Delta }_0}=40$. Also, we set $\left(-{\Delta }_0\times {10}^{-3}\le E\le {\Delta }_0\times {10}^{-3}\right)$, and $N_{normal}=60$ (the number of pints in normal region). As Fig.A1 shows, the total current ($I_L-I_R$) behaves as, $I_0{\mathrm{sin} (\Delta \varphi )\ }$ when the phase $\varphi $ ($-\varphi $) is applied to the left (right) lead at the range $\left(0,\pi \right)$. The behavior is attributed to the Andreev bound states and shows that he transmission value $\tau <1$ (i.e., anti-crossing regime) [48,56]. It should be noted that, in addition to the above mentioned constraint related to the lattice parameter, the length of the normal region (i.e., the number of lattice points) is also important to satisfy the condition $L\gg \xi $ ($L\ll \xi $) for long (short) SC/N/SC junction where $\xi =\frac{\hslash v_F}{\pi {\Delta }_0}$ is the superconducting coherence length, with $v_F$ is the Fermi velocity [57].


