\begin{lemma}\label{lem_wellpose-proj}
If $[Q,H]$ can be extended as a bounded operator on $\ell^2(\Z^d)$, then $\chi_I(H) u \in \CH^1(\Z^d)$ for any $I\subset \R$ and any $u\in \CH^1(\Z^d)$.
\end{lemma}
\proof Since $[Q,H]$ can be extended as a bounded operator on $\ell^2(\Z^d)$, for any $z\in\C\setminus \R$, it holds on $\ell^2(\Z^d)$ that
$$[Q,(H-z)^{-1}]=-(H-z)^{-1}[Q,H](H-z)^{-1}.$$
Through the Helffer-Sj\"ostrand representation \cite{HS1989}, for $\varphi\in C_c^\infty(\R)$, we have that
$[Q,\varphi(H)]$ can be extended as a bounded operator on $\ell^2(\Z^d)$.

Now, for $\chi_I$, there exists a sequence $\{\varphi_n\}\subset C_c^\infty(\R)$ such that $\sup|\varphi_n|\leq 1$ and $\varphi_n\to \chi_I$ pointwise. By the uniform bound $\|[Q,\varphi_n(H)]\|_{\CB(\ell^2(\Z^d))}\leq C$
%\marginpar{The notation $\| \cdot \|_{\ell^2(\Z^d)}$ is non-standard. If this is just the operator norm, it is usually denoted by $\| \cdot \|$ or $\| \cdot \|_{\mathcal{B}(\ell^2(\Z^d))}$.} 
for some $C>0$, as well as the strong convergence $[Q,\varphi_n(H)]\to [Q,\chi_I(H)]$, we have
$\|[Q,\chi_I(H)]\|_{\CB(\ell^2(\Z^d))}\leq C$.
%Hence $[Q,\chi_I(H)]$ is bounded.
Since $\chi_I(H)$ is bounded on $\ell^2(\Z^d)$,
$$ Q \chi_I(H) u = \chi_I(H) Q u + [Q,\chi_I(H)] u \in \ell^2(\Z^d),\quad \forall \ u\in \CH^1(\Z^d). \qed $$

%\begin{remark} The assumption of Lemma \ref{lem_wellpose-proj} corresponds to the convention $H\in C^1(Q)$
%\cite[Definition 6.2.2, Theorem 6.2.10]{ABG1996}. This assumption holds for the discrete Schr\"odinger operator $H=-\Delta + V$ with any real-potential $V$.\marginpar{Is there a reference for this?}
%%Since $H\in C^1(Q)$, .
%%According to \cite[(6.2.24)]{ABG1996}, 
%\end{remark}

\begin{prop}\label{prop_H1orthog}
Let $H$ be a self-adjoint operator on $\ell^2(\Z^d)$ with non-empty a.c. spectrum. Assume that $[Q,H]$ can be extended as a bounded operator on $\ell^2(\Z^d)$.
Given $I,J\subset\R$ with $0<\Leb(I) , \ \Leb(J)<\infty$ and $I\cap J=\emptyset$, we have, for $u\in \CH_{\rm ac}^1(\Z^d)$,
\begin{equation}\label{wellpose-proj_IJ}
Q e^{-\ri tH}\chi_I(H) u, \  Q e^{-\ri tH}\chi_J(H) u\in \ell^2(\Z^d),\quad \forall \ t\in\R,
\end{equation}
and for $t>0$ sufficiently large,
\begin{eqnarray}
& &\left\|Q e^{-\ri tH}(\chi_I(H) u + \chi_J(H) u)\right\|_0\nonumber\\
&> &\frac12 \max\left\{\|Q e^{-\ri tH}\chi_I(H) u\|_0, \ \|Q e^{-\ri tH}\chi_J(H) u\|_0\right\}.\label{almost_orthog}
\end{eqnarray}
\end{prop}
\proof Suppose $u\in \CH_{\rm ac}^1(\Z^d)$. In view of the ballistic upper bound (see Proposition \ref{prop-upper} below), we have 
$e^{-\ri tH} u\in \CH^1(\Z^d)$. Noting that
$$e^{-\ri tH}\chi_I(H) u=\chi_I(H)  e^{-\ri tH} u,\quad e^{-\ri tH}\chi_J(H) u=\chi_J(H)  e^{-\ri tH} u,$$
we obtain (\ref{wellpose-proj_IJ}) according to Lemma \ref{lem_wellpose-proj}.

Direct computations yield that
\begin{eqnarray*}
  & &\|Q e^{-\ri tH}(\chi_I(H) u + \chi_J(H) u)\|^2_0\\
   &=&  \|Q e^{-\ri tH}\chi_I(H) u\|^2_0 + \|Q e^{-\ri tH}\chi_J(H) u\|^2_0  +  C^u_{I,J}(t) + C^u_{J,I}(t),
\end{eqnarray*}
with $C^u_{I,J}(t)$ and $C^u_{J,I}(t)$ defined as
\begin{eqnarray*}
C^u_{I,J}(t)&:=&\left\la Q e^{-\ri tH} \chi_I(H) u, Q e^{-\ri tH}  \chi_J(H) u\right\ra,\\
C^u_{J,I}(t)&:=&\left\la Q e^{-\ri tH} \chi_J(H) u, Q e^{-\ri tH}  \chi_I(H) u\right\ra.
\end{eqnarray*}
To show (\ref{almost_orthog}), it is sufficient to show that
$C^u_{I,J}(t)$, $C^u_{J,I}(t)\to 0$ as $t\to \infty$.
Let $E_{H}(\cdot)$ be the projection-valued measure of $H$ and let $\{\delta_n\}_{n\in\Z^d}$ be the standard basis of $\ell^2(\Z^d)$. Define the scalar measure $\mu_n(\cdot)=\la \delta_n, E_{H}(\cdot) u\ra$, which is a.c.\ on $\sigma_{\rm ac}(H)$ since $u\in\CH_{\rm ac}^1(\Z^d)$.
Then we have
$$(e^{-\ri tH}\chi_I(H) u)_n=\int_{I}e^{-\ri t\lambda} d\mu_n(\lambda),\quad (e^{-\ri tH}\chi_J(H) u)_n=\int_{J}e^{-\ri t\sigma} d\mu_n(\sigma), $$
and hence, by Fubini's theorem,
\begin{eqnarray*}
C^u_{I,J}(t)&=& \sum_{n\in\Z^d}(1+|n|^2)\left(\int_{I}e^{-\ri t\lambda} d\mu_n(\lambda)\right)\overline{\left(\int_{J}e^{-\ri t\sigma} d\mu_n(\sigma)\right)}\\
&=&\int_I \int_J e^{-\ri t (\lambda-\sigma)}\sum_{n\in\Z^d}(1+|n|^2)d\mu_n(\lambda) d\bar\mu_n(\sigma)\\
&=:&\int_{\R} e^{-\ri tE} d\nu(E),
\end{eqnarray*}
where the measure $\nu$ is defined as: for $B\subset\R$,
$$\nu(B)=\sum_{n\in\Z^d}(1+|n|^2) \int_{I\times J} \chi_{\{\lambda-\sigma\in B\}}(\lambda,\sigma)  d\mu_n(\lambda) d\bar\mu_n(\sigma).$$
Since $u\in \CH_{\rm ac}^1(\Z^d)$, we have
\begin{eqnarray*}
|\nu(\R)|&\leq&\sum_{n\in\Z^d}(1+|n|^2)\left| \mu_n(I)\right| \left|\bar\mu_n(J)\right|\\
&\leq&\sum_{n\in\Z^d}(1+|n|^2)|(\chi_I(H) u)_n||(\chi_J(H) \bar u)_n|\\
&\leq&\frac12(\|\chi_I(H) u\|_1^2+\|\chi_J(H) u\|_1^2).
\end{eqnarray*}
According to the Riemann-Lebesgue lemma, $C^u_{I,J}(t)\to 0$ as $t\to\infty$.
Similarly, $C^u_{J,I}(t)\to 0$.\qed


\subsection{Strict Mourre Estimate}

From now on, for the self-adjoint operator $H$,
we always assume that $[Q,H]$ can be extended to a bounded operator on $\ell^2(\Z^d)$, such that Lemma \ref{lem_wellpose-proj} and Proposition \ref{prop_H1orthog} are applicable. We will verify this assumption for the class of Schr\"odinger operators of interest to us in Example~\ref{ex.so} below.

\begin{prop}\label{prop-mourre-ballistic}
For a self-adjoint operator $H$ acting on $\ell^2(\Z^d)$, assume that, on $I\subset\R$ with $\Leb(I\cap\sigma(H))>0$, there is $\theta >0$ such that
\begin{equation}\label{strictMourre}
 \chi_I(H)[H,[H,-Q^2]]\chi_I(H)\geq \theta\chi_I(H). \end{equation}
Then, we have
\begin{equation}\label{ballistic-lower}
\frac{\|e^{-\ri tH} u\|_{1}}{t}\gtrsim \theta^\frac12  \|\chi_I(H) u\|_{0},\quad  \forall \ u\in \CH_{\rm ac}^1(\Z^d), \; t > 0.
\end{equation}
\end{prop}
\begin{remark} 
(a) It is well known that the strict Mourre estimate implies purely a.c. spectrum; compare \cite[Section~7.2]{ABG1996}. Hence, under the assumption \eqref{strictMourre}, $\chi_I(H)u\in \CH_{\rm ac}(H)$ for any $u\in\ell^2(\Z^d)$.
\\[1mm]
(b) Beyond the $\ell^2(\Z^d)$ setting, the Mourre estimate has also been employed to establish the absence of singular continuous spectrum for adjacency operators on graphs \cite{MRT07}. Moreover, it plays an important role in the study of scattering theory; see, e.g., \cite{BS12, DG97, GN98}.
\end{remark}


The proof of Proposition~\ref{prop-mourre-ballistic} relies on the following lemma.

