\begin{lemma}Under the assumption of Proposition \ref{prop-mourre-ballistic}, we have that
\begin{equation}\label{lowerbound}
\frac{\| Q e^{-\ri tH} \chi_I(H) u\|_{0}}{t}\gtrsim \theta^\frac12  \|\chi_I(H) u\|_{0} ,\quad \forall \ u\in \CH^1(\Z^d), \; t > 0.
\end{equation}
\end{lemma}

\proof  Based on the proofs of  \cite[Proposition 1.2]{CH1992} and \cite[Proposition 4.6]{DMY2024}, we have
%\begin{eqnarray*}
%\|Q e^{-\ri tH} u\|_{L^2}^2&=&\la u, Q^2 u \ra+\int_0^t \la u, \ri [H, Q^2]u\ra  ds\\
%&=&\la u, Q^2 u \ra - \int_0^t \la u, \ri e^{\ri t H} A  e^{-\ri t H}u\ra  ds\\
%\end{eqnarray*}
for $u\in \CH^1(\Z^d)$,
\begin{eqnarray}
\|Q e^{-\ri tH}  \chi_I(H)  u\|_0^2&=&\la  \chi_I(H)  u, e^{\ri tH} Q^2 e^{-\ri tH}  \chi_I(H)   u \ra\nonumber \\
&=& \la  \chi_I(H)  u,  Q^2   \chi_I(H)   u \ra - \ri t \la \chi_I(H)  u, [H,- Q^2]   \chi_I(H)   u  \ra\nonumber \\
 & & + \, \int_0^t \int_0^s   \left\la  e^{-\ri \sigma H}  \chi_I(H)  u, [H,[H,-Q^2]] e^{-\ri \sigma H}  \chi_I(H)  u \right\ra \, d\sigma \, ds,\label{integal-second}
\end{eqnarray}
%{\clr In \cite{DMY2024}, it is assumed that the interval satisfies $I\subset \sigma(H)$, which assumes that $\sigma(H)$ is a union of intervals. It can be generalized to $\Leb(I\cap\sigma(H))>0$.}
where the assumption $\chi_I(H)  u\in \CH^1(\Z^d)$ in \cite[Proposition 4.6] {DMY2024} is guaranteed by Lemma \ref{lem_wellpose-proj} once we have $u\in \CH^1(\Z^d)$.

As $t\to\infty$, we obtain \eqref{lowerbound},
since the strict Mourre estimate \eqref{strictMourre} implies that the integral term in \eqref{integal-second} satisfies
$$\left|\int_0^t \int_0^s   \left\la  e^{-\ri \sigma H}  \chi_I(H)  u, [H,[H,-Q^2]] e^{-\ri \sigma H}  \chi_I(H)  u \right\ra \, d\sigma \, ds \right| \geq \frac{\theta \|\chi_I(H)  u\|_0^2 }{2} t^2. \qed$$


\medskip 

\noindent{\it Proof of Proposition \ref{prop-mourre-ballistic}.} Write $\sigma(H)=I\cup I^c$ with $I$ and $I^c$ mutually disjoint. For $u\in \CH_{\rm ac}^1(\Z^d)$, we have
$$
u=\chi_{I}(H)u+\chi_{I^c}(H)u,
$$ 
and according to Proposition \ref{prop_H1orthog}, we have 
$$
\|Qe^{-\ri tH} u\|_{0}\geq \frac12 \|Qe^{-\ri tH} \chi_{I}(H) u\|_{0}
$$
for $t > 0$ sufficiently large, which together with \eqref{lowerbound} implies \eqref{ballistic-lower}.\qed

