\subsection{Mourre Estimate With a Compact Perturbation}

According to Proposition~\ref{prop-mourre-ballistic}, the strict Mourre estimate \eqref{strictMourre}, which implies purely a.c. spectrum of $H$ on $I$ \cite[Section~7.2]{ABG1996}, also implies ballistic transport for any initial state with non-trivial projection onto $\Ran \, \chi_I (H)$. It can be suitably generalized for the general Mourre estimate on $I$: there exist $\theta >0$ and a self-adjoint compact operator $K$ such that
\begin{equation}\label{Mourre-compact}
 \chi_I(H)[H, [H, -Q^2]]\chi_I(H)\geq \theta\chi_I(H)+K.
\end{equation}
In view of \cite{M1981} or \cite[Corollary 7.2.11]{ABG1996}, the estimate \eqref{Mourre-compact} implies that in $I$, the singular continuous spectrum of $H$ is empty and all eigenvalues of $H$ are isolated.

\begin{prop}\label{prop-mourre-ballistic-compact}
For a self-adjoint operator $H$ acting on $\ell^2(\Z^d)$, assume that on $I\subset\R$ with $\Leb(I\cap\sigma(H))>0$, the estimate \eqref{Mourre-compact} holds. Then there exists a subset $I_1\subset I$ with $\Leb(I_1\cap\sigma(H))>0$ such that
\begin{equation}\label{strictMourre-compact}
 \chi_{I_1}(H)[H, [H, -Q^2]]\chi_{I_1}(H)\geq \frac{\theta}{2} \chi_{I_1}(H).
 \end{equation}
%  for $u\in \CH^1(\R^d)$ with $e^{-\ri tH}  u\in \CH^1(\R^d)$, we have
%$$\frac{\|e^{-\ri tH} u\|_{\CH^1}}{t}\gtrsim \theta^\frac12  \|\chi_I(H) u\|_{\CH^0} . $$
\end{prop}
\proof Similar to the proof of Lemma 2.13 in \cite{M2022}, we show that, by shrinking $I$ enough, a strict Mourre estimate \eqref{strictMourre-compact} is true.

Take $E_0 \in I \cap\left(\sigma_{a c}\left(H\right) \setminus \sigma_{p p}\left(H\right)\right)$ and $\delta>0$, define the subset $I_1(\delta)$ as
$$
I_1(\delta):=\left]E_0-\delta, E_0+\delta\right[ \cap I \quad {\rm s. \ t.} \quad  I_1(\delta)\cap\sigma_{p p}\left(H\right)=\emptyset. 
$$
This is possible since the eigenvalues of $H$ in $I$ are isolated. If $\delta$ is sufficiently small, we have in addition
\begin{equation}\label{Ksmall}
\left\|\chi_{I_1(\delta)}\left(H\right) K \chi_{I_1(\delta)}\left(H\right)\right\|_{\CH^0 \to \CH^0} \leq \frac{\theta}{2}.
\end{equation}
Indeed, the spectral measure of $H$ on $I_1(\delta)$ is purely a.c., which means that
$$\varphi_{\delta}:=\chi_{I_1(\delta)}\left(H\right) \varphi\in \CH_{\rm ac}(H),\qquad  \forall \ \varphi \in \CH^0(\Z^d).$$
Then, by the dominated convergence theorem, we have
$$
\left\|\chi_{I_1(\delta)}\left(H\right) \varphi\right\|_0^2=\int_{\mathbb{R}} \chi_{I_1(\delta)}\left(E\right)^2 \mathrm{~d} m_{\varphi_{\delta}}(E) \rightarrow 0 \quad {\rm as } \quad \delta \rightarrow 0.
$$
In particular, $\chi_{I_1(\delta)}\left(H\right) \rightarrow 0$ strongly as $\delta \rightarrow 0$. Since $K$ is compact, $\chi_{I_1(\delta)}\left(H\right) K \rightarrow 0$ uniformly as $\delta \rightarrow 0$.
Therefore, for $\delta$ sufficiently small, \eqref{Ksmall} holds true.

Combining this with \eqref{Mourre-compact}, we have that
%\marginpar{Why is there a minus sign in the third line and not a plus sign?}
\begin{eqnarray*}
& &\chi_{I_1(\delta)}\left(H\right) [H, [H, -Q^2]] \chi_{I_1(\delta)}\left(H\right)\\
&=&\chi_{I_1(\delta)}\left(H\right) \chi_{I}\left(H\right) [H, [H, -Q^2]] \chi_{I}\left(H\right) \chi_{I_1(\delta)}\left(H\right) \\
&\geq&\theta \chi_{I_1(\delta)}\left(H\right) \chi_{I}\left(H\right) \chi_{I_1(\delta)}\left(H\right)+\chi_{I_1(\delta)}\left(H\right) K \chi_{I_1(\delta)}\left(H\right)\\
&\geq& \frac{\theta}{2}\chi_{I_1(\delta)}\left(H\right),
\end{eqnarray*}
which implies (\ref{strictMourre-compact}).\qed

\medskip

Under the assumption \eqref{Mourre-compact} on $I$, for any non-vanishing $u\in \CH_{\rm ac}(H)$, there is one subset $I_1$ such that $\|\chi_{I_1}(H) u\|_{0}>0$. Then, according to Proposition \ref{prop-mourre-ballistic}, we have

\begin{cor}\label{cor-Mourre-compact-ballistic}
For a self-adjoint operator $H$ on $\ell^2(\Z^d)$, if it satisfies the Mourre estimate \eqref{Mourre-compact}, then $e^{-\ri t H}$ exhibits the order$-1$ ballistic lower bound: $\forall \ u \in \CH_{\rm ac}^1(\Z^d)$, there exists $I_1\subset I$ with ${\rm Leb}(I_1\cap \sigma(H))>0$ such that
$$\frac{\|e^{-\ri tH} u\|_{1}}{t}\gtrsim \theta^\frac12  \|\chi_{I_1}(H) u\|_{0},\quad \forall \ t >0. $$
\end{cor}

%\begin{remark} From Proposition \ref{prop-mourre-ballistic-compact} and Corollary \ref{cor-Mourre-compact-ballistic}, we see that the ballistic lower bound obtained through Mourre estimate is stable under compact perturbations, {\clo if there are at most finitely many embedding eigenvalues}.
%\end{remark}

\section{Proof of Theorem \ref{thm-ballistic-decay}}



In this section, we provide a proof of Theorem \ref{thm-ballistic-decay}. We will split it into two parts, presented in separate subsections, one addressing the upper bound and one addressing the lower bound in \eqref{ballistic-decayingV}.


\subsection{Ballistic Upper Bound}

By general principles, the upper bound in \eqref{ballistic-decayingV} holds for any $r > 0$ and for any self-adjoint discrete Schr\"odinger operator. That is, all we require is that the potential is real-valued, $V : \Z^d \to \R$, in which case the associated Schr\"odinger operator $H=-\Delta+V$ is self-adjoint on the domain
$$
D(H) = D(V) = \{ u \in \ell^2(\Z^d) : Vu \in \ell^2(\Z^d) \}.
$$

Such a result is well known; compare, for example, the discussions in \cite[Appendix~B]{AW12}, \cite[Lemma~B.2]{BDMY23}, \cite[Theorem~A.1]{BS23}, \cite[Theorem 2.6.2]{DF22}, \cite[Theorem 2.22]{DT2010}, and \cite[Theorem~3]{ZZ2017}.\footnote{There is also a ballistic upper bound result in the continuum case due to Radin and Simon \cite{RS78}.} For the reader’s convenience, we include a proof below. In fact, in doing so we establish a particular instance of the upper bound, \eqref{balistic-upper-2}, that is crucial in our discussion of the order$-r$ ballistic lower bound for $0 < r < 1$ below; compare Lemma~\ref{lemSmallorder}.

\begin{prop}\label{prop-upper}
For any self-adjoint discrete Schr\"odinger operator $H=-\Delta+V$ on $\ell^2(\Z^d)$, we have the ballistic upper bound: there exists a constant $c_r>0$, independent of $u$, such that
\begin{equation}\label{balistic-upper-r}
\|e^{-\ri t H} u \|_r\leq c_r\|u\|_r t^r ,\quad \forall \ u\in\CH^r(\Z^d), \; t \ge 1. 
\end{equation}
Moreover, there exists $\tilde c_2>0$ such that
\begin{equation}\label{balistic-upper-2}\|e^{-\ri t H} u \|_2\leq \|u\|_2+ \|u\|_1 t+ \tilde c_2  \|u\|_0 t^2, \quad \forall \ u\in\CH^2(\Z^d), \; t \ge 1. 
\end{equation}
\end{prop}
%\begin{remark} The upper bound (\ref{balistic-upper-2}) with refined coefficients will be used to establish a density argument in order to show the order$-r$ ballistic lower bound with $0<r<1$. See the proof of Lemma \ref{lemSmallorder}.
%\end{remark}
\proof Given $m\in\N^*$, for $u\in \CH^{m}(\Z^d)$, we have
\begin{equation}\label{com-int-upper}
e^{\ri tH}Q^m e^{-\ri tH}  u = Q^m u+\ri \int_0^t  e^{\ri sH}[H, Q^m]e^{-\ri sH}  u \,  ds,
\end{equation}
where $[H, Q^m]$ is well-defined on $\CH^{m-1}(\Z^d)$. Indeed, noting that $[H, Q^m]=[Q^m,\Delta]$ for $H=-\Delta+V$ for any potential $V$,  we have, for $\psi\in \CH^{m-1}(\Z^d)$ and $n\in\Z^d$,
\begin{eqnarray*}
([H, Q^m]\psi)_n&=&([Q^m,\Delta]\psi)_n\\
&=&\sum_{j=1}^d \left((1+|n|^2)^{\frac{m}2}-(1+|n+e_j|^2)^{\frac{m}2}\right)\psi_{n+e_j}\\
& &+ \, \sum_{j=1}^d \left((1+|n|^2)^{\frac{m}2}-(1+|n-e_j|^2)^{\frac{m}2}\right)\psi_{n-e_j},
\end{eqnarray*}
which implies that
$$\|[H, Q^m]\psi\|_0\lesssim_m \|Q^{m-1}\psi\|_0=\|\psi\|_{m-1},$$
since, for $j=1,\cdots,d$, for $n\in\Z^d$,
\begin{eqnarray*}
& &\left|(1+|n|^2)^{\frac{m}2}-(1+|n+e_j|^2)^{\frac{m}2}\right|\\
&\leq&\sum_{k=1}^m\binom{m}{k}\left|\la n+e_j, n+e_j\ra^{\frac{k}2}-\la n, n\ra^{\frac{k}2}\right|\\
&\leq&\sum_{k=1}^m\binom{m}{k}\sum_{l=1}^k\binom{k}{l}|2n_j+1|^{\frac{l}2}\la n+e_j, n+e_j\ra^{\frac{k-l}2} \\
&\lesssim_m& (1+|n+e_j|^2)^{\frac{m-1}2},
\end{eqnarray*}
and similarly, 
$$\left|(1+|n|^2)^{\frac{m}2}-(1+|n-e_j|^2)^{\frac{m}2}\right|\lesssim_m (1+|n-e_j|^2)^{\frac{m-1}2}.$$
Hence, when $V$ is a real potential, we have, through \eqref{com-int-upper},
\begin{eqnarray*}
\|e^{-\ri tH}   u\|_{m}&=&\|e^{\ri tH}Q^{m} e^{-\ri tH}  u \|_0\\
&\leq& \|Q^{m} u\|_0+ \int_0^t \|[H, Q^{m}]e^{-\ri sH} u\|_0 \, ds\\
&\lesssim_m& \|u\|_m+ \int_0^t \|e^{-\ri sH} u\|_{m-1} \, ds,\quad \forall \  t\geq 0.
\end{eqnarray*}
Since for $m=1$, $\|e^{-\ri tH}   u\|_{m-1}=\|u\|_{0}$, we obtain the linear upper bound for $\|e^{-\ri tH}   u\|_1$ for $u\in \CH^{1}(\Z^d)$: there exists $\tilde c_1>0$ such that
$$\|e^{-\ri tH}   u\|_{1}\leq  \|u\|_1+\tilde c_1\|u\|_0  t ,\quad \forall \  t\geq 0. $$ 
Then, via induction, for $u\in \CH^{2}(\Z^d)$,
\begin{eqnarray*}
\|e^{-\ri tH}   u\|_{2}&\leq& \|u\|_2+ \int_0^t \|e^{-\ri sH} u\|_1 \, ds\\
&\leq& \|u\|_2+ \|u\|_1 t  + \frac{\tilde c_1}{2} \|u\|_0  t^2,\quad \forall \  t\geq 0.
\end{eqnarray*}
which shows \eqref{balistic-upper-2}. The above inequalities also imply that, for $m=1, 2$, 
$$\|e^{-\ri tH}   u\|_{m}\leq   c'_m \|u\|_m (1+t)^m ,\quad \forall \  t\geq 0, $$
through which we obtain \eqref{balistic-upper-r} for $r=1,2$.

%\marginpar{\clo But not for all $t > 0$.}


Assume that, for $m\in\N^*$, there exists a constant $c'_m>0$ such that, for any $u\in \CH^{m}(\Z^d)$,
%\marginpar{\clo We don't have this for for all $t > 0$.}
$$
\|e^{-\ri tH}   u\|_m\leq c'_m \|u\|_{m} (1+t)^m,\quad \forall \  t\geq 0.
$$ 
By induction, we have
%\marginpar{\clo Here we are actually using the bound for all $t > 0$.}
\begin{eqnarray*}
\|e^{-\ri tH}   u\|_{m+1}&\lesssim_m& \|u\|_{m+1}+ \int_0^t \|e^{-\ri sH} u\|_{m} \, ds\\
&\lesssim_m& \|u\|_{m+1}+ \frac{c'_m}{m+1}  \|u\|_{m} (1+t)^{m+1},\quad \forall \  t\geq 0.
\end{eqnarray*}
Therefore, the upper bound \eqref{balistic-upper-r} is shown when $r>0$ is an integer.

For $r\in \, ]m,m+1[$ with some $m\in\N$ ($ = \{0,1,2,\ldots\}$) we have
$$r=\left((m+1)-r\right)m+\left(r-m\right)(m+1).$$
%\marginpar{Do you mean the Riesz-Thorin interpolation theorem? If so, let's mention it, this makes it easier for the reader to look it up.} 
Applying H\"older’s inequality, we obtain, for $\psi\in\CH^{m+1}(\Z^d)$,
\begin{eqnarray}
\|\psi \|^2_r&=&\sum_{n\in\Z^d}(1+|n|^2)^{\left((m+1)-r\right)m+\left(r-m\right)(m+1)}  \left|\psi_n\right|^{2}\nonumber\\
&\leq&\left(\sum_{n\in\Z^d}(1+|n|^2)^{m} \left|\psi_n\right|^2\right)^{(m+1)-r}
\left(\sum_{n\in\Z^d}(1+|n|^2)^{m+1} \left|\psi_n\right|^2\right)^{r-m}\nonumber\\
&=&\|\psi \|_m^{2(m+1-r)} \|\psi \|_{m+1}^{2(r-m)}.\label{interpol}
\end{eqnarray}
%\marginpar{Should $ \|u\|_0$ be replaced by $ \|u\|_{m+1}$ on the RHS of \eqref{interpo-upper}?}
In view of the integer order ballistic upper bound, for $u\in\CH^{m+1}(\Z^d)$,
\begin{eqnarray}
\|e^{-\ri t H} u \|_r&\leq& \|e^{-\ri t H} u \|_m^{m+1-r} \|e^{-\ri t H} u \|_{m+1}^{r-m}\nonumber\\
&\leq&  c^{m+1-r}_m c^{r-m}_{m+1} \|u \|_m^{m+1-r} \| u \|_{m+1}^{r-m}\cdot  t^{\left((m+1)-r\right)m+\left(r-m\right)(m+1)} \nonumber\\
&\leq&c_r \|u\|_r t^r ,  \quad  {\rm with} \   c_r:=  c^{m+1-r}_m c^{r-m}_{m+1} . \label{interpo-upper}
\end{eqnarray}
Note that $\CH^{m+1}(\Z^d)$ is dense in $\CH^r(\Z^d)$ in the sense that, given $u\in\CH^r(\Z^d)$, for any $\varepsilon>0$, there exists $u_\varepsilon\in\CH^{m+1}(\Z^d)$ such that
$\|u_\varepsilon-u\|_r< \varepsilon$. Since \eqref{interpo-upper} implies that, for fixed $t\geq 0$, the time-evolution $e^{-\ri t H}: \CH^{m+1}(\Z^d)\to \CH^r(\Z^d)$ is bounded with operator norm controlled by $c_r t^r$,
through the Bounded Linear Transformation Theorem, $e^{-\ri t H}$ is bounded on $\CH^{r}(\Z^d)$ and (\ref{balistic-upper-r}) is satisfied.\qed


