\subsection{Ballistic Lower Bound}

Let us next focus on establishing the lower bound in \eqref{ballistic-decayingV}.

For the Schr\"odinger operator $H=-\Delta+V$, with the real potential $V=(V_n)$ decaying with respect to $|n|$, we show first the following spectral result:
%\marginpar{Should we add the statement $\sigma_{\rm sc}(H)= \emptyset$ to the theorem?}

\begin{prop}\label{p.nosc} 
If $V_n=o(|n|^{-1})$, then $\sigma_{\rm sc}(H)= \emptyset$ and 
$$
\sigma_{\rm ac}(H)=\sigma(-\Delta)=[-2d,2d].
$$
\end{prop}
%{\clo \begin{remark} $J_\theta\subset \sigma_{\rm ac}(H)$
%For any $u$ not eigenvector, $\exists \ \theta>0$ such that
% $\CH_{\rm ac}u\in {\rm Ran}\chi_{J_\theta}$
%\end{remark}}
\proof Since the essential spectrum is invariant under compact perturbations \cite{RS-1}, the essential spectrum of $H=-\Delta+V$ is equal to $\sigma_{\rm ess}(-\Delta) = \sigma(-\Delta) = [-2d,2d]$, provided that the potential $V=(V_n)$ is decaying with respect to $|n|$. 

Furthermore, if $V_n=o(|n|^{-1})$, then we have the compactness of 
\begin{eqnarray*}
([V, [H, -Q^2]]u)_n&=& \sum_{i=1}^d\left(\left(2n_i+1\right) (V_n - V_{n+e_i}  ) u_{n+e_i}\right.\\
& & \  \  \  \  \  \  \left.-\left(2n_i-1\right) (V_n - V_{n-e_i}  ) u_{n-e_i}\right).
\end{eqnarray*}
Hence, given $0<\theta<2d$, for the interval $J_\theta$ defined as in (\ref{Itheta}), we have
$$  \chi_{J_\theta}(H) [H, [H, -Q^2]]\chi_{J_\theta}(H)\geq \frac{2}{d} \theta\chi_{J_\theta}(H)+[V, [H, -Q^2]] \chi_{J_\theta}(H).$$
According to Mourre \cite{M1981} (see also \cite[Section~7.2]{ABG1996}), for any $0<\theta<2d$, in $J_\theta$ there is no singular continuous spectrum and all eigenvalues are isolated. Since we already know that $\sigma_{\rm ess}(H)=[-2d,2d]$, this forces $\sigma_{\rm ac}(H)=[-2d,2d]$ and concludes the proof of the proposition. \qed


%There could, in principle, be eigenvalues of infinite multiplicity or singular continuous spectrum within $[-2d,2d]$. However, we have established a Mourre estimate for H on the interval $(-2d+\theta,2d-\theta)$ for any $\theta>0$, which excludes the presence of such spectrum types in that region. This suggests that only isolated eigenvalues of finite multiplicity could potentially be embedded in $(-2d+\theta,2d-\theta)$. Does this mean that the ac spectrum of $H$ is $[-2d,2d]$? Or at least includes $(-2d,2d)$? 

\medskip

We first show the lower bound in \eqref{ballistic-decayingV} for the case $r=1$. 
For any non-vanishing $u \in \CH_{\rm ac}^1(\Z^d)$, there is $0<\theta<2d$ with $\chi_{J_\theta}(H) u$ non-vanishing.
According to Corollary~\ref{cor-Mourre-compact-ballistic}, $e^{-\ri t H}$ exhibits the order$-1$ ballistic lower bound: for any non-vanishing $u \in \CH_{\rm ac}^1(\Z^d)$, there exists $I_\theta\subset J_\theta$ with $\Leb(I_\theta)>0$ and $\chi_{I_\theta}(H) u$ non-vanishing, such that there is $a_{1}>0$, independent of $u$, such that
\begin{equation}\label{lower-order-1}
\|e^{-\ri tH} u\|_{1}  > a_1 \theta^{\frac12} \|\chi_{I_\theta}(H) u\|_0 \, t,
\end{equation}
which establishes the lower bound in \eqref{ballistic-decayingV} in the case $r=1$.

\medskip

The order$-r$ ballistic lower bound for $r\geq 1$ is deduced from the following lemma. 

\begin{lemma}\label{lemJensen}
For the self-adjoint operator $H$ on $\ell^2(\Z^d)$, if there exists $r>0$ such that for any non-vanishing $u\in \CH_{\rm ac}^r(\Z^d)$, $\|e^{-itH} u \|_{r} \geq b_{r,u} t^r$ for some constant $b_{r,u} > 0$,
then for any $r'>r$ and $u\in \CH_{\rm ac}^{r'}(\Z^d)\setminus\{0\}$, there exists a constant $b_{r',u} > 0$ such that
$\|e^{-itH} u \|_{r'} \geq b_{r',u} t^{r'}$.
\end{lemma}

\begin{remark}
This argument is a variation of the argument given in the proof of \cite[Lemma~2.7]{DT2010}.
\end{remark}

\proof Suppose that $u\in \CH_{\rm ac}^r(\Z^d)$ is  $\ell^2$-normalized. By assumption, there exists a constant $b_{r,u} > 0$ such that $\| e^{-itH} u \|_{r} \geq b_{r,u}  t^r$, which means that
$$
\sum_{n \in \Z^d} (1+|n|^2)^{r} |\la \delta_n , e^{-itH} u \ra|^2  \geq b^2_{r,u}  t^{2r}.
$$
For $r' > r$, note that $x \mapsto |x|^{\frac{r'}{r}}$ is convex on $\R$. Using Jensen's inequality (and emphasizing that $u$ is $\ell^2$-normalized so that $n \mapsto |\langle \delta_n , e^{-itH} u \rangle|^2$ is a probability distribution on $\Z^d$), we observe that, for any $\ell^2$-normalized $u\in \CH_{\rm ac}^{r'}(\Z^d)\subset  \CH_{\rm ac}^{r}(\Z^d)$,
\begin{align*}
\sum_{n \in \Z^d} (1+|n|^2)^{r'} |\langle \delta_n , e^{-itH} u \rangle|^2 & = \sum_{n \in \Z^d} \left( (1+|n|^2)^{r} \right)^{\frac{r'}{r}} |\langle \delta_n , e^{-itH} u \rangle|^2 \\
& \geq \left( \sum_{n \in \Z^d}(1+|n|^2)^{r}  |\langle \delta_n , e^{-itH} u \rangle|^2 \right)^{\frac{r'}{r}}  \\ 
& \geq b^{\frac{2r'}{r}} _{r,u}  t^{2r'},
\end{align*}
which implies that $\| e^{-itH} u \|_{r} \geq b_{r',u}  t^{r'}$ with $b_{r',u} =b_{r,u}^{\frac{r'}{r}} $. By scaling, the bound extends to non-normalized $u\in \CH_{\rm ac}^{r'}(\Z^d)\setminus\{0\}$.\qed


\medskip

As for the case $0<r<1$, we have the following lemma, which completes the proof of Theorem \ref{thm-ballistic-decay}.

\begin{lemma}\label{lemSmallorder} 
For the Schr\"odinger operator $H=-\Delta+V$ with $V_n=o(|n|^{-1})$, for any $0<r<1$ and any non-vanishing $u\in \CH_{\rm ac}^r(\Z^d)$, there exists a constant $b_{r,u} > 0$ such that for $t \ge 1$,
$$
\|e^{-\ri tH} u \|_{r} \geq b_{r,u} t^{r}. 
$$
\end{lemma}
\proof 
Similar to (\ref{interpol}), applying H\"older's inequality, we obtain
$$\|e^{-\ri t H}u\|_1\leq \|e^{-\ri t H}u\|_r^{\frac{1}{2-r}}\|e^{-\ri t H}u\|^{\frac{1-r}{2-r}}_2.$$
According to (\ref{balistic-upper-2}) in Proposition \ref{prop-upper} and \eqref{lower-order-1}, for any $u\in\CH^2_{\rm ac}(\Z^d)\setminus\{0\}$, there exist $0<\theta<2d$ and $I_{\theta}\subset J_{\theta}$, with $J_{\theta}$ defined as in (\ref{Itheta}),
such that $\chi_{I_{\theta}}(H) u$ is non-vanishing and
%\marginpar{It may be better to have a suitable norm of $u$ on the RHS. This shouldn't be hidden in the constant; compare below.}
$$
\|e^{-\ri t H}u\|_1\geq a_1 \theta^\frac12  \|\chi_{I_{\theta}}(H) u\|_{0} \, t,\quad  \|e^{-\ri t H}u\|_2 \leq \|u\|_2+ \|u\|_1 t+ \tilde c_2  \|u\|_0 \, t^2,
$$
which implies that, as $t\to\infty$,
$$
\|e^{-\ri t H}u\|_r\geq \frac{ (a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u\|_{0} t)^{2-r}}{(\|u\|_2+ \|u\|_1 t+ \tilde c_2  \|u\|_0 t^2)^{1-r}}
\geq \frac{(a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u\|_{0})^{2-r}}{2^{1-r}(\tilde c_2  \|u\|_0 )^{1-r}} t^r. 
$$

Note that $\CH^{2}_{\rm ac}(\Z^d)=\CH^{2}(\Z^d)\cap \CH_{\rm ac}(H)$ is dense in $\CH^r_{\rm ac}(\Z^d)=\CH^r(\Z^d)\cap \CH_{\rm ac}(H)$
%\marginpar{Should we write ``$\CH^{2}_{\rm ac}(\Z^d)$ is dense in $\CH^r_{\rm ac}(\Z^d)$''?} 
in the sense that, given $u\in\CH_{\rm ac}^r(\Z^d)$, for any $\varepsilon>0$, there exists $u_\varepsilon\in \CH_{\rm ac}^{2}(\Z^d)$ such that
 $\|u_\varepsilon-u\|_{r}< \varepsilon$, which implies that, for $\varepsilon$ sufficiently small,
 %\marginpar{\clo Discuss this step.}
 \begin{eqnarray*}\|\chi_{I_{\theta}}(H) u_\varepsilon\|_0&\geq&\|\chi_{I_{\theta}}(H) u\|_0- \|u_\varepsilon-u\|_0\\ 
&\geq&\|\chi_{I_{\theta}}(H) u\|_0- \|u_\varepsilon-u\|_r  \  \geq \ \frac12\|\chi_{I_{\theta}}(H) u\|_0,\\
 \|u_\varepsilon\|_0&\leq&   \|u\|_0 +  \|u_\varepsilon-u\|_0  \  \leq   \   2\|u\|_0.
\end{eqnarray*}
According to (\ref{balistic-upper-r}) in Proposition \ref{prop-upper}, for $t\geq 0$,
$$\|e^{-\ri t H}(u_\varepsilon-u)\|_{r}\leq c_r \|u_\varepsilon-u\|_{r}  t^r.$$
 Then, for $\varepsilon$ sufficiently small, as $t\to\infty$, we have
 %\marginpar{Here it is important to make the norm on the RHS explicit.}
\begin{align*}
\|e^{-\ri t H}u\|_r & \geq \|e^{-\ri t H}u_\varepsilon\|_r -  \|e^{-\ri t H}(u_\varepsilon-u)\|_{r}\\
& \geq \frac{ (a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u_\varepsilon\|_{0})^{2-r}}{2^{1-r}(\tilde c_2  \|u_\varepsilon\|_0 )^{1-r}} \cdot t^r -c_r \|u_\varepsilon-u\|_{r}  t^r \\
& \geq \left(\frac{(a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u\|_{0})^{2-r}}{2^{4-3r} (\tilde c_2  \|u\|_0 )^{1-r}}  -c_r\varepsilon \right)t^r \\
& \geq  \frac{(a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u\|_{0})^{2-r}}{16 (\tilde c_2  \|u\|_0 )^{1-r}} t^r.\qed
%\quad {\rm with}  \  b_r:=\frac{(a_1 \theta^\frac12 \|\chi_{I_{\theta}}(H) u\|_{0})^{2-r}}{2^{2-r} (\tilde c_2  \|u\|_0 )^{1-r}} 
\end{align*}

