Suppose $u=\{u_1,u_2,\dots, u_r\}\subseteq \{1,2,\dots,k\}$ such that $u_1< u_2< \dots < u_r.$ Define $\mathbf{e}(u):=\mathbf{e}_{u_1}+\mathbf{e}_{u_2}+\dots+\mathbf{e}_{u_r},$  where $\mathbf{e}_{i}:=(0,0,\dots,1,0,\dots 0),$ i.e., $1$ at $i^{th}$ place and $0$ otherwise. Next we define the following Brehmer-Solel condition:
\begin{definition}
	Let $(\sigma, T^{(1)}, T^{(2)},\dots, T^{(k)})$ be  a completely contractive representation of $\mathbb{E}$ over $\mathbb{N}^k_0$ on $\mathcal{H}.$ We say that it
	satisfies {\rm Brehmer-Solel condition} (cf. \cite{S08}) if it satisfies the condition 
	\begin{align*}
		\sum_{u \subseteq \{1,2,\dots,k\}}(-1)^{|u|}\widetilde{V}_{\mathbf{e}(u)}\widetilde{V}_{\mathbf{e}(u)}^{*}\geq 0.
	\end{align*}
\end{definition} 


The following theorem gave an isometric dilation of completely contractive covariant representations of product system due to Rohilla, Trivedi and Veerabathiran \cite[Theorem 3.5]{RTV}: 

\begin{theorem}\label{6}
	Let $(\sigma, T^{(1)}, T^{(2)},\dots, T^{(k)})$  be a pure completely contractive covariant representation of $\mathbb{E}$ on $\mathcal{H},$ satisfying Brehmer-Solel condition. Then there exist a Hilbert space $\mathcal{D}_{*,k}( T)$ and an isometry $\Pi: \mathcal{H} \to \mathcal{F}(\mathbb{E})\otimes_{\sigma}\mathcal{D}_{*,k}( T)$ such that \begin{align*}
		\Pi\sigma(a)=\rho(a)\Pi \:\:\:\:\mbox{and}\:\:\:\: (I_{E_{i}} \ot \Pi)\widetilde{T}^{(i)*}=\widetilde{S}^{(i)*}\Pi \quad \mbox{for}\quad a \in \mathcal{M}, 1\le i\le k. 
	\end{align*}
	We say that the induced representation $(\rho,S^{(1)},\dots,S^{(k)})$ of $\mathbb{E}$ induced by $\sigma|_{\mathcal{D}_{*,T}}$ is an {\rm isometric dilation} of $(\sigma, T^{(1)},\dots, T^{(k)}).$
\end{theorem}


\section{Ando type dilation for completely contractive
	representations of product system over $\mathbb N^2_0$}

This section aims to construct an explicit isometric dilation of completely contractive covariant representations of product system over $\mathbb{N}_0^2.$ In particular, the isometric dilation of completely contractive covariant representation with finite defect indices, as this will play a key role in the subsequent analysis.

Assume $\be$ to be a product system over $\mathbb N^2_0$. Let $(\sigma, T^{(1)}, T^{(2)})$ be a completely contractive covariant representation  of $\be$ on $\mathcal H.$ Define $\widetilde T:=\wT^{(1)} (I_{E_1} \ot \wT^{(2)}),$ then by Lemma \ref{DSAZ1} $(\sigma, T)$ is also a completely contractive covariant represenation of $E_1 \ot E_2$ on $\mathcal{ H}.$ Note that
\begin{align*}
	&I_{\mathcal H}- \wT^{(1)}
	\wT^{(1)^*}+\wT^{(1)} (I_{E_1} \ot (I_{\mathcal H}-\wT^{(2)}\wT^{(2)^*}))\wT^{(1)^*}\\&=
	I_{\mathcal H}-\wT^{(1)} (I_{E_1} \ot \wT^{(2)})(I_{E_1} \ot \wT^{(2)^*})\wT^{(1)^*}=	I_{\mathcal H}-{\widetilde T}{\widetilde T^*}\\&=	I_{\mathcal H}- \wT^{(2)}
	\wT^{(2)^*}+\wT^{(2)} (I_{E_2} \ot (I_{\mathcal H}-\wT^{(1)}\wT^{(1)^*}))\wT^{(2)^*}.
\end{align*}
This implies that, for $h\in \mathcal{ H}$
\begin{align*}
	&\|\Delta_*(T^{(1)})h\|^2+\|(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h\|^2
	\\&=\|(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h\|^2+\|\Delta_*(T^{(2)})h\|^2.
\end{align*}
Therefore we get an isometry \begin{align*}
	U:\{\Delta_*(T^{(1)})h\oplus (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h:~h\in \mathcal H\}\to\\ \{(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h\oplus \Delta_*(T^{(2)})h:~h\in \mathcal H\}
\end{align*}
defined by
\begin{align}\label{equation1} 
	\nonumber	&U(\Delta_*(T^{(1)})h,  (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h)\\&=((I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h, \Delta_*(T^{(2)})h),
\end{align} $h\in \mathcal H.$ Let  $\phi_1$ and $\phi_2$ be the left actions of $\mathcal{M}$ on $E_1$ and $E_2,$ respectively. It is easy to check that for $a \in \mathcal{M}$ and $ h \in \mathcal{H},$ $U$ is a module map, that is,
\begin{align*}
	U\rho^{'}(a)=\rho^{''}(a)U,
\end{align*} where $\rho^{'}(a)=\big(\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}, \phi_{1}(a)\ot I_{\mathcal{D}_{*, T^{(2)}}}\big)$ and $\rho^{''}(a)=\big( \phi_2(a)\ot I_{\mathcal{D}_{*, T^{(1)}}},\\ \sigma(a)|_{\mathcal{D}_{*, T^{(2)}}} \big)$ are the left actions of $\mathcal{M}$ on the Hilbert spaces $\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}})$ and   $(E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}},$ respectively. Indeed, for $h\in \mathcal{H}$ we have 

\begin{align*}
	&U\rho^{'}(a)(\Delta_*(T^{(1)})h,  (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h)\\&=U(\sigma(a)\Delta_*(T^{(1)})h, (\phi_{1}(a)\ot I_{\mathcal{D}_{*, T^{(2)}}})(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h)\\&=U(\Delta_*(T^{(1)})\sigma(a)h, (I_{E_1} \ot \Delta_*(T^{(2)}))(\phi_{1}(a)\ot I_{\mathcal{H}})\wT^{(1)^*}h)\\&=U(\Delta_*(T^{(1)})\sigma(a)h, (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}\sigma(a)h)\\&=((I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}\sigma(a)h, \Delta_*(T^{(2)})\sigma(a)h)\\&=((\phi_{2}(a)\ot I_{\mathcal{D}_{*, T^{(1)}}})(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h, \sigma(a)\Delta_*(T^{(2)})h)\\&=\rho^{''}(a)U(\Delta_*(T^{(1)})h,  (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h)
\end{align*}
Moreover, if  $ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}))$ =  $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )$ which is finite, it follows that $U$ extends to a
unitary module map, denoted again by $U,$ from $\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}})$ to $(E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}}. $ In
particular, there exists a unitary 
\begin{equation*}
	U: = \begin{bmatrix}A&B\\C&\widetilde{D}\end{bmatrix}:
	\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}})\to (E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}},
\end{equation*}
and it satisfies Equation (\ref{equation1}), where $ A:\mathcal{D}_{*, T^{(1)}} \to E_2 \ot \mathcal{D}_{*, T^{(1)}},$ $ B:E_1 \ot \mathcal{D}_{*, T^{(2)}} \to E_2 \ot \mathcal{D}_{*, T^{(1)}},$ $ C:\mathcal{D}_{*, T^{(1)}} \to \mathcal{D}_{*, T^{(2)}}$ and $ \widetilde{D} : E_1 \ot\mathcal{D}_{*, T^{(2)}}\to  \mathcal{D}_{*, T^{(2)}}.$ 
For $\eta \in \mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}})$ we have
\begin{equation}\label{inner}
	U\rho^{'}(a)\eta =\rho^{''}(a)U\eta.
\end{equation}
Therefore $U$ is a module map, and hence each entry of $U$ is also a module map. That is, $A,B,C$ and $\widetilde{D}$ are module maps. In particular, $A=P_{E_2 \ot \mathcal{D}_{*, T^{(1)}}}U|_{\mathcal{D}_{*, T^{(1)}}}:\mathcal{D}_{*, T^{(1)}} \to E_2 \ot \mathcal{D}_{*, T^{(1)}} ,$  we have $A\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}=(\phi_2(a)\ot I_{\mathcal{D}_{*, T^{(1)}}})A$ for $a\in \mathcal{M}.$ That is,\begin{equation*}
	\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}A^{*}=A^{*}(\phi_2(a)\ot I_{\mathcal{D}_{*, T^{(1)}}}),
\end{equation*} where $P_{E_2 \ot \mathcal{D}_{*, T^{(1)}}}$ is the orthogonal projection of $E_2\ot \mathcal{ H}$ onto $E_2 \ot \mathcal{D}_{*, T^{(1)}}.$ Indeed, by using Equation (\ref{inner}) for $h\in \mathcal{D}_{*, T^{(1)}}$ we obtain \begin{align*}\label{A}
	A\sigma(a)h=P_{E_2 \ot \mathcal{D}_{*, T^{(1)}}}U\sigma(a)h&=P_{E_2 \ot \mathcal{D}_{*, T^{(1)}}}(\phi_2(a)\ot I_{\mathcal{D}_{*, T^{(1)}}})Uh\\&=(\phi_2(a)\ot I_{\mathcal{D}_{*, T^{(1)}}})Ah.
\end{align*}

From Lemma \ref{DSAZ1}, we define a completely contractive covariant representation $(\psi_1, X)$ of $E_2$ on the Hilbert space $\mathcal{D}_{*, T^{(1)}}$ by $$X(\xi_2)h:=A^*(\xi_2\ot h),$$ where $\xi_2\in E_2, h\in \mathcal{D}_{*, T^{(1)}}$ and $\psi_1(a):=\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}, a\in \mathcal{M}.$ Similarly, $(\sigma_1,D)$ is a completely contractive covariant representation of $E_1$ on the Hilbert space $\mathcal{D}_{*, T^{(2)}},$ where $\sigma_1(a):=\sigma(a)|_{\mathcal{D}_{*, T^{(2)}}}, a\in \mathcal{M}.$




The following lemma is crucial to our discussion.

\begin{lemma}\label{identity}
	Assume $\be$ to be a product system over $\mathbb N^2_0$. Let $(\sigma, T^{(1)}, T^{(2)})$ be a completely contractive covariant representation  of $\be$ on $\mathcal H$ such that $(\sigma,T^{(1)})$ is pure and  $ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}))$ =  $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )<\infty.$  Then 
	\begin{align*}&
		(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}= A\Delta_*(T^{(1)})
		\\&\hspace{0.2in}
		+  \sum_{n= 0}^\infty
		B(I_{E_1}\ot \widetilde{D}_n)(I_{E_1^{\otimes n+1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{n+1},
	\end{align*}
	where $U=\begin{bmatrix}A&B\\C&\widetilde{D}\end{bmatrix}$ defined as above, $\widetilde{D}_n=\widetilde{D}(I_{E_1} \otimes \widetilde{D}) \dots (I_{E_1^{\ot(n-1)}} \otimes  \widetilde{D})$ and the series converges with respect to the strong operator topology.
\end{lemma}
\begin{proof}
	Let $h \in \mathcal H$ we get
	\[\begin{bmatrix}A&B\\C&\widetilde{D}\end{bmatrix} \begin{bmatrix} \Delta_*(T^{(1)})h\\ (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h \end{bmatrix}= \begin{bmatrix} (I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h \\  \Delta_*(T^{(2)})h\end{bmatrix}.\] It follows that
	\begin{equation} \label{one} (I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h= A\Delta_*(T^{(1)})h+
		B(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h
	\end{equation}and
	\begin{equation*}
		\Delta_*(T^{(2)})h= C\Delta_*(T^{(1)})h+
		\widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h.
	\end{equation*} This implies that
	\begin{align*}
		&(I_{E_1}\ot \Delta_*(T^{(2)}))\wT^{(1)^*}h= (I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h+\\& \quad \quad
		(I_{E_1}\ot \widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*})\wT^{(1)^*}h,	
	\end{align*}
	and further we get\begin{align*}
		&(I_{E_1^{\otimes 2}}\ot \Delta_*(T^{(2)}))\wT^{(1)^*}_2h\\&= (I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h+
		(I_{E_1^{\otimes 2}}\ot \widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*})\wT^{(1)^*}_2h,
	\end{align*} and hence
	\begin{align*}
		&(I_{E_1^{\otimes 2}}\ot \Delta_*(T^{(2)}))\wT^{(1)^*}_2h\\&= (I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h+
		(I_{E_1^{\otimes 2}}\ot \widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)})))\wT^{(1)^*}_3h.
	\end{align*}From Equation ~\eqref{one} we obtain
	\[\begin{split}&
		(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h\\&= A\Delta_*(T^{(1)})h+
		B(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h \\ & =  A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h   \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*})\wT^{(1)^*}h
		\\ & =  A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h  \\&  \quad \quad +
		B(I_{E_1}\ot \widetilde{D})(I_{E_1^{\otimes 2}} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}_2h
		\\&=A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h  \\&  \quad \quad +
		B(I_{E_1}\ot \widetilde{D})(I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D})
		(I_{E_1^{\otimes 2}}\ot \widetilde{D}(I_{E_1} \ot \Delta_*(T^{(2)})))\wT^{(1)^*}_3h 
		\\&=A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h  \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D})(I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h  \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D})
		(I_{E_1^{\otimes 2}}\ot \widetilde{D})(I_{E_1^{\otimes 3}}\ot\Delta_*(T^{(2)}))\wT^{(1)^*}_3h\\&=A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h  \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D})(I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h  \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D}(I_{E_1}\ot \widetilde{D}))
		(I_{E_1^{\otimes 3}}\ot\Delta_*(T^{(2)}))\wT^{(1)^*}_3h\\&=A\Delta_*(T^{(1)})h+
		B(I_{E_1}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}h  \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D})(I_{E_1^{\otimes 2}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_2h \\& \quad \quad +
		B(I_{E_1}\ot \widetilde{D}_{2})
		(I_{E_1^{\otimes 3}}\ot\Delta_*(T^{(2)}))\wT^{(1)^*}_3h.
	\end{split}\] 
	Therefore iteratively for each $m\in\mathbb N$, we have
	\begin{align*}
		(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h= &  A\Delta_*(T^{(1)})h
		\\& +\sum_{n= 0}^m 
		B(I_{E_1}\ot \widetilde{D}_{n})(I_{E_1^{\otimes n+1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{n+1}h  \\&+ 
		B(I_{E_1}\ot \widetilde{D}_{m+1})(I_{E_1^{\otimes m+2}}\ot \Delta_*(T^{(1)}))\wT^{(1)^*}_{m+2}h.
	\end{align*}
	Since $(\sigma,T^{(1)})$ is pure and $\|\widetilde{D}\| \leq 1,$ it gives
	\begin{align*}
		\|(I_{E_2} \ot & \Delta_*(T^{(1)}))\wT^{(2)^*}h - A\Delta_*(T^{(1)})h-\\& \sum_{n= 0}^m 
		B(I_{E_1}\ot \widetilde{D}_{n})(I_{E_1^{\otimes n+1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{n+1}h\|\\& =\|B(I_{E_1}\ot \widetilde{D}_{m+1})(I_{E_1^{\otimes m+2}}\ot \Delta_*(T^{(1)}))\wT^{(1)^*}_{m+2}h\| \\&
		\leq\|\wT^{(1)^*}_{m+2}h\|  \to 0~\mbox{as}~m\to\infty.
	\end{align*}  This complets the proof.
\end{proof}


\begin{observation}
	Under the above assumptions, the conclusion of Lemma \ref{identity} remains valid even when we incorporate the possibility
	$ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}))$ or $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )$ is an infinite dimensional space. The conclusion of Lemma \ref{identity} remains valid. If  $ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}))=\infty$ or $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )=\infty,$ 
	then there exists an infinite dimensional 
	Hilbert space $\mathcal{D}$ such that the isometry 
	\begin{align*}&
		U:\{\Delta_*(T^{(1)})h\oplus (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h:~h\in \mathcal H\} \oplus \{0_\mathcal{D}\}\to \\& \:\:\:\:\:\:\:\: \{(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h\oplus \Delta_*(T^{(2)})h:~h\in \mathcal H\} \oplus \{0_\mathcal{D}\}
	\end{align*} is defined by 
	\begin{align*} 
		&U(\Delta_*(T^{(1)})h,  (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h,0_\mathcal{D})\\&=((I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h, \Delta_*(T^{(2)})h,0_\mathcal{D}),
	\end{align*} for all $h\in \mathcal H$ 
	extends to a unitary, denoted again by $U,$ from
	$\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}) \oplus \mathcal{D}$  to
	$  (E_2 \ot\mathcal{D}_{*, T^{(1)}}) \oplus \mathcal{D}_{*, T^{(2)}} \oplus \mathcal{D}.$ Now we proceed similarly
	with the unitary matrix \begin{equation*}
		U = \begin{bmatrix}A&B\\C&\widetilde{D}\end{bmatrix}:
		\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}) \oplus \mathcal{D}\to (E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}}\oplus \mathcal{D} ,
	\end{equation*} defined by 	\begin{align*} &U(\Delta_*(T^{(1)})h,  (I_{E_1} \ot \Delta_*(T^{(2)}))\wT^{(1)^*}h,0_\mathcal{D})\\&=((I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}h, \Delta_*(T^{(2)})h,0_\mathcal{D}),\end{align*} to obtain the same conclusion as in Lemma \ref{identity}.
\end{observation}


\subsection{Transfer Function}

Suppose that $\mathbb{E}$ is a product system over $\mathbb{N}_0^2,$ and $\pi $ is a representation of $\mathcal{M}$ on $\mathcal{K}.$ Let $\Theta: E_2 \longrightarrow B(\mathcal{K}, \mathcal{F}(E_1) \otimes_{\pi} \mathcal{K})$ be a completely bounded { bi-module map}. Define a bounded linear map $\widetilde{\Theta}: E_2 \otimes \mathcal{K} \longrightarrow \mathcal{F}(E_1) \otimes_{\pi} \mathcal{K}$  by $\widetilde{\Theta}(\xi \otimes h)=\Theta(\xi)h$ for all $\xi\in E_2,h\in \mathcal{K},$ and it satisfies $\widetilde{\Theta}(\phi_2(a) \ot I_{ \mathcal{K}})=\rho(a)\widetilde{\Theta},a\in \mathcal{M},$ where $\phi_2$ is the left action of $\mathcal{M}$ on $E_2.$
We define a corresponding completely bounded bi-module map \cite{DTV1} $M_{\Theta} :E_2  \longrightarrow B(\mathcal{F}(E_1) \otimes_{\pi} \mathcal{K})$ by
\begin{align*}
	M_{\Theta}(\xi) (S_n^{(1)}(\xi_n) h)=\widetilde{S}_n^{(1)}(I_{E_1^{\otimes n}} \otimes \widetilde{\Theta})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{K}})(\xi \otimes \xi_n \otimes h),
\end{align*}
where  $\xi_n \in E_1^{\otimes n}, \xi \in E_2, h\in \mathcal{K}, n \in \mathbb{N}_0$ and $t_{2,1}^{(1,n)}: E_2 \ot E_1^{\ot n}  \rightarrow E_1^{\ot n} \ot E_2 $ is an isomorphism which is a composition of the isomorphisms $\{t_{i,j}\: :\: 1 \leq i, j \leq 2\}.$
Clearly  $M_{\Theta}(\xi)|_{\mathcal{K}}=\Theta(\xi)$ for each $\xi \in E_2,$  $(\rho,{M}_{\Theta})$ is a c.b.c. representation of $E_2$ on $\mathcal{F}(E_1) \otimes_{\pi} \mathcal{K},$ and it satisfies
\begin{align*}
	M_{\Theta}(\xi)\left(\bigoplus_{n \in \mathbb{N}_0}\xi_n \otimes h_n\right)=\sum_{n \in \mathbb{N}_0}\widetilde{S}_n^{(1)}(I_{E_1^{\otimes n}} \otimes \widetilde{\Theta})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{K}})(\xi \otimes \xi_n \otimes h_n),
\end{align*} 
where $\xi \in E_2, \xi_n \in E_1^{\otimes n}, h_n \in \mathcal{K}.$  Let  $(\rho, S)$ be the induced representation of $E_1$ induced by $\pi,$ then $(\rho, S, M_{\Theta})$ is a c.b.c. representation of $\mathbb{E}$ on $\mathcal{F}(E_1) \otimes _{\pi} \mathcal{K} .$
Note that  $(\rho, M_{\Theta})$ is an isometric covariant representation if and only if $\widetilde{\Theta}$  is an isometry.


With the help of unitary module map $U$ as we defined above, we define a bounded linear map $\widetilde{\Theta}: E_{2}\ot \mathcal{D}_{*, T^{(1)}} \to F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}}  $ by \begin{equation*}
	\widetilde{\Theta}:=A^{*}\oplus \bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_n)B^{*}.
\end{equation*} First we will show that it is well defined, it is enough to prove that $\|\bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}} \ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_n)B^{*}(\eta)\|^{2}< \infty$ for $\eta \in E_{2}\ot \mathcal{D}_{*, T^{(1)}}.$ Indeed, using $UU^*=I$ we have
\begin{align*}
	&\|\bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_n)B^{*}(\eta)\|^{2}\\&=\sum_{n= 0}^{\infty}\langle B(I_{E_1} \ot \widetilde{D}_{n})(I_{E_{1}^{\ot n+1}}\ot  CC^{*})(I_{E_1} \ot \widetilde{D}^*_n)B^{*}\eta,\eta \rangle\\&=\sum_{n= 0}^{\infty}\langle B(I_{E_1} \ot \widetilde{D}_{n})(I_{E_{1}^{\ot n+1}}\ot  (I_{\mathcal{D}_{*, T^{(2)}}}-\widetilde{D}\widetilde{D}^{*}))(I_{E_1} \ot \widetilde{D}^*_n)B^{*}\eta,\eta \rangle\\&=\sum_{n= 0}^{\infty}\langle\big(B(I_{E_1} \ot \widetilde{D}_{n}\widetilde{D}^*_n)B^{*}-B(I_{E_1} \ot \widetilde{D}_{n+1}\widetilde{D}_{n+1}^*)B^{*}\big)\eta,\eta \rangle\\&=\langle BB^{*}-\lim_{n \rightarrow \infty}B(I_{E_1} \ot \widetilde{D}_{n}\widetilde{D}^*_n)B^{*}\eta,\eta \rangle\\&=
	\|B^{*}\eta\|^{2}-\lim_{n \rightarrow \infty}\langle B(I_{E_1} \ot \widetilde{D}_{n}\widetilde{D}^*_n)B^{*}\eta,\eta \rangle<\|B^{*}\eta\|^{2}.
\end{align*}
Here the last inequality follows by the fact that $B$ and $\widetilde{D}$ are contractions. This shows that $\widetilde{\Theta}$ is well defined and contractive.


Since $(\sigma_1, D)$ is a completely contractive covariant representation of $E_1$ on $\mathcal{D}_{*, T^{(2)}},$ from Theorem \ref{contra}, $\mathcal{D}_{*, T^{(2)}}=\mathcal{D}^{(1)}_{*, T^{(2)}} \oplus \mathcal{D}^{(2)}_{*, T^{(2)}}$ has unique orthogonal decomposition such that $\mathcal{D}^{(1)}_{*, T^{(2)}},$ $\mathcal{D}^{(2)}_{*, T^{(2)}}$ reduces $(\sigma_1, D),$  $(\pi_1,V^{(1)}):=(\sigma_1, D)|_{\mathcal{D}^{(1)}_{*, T^{(2)}}}$ is an isometric as well as co-isometric covariant representation and  $(\pi_2,V^{(2)}):=(\sigma_1, D)|_{\mathcal{D}^{(2)}_{*, T^{(2)}}}$ is a completely non-unitary covariant representation. That is,  $\widetilde{D}^{*}\widetilde{D}|_{E_1 \ot\mathcal{D}^{(1)}_{*, T^{(2)}}}=I_{E_1 \ot\mathcal{D}^{(1)}_{*, T^{(2)}}}.$   Also using the fact that $U$ is unitary, we have $B^{*}B+\widetilde{D}^{*}\widetilde{D}=I_{E_1 \ot\mathcal{D}_{*, T^{(2)}}},$ therefore $B^{*}B|_{E_1 \ot\mathcal{D}^{(1)}_{*, T^{(2)}}}=0,$ i.e., $E_1 \ot\mathcal{D}^{(1)}_{*, T^{(2)}}\subseteq ker(B),$ or equivalently, ${Im(B^{*})}\subseteq E_1 \ot\mathcal{D}^{(2)}_{*, T^{(2)}}.$ Hence $(I_{E_1} \ot \widetilde{D}_{n}\widetilde{D}_n^*)B^{*}=(I_{E_1} \ot \widetilde{V}_n^{(2)}\widetilde{V}_n^{(2)*})B^*.$  Finally, we can rewrite $\lim_{n \rightarrow \infty} B(I_{E_1} \ot \widetilde{D}_n\widetilde{D}_n^*)B^{*}=\lim_{n \rightarrow \infty} B(I_{E_1} \ot \widetilde{V}_{n}^{(2)}\widetilde{V}_{n}^{(2)*})B^*.$
\begin{observation}
	$\widetilde{\Theta}$ is an isometry if and only if $(\pi_2, V^{(2)})$ is pure.
\end{observation}
Define ${\Theta}: E_{2} \to B(\mathcal{D}_{*, T^{(1)}},F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}})$ by ${\Theta}(\eta)h=\widetilde{\Theta}(\eta\ot h),$ where $\eta \in E_{2}$ and $ h \in\mathcal{D}_{*, T^{(1)}}.$ We need to show that $\Theta$ is a bi-module map. That is, $\Theta(a.\eta. b)=\rho(a)\Theta(\eta)\rho(b).$ Let $ h \in \mathcal{D}_{*, T^{(1)}}$ we have \begin{align*}&
	\widetilde{\Theta}(a.\eta. b\ot h)= A^{*}(a.\eta. b\ot h)\oplus \bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_{n})B^{*}(a.\eta. b\ot h)\\&=A^{*}(a.\eta \ot b .h)\oplus \bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_{n})B^{*}(a.\eta \ot b .h)\\&=\big(A^{*}(\phi_2(a) \ot I_{ \mathcal{D}_{*, T^{(1)}}})\oplus \\& \quad \quad \bigoplus_{n=0}^{\infty}(I_{E_1} \ot (I_{E_{1}^{\ot n}}\ot  C^{*})\widetilde{D}^*_{n})B^{*}(\phi_{2}(a)  \ot I_{ \mathcal{D}_{*, T^{(1)}}})\big)(\eta \ot b. h)\\&=\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}A^{*}(\eta \ot b. h)\oplus \\& \quad \quad \bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}^*_{n})(\phi_{1}(a) \ot I_{ \mathcal{D}_{*, T^{(2)}}})B^{*}(\eta \ot b. h)\\&=\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}A^{*}(\eta \ot b. h)\oplus \\& \quad \quad \bigoplus_{n=0}^{\infty}(I_{E_{1}^{\ot n+1}}\ot  C^{*})(\phi_1^{n+1}(a) \ot I_{ \mathcal{D}_{*, T^{(2)}}})(I_{E_1} \ot \widetilde{D}_n^{*})B^{*}(\eta \ot b. h)\\&=\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}A^{*}(\eta \ot b. h)\oplus \\& \quad \quad \bigoplus_{n=0}^{\infty}(\phi_1^{ n+1}(a) \ot I_{ \mathcal{D}_{*, T^{(1)}}})(I_{E_{1}^{\ot n+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}_n^{*})B^{*}(\eta \ot b. h).
\end{align*} Finally, we obtain \begin{align*}
	&\widetilde{\Theta}(a.\eta. b\ot h)=\big(\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}A^{*}\oplus \\& \quad \quad  \bigoplus_{n=0}^{\infty}(\phi_1^{ n+1}(a) \ot I_{ \mathcal{D}_{*, T^{(1)}}})(I_{E_1} \ot (I_{E_{1}^{\ot n}}\ot  C^{*})\widetilde{D}_n^{*})B^{*}\big)( \eta .b\ot h)\\&=\big(\big(\sigma(a)|_{\mathcal{D}_{*, T^{(1)}}}\oplus \bigoplus_{n=0}^{\infty}(\phi_1^{n+1}(a) \ot I_{ \mathcal{D}_{*, T^{(1)}}})\big)(A^{*}\oplus \\& \quad \quad \bigoplus_{n=0}^{\infty}(I_{E_1} \ot (I_{E_{1}^{\ot n}}\ot  C^{*})\widetilde{D}_n^{*})B^{*}))\big( \eta .b\ot h)\\&=\rho(a)\Theta(\eta)\rho(b)h.
\end{align*} Thus $\Theta$ is a bi-module map. From \cite[Lemma 2.2]{DTV1}, $(\rho,S^{(1)},M_{\Theta})$ is a completely contractive covariant representation of $\mathbb{E}$ over $\mathbb{N}_0^2$ on 	$\mathcal{F}(E_1) \otimes \mathcal{D}_{*, T^{(1)}}.$ The contractive linear map $\widetilde{\Theta}$ is called the {\it transfer function} of unitary module map $U.$
