\subsection{Ando Dilations}


We are ready to prove our main result, a generalization of \cite[Theorem 3.1]{BJ17}.   
\begin{theorem}\label{DSAR2}
	Assume $\be$ to be a product system over $\mathbb N^2_0$. Let $(\sigma, T^{(1)}, T^{(2)})$ be a completely contractive covariant representation of $\be$ on $\mathcal H$ such that $(\sigma,T^{(1)})$ is pure and  $ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}}))$ =  $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )<\infty.$ Then there exist an isometry $\Pi_{1}: \mathcal{H} \longrightarrow \mathcal{F}(E_{1})\otimes \mathcal{D}_{*, T^{(1)}}$ and a completely contractive bi-module map ${\Theta}: E_{2} \to B(\mathcal{D}_{*, T^{(1)}},F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}})$ such that 	
	\begin{align*}
		\Pi_{1} \sigma(a)=\rho(a)\Pi_1, (I_{E_1} \ot \Pi_{1})\widetilde{T}^{(1)*}=\widetilde{S}^{(1)*}\Pi_{1} \:\: \mbox{and} \:\: {(I_{E_{2}} \ot\Pi_{1}) \wT^{(2)}}^{*} = \widetilde{M}^{*}_{\Theta}\Pi_{1},
	\end{align*} for all $a\in \mathcal{M}.$
\end{theorem}
\begin{proof}
	Let $(\sigma, T^{(1)})$ be a pure completely contractive covariant representation of $E_1$ on $\mathcal H,$ then from Theorem \ref{dilation}, there exists an isometry $\Pi_{1}: \mathcal{H} \longrightarrow \mathcal{F}(E_{1})\otimes \mathcal{D}_{*, T^{(1)}}$ defined by $$\Pi_{1} h=\sum_{k\geq0}(I_{E_{1}^{\otimes k}}\otimes\Delta_*(T^{(1)}))\wT^{(1)^*}_{k}h,\:\:\: h \in \mathcal{H}$$ such that
	\begin{align*}
		\Pi_{1} \sigma(a)=\rho(a)\Pi_1 \:\: \mbox{and} \:\: (I_{E_1} \ot \Pi_{1})\widetilde{T}^{(1)*}=\widetilde{S}^{(1)*}\Pi_{1},
	\end{align*}
	where $(\rho,S^{(1)})$ is an induced representation of $E_1$ induced by $\sigma|_{\mathcal{D}_{*,T^{(1)}}}.$ We only need to show that $ {(I_{E_{2}} \ot\Pi_{1}) \wT^{(2)}}^{*} = \widetilde{M}^{*}_{\Theta}\Pi_{1}.$ 
	Define a completely contractive bi-module map ${\Theta}: E_{2} \to B(\mathcal{D}_{*, T^{(1)}},F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}})$ by $\Theta(\xi)h=\widetilde{\Theta}(\xi \ot h)$ where $\xi\in E_2,h\in \mathcal{D}_{*, T^{(1)}}$ and $
	\widetilde{\Theta}=A^{*}\oplus \bigoplus_{m=0}^{\infty}(I_{E_{1}^{\ot m+1}}\ot  C^{*})(I_{E_1} \ot \widetilde{D}_m^{*})B^{*}.$ Define a corresponding contractive linear map $\widetilde{M}_{\Theta} :E_2 \ot F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}}  \longrightarrow F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}} $ by $$\widetilde{M}_{\Theta}=\widetilde{S}^{(1)}_n(I_{E_1^{\otimes n}} \otimes \widetilde{\Theta})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}}}),$$ and it satisfies $\widetilde{M}_{\Theta}(\phi_2(a) \ot I_{F(E_{1}) \ot \mathcal{D}_{*, T^{(1)}} })=\rho(a)\widetilde{M}_{\Theta}$ for $a \in \mathcal{M}.$ For $ \eta_n \in {E_2}\ot E_1^{\otimes n}\ot \mathcal{D}_{*, T^{(1)}},h\in \mathcal{ H}$ and from Lemma \ref{identity} we have

	\begin{align*} &
		\langle\widetilde{M}^{*}_{\Theta}\Pi_{1}h ,\eta_n\rangle \\&=\langle\sum_{k= 0}^\infty (I_{E_1^{\otimes k}}\ot \Delta_*(T^{(1)}))\wT^{(1)^*}_{k}h ,\widetilde{S}_n^{(1)}(I_{E_1^{\otimes n}} \otimes \widetilde{\Theta})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle \\&=\langle(I_{E_1^{\otimes n}}\ot \Delta_*(T^{(1)}))\wT^{(1)^*}_{n}h,(I_{E_1^{\otimes n}}\ot A^{*})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle\\&  \quad \quad +\sum_{m=0}^{\infty}\langle(I_{E_1^{\otimes n+m+1}}\ot \Delta_*(T^{(1)}))\wT^{(1)^*}_{n+m+1}h,\\& \quad \quad\quad (I_{E_1^{\otimes n}}\ot (I_{E_1} \ot (I_{E_{1}^{\ot m}}\ot  C^{*})\widetilde{D}_m^{*})B^{*})(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle \\&= \langle(I_{E_1^{\otimes n}}\ot A\Delta_*(T^{(1)}))\wT^{(1)^*}_{n}h,(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle\\&  \quad \quad +\sum_{m=0}^{\infty}\langle(I_{E_1^{\otimes n}}\ot( B(I_{E_1}\ot \widetilde{D}_{m})))(I_{E_1^{\otimes n+m+1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{n+m+1}h,\\& \quad \quad\quad (t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle\\&= \langle\big(I_{E_1^{\otimes n}}\ot A\Delta_*(T^{(1)})+\sum_{m=0}^{\infty}(I_{E_1^{\otimes n}}\ot( B(I_{E_1}\ot \widetilde{D}_{m})))\\& \quad \quad (I_{E_1^{\otimes n+m+1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{m+1})\big)\wT^{(1)^*}_{n}h,(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle\\&= \langle (I_{E_1^{\otimes n}}\ot \big(A\Delta_*(T^{(1)})+\sum_{m=0}^{\infty} B(I_{E_1}\ot \widetilde{D}_{m}) (I_{E_1^{\otimes m +1}}\ot C\Delta_*(T^{(1)}))\wT^{(1)^*}_{m+1})\big)\wT^{(1)^*}_{n}h,\\&\quad \quad (t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle\\&= \langle (I_{E_1^{\otimes n}}\ot	(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*}\big)\wT^{(1)^*}_{n}h,(t_{2,1}^{(1,n)} \otimes I_{\mathcal{D}_{*, T^{(1)}} }) \eta_n\rangle.
	\end{align*} 
	On the other hand, since  

	\begin{align*}&
		\langle{(I_{E_{2}} \ot\Pi_{1}) \wT^{(2)}}^{*}h, \eta_n\rangle 
		=\langle{(I_{E_{2}} \ot\sum_{k\geq0}(I_{E_{1}^{\otimes k}}\otimes \Delta_*(T^{(1)}))\wT^{(1)^*}_{k}) \wT^{(2)}}^{*}h , \eta_n\rangle \\&=
		\langle{(I_{E_{2}} \ot(I_{E_{1}^{\otimes n}}\otimes\Delta_*(T^{(1)}))\wT^{(1)^*}_{n}) \wT^{(2)}}^{*}h , \eta_n\rangle \\&=
		\langle h ,{\wT^{(2)}(I_{E_{2}} \ot\wT^{(1)}_{n}(I_{E_{1}^{\otimes n}}\otimes\Delta_*(T^{(1)}))) } \eta_n\rangle  \\&=
		\langle h ,{\wT^{(1)}_{n}(I_{E_{1}^{\otimes n}} \ot\wT^{(2)}(I_{E_{2}}\otimes\Delta_*(T^{(1)}))) }(t_{2,1}^{(1,n)} \ot I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle \\&=
		\langle (I_{E_1^{\otimes n}}\ot(I_{E_2} \ot \Delta_*(T^{(1)}))\wT^{(2)^*})\wT^{(1)^*}_{n}h ,(t_{2,1}^{(1,n)} \ot I_{\mathcal{D}_{*, T^{(1)}} })\eta_n\rangle  =
		\langle\widetilde{M}^{*}_{\Theta}\Pi_{1}h ,\eta_n\rangle,
	\end{align*} we get $ {(I_{E_{2}} \ot\Pi_{1}) \wT^{(2)}}^{*} = \widetilde{M}^{*}_{\Theta}\Pi_{1}.$ This complets the proof.
\end{proof} 

\begin{observation}
	\begin{enumerate}
		\item In the setting of Theorem \ref{DSAR2}, if $\mathcal{Q}:=\Pi_1\mathcal{H},$ then $$\rho(a)\mathcal{Q}\subseteq \mathcal{Q}, ~\widetilde{S}^{
			(1)^*}(\mathcal{Q})\subseteq E_1\ot \mathcal{Q}\quad \mbox{and}\quad \widetilde{M}_{\Theta}^*(\mathcal{Q})\subseteq E_2\ot \mathcal{Q} \quad \mbox{for}\quad a\in \mathcal{M}.$$
		\item The representations $(\pi',X,Y)$ and $(\sigma, T^{(1)}, T^{(2)})$ of $\mathbb{E}$ acting on the Hilbert spaces $\mathcal{Q}$ and $\mathcal{H},$ respectively, are isomorphic, where $\pi'=\rho|_{\mathcal{Q}},$
		$\widetilde{X}= P_{\mathcal{Q}}\widetilde{S}^{(1)}|_{E_1\ot \mathcal{Q}}$ and $\widetilde{Y}= P_{\mathcal{Q}}\widetilde{M}_{\Theta}|_{E_2\ot \mathcal{Q}}.$
		\item Theorem \ref{DSAR2} remains valid if we drop the assumption that $ \dim (\mathcal{D}_{*, T^{(1)}} \oplus  (E_1 \ot\mathcal{D}_{*, T^{(2)}})) < \infty$ and $ \dim ((E_2 \ot \mathcal{D}_{*, T^{(1)}}) \oplus  \mathcal{D}_{*, T^{(2)}} )<\infty.$
	\end{enumerate}
\end{observation}




