\subsection{Weighted-cost upper bound}\label{sec: Weighted-Cost Upper Bound}
In this subsection we consider an approach to bound Wasserstein distance by down-scaling the grid $\calX$ to $\tilde{\calX}=\tilde{\calY}$ and the measures to $\tilde\vmu,\tilde\vnu \in \Sigma_{n^d}$ using regular hypercubes as described in \cref{sec:coarsening}. We define the marginally weighted coarse cost

\begin{align}\label{eq: marginally weighted cost}
    \bar{C}_{k\ell}
    :=
    \frac{1}{\mu(X_k)\nu(Y_\ell)} \sum_{\substack{
    x\in X_k, y\in Y_\ell}}
    \rho(x,y)^p \mu(x)\nu(y).
\end{align}
It follows that $\bar{C} = \code{SumPool}(C\odot\pi_\otimes, \kappa) \oslash \code{SumPool}(\pi_\otimes, \kappa)$, which can be used efficiently for small enough grids. Then we compute the optimal coupling for the marginally weighted coarse cost using network simplex solver \citep{bonneelDisplacementInterpolationUsing2011}, defining an upper bound
\begin{align}
    \overline{\Wass}_p^{\otimes} := L_{\bar{C}}(\tilde{\mu},\tilde{\nu})^\frac{1}{p}.
\end{align}

\begin{theorem}\label{th: weighted cost UB}
    The optimal transport loss under the marginally weighted coarse cost $L_{\bar{C}}(\tilde{\mu},\tilde{\nu})$ is an upper bound to the optimal transport loss $L_C(\mu,\nu)$, and similarly for the Wasserstein distance,
    \begin{equation}
        L_{\bar{C}}(\tilde{\mu},\tilde{\nu})^\frac{1}{p} \ge \Wass_p(\mu,\nu).
    \end{equation}
\end{theorem}
The proof uses an auxiliary coupling transferring the mass between each pair of sub-regions $(X_i, Y_j)$ using the trivial coupling, weighted by a coarse coupling, choosing the optimal coarse coupling. A detailed proof is provided in \cref{sc: proof of weighted cost UB}.

\subsection{Min-cost lower bound}\label{sec: Min-Cost Lower Bound}
For the same coarsening, we define the locally minimal cost
\(
    C_{k\ell}^{\min} := \min_{x\in X_k,y\in Y_\ell} \rho(x,y)^p,
\)
and compute the optimal coupling for this coarse cost using a network simplex solver, yielding a lower bound
\(
    \underline{\Wass}_p^{\min} := L_{C^{\min}}(\tilde{\mu},\tilde{\nu})^\frac{1}{p}.
\)
The following theorem is proved in \cref{sec: additional proofs}.
\begin{theorem}\label{th: locally-minminal cost LB}
    The coarse optimal transport cost set by the locally minimal cost, is a lower bound of the optimal transport.
    \(
        L_{C^{\min}}(\tilde{\mu},\tilde{\nu}) \le L_C(\mu,\nu).
    \)
\end{theorem}

\subsection{Primal upscaling upper bound}\label{sec: Upscaling upper bound}
In this approach we upscale an optimal coupling for the coarse cost $\tilde{c}_{k\ell} = \rho(\tilde{x}_k,\tilde{y}_\ell)^p$ computed using a network simplex solver $\tilde{\pi}^* = \argmin_{\tilde{\pi} \in \Pi(\tilde{\vmu}, \tilde{\vnu})}\inner{\tilde{\pi},\tilde{C}}$ back to the original problem size.
\paragraph*{Up-scaled coupling}\label{p: step 1}
A coupling matrix $\pi$ of dimensions $n^d \times n^d$ can equivalently be represented as a $2d$-tensor of the shape \( n \times n \times \dots \times n \).
We formally define operations for reshaping matrices into tensors and back.
Let \code{reshape} be a cardinality-preserving transformation from A to $\mathbf{B}$ such that $a_{ij}=b_{u_1,\dots,u_d,\,v_1,\dots,v_d}$
where $(u_1, \dots, u_d)$ is a multi-index that corresponds to a matrix row by $i = 1 + \sum_{k=1}^d u_k n^{k-1}$.
Similarly the multi-index $(v_1, \dots, v_d)$ corresponds to the column index $j$.
Reshaping the coarse optimal coupling $\tilde{\pi}^*$ into a $2d$-tensor $\tilde{\tP}^*$,
we up-scale the optimal coupling using a normalized positive-valued kernel  $\tK$, a $2d$-tensor representing a hypercube of width $\kappa$.
\begin{equation}\label{eq: coupling tensor upscale}
    \hat{\tP} := \tilde{\tP}^* \otimes \tK.
\end{equation}
By inversely reshaping the up-scaled tensor $\hat{\tP}$ into an up-scaled matrix $\hat{\pi}$, we obtain the approximate up-scaled coupling. Using a uniform kernel $\tK$ is equivalent to nearest-neighbor interpolation.
\begin{lemma}\label{lm: normalized coupling}
    Using a normalized positive-valued kernel $\tK$ ensures $\hat{\pi}$ represents a coupling. Satisfying $\hat\pi \in \R_+^{N^d\times N^d}$ and $\sum_{i=1}^{N^d}\sum_{j=1}^{N^d} \hat{\pi}_{ij} = 1$, such that $\hat{\pi} \in \Pi(\hat\pi\ones_{N^d}, \hat\pi^{\top}\ones_{N^d})$.
\end{lemma}

\paragraph*{Iterative proportional fitting}\label{p: step 2}
The approximate up-scaled coupling is $\xi$-fitted into $\hat{\pi}_\xi = \diag(\va)\hat{\pi}\diag(\vb)$ by iterative proportional fitting using Sinkhorn's theorem , until the marginals  $\hat{\vmu}_\xi = \va \odot (\hat{\pi} \vb),\, \hat{\vnu}_\xi = \vb \odot (\hat{\pi}^\top \va)$ are converged to $\|\hat{\vmu}_\xi - \vmu\|_1 + \|\vnu - \hat{\vnu}_\xi\|_1 <  \xi$, where $\va, \vb \in \R_+^{N^d}$ are the vector scale factors.
yielding the approximation
\(
    \widehat{\Wass}_p(\mu,\nu) := \inner{\hat{\pi}_\xi, C}^{\frac{1}{p}}.
\)

\paragraph*{Upper bound}\label{p: step 3}
Using weighted total variation (\cref{eq: weighted total variation}) we define an upscaling upper bound
\begin{align}
    \overline{\Wass}_{p}(\mu,\nu)
    :=
    \widehat{\Wass}_p(\mu,\nu)
    + \Delta_{\hat{\mu}_\xi}
    + \Delta_{\hat{\nu}_\xi} ,
\end{align}

\begin{theorem}[Upscaling Upper Bound]\label{th: Upscaling upper bound}
    $\overline{\Wass}_p(\mu,\nu)$ is upper bound of the Wasserstein distance,
    \begin{align}
        \Wass_p(\mu,\nu) \le \overline{\Wass}_p(\mu,\nu).
    \end{align}
\end{theorem}

\begin{proof}[Proof of \cref{th: Upscaling upper bound}]
    The up-scaled matrix $\hat{\pi} \in \Pi(\hat\pi\ones_{N^d}, \hat\pi^{\top}\ones_{N^d})$ is normalized as a coupling, by \cref{lm: normalized coupling}, and $\hat{\pi}_\xi$ retains this normalization, by Sinkhorn's theorem.  $\overline{\Wass}_p(\mu,\nu)$ is than an upper bound of the Wasserstein distance, by \cref{lm: triangle inequality upper bound}.
\end{proof}

\begin{remark}
    Considering $\calX = [N]^d$ with $L^2$ norm, the radius becomes $r=\frac{1}{2}d^{\frac{1}{2}}N$ (see \cref{th: $L^1$ upper bound on weighted total variation}) such that the weighted total variation correction $\Delta_{\hat\mu} + \Delta_{\hat\nu}$ is at most $2^{1-\frac{2}{p}}d^{\frac{1}{2}}N\xi^{\frac{1}{p}}$. Negligible for $\xi \ll N^{-p}$, and can be ignored for many practical use cases.
\end{remark}

\subsection{Dual upscaling lower bound}\label{sec: Upscaling Lower Bound}
We construct a lower bound for the Wasserstein distance $\Wass_p(\mu,\nu)$ by solving a down-scaled optimal transport problem using coarsened measures.
The coarse optimal Kantorovich potentials are than up-scaled using a multi-linear interpolation and improved using a c-transform.
Considering the same setting as in \cref{sec: Upscaling upper bound}, we solve for the optimal potentials of the down-scaled discrete measures
\begin{align}
    (\tilde{\vf}^*,\tilde{\vg}^*) = \argmax_{(\tilde{\vf},\tilde{\vg}) \in \mathcal{R}(\tilde{C})} \inner{\tilde{\vf}, \tilde\vmu} + \inner{\tilde{\vg}, \tilde\vnu}
\end{align}
and evaluate the dual transport cost at the original scale by up-scaling the optimal potentials. Up-scaling can be performed by any multivariate interpolation method such as nearest-neighbor, spline, multi-linear and polynomial methods.
Using an interpolation function
$R: \calX \cup \tilde{\calX} \rightarrow \R$,
the up-scaled potential
$\hat{\vf}$ is defined by
\begin{align}
    \hat{\vf} := \{R_{\tilde{\vf}, \tilde{\calX}}(x_i)\}_{i\in[N^d]}.
\end{align}
An important property of the dual formulation is that for every potential $\vf \in \R^n$ we can easily find a \emph{tight} potential $\vf^\c \in \R^m$ such that $(\vf,\vf^\c) \in \mathcal{R}(C)$, by
\(
    f_j^\c := \min_i C_{ij}-f_i \,.
\)
This is known as a \emph{c-transform}. It can be shown that repeating this process once more achieves a tight pair
$(\vf^\c, \vf^{\c\c}) \in \mathcal{R}(C)$, where
$f_i^{\c\c} := \min_j C_{ij}-f_j^\c$.
Thus, a lower bound is guaranteed by using the c-transform to generate the potential pair from the up-scaled potential
$\vf = \hat{\vf}^{\c\c}$ and $\vg = \hat{\vf}^{\c}$,
which yields the upscaling lower bound
\begin{equation}\label{eq: upscaling lower bound}
    \underline{\Wass}_p(\mu, \nu) := \left(\inner{\vf,\vmu} + \inner{\vg,\vnu} \right)^{\frac{1}{p}}.
\end{equation}

Since by the admissibility of a c-transformed pair $(\vf, \vg) \in \mathcal{R}(C)$, we can write
\begin{proposition}
    Considering an approximate potential $\hat{\vf} \in \R^{N^d}$. For $\vf = \hat{\vf}^{\c\c}$ and $\vg = \hat{\vf}^{\c}$
    \begin{align}
        \inner{\vf,\vmu} + \inner{\vg,\vnu} \le L_C(\mu, \nu).
    \end{align}
\end{proposition}

\section{Computational complexity analysis}\label{sec:complexity}
The quantization-based bounds involve the following steps: computing the Wasserstein metric on the quantized measures, upscaling the dual potentials or couplings to the original scale, and the calculation of weighted total variation correction terms.
The latter is calculated in linear time and space, thus negligible w.r.t. the other steps. In the following, we detail the computational gains provided by the proposed methods.

\paragraph{Downscaled optimal transport}
The solution to the Kantorovich problem of the scaled measures can be solved by dedicated linear programming methods, such as the network  simplex used in \citet{bonneelDisplacementInterpolationUsing2011}, with $O\left(n^{3d}\log{n}\right)$  time complexity \citep{ahujaNetworkFlowsTheory1993}. By solving only for the optimal transport of the coarse measures, we produce a computational speedup of \(\Theta(\kappa^{3d})\) (up to log factors).
The space complexity can also be significantly reduced, since one can avoid storing the full cost matrix of size $N^d \times N^d$, by using coarse cost matrices, e.g. $\bar{C},C^{\min}$, and $\tilde{C}$ of size $n^d\times n^d$, realizing a memory gain of $\Theta(\kappa^{2d})$.

\paragraph{Upscaled optimal coupling}
The optimal coarse coupling $\tilde{\pi}^*$ is a sparse matrix with at most $2n^d - 1$ positive entries \citep[Proposition~3.4]{peyreComputationalOptimalTransport2019}. Thus, the up-scaled approximate coupling from \cref{eq: coupling tensor upscale} conserves this sparsity with $\#\supp{\hat{\pi}} \le \kappa^{2d}(2n^d - 1)$, allowing to calculate the approximate optimal transport
\begin{equation}
    \inner{\hat{\pi}_\xi, C} = \sum_{(i, j) \in \supp{\hat{\pi}}}  \overbrace{a_i\hat{\pi}_{ij}b_j}^{(\hat{\pi}_\xi)_{ij}} \, \rho(x_i, y_j)^p.
\end{equation}
without impacting the total time and space complexity of the coarse optimal transport solution.
\begin{equation}
    \frac{\#{C}}{\#\supp{\hat{\pi}}} = \frac{N^{2d}}{\kappa^{2d}(2n^d - 1)}
    =
    \Theta\big( \left( N/\kappa \right)^d \big).
\end{equation}

\paragraph{Lazy c-transform}
To reduce the memory requirements of \cref{eq: upscaling lower bound}, we evaluate the c-transform on-demand (i.e. "lazy") without storing the entire cost matrix $C$.
\begin{align}\label{eq: lazy c-transform}
    g_j & \leftarrow \min_{i} \rho(x_i,y_j)^p - \hat{f}_i \\
    f_i & \leftarrow \min_{j} \rho(x_i,y_j)^p - g_j
\end{align}

