\section{Algorithms}\label{sec: algorithms}
Lower-bound based on entropic regularization described in \cref{sec: reg lower bound}.
This method simply runs the iterative Sinkhorn algorithm an then returns the unregularized cost term of the dual solution to the entropic regularization problem.
\begin{algorithm}
    \caption{Regularization-Based Lower Bound}
    \label{alg: regularization lower bound}
    \begin{algorithmic}
        \REQUIRE $\vmu,\vnu \in \Sigma_{N^d}$ on $\calX = [N]^d$, $p \ge 1, \varepsilon > 0, \xi > 0$ and metric $\rho$.
        \STATE $C \gets \{\rho(x_i,y_j)^p\}_{ij}$
        \STATE $K \gets \exp\left( -\frac{C}{\varepsilon} \right)$
        \STATE Initialize $\vf \gets \zeros_n$, $\vg \gets \zeros_m$
        \STATE Initialize $\vb \gets \exp\left( \frac{\vg}{\varepsilon} \right)$
        \REPEAT
        \STATE $\va \gets \vmu \oslash (K \vb)$
        \STATE $\vf \gets \varepsilon \log \va$
        \STATE $\vb \gets \vnu \oslash (K^\top \va)$
        \STATE $\vg \gets \varepsilon \log \vb$
        \UNTIL{$\|\va \odot K\vb - \vmu\|_1 + \|\vnu - \vb \odot K^\top \va\|_1 < \xi$}
        \RETURN $\left(\inner{\vf,\vmu} + \inner{\vg,\vnu}\right)^\frac{1}{p}$
    \end{algorithmic}
\end{algorithm}


Algorithm for entropic regularization-based upper bound described in \cref{sec: reg upper bound}, using the unregularized term of the primal solution to the entropic regularization problem, with weighted total variation marginal corrections.
\begin{algorithm}
    \caption{Regularization-Based Upper Bound}
    \label{alg: regularization upper bound}
    \begin{algorithmic}
        \REQUIRE $\vmu,\vnu \in \Sigma_{N^d}$ on $\calX = [N]^d$, $p \ge 1, \varepsilon > 0, \xi > 0$ and metric $\rho$.
        \STATE $C \gets \{\rho(x_i,y_j)^p\}_{ij}$
        \STATE $K \gets \exp\left( -\frac{C}{\varepsilon} \right)$
        \STATE Initialize $\vb \gets \ones_{N^d}$
        \REPEAT
        \STATE $\va \gets \vmu \oslash K\vb$
        \STATE $\vb \gets \vnu \oslash K^\top \va$
        \STATE $\hat{\vmu} \gets \va \odot (K \vb)$
        \STATE $\hat{\vnu} \gets \vb \odot (K^\top \va)$
        \UNTIL{$\|\hat{\vmu} - \vmu\|_1 + \|\vnu - \hat{\vnu}\|_1 < \xi$}
        \STATE $\hat\pi_\varepsilon \gets \diag{(\va)}K\diag{(\vb)}$
        \STATE $\bar{x} \gets \code{mean}(\calX)$
        \STATE $\vw \gets \{\rho(\bar{x},x_i)^p\}_i$
        \STATE $\Delta_{\hat\mu} \gets 2^{1-\frac{1}{p}} \inner{\vw, |\hat{\vmu} - \vmu|}^{\frac{1}{p}}$
        \STATE $\Delta_{\hat\nu} \gets 2^{1-\frac{1}{p}} \inner{\vw, |\vnu - \hat{\vnu}|}^{\frac{1}{p}}$
        \RETURN $\inner{\hat\pi_\varepsilon, C}^\frac{1}{p} + \Delta_{\hat\mu} + \Delta_{\hat\nu}$
    \end{algorithmic}
\end{algorithm}

Algorithm for quantization-based upper bound described in \cref{sec: Weighted-Cost Upper Bound}, using coarse cost weighted by the trivial coupling.
\begin{algorithm}[H]
    \caption{Weighted-Cost Upper Bound}
    \label{alg: weighted cost upper bound}
    \begin{algorithmic}
        \REQUIRE $\vmu,\vnu \in \Sigma_{N^d}$ on $\calX = [N]^d$, $p \ge 1, \kappa\in\N$ and metric $\rho$.
        \STATE $\tilde{\vmu} \gets \code{SumPool}(\vmu;\kappa)$
        \STATE $\tilde{\vnu} \gets \code{SumPool}(\vnu;\kappa)$
        \STATE $\bar{C}_{k\ell}
        \gets
        \left\{\frac{1}{\tilde\mu_k \tilde\nu_\ell} \sum_{\substack{
        x\in X_k \\
        y\in Y_\ell}}
        \rho(x,y)^p \mu(x)\nu(y) \right\}_{k\ell}$
        \STATE Solve $L_{\bar{C}} \gets \min_{\tilde{\pi} \in \Pi(\tilde{\vmu}, \tilde{\vnu})} \inner{\tilde{\pi}, \bar{C}}$
        \RETURN ${L_{\bar{C}} }^{\frac{1}{p}}$
    \end{algorithmic}
\end{algorithm}

Algorithm for bi-level quantization-based upper bound described in \cref{sec: Upscaling upper bound}, using nearest-neighbor upscaling of the optimal coarse coupling, iterative proportional fitting of the marginals (i.e. Sinkhorn iterations), with weighted total variation marginal corrections.
\begin{algorithm}[H]
    \caption{Upscaling Upper Bound}
    \label{alg: upscaling upper bound}
    \begin{algorithmic}
        \REQUIRE $\vmu,\vnu \in \Sigma_{N^d}$ on $\calX=[N]^d$,\, $p \ge 1,\, \kappa\in\N,\, \xi>0$ and metric $\rho$.
        \STATE $\tilde{\calX} \gets \code{AvgPool}(\calX;\kappa)$
        \STATE $\tilde{\vmu} \gets \code{SumPool}(\vmu;\kappa)$
        \STATE $\tilde{\vnu} \gets \code{SumPool}(\vnu;\kappa)$
        \STATE $\tilde{C} \gets \{\rho(\tilde{x}_k, \tilde{x}_\ell)^p \}_{k\ell}$
        \STATE Solve $\tilde{\pi}^* \gets \argmin_{\tilde{\pi} \in \Pi(\tilde{\vmu}, \tilde{\vnu})} \inner{\tilde{\pi}, \tilde{C}}$
        \STATE \COMMENT{\nameref{p: step 1}}
        \STATE $\tilde{\tP}^* \gets \code{reshape}(\tilde{\pi}^*;n)$ \hfill\COMMENT{Reshape as tensor}
        \STATE $\tK \gets \{\kappa^{-2d}\}_{t \in [\kappa]^{2d}}$
        \STATE $\hat{\tP} \gets \tilde{\tP}^* \otimes \tK$ \hfill\COMMENT{Upscaling}
        \STATE $\hat{\pi} \gets \code{reshape}^{-1}(\hat{\tP};N)$
        \STATE \COMMENT{\nameref{p: step 2}}
        \STATE Initialize $\vb \gets \ones_{N^d}$
        \REPEAT
        \STATE $\va \gets \vmu \oslash \hat{\pi}\vb$
        \STATE $\vb \gets \vnu \oslash \hat{\pi}^\top \va$
        \STATE $\hat{\vmu} \gets \va \odot (\hat{\pi} \vb)$
        \STATE $\hat{\vnu} \gets \vb \odot (\hat{\pi}^\top \va)$
        \UNTIL{$\|\hat{\vmu} - \vmu\|_1 + \|\vnu - \hat{\vnu}\|_1 < \xi$}
        \STATE \COMMENT{\nameref{p: step 3}}
        \STATE $\widehat{\Wass}_p \gets \left(\sum_{(i, j) \in \supp(\hat{\pi}) } a_i\hat{\pi}_{ij}b_j \, \rho(x_i, x_j)^p \right)^{\frac{1}{p}}$
        \STATE $\bar{x} \gets \code{mean}(\calX)$
        \STATE $\vw \gets \{\rho(\bar{x},x_i)^p\}_i$
        \STATE $\Delta_{\hat\mu} \gets 2^{1-\frac{1}{p}} \inner{\vw, |\hat{\vmu} - \vmu|}^{\frac{1}{p}}$
        \STATE $\Delta_{\hat\nu} \gets 2^{1-\frac{1}{p}} \inner{\vw, |\vnu - \hat{\vnu}|}^{\frac{1}{p}}$
        \RETURN $\widehat{\Wass}_p + \Delta_{\hat\mu} + \Delta_{\hat\nu}$
    \end{algorithmic}
\end{algorithm}

Algorithm for bi-level quantization-based lower bound described in \cref{sec: Upscaling Lower Bound}, using interpolation for upscaling the optimal coarse dual potentials, and c-transform to achieve optimized admissible dual potentials pair.
\begin{algorithm}[H]
    \caption{Upscaling Lower Bound}
    \label{alg: upscaling lower bound}
    \begin{algorithmic}
        \REQUIRE $\vmu,\vnu \in \Sigma_{N^d}$ on $\calX = [N]^d$, $p \ge 1, \kappa\in\N$ and metric $\rho$.
        \STATE $\tilde{\calX} \gets \texttt{AvgPool}(\calX;\kappa)$
        \STATE $\tilde{\vmu} \gets \code{SumPool}(\vmu;\kappa)$
        \STATE $\tilde{\vnu} \gets \code{SumPool}(\vnu;\kappa)$
        \STATE $\tilde{C} \gets \{\rho(\tilde{x}_k, \tilde{x}_\ell)^p \}_{k\ell}$
        \STATE Solve $(\tilde{\vf}^*,\tilde{\vg}^*) \gets \argmax\limits_{(\tilde{\vf},\tilde{\vg}) \in \mathcal{R}(\tilde{C})} \inner{\tilde{\vf},\tilde\vmu} + \inner{\tilde{\vg}, \tilde{\vnu}}$
        \STATE $\hat{\vf} \gets \{R_{\tilde{\vf}, \tilde{\calX}}(x_i)\}_{i\in[N^d]}$
        \STATE $\vg \gets \left\{\min_{i} \rho(x_i,x_j)^p - \hat{f}_i\right\}_j$
        \STATE $\vf \gets \left\{\min_{j} \rho(x_i,x_j)^p - g_j\right\}_i$
        \RETURN $\big(\inner{\vf,\vmu} + \inner{\vg,\vnu} \big)^{\frac{1}{p}}$
    \end{algorithmic}
\end{algorithm}

