\section{Proofs}\label{sc: proofs}
\subsection{Weighted total variation correction terms}\label{sc: proof of triangle inequality upper bound}
\begin{proof}[Proof of \cref{lm: triangle inequality upper bound}]
    Using the triangle inequality for the Wasserstein metric, we can write
    \begin{equation}
        \Wass_p(\mu,\nu) \le \Wass_p(\mu,\hat{\mu}) + \Wass_p(\hat{\mu},\hat{\nu}) + \Wass_p(\hat{\nu},\nu)
    \end{equation}
    controlling for each element separately, we have
    \begin{align}
           \Wass_p(\mu,\hat{\mu}) \le \mathcal{TV}_p^\vw(\hat{\mu},\mu) \qquad\text{and}\qquad
    \Wass_p(\hat{\nu},\nu) \le \mathcal{TV}_p^\vw(\nu,\hat{\nu})
    \end{align}

    by the property of weighted total variation, and
    \begin{align}
        \Wass_p(\hat{\mu},\hat{\nu})
        =
        \left(
        \min_{\pi \in \Pi(\hat{\mu},\hat{\nu})}
        \inner{\pi,C}
        \right)^{\frac{1}{p}}
        \le
        \inner{\hat{\pi},C}^{\frac{1}{p}}
    \end{align}
    by evaluating the transport cost using a coupling in the problem's original space.
\end{proof}
\begin{proof}[Proof of \cref{th: $L^1$ upper bound on weighted total variation}]
    Consider the definition of weighted total variation,
    \begin{align}
        \mathcal{TV}_p & (\hat{\mu}, \mu; w) + \mathcal{TV}_p(\nu, \hat{\nu}; w)
        \\  \nonumber &= 2^{1-\frac{1}{p}} \inner{w,|\hat\mu-\mu|}^{\frac{1}{p}} + 2^{1-\frac{1}{p}} \inner{w,|\nu - \hat\nu|}^{\frac{1}{p}}
        \\  \nonumber &=
        2^{1-\frac{1}{p}} \left(\left(\sum \rho(\bar{x},x)^p |\hat{\mu}_x - \mu_x| \right)^\frac{1}{p} + \left(\sum \rho(\bar{x},x)^p |\nu_x - \hat{\nu}_x| \right)^\frac{1}{p} \right)
        \\  \nonumber &\le
        2^{1-\frac{1}{p}} \Big(r\|\hat{\mu} - \mu\|_1^\frac{1}{p} + r\|\nu - \hat{\nu}\|_1^\frac{1}{p} \Big)
                       &                                                         & \text{bounding radius} \nonumber
        \\ &\le
        2^{2-\frac{2}{p}} \left(\|\hat{\mu} - \mu\|_1 + \|\nu - \hat{\nu}\|_1  \right)^\frac{1}{p} r
                       &                                                         & \text{Jensen's inequality} \nonumber
        \\ &<
        2^{2-\frac{2}{p}} \xi^\frac{1}{p} r
                       &                                                         & \text{convergence criteria} \nonumber
    \end{align}
\end{proof}

\subsection{Proof of \cref{th: weighted cost UB} \label{sc: proof of weighted cost UB}}
First, let us consider the following lemma discussing a coupling constructed ad hoc using coarsened measures.
\begin{lemma}\label{lm: admissible quantization coupling}
    Let  $\mu,\nu$ measures with set of admissible couplings $\Pi(\vmu,\vnu)$, the trivial coupling $\pi_\otimes$ , and  $\tilde{\mu}$ and $\tilde{\nu}$ the respective coarsened measures. For any coupling $\tilde{\pi}\in\Pi(\tilde{\mu},\tilde{\nu})$, the measure on the product space $\calX\times\calY$

    \begin{equation}\label{eq: quantization coupling}
        \pi_{\tilde{\pi}}(x,y) := \frac{\tilde{\pi}_{k_\sX(x)\ell_\sY(y)}}{\mu(X_{k_\sX(x)})\nu(Y_{\ell_\sY(y)})}\pi_{\otimes} (x,y)
    \end{equation}
    is an admissible coupling $\pi_{\tilde{\pi}} \in \Pi(\vmu,\vnu)$, where the coarsening inverse index functions $k_\sX(x),\,\ell_\sY(y)$ are defined as  $k_\sX(x):=\{k: x\in X_k\}, \ell_\sY(y):=\{\ell: y\in Y_\ell\}$.
\end{lemma}

\begin{proof}[Proof of \cref{lm: admissible quantization coupling}]
    Following Definition 1.1 (Coupling) from \citep{villaniOptimalTransportOld2009}, one can show $\pi_{\tilde{\pi}}(x, y)$ \cref{eq: quantization coupling} is admissible. For $\varphi, \psi$ be any integrable measurable functions on $\calX,\calY$ respectively, than $\pi_{\tilde{\pi}}(x, y)$ admits

    \begin{align}
         & \int_{\calX \times \calY} \big(\varphi(x)+\psi(y)\big)\mathrm{d}\pi_{\tilde{\pi}}(x, y) \\  \nonumber &= 
        \sum_{k,\ell} \int_{X_{k} \times Y_{\ell}} \big(\varphi(x)+\psi(y)\big) \mathrm{d}\pi_{\tilde{\pi}}(x, y)\\  \nonumber
        &=
        \sum_{k,\ell} \int_{X_{k}\times Y_{\ell}}\big(\varphi(x)+\psi(y)\big) \frac{\bm{\Pi}_{k\ell}}{\mu(X_{k})\nu(Y_{\ell})} \mathrm{d}\mu(x) \mathrm{d}\nu(y) \qquad\quad\text{plug-in coupling's definition} \\ \nonumber
        &=
        \sum_{k,\ell} \Big(\frac{\tilde{\pi}_{k\ell}}{\mu(X_{k})\nu(Y_{\ell})}\int_{X_{k}\times Y_{\ell}}\varphi(x) \mathrm{d}\mu(x) \mathrm{d}\nu(y) + \frac{\tilde{\pi}_{k\ell}}{\mu(X_{k})\nu(Y_{\ell})} \int_{X_{k}\times Y_{\ell}}\psi(y)  \mathrm{d}\mu(x) \mathrm{d}\nu(y) \Big) \\ \nonumber
        &=
        \sum_{k,\ell} \frac{\tilde{\pi}_{k\ell}}{\mu(X_{k})}\int_{X_{k}}\varphi(x) \mathrm{d}\mu(x) + \sum_{k,\ell} \frac{\tilde{\pi}_{k\ell}}{\nu(Y_{\ell})} \int_{Y_{\ell}}\psi(y) \mathrm{d}\nu(y) \qquad\text{sum over marginals}\\ \nonumber
        &=
        \sum_{k} \int_{X_{k}}\varphi(x) \mathrm{d}\mu(x) + \sum_{\ell} \int_{Y_{\ell}}\psi(y) \mathrm{d}\nu(y)\\ \nonumber
        &=
        \int_{\calX}\varphi(x) \mathrm{d}\mu(x) + \int_{\calY}\psi(y) \mathrm{d}\nu(y)
    \end{align}
\end{proof}
Next, we consider the transport cost of such a coupling.
\begin{lemma}\label{lm: weighted cost transport identity}
    The transport loss assigned by the cost $c(x,y)$ and a coupling $\pi_{\tilde{\pi}}$ identifies with the coarse transport loss assigned by marginally weighted cost $\bar{C}$ \cref{eq: marginally weighted cost} and the coarse coupling $\tilde{\pi}$,
    \begin{equation}
        \inner{\pi_{\tilde{\pi}}, C} = \inner{\tilde{\pi}, \bar{C}}
    \end{equation}
\end{lemma}
\begin{proof}
    \begin{align}
        \inner{\pi_{\tilde{\pi}}, C} & =
        \sum_{i,j} c(x_i,y_j) \pi_{\tilde{\pi}}(x_i,y_j) =
        \sum_{k,\ell} \sum_{\substack{x\in X_k                                   \\y\in Y_\ell}} c(x,y)\pi_{\tilde{\pi}}(x,y) \\  \nonumber &=
        \sum_{k,\ell} \sum_{\substack{x\in X_k                                   \\y\in Y_\ell}} c(x,y) \frac{\tilde\pi_{k\ell}}{\mu(X_{k})\nu(Y_{\ell})} \pi_{\otimes}(x,y) \\  \nonumber &=
        \sum_{k,\ell} \frac{1}{\mu(X_{k})\nu(Y_{\ell})} \sum_{\substack{x\in X_k \\y\in Y_\ell}} c(x,y) \mu(x)\nu(y)\,\tilde\pi_{k\ell} \\  \nonumber &=
        \sum_{k,\ell} \bar{C}_{k\ell} \tilde\pi_{k\ell} =
        \inner{\tilde{\pi}, \bar{C}}
    \end{align}
\end{proof}

Finally, we can write
\begin{proof}[Proof of \cref{th: weighted cost UB}]
    Based on admissibility of $\pi_{\tilde{\pi}}$ shown in \cref{lm: admissible quantization coupling} the transport cost
    \begin{align}
        \inner{\pi_{\tilde{\pi}}, C} \ge L_C(\mu,\nu),\ \forall \tilde{\pi}\in\Pi(\tilde{\mu},\tilde{\vnu}).
    \end{align}
    In particular, for $\tilde{\pi}^* = \argmin_{\tilde{\pi} \in \Pi(\tilde{\vmu}, \tilde{\vnu})} \inner{\tilde{\pi},\bar{C}}$,
    \begin{equation}
        \inner{\tilde{\pi}^*,\bar{C}} = \inner{\pi_{\tilde{\pi}^*},C} \ge L_C(\mu,\nu)
    \end{equation}
    by the identity shown in \cref{lm: weighted cost transport identity}.
\end{proof}

\subsection{Additional proofs}\label{sec: additional proofs}
\begin{proof}[Proof of \cref{th: locally-minminal cost LB}]
    Consider
    \begin{align}
        \pi^* = \argmin_{\pi\in\Pi(\vmu,\vnu)}\inner{\pi,C}
    \end{align}
    and coarsening of the optimal coupling
    \begin{align}
        \hat{\pi}^*_{k\ell} := \sum_{\substack{
                x\in X_k\\
                y\in Y_\ell}}
        \pi^*(x,y)
    \end{align}
    such that,
    \begin{align}
        L_C(\vmu,\vnu) 
        &= \inner{\pi^*,C} \\ \nonumber
        &= \sum_{\substack{
        x\in \calX                           \\
                y\in \calY}}
        \rho(x,y)^p \pi^*(x,y) \\ \nonumber
        &= \sum_{k,\ell}\sum_{\substack{
        x\in X_k                             \\
                y\in Y_\ell}}
        \rho(x,y)^p \pi^*(x,y)               \\ \nonumber
        &\ge  \sum_{k,\ell} C_{k\ell}^{\min}
        \sum_{\substack{
        x\in X_k                             \\
                y\in Y_\ell}}
        \pi^*(x,y) \\ \nonumber
        &= \inner{\hat{\pi}^*, C^{\min}} \\ \nonumber
        &\ge \min_{\tilde{\pi}\in\Pi(\tilde{\vmu},\tilde{\vnu})}\inner{\tilde\pi, C^{\min}} \\ \nonumber
        &= L_{C^{\min}}(\tilde{\mu},\tilde{\nu}).
    \end{align}
\end{proof}

\begin{proof}[Proof of \cref{lm: normalized coupling}]
    Let $\tilde{\pi}^* \in \Pi(\tilde{\vmu}, \tilde{\vnu})$ be the coarse optimal coupling and $\tK$ be the positive valued normalized kernel tensor satisfying $\sum_{t \in [\kappa]^{2d}} \tK_t = 1$. Recall that $\hat{\tP} = \tilde{\tP}^* \otimes \tK$ and $\hat{\pi}$ is obtained by reshaping $\hat{\tP}$.

    First, we show that the sum of all elements equals 1:
    \begin{align}
        \sum_{i=1}^{N^d}\sum_{j=1}^{N^d} \hat{\pi}_{ij}
        &= \sum_{t \in [\kappa]^{2d}} \sum_{k=1}^{n^d}\sum_{\ell=1}^{n^d} \tilde{\pi}^*_{k\ell} \tK_t \\ \nonumber
        &= \sum_{k=1}^{n^d}\sum_{\ell=1}^{n^d} \tilde{\pi}^*_{k\ell} \sum_{t \in [\kappa]^{2d}} \tK_t \\ \nonumber
        &= \sum_{k=1}^{n^d}\sum_{\ell=1}^{n^d} \tilde{\pi}^*_{k\ell} \cdot 1 
        = 1
    \end{align}
    where the last equality follows from $\tilde{\pi}^*$ being a coupling.

    Second, we show that $\hat{\pi}$ is non-negative. Since $\tilde{\pi}^*$ is a coupling, it is non-negative, and $\tK$ is a positive-valued kernel, their tensor product $\hat{\tP}$ and its reshaped form $\hat{\pi}$ are non-negative.

    Thus, $\hat{\pi}$ satisfies all the properties of a coupling measure.
\end{proof}

