 {\bar \Theta}_{\bs\vartheta_M}(\bs c) := \{ \bs\vartheta_M \in  \Theta_{\bs\vartheta_M} : \bs \alpha\in \Theta_{\bs\alpha,c_1}, \ \min_j \sigma_j^2\geq c_2 \sum_{k=1}^M  \alpha_k\sigma_k^2,\   \sum_{k=1}^M \alpha_k \sigma_k^2\geq c_3 \}.
 \]
