We may also estimate the number of components by the penalized maximum likelihood estimator
\[
\widehat{M}_{PL} = \arg\max_{M\in\{1,2,...,\overline{M}\}}  p\ell_{n}^M(\hat{\bs{\vartheta}}_{M}),
\]
where
\[
p\ell_{n}^M(\hat{\bs{\vartheta}}_{M}):=\ell_n^M(\hat{\bs{\vartheta}}_{M}) - p_{n,k_M},
\]
and $\hat{\bs{\vartheta}}_{M}$ is the MLE defined by (\ref{eq:MLE}) while $ p_{n,k_M}$ is a penalization term with $k_M:= \text{dim}(\bs{\vartheta}_{M})$ representing the number of estimated parameters for  mixture models (\ref{eq:fm}).  %We set $p_{n,k_M}=k$ for AIC and $p_{n,k_M}=(k_M/2)\log(n)$ for BIC.

The following proposition states that the penalized maximum likelihood estimator of the number of components is consistent under the regularity condition.
\begin{assumption}\label{assumption: penalty}
For all \( n > 1 \), the penalty function $p_{n,k}$ satisfies (a) $p_{n,k+1}\geq p_{n,k}>0$, (b) $\lim_{n \to \infty} p_{n,k} = \infty$,  (c) $p_{n,k} = o(n)$,
and (d)
$\lim_{n \to \infty} \frac{p_{n,k'}}{p_{n,k}} > 1$ for $k<k'\leq \overline{M}$.
\end{assumption}
\begin{assumption}\label{assumption:bound}
For $M\in\{M_0+1,M_0+2,...,\overline M\}$, $\ell_{n}^M(\hat{\bs\vartheta}_{M})-\ell_n^{M_0}(\hat{\bs\vartheta}_{M_0})=O_p(1)$.
\end{assumption}

\begin{proposition}[Consistent estimation by the maximum penalized likelihood estimator]\label{proposition:bic}
Suppose that Assumptions \ref{assumption:Q_M}-\ref{assumption:bound} hold. Then, $\widehat{M}_{PL} \overset{p}{\rightarrow} M_0$.
\end{proposition}

