		\bs{s}_{\bs{\bs\eta}}^{j}(\bs W)   \\
		\bs{s}_{\bs{\lambda}}^{j}(\bs W)
\end{pmatrix}\quad \text{with}  \quad \bs{s}_{\bs{\bs\eta} }^{j}(\bs W) :=
\begin{pmatrix}
\bs{s}_{\bs{\alpha}}^{j}(\bs W) \\
\bs{s}_{\bs{\nu}}^{j}(\bs W)
\end{pmatrix}\quad\text{and}\quad \bs{s}_{\bs{\lambda}}^{j}(\bs W) :=
\begin{pmatrix}
\bs{s}_{\bs{\lambda}_1^j}^{j}(\bs W) \\
\vdots\\
\bs{s}_{\bs{\lambda}_{M_0}^j}^{j}(\bs W)
\end{pmatrix},
\end{align}
where
\begin{align}
\bs{s}_{\bs{\alpha}}^{j}(\bs W) =
\begin{pmatrix}
\frac{f_{1}(\bs W;\bs\theta_1^*)-f_{M_0}(\bs W;\bs\theta_{M_0}^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}\\
\vdots\\
\frac{f_{M_0-1}(\bs W;\bs\theta_{M_0-1}^*)-f_{M_0}(\bs W;\bs\theta_{M_0}^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}
\end{pmatrix},\quad
\bs{s}_{\bs{\nu}}^{j}(\bs W) =
\begin{pmatrix}
\frac{\alpha_1^* \nabla_{  \bs\theta} f(\bs W;\bs\theta_1^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}\\
\vdots\\
\frac{\alpha_{M_0}^* \nabla_{ \bs\theta} f(\bs W;\bs\theta_{M_0}^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}\\
\end{pmatrix},\quad\text{and}
\end{align}
\begin{align}
\bs{s}_{\bs{\lambda}_h^j}^{j}(\bs W)=
\begin{pmatrix}
\widetilde{\textnormal{vech}}_2\left(\frac{\alpha_h^* \nabla_{\bs\theta\otimes  \bs\theta}  f(\bs W;\bs\theta_h^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}\right)\\
\vdots\\
\widetilde{\textnormal{vech}}_{p_h^j}\left(\frac{\alpha_h^* \nabla_{\bs\theta^{\otimes  {p_h^j}}}   f(\bs W;\bs\theta_h^*)}{g_{M_0}(\bs W;\bs\vartheta_{M_0}^*)}\right)
\end{pmatrix}\quad\text{for $h=1,...,M_0$}.
\end{align}


We  denote $\bs s_i^j:=\bs s^j(\bs W_i)$. We assume that $l_{\bs\psi_{M}^j\bs\tau^j,i}$ can be expanded around $l_{\bs\psi_{M}^j\bs\tau^j,i}=1$ as follows. Let $ P_n({\bs s}^j_i({\bs s}^j_i)\t):=n^{-1}\sum_{i=1}^n {\bs s}^j_i({\bs s}^j_i)\t$ and $\nu_n( {\bs s}^j_i):= n^{-1/2}\sum_{i=1}^n [ {\bs s}^j_i- \mathbb{E}_{\bs\theta^*}[ {\bs s}^j_i]]$.

For \( \epsilon > 0 \), define the neighborhood of the set \( \bs\psi_{M}^j \) corresponding to the null hypothesis \( H_0: M = M_0 \) as follows:
\[
\mathcal{N}_\epsilon = \{\bs\psi_{M}^j \in \Theta_{\bs\psi_{M}^j} : \sup_{\bs\tau^j \in \Theta_{\bs\tau^j,c_1}} \|\bs{t}_{\bs{\psi}_{M}^j \bs\tau^j}\| < \epsilon\},
\]
where \( \Theta_{\bs\tau^j,c_1} \) denotes the parameter space of \( \bs\tau^j \), as implied by the parameter space \( \Theta_{\bs\alpha,c_1} \) of \( \bs\alpha \), which restricts the values of \( \tau_h^j \) to be bounded away from 0 and 1.




\begin{assumption}\label{assumption:BIC} For $M=M_0+1,...,\bar M$, the following assumption holds when the data is generated from the $M_0$-component model.
For all $j=1,...,J_{M}$ and
$i=1,...,n$, $l_{\bs\psi_{M}^j\bs\tau^j,i}-1$ admits an expansion
\begin{equation}\label{density-ratio}
l_{\bs\psi_{M}^j\bs\tau^j,i} -1 = \left(  \bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}\right)\t \bs s_i^j + r_{\bs\psi_{M}^j\bs\tau^j,i},
\end{equation}
where  $\bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}$ satisfies $\bs\psi_{M}^j\rightarrow \bs\psi_{M}^{j*}$ if $\sup_{\bs\tau^j\in \Theta_{\bs\tau^j,c_1}}|| \bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}||\rightarrow 0$, and $(\bs s_i^j, r_{\bs\psi_{M}^j\bs\tau^j,i})$ satisfy, for some $C\in (0,\infty)$, $\delta>0$, $\epsilon>0$, and $\rho\in(0,1)$, (a) $\mathbb{E}_{\bs\vartheta_{M_0}^*}||\bs s_i^j||^{2+\delta}<C$, (b) $||P_n(\bs{s}_i^j(\bs{s}_i^j)\t) - \bs{\mathcal{I}}^j|| = o_p(1)$, where $\bs{\mathcal{I}}^j:= \mathbb{E}[\bs{s}^j_i (\bs{s}^j_i) ^\top]$ is finite and non-singular, (c) $\mathbb{E}_{\bs\theta^*}[\sup_{{\bs\psi_{M}^j} \in \mathcal{N}_\varepsilon} |r_{\bs\psi_{M}^j\bs\tau^j,i}/(||\bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}||||\bs\psi_{M}^j-\bs\psi_{M}^{j*}||)|^2] < \infty$, (d) $\sup_{{\bs\psi_{M}^j} \in \mathcal{N}_\varepsilon} [ \nu_n(r_{\bs\psi_{M}^j\bs\tau^j,i})/(||{\bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}}||||\bs\psi_{M}^j-\bs\psi_{M}^{j*}||)] = O_p(1)$,  and  (e) $\sup_{{\bs\psi_{M}^j} \in \mathcal{N}_{\varepsilon}} ||\nu_n(\bs{s}_i^j)|| =O_p(1)$.

\end{assumption}

Assumption \ref{assumption:BIC}(b) is a key regularity condition that requires   the unique elements of ${\nabla_{\bs\theta} f_h^*}/{g_{M_0}^*}$, ${\nabla_{\bs\theta\otimes  \bs\theta} f_h^*}/{g_{M_0}^*}$, ...., ${\nabla_{ \bs\theta^{\otimes  p_h}} f_h^*}/{g_{M_0}^*} $ are linearly independent and their expectation is finite.



\begin{proposition} \label{Ln_thm1}
Suppose that Assumption \ref{assumption:BIC} holds. Then,  for any $c>0$,
\begin{equation*}
\sup_{\bs\psi_{M}^j \in  \mathcal{N}_{c/\sqrt{n}}}\left|\ell_n(\bs\psi_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j) - \sqrt{n} \bs t^{\top}_{\bs\psi_{M}^j\bs\tau^j} \nu_n (\bs s_i^j) + n \bs t^{\top}_{\bs\psi_{M}^j\bs\tau^j} \bs{\mathcal{I}}^j \bs t_{\bs\psi_{M}^j\bs\tau^j}/2 \right| = o_{p }(1).
\end{equation*}
\end{proposition}


The following proposition expands $\ell_n(\bs\psi_{M}^j,\bs\tau^j)$ in $A_{\varepsilon_n}(\eta) := \{\bs\psi_{M} \in \mathcal{N}_{\varepsilon_n}: \ell_n(\bs\psi_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j) \geq -\eta \}$ for some $\eta \in [0,\infty)$ and for $\varepsilon_n\rightarrow 0$ slowly to ensure $\Pr( \hat{\bs\psi}_M \in \mathcal{N}_{\varepsilon_n})=1$. % Let $\hat t_{\bs\psi_M\bs\alpha}$ be the reparameterized MLE. %Let $A_{n\varepsilon c}(\eta) := A_{n\varepsilon}(\eta) \cup \mathcal{N}_{c/\sqrt{n}}$ for any $c>0$.
\begin{proposition} \label{Ln_thm2}
Suppose that Assumption \ref{assumption:BIC} holds.
Then, for all $j=1,...,J_{M}$, for any $\eta>0$, and for any $\{\varepsilon_n: n=1,2,...\}$ such that $\varepsilon_n\rightarrow 0$ but $\Pr( \hat{\bs\psi}_M \in \mathcal{N}_{\varepsilon_n})=1$, \\(a) $ \sup_{\bs\psi_M \in A_{\varepsilon_n}(\eta)} \left|\bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}\right| = O_{p   }(n^{-1/2})$,  (b) for any $c>0$,
\begin{equation*}
\sup_{\bs\psi_M \in A_{\varepsilon_n}(\eta) \cup \mathcal{N}_{c/\sqrt{n}} }\left|\ell_n(\bs\psi_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j) - \sqrt{n} \bs{t}_{\bs{\psi}_{M}^j\bs\tau^j} \nu_n (\bs s_i^j) + n \bs{t}_{\bs{\psi}_{M}^j\bs\tau^j} \bs{\mathcal{I}}^j \bs{t}_{\bs{\psi}_{M}^j\bs\tau^j}/2 \right| = o_{p }(1),
\end{equation*}
and (c) $\sup_{\bs\psi_M \in A_{\varepsilon_n}(\eta)} \left|\ell_n(\bs\psi_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j) \right| =O_p(1)$.
\end{proposition}


Because a consistent MLE is in $ A_{\varepsilon_n}(\eta)$ by definition, Proposition \ref{Ln_thm2} implies that $\ell_n(\hat{\bs\psi}_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j)  =O_p(1)$ for a consistent MLE.






\subsection{Bootstrap procedure for the ave- and max-rk statistic}\label{sec:bootstrap}


We consider the following Bayesian bootstrap by drawing $\{\omega^{(b)}_i\}_{i=1}^n$ for $b=1,...,B$, where  $\omega_{i}^{(b)} = \tilde\omega_i^{(b)}/\sum_{j=1}^n \tilde\omega_j^{(b)}$ with
$\tilde\omega_i^{(b)}\overset{iid}{\sim} Exp(1)$ for $i=1,...,n$, and compute the bootstrap version of $\widehat{\bs P}_k$ as
\[
\widehat{\bs P}_k^{(b)} =  \left[
\begin{array}{ccc}
 \sum_{i=1}^n \omega_i^{(b)}  \mathbb{I}(Y_k \in \delta_{1},\bs Y_{\mathcal{T}_{-k}} \in \bs\delta_{1}^{\mathcal{T}_{-k}}) & \cdots &  \sum_{i=1}^n \omega_i^{(b)}  \mathbb{I}(Y_{k} \in \delta_{1},\bs Y_{\mathcal{T}_{-k}} \in \bs \delta_{|\Delta_{\mathcal{T}_{-k}}|}^{\mathcal{T}_{-k}})  \\
\vdots  & \ddots  & \vdots  \\
 \sum_{i=1}^n \omega_i^{(b)} \mathbb{I}( Y_{k} \in \delta_{|\Delta_{t}|},\bs Y_{\mathcal{T}_{-k}} \in \bs \delta_{1}^{\mathcal{T}_{-k}}) & \cdots & \sum_{i=1}^n \omega_i^{(b)} \mathbb{I}(  Y_{k} \in \delta_{|\Delta_{t}|},\bs Y_{-k} \in \bs\delta_{|\Delta_{\mathcal{T}_{-k}}|}^{\mathcal{T}_{-k}})\end{array}
\right] %\label{P*_defn}
\]
for $k=1,...,T$. Note that we use the same weights across different $k$s to accomodate the dependencies across $k$s so that the bootstrapped correlation between $\widehat{\bs P}_k^{(b)}$ and $\widehat{\bs P}_\ell^{(b)}$ for $k\neq \ell$ correctly captures the corresponding sample correlation between $\widehat{\bs P}_k$ and $\widehat{\bs P}_\ell$.


With this bootstrapped $\{\widehat{\bs P}_k^{(b)} \}_{k=1}^T$ for $b=1,...,B$, we construct the bootstrapped rk-statistics as
\begin{equation}\label{bootstrap-1}
\text{rk}^{k(b)}(r) = n (\widehat{\bs{\lambda}}_r^{k(b)} -\widehat{\bs{\lambda}}_r^{k} )^\top (\widehat{\boldsymbol{\Omega}}^{k(b)}_r) ^{-1}(\widehat{\bs{\lambda}}_r^{k(b)}-\widehat{\bs{\lambda}}_r^{k})\quad\text{for $k=1,...,T$},
\end{equation}
where $\widehat{\bs{\lambda}}_r^{k(b)}$ and $\widehat{\boldsymbol{\Omega}}^{k(b)}_r$ are computed as described in Proposition \ref{rk} but we compute $\widehat{\mathbf{A}}_{r }^k$ and $\widehat{\bs\Sigma}_k$ using $\widehat{\bs P}_k^{(b)}$ in place of $\widehat{\bs P}_k$.

Based on $\{\text{rk}^{k(b)}(r)  \}_{k=1}^T$ derived as above, we can construct bootstrapped ave- and max-rk-statistics as:
\begin{align*}
\text{ave-rk}^{(b)}(r) = \frac{1}{T} \sum_{k=1}^T \mathrm{rk}^{k(b)}(r)\ \text{ and }\ \text{max-rk}^{(b)}(r) = \max\{ \mathrm{rk}^{1(b)}(r),...,\mathrm{rk}^{T(b)}(r)\} \ \text{ for $b=1,2,...,B$.} %\quad\text{and}\quad
%\text{max-rk}(r) = \max\{\mathrm{rk}^1(r),\mathrm{rk}^2(r),...,\mathrm{rk}^T(r)\},
\end{align*}


We then compute the bootstrap p-value as the empirical proportion of the bootstrapped test statistics \(\text{max-rk}^{(b)}(r)\) that equal or exceed the observed statistic \(\text{max-rk}(r)\): $\text{bootstrap p-value} = \frac{1}{B} \sum_{b=1}^{B} \mathbb{I}\left(\text{max-rk}^{(b)}(r) \geq \text{max-rk}(r)\right)$.
We reject the null hypothesis that \(\text{rank}(\bs P_k)\leq r\) for all \(k=1,\dots,T\) at significance level \(\alpha\) if the bootstrap p-value is strictly less than \(\alpha\).



\subsection{Asymptotic distribution under local alternatives}\label{sec:local}
We derive the asymptotic distribution of the LRTS under local alternatives. For brevity, we focus on testing $H_0: M=1$ against $H_A: M=2$. Consider the following local alternative to the homogeneous model $f(\bs w;\bs\gamma^*,\bs\theta^*)$ with $\bs\theta^*=(\mu^*,\sigma^{*2},(\bs{\beta}^*)\t)\t$. For brevity, we omit the common parameter $\bs \gamma$ in this section.
In a reparameterized parameter, $\bs{\Psi}^* = ((\bs\nu^*)\t, (\bs{\lambda}^*)\t)\t$.
For $\alpha^*\in (0,1)$  and a local parameter $\bs h=(\bs {h}_{\bs\nu}\t,\bs {h}_{\bs\lambda}\t)\t$ with $\bs h_{\bs \lambda}\in v(\bs\Theta_{\bs\lambda})$,  we consider a sequence of contiguous local alternatives
$(\alpha_n,\bs{\psi}_n\t)\t = (\alpha_n,\bs\nu_n\t,\bs\lambda_n\t)\in  \bs{\Theta}_\alpha\times \bs{\Theta}_{\bs\nu}\times\bs{\Theta}_{\bs\lambda}$ such that, with $\bs{t}_{\bs\lambda}(\bs\lambda,\alpha)$ given by (\ref{eq:t_1}),
\begin{equation}\label{eq:h}
 %\bs {h_\lambda} =\sqrt{n} \bs{t}_{\bs\lambda}(\bs\lambda_n,\alpha_n).
\bs {h_\nu}= \sqrt{n}(\bs\nu_n -\bs\nu^*),\quad \bs {h_\lambda} =\sqrt{n} \bs{t}_{\bs\lambda}(\bs\lambda_n,\alpha_n),\quad \text{and} \quad \alpha_n = \alpha^* + o(1).
\end{equation}
Equivalently, the non-reparameterized contiguous local alternatives are given by
\begin{equation}\label{eq:local-alt}
\bs\theta_{1,n} =\bs \nu_n + (1-\alpha_n) \bs\lambda_n\quad\text{and}\quad \bs\theta_{2,n} = \bs\nu_n - \alpha_n \bs\lambda_n
\end{equation}
for  $\bs\nu_n = \bs \nu^* + n^{-1/2} \bs{h}_{\nu}$ and
$\bs\lambda_n= (\lambda_{1,n},\lambda_{2,n},....,\lambda_{q,n})\t$ with
\begin{align*}
\lambda_{j,n} = n^{-1/4} (\alpha_n(1-\alpha_n))^{-1/2} h_{\lambda,j}\quad \text{for $j=1,...,q$},
\end{align*}
where $\bs{h}_{\bs\lambda}=(h_{\lambda,1}^2,2h_{\lambda,1}h_{\lambda,2},h_{\lambda,1}^2,...,2h_{\lambda,q-1}h_{\lambda,q},h_{\lambda,q}^2)\t$. The local alternatives are of order $n^{1/4}$ rather than $n^{1/2}$. See
  the discussion following Proposition \ref{prop:t2_distribution}.

The following proposition provides the asymptotic distribution of the LRT  test statistics under contiguous local alternatives.
\begin{proposition}\label{prop:local-power}
Suppose that the assumptions in Proposition \ref{prop:tm0_distribution} hold for $M_0=1$. Consider a sequence of contiguous local alternatives $\bs\vartheta_{2,n} = (\alpha_n,\bs\theta_{1,n}^\top,\bs\theta_{2,n}^\top)\t$ given in (\ref{eq:local-alt}), where  $\alpha_n$ and $\bs\lambda_n$ satisfy (\ref{eq:h}). Then, under $H_{1,n}: \bs\vartheta=  \bs\vartheta_{2,n}$, we have $LR_n\overset{d}{\rightarrow} (\tilde{\bs{t}}_{\bs\lambda} )\t \bs{\mathcal{I}}_{\bs\lambda,\bs\eta}  \tilde{\bs{t}}_{\bs\lambda}$,
where $\tilde{\bs t}_{\bs\lambda}$ has the same distribution as $\widehat {\bs t}_{\bs\lambda}$ in Proposition \ref{prop:t2_distribution} but $\bs{G}_{\bs{\lambda,\bs{\eta}}}$ is replaced with $ ( \bs{\mathcal{I}}_{\bs\lambda,\bs\eta}  )^{-1} \bs{S}_{\bs\lambda,\bs\eta} + \bs h_{\bs\lambda}$.
\end{proposition}
Importantly, a set of contiguous local alternatives considered in (\ref{eq:local-alt}) excludes a sequence such that $\alpha_n\rightarrow 0$ or $1$.


\subsection{Proof of Propositions}

\begin{proof}[Proof of Proposition \ref{prop:unbounded_likelihood}]


	We first consider a model with an intercept parameter and a variance parameter but without covariates with  $\mathbf W_i = \{ y_{it} \}_{t=1}^T$ for the model (\ref{eq:fm}) with normal density (\ref{eq:f1}).

		Define
	\[
	s_i^2 = \frac{1}{T-1}\sum_{t=1}^T (Y_{it}-\bar Y_i)^2 \quad\text{with}\quad \bar Y_i = \frac{1}{T} \sum_{t=1}^T Y_{it},
	\]
	where $(T-1)s_i^2/\sigma^{*2}$ follows a chi-square distribution with $T-1$ degrees of freedom.
Let $i^* = \arg\min_{i=1,\ldots,n} \{s_i^2\}$ so that  $s_{i^*}^2  = \min\{s_1^2,\ldots,s_n^2\}$ is the minimum of $s_i^2$ across all values of $i$.
We consider a sequence of parameters $\bs\vartheta_{2,n}=(\alpha_n,\bs\theta_{1,n}\t,\bs{\theta}_{2,n}\t)\t$ with $\alpha_n = 1/n$,  $\bs\theta_{1,n}=(\mu_{1,n},\sigma_{1,n}^2)\t=(\bar Y_{i^*},s_{i^*}^2)\t$, and  $\bs\theta_{2,n}=\bs\theta^*=(\mu^*,\sigma^*)\t$ for all $n$. %Because $LR_n^*(\bs\vartheta_{2,n})\leq LR_n^*(\tilde{\bs\vartheta}_{2,n})$,
It suffices to show that $LR_n^*(\bs\vartheta_{2,n})$ is unbounded in probability.

	Define \[
	\ell(\bs{W}_i;\bs\theta) : = \log f(\bs{W}_i;\bs\theta) = -\frac{T}{2}\log \sigma^2 - \frac{T}{2}\log(2\pi) - \frac{1}{2}\sum_{t=1}^T \left(\frac{Y_{it}-\mu}{\sigma}\right)^2.
	\]
	Then, the LRT statistic for a two-component mixture is written as
		\begin{align}
		LR_n^*(\bs\vartheta_{2,n}) & = 2 \left\{\sum_{i=1}^n \log\left(\alpha_n \prod_{t=1}^T \frac{1}{\sigma_{1,n}}\phi\left(   \frac{Y_{it}-\mu_{1,n}}{\sigma_{1,n}}\right)
	+(1-\alpha_n) \prod_{t=1}^T \frac{1}{\sigma^*}\phi\left(  \frac{Y_{it}-\mu^*}{\sigma^*}\right)\right)-  \sum_{i=1}^n\ell(\bs{W}_i;\bs\theta^*) \right\}\nonumber\\
	%&=\sum_{i=1}^n \log\left(   \exp(\log\alpha_n+\ell(\bs{W}_i;{\bs\theta}_{1,n})) + \exp(\log (1-\alpha_n)+\ell(\bs{W}_i;{\bs\theta}_{2,n}))\right)-\ell(\bs{W}_i;\bs\theta^*)\\
	& =
	2\sum_{i\neq i^*} \left\{\log\left(   \exp(\log\alpha_n+\ell(\bs{W}_i;{\bs\theta}_{1,n})) + \exp(\log (1-\alpha_n)+\ell(\bs{W}_i;{\bs\theta}^*))\right)-\ell(\bs{W}_i;\bs\theta^*)\right\} \nonumber \\
	&\quad +2 \left\{\log\left(   \exp(\log\alpha_n+\ell(\bs{W}_{i^*};{\bs\theta}_{1,n})) + \exp(\log (1-\alpha_n)+\ell(\bs{W}_{i^*};{\bs\theta}^*))\right)-\ell(\bs{W}_{i^*};\bs\theta^*)\right\} \label{lr-1}.
	\end{align}


	The first term on the right-hand side of (\ref{lr-1}) can be rewritten as
	\begin{align*}
	 = 2(n-1) \log \left(\frac{n-1}{n}\right)
	+ 2	\sum_{i\neq i^*}\log\left(1+\frac{1}{n-1} \exp(\ell(\bs{W}_i;{\bs\theta}_{1,n})-\ell(\bs{W}_i;{\bs\theta}^*))\right),
	\end{align*}
	which is bounded from below by $-2$ as $n\rightarrow \infty$ because  $\lim_{n\rightarrow \infty} 2(n-1) \log \left(\frac{n-1}{n}\right)  =-2$ and $\log\left(1+\frac{1}{n-1} \exp(\ell(\bs{W}_i;{\bs\theta}_{1,n})-\ell(\bs{W}_i;{\bs\theta}^*))\right)\geq 0$ for all $n$.

The second term  on the right-hand side of (\ref{lr-1}) is written as
\begin{align}
2\{ - \log n + \ell(\bs{W}_{i^*};{\bs\theta}_{1,n})\} + 2 \log\left(1 + (n-1)  \exp(\ell(\bs{W}_{i^*};{\bs\theta}^*)-\ell(\bs{W}_{i^*};{\bs\theta}_{1,n}))\right) - 2 \ell(\bs{W}_{i^*};\bs\theta^*),\label{lr-2}
\end{align}
where  $2\{ - \log n + \ell(\bs{W}_{i^*};{\bs\theta}_{1,n})\}$ diverges to infinity as $n\rightarrow
\infty$ by   Lemma \ref{lemma:unbounded_likelihood}, the second term in (\ref{lr-2}) is bounded below from zero, and the third term is bounded in probability because $\ell(\bs{W}_{i^*};\bs\theta^*)=O_p(1)$. Therefore,    for any $M<\infty$, we have
	$\Pr \Big(LR_n^*(\bs\vartheta_{2,n}) \le M \Big) \to 0$ as $n \to \infty$. % The stated result follows from $LR_n^*(\bs\vartheta_{2,n})\leq LR_n^*(\tilde{\bs\vartheta}_{2,n})$ for all $n$.


For a model with covariates for the model (\ref{eq:fm}) with normal density (\ref{eq:f1}), we can consider a sequence of parameters $\bs\vartheta_{2,n}=(\alpha_n,\bs\theta_{1,n}\t,\bs{\theta}_{2,n}\t)\t$ with $\alpha_n = 1/n$,  $\bs\theta_{1,n}=(\mu_{1,n},\sigma_{1,n}^2,\bs\beta_{1,n}\t)\t=(\bar Y_{i^*}, s_{i^*}^2,\bs 0\t)\t$ with    $\bs\theta_{2,n}=\bs\theta^*=(\mu^*,\sigma^*,(\bs\beta^*)\t)\t$. Then, repeating the above argument, the stated result follows.

For the model (\ref{eq:fm}) with normal mixture density (\ref{eq:f1-mixture}), suppose that $\mu_{j1}<\mu_{j2}$ for $j=1,2$. Then, in veiw of (\ref{bound-mixture-density}),  we can bound the log-likelihood function from below as
\begin{align*}
&\sum_{i=1}^n \log\left(\alpha \prod_{t=1}^T \sum_{k=1}^{{\cal{K}}} \tau_{1k} \frac{1}{\sigma_{1}}\phi\left(   \frac{Y_{it}-\mu_{1k}}{\sigma_{1}}\right)
	+(1-\alpha) \prod_{t=1}^T \sum_{k=1}^{{\cal{K}}} \tau_{2k}\frac{1}{\sigma_2}\phi\left(  \frac{Y_{it}-\mu_{2k}}{\sigma_2}\right)\right) \\
	\geq &\sum_{i=1}^n \log\left(\alpha \prod_{t=1}^T  \frac{1}{\sigma_{1}}\phi\left(   \frac{Y_{it}-\mu_{11}}{\sigma_{1}}\right)
	+(1-\alpha) \prod_{t=1}^T  \frac{1}{\sigma_2}\phi\left(  \frac{Y_{it}-\mu_{21}}{\sigma_2}\right)\right).
\end{align*}
Therefore, the LRT statistic for a two-component mixture, $LR_n^*(\bs\vartheta_{2,n})$, is bounded below by the right hand side of (\ref{lr-1}).
Then, repeating the argument following (\ref{lr-1}),  the stated result follows from  Lemma \ref{lemma:unbounded_likelihood}. This proves part (i).

For part (ii), consider a model without covariates for the dynamic panel model (\ref{eq:fm-dynamic}) with (\ref{eq:f1-dynamic}). Let $Y_{11}$ denote the first observation at time $t=1$.
Given the realized data of a fixed sample size $n$, consider a sequence of parameters $\{(\alpha_\ell,\bs\theta_{1,\ell}\t,\bs{\theta}_{2,\ell}\t)\t\}_{\ell=1}^\infty$ with $\alpha_\ell = 1/2$, $\bs\theta_{1,\ell}=(\mu_{11,\ell},\mu^*,\rho^*,\sigma_{1,\ell}^{2},\sigma^{*2})\t$, and  $\bs\theta_{2,\ell}=\bs\theta^*=(\mu_{1}^*,\mu^*,\rho^*,\sigma_1^{*2},\sigma^{*2})\t$, where $\{\mu_{11,\ell},\sigma_{1,\ell}^2\}_{\ell=1}^\infty$ satisfies $(\mu_{11,\ell},\sigma_{1,\ell}^2)\rightarrow (Y_{11},0)$ as $\ell\rightarrow\infty$ such that
\[
\frac{
\mu_{11,\ell} - Y_{11}}{\sigma_{1,\ell}} \rightarrow C \quad\text{as $\ell\rightarrow\infty$,}
\]
where $C$ is some constant. Then, for any positive and large constant $B>0$, we have $LR_n^*(\bs\vartheta_{2,\ell})>B$ by taking a sufficiently large value of $\ell$ because
\[
\lim_{\ell\rightarrow\infty} \frac{1}{\sigma_{1,\ell}} \phi\left(\frac{
\mu_{11,\ell} - Y_{11}}{\sigma_{1,\ell}} \right)  = \phi\left(C\right) \times \lim_{\sigma_{1,\ell}\rightarrow 0}  \frac{1}{\sigma_{1,\ell}}= \infty.
\]
The analogous argument applies to the model (\ref{eq:fm-dynamic}) with normal mixture density (\ref{eq:f1-dynamic-mixture}), and the stated result of part (ii) follows.


\end{proof}



