%so that all derivatives are proportional to \(f^{*}\).  
Note that, for $Z=\tfrac{Y-\mu}{\sigma}$,
\[\frac{\partial}{(\partial\mu)}
\Bigl[\tfrac{1}{\sigma}\,\phi(Z)\Bigr]
\;=\;
\tfrac{Z}{\sigma}\;\frac{1}{\sigma}\,\phi(Z),
\quad
\frac{\partial^{2}}{(\partial\mu)^{2}}
\Bigl[\tfrac{1}{\sigma}\,\phi(Z)\Bigr]
\;=\;
\tfrac{Z^{2}-1}{\sigma^{2}}\;\frac{1}{\sigma}\,\phi(Z), 
\]
\[\text{and}\quad
\frac{\partial}{\partial\sigma^{2}}
\Bigl[\tfrac{1}{\sigma}\,\phi(Z)\Bigr]
\;=\;
\tfrac{1}{2\,\sigma^{2}}\,(Z^{2}-1)\;\frac{1}{\sigma}\,\phi(Z).
\]

Hence, for either \(j=1,2\), a straightforward calculation gives
\begin{equation} \label{eq:prop-2} 
\left.\frac{\partial^{2}g_{2}}{(\partial\mu_{j})^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\;=\bar\alpha\;
f^{*}\,\frac{1}{\sigma^{*2}}\,
\Bigl[\,(Z_{1}+\cdots+Z_{T})^{2}-T\Bigr]\quad\text{and}\quad
\left.\frac{\partial\,g_{2}}{\partial\sigma_{j}^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\;=\bar\alpha\;
f^{*}\,\frac{1}{2\,\sigma^{*2}}
\sum_{t=1}^{T}\bigl(Z_{t}^{2}-1\bigr),
\end{equation}
where 
\[
Z_{t}:=\frac{Y_{t}-\mu^{*}}{\sigma^{*}},
\qquad
t=1,\dots,T.
\]

Suppose, for contradiction, that real constants \(a,b\) exist such that
\[
\left.\frac{\partial^{2}g_{2}}{(\partial\mu_{j})^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\;=\;
a
\;+\;
b\,
\left.\frac{\partial\,g_{2}}{\partial\sigma_{j}^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\]
with positive probability.  Since \(\bar\alpha  f^{*}/\sigma^{*2}>0\) almost surely, substituting (\ref{eq:prop-2}) into the above equation, and dividing both sides by \(\bar\alpha f^{*}/\sigma^{*2}\) gives
\[
(Z_{1}+\cdots+Z_{T})^{2}\;-\;T
\;=\;
\frac{a\,\sigma^{*2}}{\bar\alpha f^{*}}
\;+\;
\frac{b}{2}\sum_{t=1}^{T}\bigl(Z_{t}^{2}-1\bigr),
\]
or equivalently
\[
(Z_{1}+\cdots+Z_{T})^{2}
\;=\;
\frac{b}{2}\sum_{t=1}^{T}Z_{t}^{2}
\;+\;\Bigl(\frac{a\,\sigma^{*2}}{\bar\alpha f^{*}}-\tfrac{b\,T}{2}\Bigr)
\;+\;T.
\]
But
\[
(Z_{1}+\cdots+Z_{T})^{2}
\;=\;
\sum_{t=1}^{T}Z_{t}^{2}
\;+\;2\sum_{1\le i<j\le T}Z_{i}Z_{j},
\]
so this would force
\[
\Bigl(1-\tfrac{b}{2}\Bigr)\sum_{t=1}^{T}Z_{t}^{2}
\;+\;
2\sum_{1\le i<j\le T}Z_{i}Z_{j}
\;=\;
C,
\quad
C \;:=\; \frac{a\,\sigma^{*2}}{\bar\alpha f^{*}} \;-\;\tfrac{b\,T}{2} \;+\; T,
\]
as a polynomial identity in \((Z_{1},\dots,Z_{T})\).  Since the coefficient of each cross‐term \(Z_{i}Z_{j}\) on the left is \(2\), but on the right must be \(0\), no choice of \(b\) can satisfy this identity except on a set of probability zero.  Hence no such constants \(a,b\) exist, and
\[
\Pr\Bigl[\, \left.
\tfrac{\partial^{2}g_{2}}{(\partial\mu_{j})^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\;=\;
a
\;+\; \left.
b\,\tfrac{\partial\,g_{2}}{\partial\sigma_{j}^{2}}\right|_{(\bar\alpha.\theta^{*},\theta^*)}
\Bigr]
\;=\;0.
\] 
\end{proof}



\begin{proof}[Proof of Proposition \ref{prop:consistency}]


Our proof closely follows the proof of Theorem 3.3 in \citet{hathaway85as} by verifying Assumptions 1, 2, 3, and 5 of \cite{kieferwolfowitz56ams}.

We first consider a model with the component-specific density function (\ref{eq:fm}) with (\ref{eq:f1}).
Because our model has additional free parameters $\bs\beta_j$s, as in the proof of \cite{kasaharashimotsu15jasa},
we consider the joint density of $m_{q}:=M(q+1)$ observations instead of $M+1$ observations in \citet[][p.\ 798]{hathaway85as}, where $q:=\text{dim}(\bs\beta)$. The joint density function of $m_{q}$ observations is itself a mixture of $M^{m_{q}}$ components, where each component is given by $\prod_{j = 1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_j} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j} ,\sigma_{i_j})$ for some choices $i_j\in \{1,\ldots,M\}$, with the density of $N(\mu,\sigma^2)$ denoted by $f(y; \mu,\sigma): = \frac{1}{\sigma}\phi((y-\mu)/\sigma)$.


% (2\pi\sigma^2)^{-1/2}\exp(-(y-\mu)^2/2\sigma^2)$.



Assumptions 1, 2, and 3 of \citet{kieferwolfowitz56ams} are easily verified for the joint density of $m_{q}$ observations. We verify Assumption 5 of \citet{kieferwolfowitz56ams} for the joint density function of $m_{q}$ observations by showing that
\begin{equation}
E\left[\log \prod_{j = 1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_j}^* + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j}^*,\sigma^*_{i_j})\right] > -\infty \label{H3.1}
\end{equation}
for $\bs{\vartheta}^*_M\in\Theta_M^*$ and that
\begin{equation}
E \sup_{\bs{\vartheta}_M \in \Theta_{\bs{\vartheta}_M}(\bs c)} \left[\log \prod_{j=1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_j} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j},\sigma_{i_j})\right]
<\infty \label{H3.2}
\end{equation}
for all component choices $i_j\in \{1,\ldots,M\}$,
which correspond to equations (3.1) and (3.4) in \citet{hathaway85as}, respectively. (\ref{H3.1}) follows from the argument in the proof of Theorem 3.3 of \citet{hathaway85as}.

For (\ref{H3.2}),  because $\bs{\vartheta}_M\in {\bar \Theta}_{\bs\vartheta_M}(\bs c)$, there exists $c\in(0,1]$ such that $\min_{j,k}\sigma_j/\sigma_k>c$.
Proceeding as in \citet[][pp.\ 798--799]{hathaway85as}, we can show that
\begin{align*}
\sup_{\bs{\vartheta}_M \in \Theta_{\bs{\vartheta}_M}(\bs c)}\log \left[ \prod_{j=1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_j} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j},\sigma_{i_j})\right]
\end{align*}
is no larger than, for some $\ell\in\{1,...,M\}$ and $j_1,j_2,...,j_{q+1}\in \{1,...,m_k\}$,
\begin{equation}\label{H3.5}
\sup_{\mu_\ell,\bs\beta_\ell,\sigma_\ell} \log \left[ \delta(\sigma_\ell)
\prod_{r=1}^{q+1}\prod_{t=1}^T f(Y_{j_rt}; \mu_{\ell} + \bs{X}_{j_rt}^{\top}\bs{\beta}_{\ell},\sigma_{\ell})\right],
\end{equation}
where $\delta(\sigma_\ell)=(2\pi)^{-T(M-1)(q+1)/2}(c\sigma_\ell)^{-T(M-1)(q+1)}$, because $f(Y_{jt}; \mu_{i_j} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j},\sigma_{i_j})=(2\pi)^{-1/2}(\sigma_{i_j})^{-1}\exp(-\{ Y_{jt}-( \mu_{i_j} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j})\}^2/2\sigma_{i_j}^2 )\leq (2\pi)^{-1/2}(\sigma_{i_j})^{-1}\leq (2\pi)^{-1/2}(c\sigma_\ell)^{-1}$ for $j \notin \{j_1,j_2,...,j_{q+1}\}$.

Note that $\prod_{q=1}^{q+1}\prod_{t=1}^T f(Y_{j_qt}; \mu_{\ell} + \bs{X}_{j_qt}^{\top}\bs{\beta}_{\ell},\sigma_{\ell})$ is the likelihood function of a linear Gaussian model. Therefore,  the maximized value of (\ref{H3.5}) equals $C_1 - C_2\log(SSR)$,
where $C_1$ and $C_2 $ are a finite constant that depends only on $M$, $k$, and $T$ while $SSR$ is the sum of squared residuals obtained from regressing $\{\{Y_{j_qt}\}_{t=1}^T\}_{q=1}^{q+1}$ on $\{\{1,\bs X_{j_qt}\}_{t=1}^T\}_{q=1}^{q+1}$. Because we have $(T-1)(q+1)$ more observations than the number of parameters, the SSR is distributed as $\sigma_\ell^{*2} \chi^2((T-1)(q+1))$.  Since $E\log(\chi^2((T-1)(q+1))) < \infty$, the expected value of (\ref{H3.5}) is finite, and (\ref{H3.2}) holds. This verifies Assumption 5 of \citet{kieferwolfowitz56ams}, and the stated consistency result follows.

When the component-specific density function is given by (\ref{eq:fm}) with (\ref{eq:f1-mixture}), where the number of components  in (\ref{eq:f1-mixture}) is $K$, the joint density function of $m_{q}$ observations can be written as  a mixture of $M^{m_{q}}\times K^{m_qT}$ components,
where each component is given by $\prod_{j = 1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_{j}i_k} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j} ,\sigma_{i_j})$ for some choices $i_j\in \{1,\ldots,M\}$ and $i_{k}\in \{1,...,K\}$. Then, repeating the same argument as above, we can show that the expected value of
$\sup_{\bs{\vartheta}_M \in \Theta_{\bs{\vartheta}_M}(\bs c)}\log \left[ \prod_{j=1}^{m_{q}}\prod_{t=1}^T f(Y_{jt}; \mu_{i_ji_k} + \bs{X}_{jt}^{\top}\bs{\beta}_{i_j},\sigma_{i_j})\right]$ is bounded, and Assumption 5 of \citet{kieferwolfowitz56ams} holds. Because Assumptions 1, 2, and 3 of \citet{kieferwolfowitz56ams} are also easily verified, the consistency result follows.

The proof for the dynamic model with the component-specific density function (\ref{eq:fm-dynamic}) using either (\ref{eq:f1-dynamic}) or (\ref{eq:f1-dynamic-mixture}) follows analogously and is therefore omitted.

\end{proof}


\begin{proof}[Proof of Proposition \ref{prop:t2_distribution}]


The proof  is similar to that of Proposition 3 in \cite{kasaharashimotsu15jasa}.

Given the value of $\bs c$ and $\alpha\in [c_1,1-c_1]$, define the space for reparameterized parameters as
$\bs{\psi} := (\bs{\nu}\t,\bs{\lambda}\t)\t \in \Theta_{\bs\psi_\alpha}$,
where $\Theta_{\bs{\psi}_\alpha} = \{ \bs{\psi}=(\bs\nu\t,\bs\lambda\t)\t:   (\alpha,\bs{\nu} + ( 1 - \alpha) \bs{\lambda}, \bs{\nu} - \alpha \bs{\lambda}) \in \Theta_{\bs\vartheta_2}(\bs c)\}.$  Under the null hypothesis $H_{01}: \bs{\theta}_1  = \bs{\theta}_2 = \bs{\theta}^*$, we have $\bs{\lambda} =\bs 0$ and $\bs{\nu} = \bs{\theta}^*$. We rewrite the reparameterized parameters under the null hypothesis as $\bs{\psi}^{*} = ((\bs{\theta}^*)\t,\bs 0\t)\t$. We denote the reparameterized  density function and its logarithm as
\begin{align}\label{eq:repar}
	g(\bs{w};\bs{\psi},\alpha) & := \alpha f(\bs{w}; \bs{\nu}  + (1 - \alpha) \bs{\lambda}) + (1 - \alpha)  f(\bs{w}; \bs{\nu} - \alpha \bs{\lambda})\ \text{ and }\  l(\bs{w};\bs{\psi},\alpha)    = \log g(\bs{w};\bs{\psi},\alpha).
\end{align}

Let $L_n(\bs{\psi},\alpha):= \sum_{i=1}^n  l(\bs{W}_i;\bs{\psi},\alpha)$ be the reparameterized log-likelihood function.
For each $\alpha\in [c_1,1-c_1]$, define the reparameterized MLE as
\begin{equation}
	  \label{eq:mle}
\hat{\bs{\psi}}_\alpha= \arg \max_{\bs{\psi} \in \Theta_{\bs\psi_\alpha}}  L_n(\bs{\psi},\alpha).
\end{equation}

Collect the relevant normalized reparameterized parameters and define $\bs{t}(\bs{\psi},\alpha)$ as
\begin{equation}
 \label{eq:t_1}
 \bs{t}(\bs{\psi},\alpha)  = \begin{pmatrix}
 \bs{t}_{\bs{\nu}} \\
 \bs{t}_{\bs{\lambda} }(\bs{\lambda},\alpha)
 \end{pmatrix}= \begin{pmatrix}
	 \bs{\nu} - \bs{\nu}^* \\
	  \alpha ( 1- \alpha)  \bs{v} (\bs{\lambda} )
 \end{pmatrix},
\end{equation}
where $v(\bs{\lambda})$  is  given by (\ref{eq:v}).


As discussed in the proof of Lemma \ref{lemma:expansion}, taking the fourth-order Taylor expansion of $L_n(\bs{\psi},\alpha)$  around $(\bs\psi^*,\alpha)$, we may write $2\{L_n(\bs{\psi},\alpha)- L_n(\bs{\psi}^*,\alpha)\}$ as a quadratic function of $\sqrt{n}\bs{t}(\bs{\psi},\alpha)$ as
\begin{align}
2\{L_n(\bs{\psi},\alpha)- &L_n(\bs{\psi}^*,\alpha)\} = 2(\sqrt{n}\bs{t}(\bs{\psi},\alpha))\t \bs S_n - (\sqrt{n}\bs{t}(\bs{\psi},\alpha))\t \bs {\mathcal{I}}_n(\sqrt{n}\bs{t}(\bs{\psi},\alpha)) + R_n(\bs{\psi},\alpha)  \label{eq:LR0} \\
 & \quad=  \bs G_n\t \bs{\mathcal{I}}_n \bs G_n -  \left[ \sqrt{n}\bs{t}(\bs{\psi},\alpha)- \bs G_n\right]\t \bs{\mathcal{I}}_n  \left[ \sqrt{n}\bs{t}(\bs{\psi},\alpha)- \bs G_n\right] + R_n(\bs{\psi},\alpha),\label{eq:LR1}
\end{align}
where   $\bs S_n := n^{-1/2} \sum_{i=1}^n {\bs s}(\bs W_i)$ and $\bs G_n:=\bs{\mathcal{I}}_n^{-1}\bs S_n$, where $\bs {\mathcal{I}}_n$ is the negative of the sample Hessian defined in the proof of Lemma \ref{lemma:expansion}. % Let $\bs{\mathcal{I}}=\E[\bs s(\bs W)\bs s(\bs W)\t]$.



%Therefore, the solution to $\bs a\t \bs s_i = 0$ is $\bs a = \bs 0$, then $\bs s_i$ is not collinear. When $T > 1$ and Assumption \ref{assumption:1} and \ref{assumption:LRT1} hold, then $\bs{\mathcal{I}}$ is non-singular.
