\begin{proof}[Proof of Proposition \ref{prop:infinite_fisher}]
	Under $H_{2,0}$,  we obtain $\vartheta_{M_0+1} \in \Upsilon_{2h}^*$,
	\begin{equation}
    % \label{eq:h_02_expansion}
		\begin{split}
		& \E [\{ \nabla_{\alpha_h}  \log f_{M_0+1}  (\bs W_i, \vartheta_{M_0+1} )\}^2  ]  \\
		& = \int  \frac{ \{ f( \bs w;   \bs \theta_{h} )   - f( \bs w;  \bs \theta_{M_0}^* )  \}^2 }{\sum_{j=1}^{M_0} \alpha_j^* f( \bs w;  \bs \theta_j^* ) } d \bs w \\
		& = \int  \frac{ \{ f( \bs w; \bs \theta_{h} ) \}^2 }{\sum_{j=1}^{M_0} \alpha_j^* f( \bs w;  \bs \theta_j^* ) } d \bs w  + \int  \frac{ \{  f( \bs w;  \bs \theta_{M_0}^* )  \}^2 }{\sum_{j=1}^{M_0} \alpha_j^*
		 f( \bs w;  \bs \theta_j^* ) } d \bs w -   2  \int  \frac{  f( \bs w;  \bs \theta_{h} )  f( \bs w;  \bs \theta_{M_0}^* )   }{\sum_{j=1}^{M_0} \alpha_j^* f( \bs w;  \bs \theta_j^* ) } d \bs w .
	\end{split} \label{eq:infinite_fisher}
 \end{equation}
The latter two terms on the right-hand side of (\ref{eq:infinite_fisher}) are bounded because
$f( \bs w;  \bs \theta_{M_0}^* )  / \sum_{j=1}^{M_0} \alpha_j^* f( \bs w;  \bs \theta_j^* )  \le (1 / \alpha_{M_0}^*)$ for any $\bs w$ and $f(\bs w; \bs \theta)$ integrates to one.
Therefore, the left-hand side of (\ref{eq:infinite_fisher}) goes to infinity if and only if the first term on the right-hand side of (\ref{eq:infinite_fisher}) goes to infinity.

Because $\max_j \alpha_j \le \sum_{j}^{M_0} \alpha_j \le M_0 \max_j \alpha_j$, we obtain
\[  \frac{1}{M_0}  \frac{ \{  f( \bs w;  \bs \theta_{h} )  \}^2 }{ \max_j  \{ \alpha_j^* f( \bs w;  \bs \theta_j^* )  \} }  \le   \frac{ \{  f( \bs w;  \bs \theta_{h} )  \}^2 }{ \sum_{j=1}^{M_0} \alpha_j^* f( \bs w;  \bs \theta_j^* ) }  \le   \frac{ \{  f( \bs w;  \bs \theta_{h} )  \}^2 }{ \max_j  \{ \alpha_j^* f( \bs w; \bs \theta_j^* )  \} }. \]

Without loss of generality, we assume that $\sigma_{M_0}^* = \max \{ \sigma_1^*,\ldots, \sigma_{M_0}^* \}$ and that the maximum is unique.
We focus on models without covariates because the law of iterated expectations implies that the stated result also holds for models with covariates if it holds for models without covariates.

We first prove the case for the component-specific density function $f(\boldsymbol{w};\boldsymbol{\theta})=\prod_{t=1}^Tf(y_t;\bs\theta)$, where $f(y_t;\bs\theta)$ is given by (\ref{eq:f1}) or  (\ref{eq:f1-mixture}) with $\bs\beta_j=\bs 0$.  Under the normal density function (\ref{eq:f1}) without covariates, there exists a sufficiently large but finite positive constant $B$, such that $\max_j \{ \alpha_j^* f (\bs w,  \mu_j^*,  \sigma_j^2) \} = \alpha_{M_0}^* f (\bs w,   \mu_{M_0}^*,  \sigma_{M_0}^2)$ when $| y_t| > B$ for all $t = 1,\ldots, T$.
Note that
\begin{equation}\label{bound}
\begin{split}
\frac{ \{  f( \bs w;  \mu_{h},  \sigma_{h} )  \}^2 }{ f( \bs w;  \mu_{M_0}^*,   \sigma_{M_0}^* )  } & = \prod_{t=1}^T \frac{ \sigma_{M_0}^{*} }{(2 \pi )^{1/2} \sigma_h^2 } \exp \left\{ -\frac{1}{\sigma_h^2} (y_t - \mu_h)^2 + \frac{1}{2 (\sigma_{M_0}^{*})^2 } (y_t - \mu_{M_0}^{*})^2 \right\} \\
& = \left(\frac{\sigma_{M_0}^* }{(2 \pi )^{1/2} \sigma_h^2 } \right)^T\exp \left\{ -  \frac{1}{\sigma_h^2}\sum_{t=1}^T( y_t - \mu_h)^2 + \frac{1}{2 (\sigma_{M_0}^{*})^2} \sum_{t=1}^T(y_t - \mu_{M_0}^{*})^2 \right\}.
\end{split}
\end{equation}
Then, the integral of the right-hand side of (\ref{bound})  over $|y_t| \ge B$ for $t=1,...,T$ is infinite if  $\sigma_h^2/ \sigma_{M_0}^{2*} > 2$, and the stated result holds.

When  $f(y_t;\bs\theta)$ is given by normal mixture density (\ref{eq:f1-mixture}), suppose that $\mu_{j1}<\mu_{j2}< \cdots<\mu_{{\cal{K}}}$ for all $j=1,....,M_0$. Then, there exists a constant $B$ such that, when $y_t>B$  for all $t = 1,\ldots, T$, we have $\max_j \{ \alpha_j^* f (\bs w,  \bs\theta^*_j) \} = \alpha_{M_0}^* f (\bs w,\bs\theta^*_{M_0})$ and
\begin{equation}\label{bound-mixture-density}
\frac{1}{\sigma_j}\exp\left(-\frac{1}{2}\left(\frac{y_t-\mu_{{\cal{K}}}}{\sigma_j}\right)^2\right)\geq \sum_{k=1}^{{\cal{K}}}\tau_{jk}\frac{1}{\sigma_j}\exp\left(-\frac{1}{2}\left(\frac{y_t-\mu_{jk}}{\sigma_j}\right)^2\right)\geq \frac{1}{\sigma_j}\exp\left(-\frac{1}{2}\left(\frac{y_t-\mu_{j1}}{\sigma_j}\right)^2\right).
\end{equation}
Then, it follows that
\[
\frac{ \{  f( \bs w;  \bs\theta_{h} )  \}^2 }{ f( \bs w;  \bs\theta_{M_0}^* )   }  \geq  \left(\frac{\sigma_{M_0}^* }{(2 \pi )^{1/2} \sigma_h^2 } \right)^T\exp \left\{ -\frac{1}{\sigma_h^2}\sum_{t=1}^T (y_t - \mu_{1h})^2 + \frac{1}{2 (\sigma_{M_0}^{*})^2 } \sum_{t=1}^T(y_t - \mu_{M_0K}^{*})^2 \right\},
\]
where  the integral of the right-hand side  over $y_t>B$ for $t=1,...,T$  is infinite if  $\sigma_h^2/ \sigma_{M_0}^{2*} > 2$ as in (\ref{bound}).

Next, for dynamic panel models,  suppose that $f(\boldsymbol{w};\boldsymbol{\theta})=f_1(y_1;\bs\theta)\prod_{t=2}^Tf(y_t|y_{t-1};\bs\theta)$ with $f_1(y_1;\bs\theta)$ and $f(y_t|y_{t-1};\bs\theta)$ given in
(\ref{eq:f1-dynamic}) with $\bs\beta_{1,j}=\bs\beta_j=\bs 0$.  Fix the value of $\{y_t\}_{t=1}^{T-1}$. Then,
\begin{align*}
\frac{ \{  f( \bs w;  \bs\theta_{h} )  \}^2 }{ f( \bs w;  \bs\theta_{M_0}^* )   } &= \left(\frac{f_1(y_1;\bs\theta_h)^2\prod_{t=2}^{T-1}f(y_t|y_{t-1};\bs\theta_h)^2}{f_1(y_1;\bs\theta_{M_0}^*)\prod_{t=2}^{T-1}f(y_t|y_{t-1};\bs\theta_{M_0}^*)}\right) \\
&\quad \times \frac{\sigma_{M_0}^* }{(2 \pi )^{1/2} \sigma_h^2 }  \exp \left\{ -  \frac{1}{\sigma_h^2} ( y_T - \mu_h-\rho_h y_{T-1})^2 + \frac{1}{2 (\sigma_{M_0}^{*})^2} (y_T - \mu_{M_0}^{*}-\rho_{M_0}^{*} y_{T-1})^2 \right\},
\end{align*}
where the integral of the right-hand side of this equation over $|y_T| \ge B$  is infinite for a sufficiently large $B$ if  $\sigma_h^2/ \sigma_{M_0}^{2*} > 2$. Therefore, $E\left[\left.\frac{ \{  f( \bs W;  \bs\theta_{h} )  \}^2 }{ f( \bs W;  \bs\theta_{M_0}^* )   } \right|  \{Y_t\}_{t=1}^{T-1}=\{y_t\}_{t=1}^{T-1}  \right]=\infty$, and the stated result follows from the law of iterated expectations. The case for $f_1(y_1;\bs\theta)$ and $f(y_t|y_{t-1};\bs\theta)$ given in
(\ref{eq:f1-dynamic-mixture}) can be proven analogously, and hence we omit it.

%We show that $E\left[\left.\frac{ \{  f( \bs W;  \bs\theta_{h} )  \}^2 }{ f( \bs W;  \bs\theta_{M_0}^* )   } \right|  \{Y_t\}_{t=1}^{T-1}=\{y_t\}_{t=1}^{T-1}  \right]=\infty$ for all $\{y_t\}_{t=1}^{T-1}\in\mathcal{Y}^{T-1}$, where the expectation is taken with respect to $Y_T$.



\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:tm0_distribution}]

Collect the score vector for testing $H_{0,1h}$ for $h = 1,\ldots, M_0$ into one vector as
\begin{equation}
    \label{eq:s_tilde}
\tilde{\bs{s}}(\bs{W}) = \begin{pmatrix}
\tilde{\bs{s}}_{\bs{\eta}} (\bs{W})  \\
\tilde{\bs{s}}_{\bs{\lambda\lambda}} (\bs{W})
\end{pmatrix}, \ \text{ where } \underset{(M_0 +  p + q +1 ) \times 1}{\tilde{\bs{s}}_{\bs{\eta}}(\bs{W})}  = \begin{pmatrix}
\bs{s}_{\bs{\alpha}}(\bs{W})  \\
\bs{s}_{ (\bs{\nu} ) } (\bs{W})
\end{pmatrix}\quad \text{ and } \tilde{\bs{s}}_{\bs{\lambda\lambda}} (\bs{W}) = \begin{pmatrix}
\bs{s}^1_{\bs{\lambda\lambda}} (\bs{W}) \\
\vdots \\
\bs{s}^{M_0}_{\bs{\lambda\lambda}} (\bs{W})
\end{pmatrix},
\end{equation}
where
\begin{equation}
    % \label{eq:s_m0}
 \begin{split}
    \bs{s}_{\bs{\alpha}} (\bs{W}) & = \begin{pmatrix}
    f(\bs{W};\bs{\theta}^*_1) -    f(\bs{W};\bs{\theta}^*_{M_0}) \\
    \vdots \\
       f(\bs{W};\bs{\theta}^*_{M_0-1}) -    f(\bs{W};\bs{\theta}^*_{M_0})
    \end{pmatrix} \Bigg / f_{M_0}(\bs{W}; \bs{\vartheta}_{M_0}^*) ,  \\
    \bs{s}_{ \bs{\nu}  } (\bs{W})   & = \sum_{j=1}^{M_0} \alpha_j^*\frac{
    \nabla_{ \bs{\nu}  }  f(\bs{W};\bs{\theta}^*_{j})}{f_{M_0}(\bs{W}; \bs{\vartheta}_{M_0}^*)},\ \ \text{and}\ \   \bs{s}^h_{\bs{\lambda\lambda}} (\bs{W})   = \frac{\widetilde{ \nabla}_{\bs\theta_h\bs\theta_h\t}  f(\bs{W};\bs{\theta}^*_h) }{ f_{M_0}(\bs{W}; \bs{\vartheta}_{M_0}^*)}\quad\text{for $h=1,2,...,M_0$} ,
    \end{split}
\end{equation}
with
$\widetilde{ \nabla}_{\bs\theta_h \bs\theta\t_h}  f(\bs{W};\bs{\theta}^*_h)  := (c_{11} \nabla_{\theta_{h1}\theta_{h1}} f^*,...,c_{qq}\nabla_{\theta_{hq}\theta_{hq}} f^*,c_{12}\nabla_{\theta_{h1}\theta_{h2}} f^*,...,c_{(q-1)q}\nabla_{\theta_{hq-1}\theta_{hq}} f^*)\t$
for $\bs{\theta}_h:=(\theta_{h1},\theta_{h2},\theta_{h3},...,\theta_{hq})\t:=(\mu_h,\sigma_h^2,\beta_{h1},...,\beta_{hq-2})\t$ and  $c_{jk}=1/2$ for $j\neq k$ and $c_{jk}=1$ for $j=k$.
% = (1 / 2)\alpha_m^* \nabla_{\bs{\theta}^{\otimes 2}} (f(\bs{w};\bs{\theta}^*_{m}) /  f^*_0).
 Define \begin{equation}
  \label{eq:I_m0}
\begin{split}
    \tilde{\bs{\mathcal{I}}} := \E[\bs{\tilde{s}}(\bs{W}) \bs{\tilde{s}}(\bs{W})^\top], \quad  \tilde{\bs{\mathcal{I}}}_{\bs{\eta}} := \E[\bs{\tilde{s}}_{\bs{\eta}}(\bs{W})  \bs{\tilde{s}}_{\bs{\eta}}(\bs{W})^\top ], \quad \tilde{\bs{\mathcal{I}}}_{\bs{\lambda} \bs{\eta}} := \E[\bs{\tilde{s}}_{\bs{\lambda\lambda}}(\bs{W}) \bs{\tilde{s}}_{\bs{\eta}}(\bs{W})^\top ], \\
    \tilde{\bs{\mathcal{I}}}_{\bs{\eta} \bs{\lambda}}  := \tilde{\bs{\mathcal{I}}}_{\bs{\lambda} \bs{\eta}}^\top, \quad \tilde{\bs{\mathcal{I}}}_{\bs{\lambda\lambda}} := \E[\bs{\tilde{s}}_{\bs{\lambda\lambda}}(\bs{W}) \bs{\tilde{s}}_{\bs{\lambda\lambda}}(\bs{W})^\top ], \quad \tilde{\bs{\mathcal{I}}}_{\bs{\bs\lambda,\bs\eta}} := \tilde{\bs{\mathcal{I}}}_{\bs{\lambda \lambda}} - \tilde{\bs{\mathcal{I}}}_{\bs{\lambda \eta}} \tilde{\bs{\mathcal{I}}}_{\bs\eta}^{-1} \tilde{\bs{\mathcal{I}}}_{\bs{\eta \lambda}}.
\end{split}
\end{equation}
Then, the asymptotic distribution of the normalized score function is given by
\[
 \tilde{\bs S}_n: = \frac{1}{\sqrt{n}} \sum_{i=1}^n \tilde{\bs s}(\bs W_i) \overset{d}{\to} \tilde {\bs S} \sim N(\bs 0,   \tilde{\bs{\mathcal{I}}}),
\]
where, in view of (\ref{eq:s_tilde}),  $ \tilde {\bs S} $ may be partitioned as $ \tilde {\bs S} =( \tilde {\bs S}_{\bs\eta}\t, \tilde {\bs S}_{\bs\lambda\bs\lambda}\t)\t$ with $n^{-1/2} \sum_{i=1}^n \tilde{\bs s}_{\bs\eta}(\bs W_i)\overset{d}{\to} \tilde {\bs S}_{\bs\eta}$ and $n^{-1/2} \sum_{i=1}^n \tilde{\bs s}_{\bs\lambda\bs\lambda}(\bs W_i)\overset{d}{\to} \tilde {\bs S}_{\bs\lambda\bs\lambda}$ .


Let $\bs{\tilde{S}}_{\bs\lambda,\bs\eta} := (\bs{{S}}_{\bs\lambda,\bs\eta}^1, \ldots, \bs{{S}}_{\bs\lambda,\bs\eta}^{M_0} )^\top:= \bs{\tilde{S}}_{\bs\lambda\bs\lambda} -
\tilde{\bs{\mathcal{I}}}_{\bs\lambda\bs\eta} \tilde{\bs{\mathcal{I}}}_{\bs\eta} ^{-1} \bs{\tilde{S}}_{\bs\eta}
 \sim N(0,   \tilde{\bs{\mathcal{I}}}_{\bs\lambda,\bs\eta})$ be a $\R^{M_0 (q)(q+1)/2}$-valued random vector. For $h=1,2,...,M_0$,  define $\tilde{\bs{\mathcal{I}}}_{\bs\lambda,\bs\eta}^h := \E[\bs{{S}}_{\bs\lambda,\bs\eta}^h ( \bs{{S}}_{\bs\lambda,\bs\eta}^h)^\top]$ and $\bs{{G}}_{\bs\lambda,\bs\eta}^h := ({\bs{\mathcal{I}}}_{\bs\lambda,\bs\eta}^h)^{-1} \bs{{S}}_{\bs\lambda,\bs\eta}^h$.

%Let $\Theta_{\bs\alpha}(\epsilon) := \{ \bs\alpha \in \Theta_{\bs\alpha} : \alpha^1, \ldots ,\alpha^{M_0} \in [\epsilon,1-\epsilon] \}$, and define the LRT statistic for testing $H_{01}$ subject to $\alpha \in \Theta_{\alpha}(\epsilon)$ as $LR^{M_0}_{n}(\epsilon) : = \max_{\bs\psi \in \Theta_{\psi},\alpha \in \Theta_{\alpha}(\epsilon)} 2 \{  L_n(\bs{\psi},\tau) -  L_{0,n}(\hat{\bs{\vartheta}}_{M_0})\} $.
Define $\hat{\bs t}^h_{\bs\lambda}  $ analogously to $\hat{\bs t}_{\bs\lambda} $ as
\begin{equation}
     \label{eq:t_h}
\begin{split}
r^h_{\bs\lambda} (\hat{\bs{t}}^h_{\bs{\lambda}} ) = \inf_{{\bs{t}}^h_{\bs{\lambda}}\in \Lambda_{\bs\lambda}} r^h({\bs{t}}^h_{\bs{\lambda}}); \quad
r^h_{\bs\lambda} ({\bs{t}}^h_{\bs{\lambda}}) := ({\bs{t}}^h_{\bs{\lambda}} - \bs{{G}}^h_{\bs\lambda,\bs\eta} )^\top  {\bs{\mathcal{I}}}_{\bs\lambda,\bs\eta}^h({\bs{t}}^h_{\bs{\lambda}} - \bs{{G}}^h_{\bs\lambda,\bs\eta} )\quad\text{for $h=1,2,...,M_0$}.
\end{split}
\end{equation}

The local quadratic-form approximation of the log-likelihood function  $LR^{M_0,h}_n$ around $\Theta^*_{\bs\vartheta_{M_0+1},1h} \subset \Theta_{\vartheta_{M_0 + 1}}$  has an identical structure to the approximation that we derive in Section \ref{sec:LRT1} in testing $H_{01}$ in the test of homogeneity.  Consequently, we can show that $LR^{M_0,h}_n\overset{d}{\to} (\hat{\bs{t}}^h_{\bs\lambda})^\top \bs{\mathcal{I}}^h_{\bs\lambda,\bs\eta}  \hat{\bs{t}}^h_{\bs\lambda}$.  Then, given (\ref{eq:LR_M0_max}), the asymptotic null distribution of the LRTS for testing $H_{01}$ is given by the maximum over $(\hat{\bs{t}}^h_{\bs\lambda})^\top \bs{\mathcal{I}}^h_{\bs\lambda,\bs\eta}  \hat{\bs{t}}^h_{\bs\lambda}$s for $h=1,2,..., M_0$. We now proceed with the proof.

 For $h = 1,\ldots, M_0$,  let $\mathcal{N}_h^* \subset \Theta_{\bs{\vartheta}_{M_0 + 1}}(\bs c) $ be a sufficiently small closed neighborhood of $\Theta^*_{\bs\vartheta_{M_0+1},1h}$ such that $\alpha_h,\alpha_{h+1} > 0$ holds and $\Theta^*_{\bs\vartheta_{M_0+1},1k} \not\subset \mathcal{N}_h^*$ if $k \neq h$. Consider the following one-to-one reparameterization from the $(M_0 + 1)$-component model parameter $\bs{\vartheta}_{M_0 + 1} = (\alpha_1,\ldots,\alpha_{M_0},\bs{\theta}^\top_1,\ldots,\bs{\theta}^\top_h,\bs{\theta}^\top_{h+1},\ldots,\bs{\theta}^\top_{M_0 + 1})^\top$.
     Similar to (\ref{eq:m0_repar2}), the one-to-one reparameterization  for testing the null hypothesis $H_{0,1h}$ is given by
    \begin{equation*}
    \begin{pmatrix}
    \bs{\lambda}_h \\
    \bs{\nu}_h
    \end{pmatrix} := \begin{pmatrix}
    \bs{\theta}_{h} - \bs{\theta}_{h+1} \\
    \tau \bs{\theta}_{h} + (1 - \tau) \bs{\theta}_{h+1}
    \end{pmatrix} \text{ so that }
    \begin{pmatrix}
    \bs{\theta}_{h} \\
    \bs{\theta}_{h+1}
    \end{pmatrix} = \begin{pmatrix}
    \bs{\nu} + ( 1- \tau) \bs{\lambda} \\
    \bs{\nu} - \tau \bs{\lambda}
    \end{pmatrix},
    \end{equation*} and  $\alpha_j$ is reparameterized for $j=1,2,...,M_0$ as
    \begin{align*}
     (\pi_1,\ldots,\pi_{h-1},\pi_h,\pi_{h+1},\ldots , \pi_{M_0 - 1}) &= (\alpha_1,\ldots,\alpha_{h-1}, (\alpha_h + \alpha_{h+1}),\alpha_{h+2},\ldots,\alpha_{M_0})\\
 \tau  &=  {\alpha_h}/({\alpha_h + \alpha_{h+1}})
      \end{align*}
    so that $\pi_h  = \alpha_h + \alpha_{h+1}$ and  $\pi_{M_0} = 1 - \sum_{j=1}^{M_0 - 1} \pi_j$.

    Collect the reparameterized parameters except $\tau$ as
\begin{equation*}
  % \label{eq:m0_repar}
 \bs{\psi}_{h,\tau}  = (\bs\eta\t,\bs{\lambda}^\top_h)^\top\quad\text{with}\quad\bs \eta= (\pi_1,\ldots,\pi_{M_0-1},\bs{\theta}^\top_1,\ldots,\bs{\theta}^\top_{h-1},\bs{\nu}^\top_h,\bs{\theta}^\top_{h+2},\ldots, \bs{\theta}^\top_{M_0+1})^\top.
\end{equation*}
 In the reparameterized model, the null restriction $\bs{\theta}_h  = \bs{\theta}_{h+1}$ implied by $H_{0,1h}$ holds if and only if $\bs{\lambda}_h = 0$. Under $H_{0,1h}$, we have $\lambda_h^*=0$ and
 $\eta^*=(\alpha_1^*,...,\alpha_{M_0-1}^*, (\bs{\theta}^*_1)^\top,\ldots, (\bs{\theta}^*_{M_0})^\top)^\top$.
  Define the log-likelihood under the reparameterized parameters as
    \begin{equation*}
    f_{M_0+1}^{h}(\bs{w};\bs{\psi}_{h,\tau},\tau )  = \pi_h g^h(\bs{w},\bs{\psi}_{h,\tau}, \tau) +  \sum_{j=1}^{h-1} \pi_j f(\bs{w};\bs{\theta}_j) +  \sum_{j=h}^{M_0} \pi_{j+1} f(\bs{w};\bs{\theta}_{j+1}),
    \end{equation*}
    where $g^h(\bs{w},\bs{\psi}_{h,\tau}, \tau)$ is defined similarly to (\ref{eq:repar}) as
    \begin{equation}
      % \label{eq:g_repar_m}
    g^h(\bs{w},\bs{\psi}_{h,\tau}, \tau) = \tau f(\bs{w};\bs{\nu}_h + (1 - \tau) \bs{\lambda}_h) + (1 - \tau) f(\bs{w};\bs{\nu}_h - \tau \bs{\lambda}_h).
    \end{equation}


 Define the local  MLE of $\bs{\psi}_{h,\tau}$ by
 \begin{equation}\label{eq:psi_mle}
 \bs{\hat{\psi}}_{h,\tau} := \argmax_{\bs{\psi}_{h,\tau}  \in \mathcal{N}_h^*}  L^h_n(\bs{\psi}_{h,\tau}, \tau),
 \end{equation}
 where $L_n^h(\bs{\psi}_{h,\tau}, \tau) := \sum_{i=1}^N \log g^h(\bs{W}_i;\bs{\psi}_{h,\tau}, \tau) $.
 Because $\bs{\psi}_{h,\tau}^*$ is the only parameter value in $\mathcal{N}_h^*$ that generates the true density, $\bs{\hat{\psi}}_{h,\tau} - \bs{\psi}_{h,\tau}^* = o_p(1)$ follows. % Proposition \ref{prop:t2_distribution}.


Define the LRTS for testing $H_{0,1h}$ as $LR_{n}^{M_0,h}  := \max_{\tau \in [c_1,1-c_1]} 2 ( L_n^h(\hat{\bs{\psi}}_{h,\tau}, \tau)  - L_{0,n}( \hat{\bs{\vartheta}}_{M_0}))$. Then, in view of (\ref{eq:LR_M0_max}), the stated result holds if
 \begin{equation}
   \label{eq:joint_LR}
(LR_{n}^{M_0,1},\ldots,LR_{n}^{M_0,M_0})^\top \overset{d}{\to} (\hat{\bs{t}}^1_{\lambda})^\top \bs{\mathcal{I}}^1_{\eta,\lambda} (\hat{\bs{t}}^1_{\lambda}) ,   \ldots, (\hat{\bs{t}}^{M_0}_{\lambda})^\top \bs{\mathcal{I}}^{M_0}_{\eta,\lambda} (\hat{\bs{t}}^{M_0}_{\lambda}) )^\top.
\end{equation}
Observe that $L^h_n(\bs{\psi}_{h,\tau}, \tau)  -  L^h_n(\bs{\psi}^*_{h,\tau}, \tau) $ admits the same expansion as
 $L_n(\bs{\hat{\psi}},\alpha)  -   L_n(\bs{{\psi}}^*,\alpha)  $ in (\ref{eq:LR1}) and (\ref{eq:LR2}) when
  $(\alpha,\bs{t}(\bs{\psi}, \alpha), \bs{t}_{\bs\lambda}(\bs{\lambda}, \alpha), \bs S_n, \bs G_n, \bs{\mathcal{I}}_n,R_n(\bs\psi,\alpha))$ is replaced with  \\ $(\tau,\bs{t}^h(\bs{\psi}^h, \tau), \bs{t}_{\bs\lambda}^h(\bs{\lambda}^h, \tau),  \bs S_n^h, \bs G_n^h,\bs{\mathcal{I}}_n^h,R_n^h(\bs\psi^h,\tau))$, where $(\bs S_n^h, \bs{\mathcal{I}}_n^h)$ is defined similarly to $(\bs S_n, \bs{\mathcal{I}}_n)$ but
  $(\bs{s}_{\bs{\eta}},\bs{s}_{\bs{\lambda\lambda}})$ is replaced with $(\tilde{\bs{s}}_{\bs{\eta}}, {\bs{s}}^h_{\bs{\lambda\lambda}})$ and $\bs G_n^h := (\bs{\mathcal{I}}_n^h)^{-1} \bs S_n^h$.  Applying the proof of Lemma \ref{lemma:expansion}, we have ${\bs S}_n^h\overset{d}{\to} {\bs S}^h \sim N(\bs 0, \bs{\mathcal{I}}^h)$ and $\bs{\mathcal{I}}_n^h\overset{p}{\to} \bs{\mathcal{I}}^h$. Then, (\ref{eq:joint_LR}) follows from the proof of Lemma \ref{lemma:expansion} and Proposition \ref{prop:t2_distribution} for each local  MLE when $(\bs G_n, \hat{\bs t}_{\bs\lambda},\bs{\mathcal{I}}_{\bs\lambda,\bs\eta})$ is replaced with  $(\bs G_n^h, \hat{\bs t}_{\bs\lambda}^h,\bs{\mathcal{I}}_{\bs\lambda,\bs\eta}^h)$ and the results are collected; note that $(\bs S_n^1,...,\bs S_n^{M_0})\overset{d}{\to} (\bs S^1,...,\bs S^{M_0})$.
\end{proof}


\begin{proof}[Proof of Proposition \ref{prop:sht}]
We first prove that when $M<M_0$, $\Pr( LR_n^M> \hat c^M_{1-q_n})\rightarrow 1$ as $n\rightarrow \infty$. Under Assumption \ref{assumption:Q_M}, by the standard consistency proof \citep[e.g., Theorem 2.5 of][]{Newey1994} give $\hat{\bs{\vartheta}}_M\overset{p}{\rightarrow} \bs{\vartheta}_M^*$ for $M\leq M_0$. Furthermore,   it follows from the argument in Theorem 3.2 of \cite{white82em} that,  for $M\leq M_0$,
 \begin{equation}\label{eq:asynormal}
 \sqrt{n} (\hat{\bs{\vartheta}}_M- \bs{\vartheta}_M^*) \overset{p}{\rightarrow} N(0, A^M(\bs{\vartheta}_M^*)^{-1} B^M(\bs{\vartheta}_M^*)A^M(\bs{\vartheta}_M^*)^{-1}).
 \end{equation}

Then, from  (\ref{eq:asynormal}) and the mean value expansion,  we have $Q_n^M(\hat{\bs{\vartheta}}_M)- Q^M({\bs{\vartheta}}_M^*) = O_p(n^{-1/2})$ and
\begin{align*}
\frac{ LR_n^M}{n} &:= 2\left( Q_n^{M+1}(\hat{\bs{\vartheta}}_{M+1}) -  Q_n^M(\hat{\bs{\vartheta}}_M) \right)= 2\left(Q^{M+1}({\bs{\vartheta}}_{M+1}^*) -Q^M({\bs{\vartheta}}_M^*)\right)  + o_p(1)
\end{align*}
for $M=1,2,...,M_0-1$.

Because $Q^{M+1}({\bs{\vartheta}}_{M+1}^*) -Q^M({\bs{\vartheta}}_M^*)>0$ by Assumption \ref{assumption:Q_M}(f), ${LR_n^M}/{n}\rightarrow \infty$ as $n\rightarrow \infty$. By Lemma \ref{lemma: sht}, $- n^{-1} \log q_n=o(1)$ and $\hat c^M_{1-q_n}-c^M_{1-q_n}=o_p(1)$ implies that $n^{-1} \hat c^M_{1-q_n}=o_p(1)$. Therefore,  when $M<M_0$,
we have $\Pr(  LR_n^M>\hat  c^M_{1-q_n})=\Pr(  LR_n^M/n>\hat c^M_{1-q_n}/n) \rightarrow 1$ as $n\rightarrow \infty$.


When $M=M_0$, because $  LR_n^{M_0} =O_p(1)$ by Proposition \ref{prop:tm0_distribution} and $\hat c^{M}_{1-q_n}\rightarrow\infty$ by $q_n=o(1)$, $ \Pr(   LR_n^{M_0} >\hat c^{M_0}_{1-q_n}) \rightarrow 0$ as $n\rightarrow \infty$.
 \end{proof}

\begin{proof}[Proof of Proposition \ref{proposition:bic}] %The proof follows the proof of Theorem 2.1 of Keribin (2000).

We first prove that $\lim_{n\rightarrow \infty} \Pr(\widehat{M}_{PL}<M_0)=0$.  To show \(\Pr(\hat{M}_{PL} < M_0) \to 0\), it suffices to prove that for each \(M<M_0\),
\[
\Pr\bigl(p\ell_n^M > p\ell_n^{M_0} \bigr) \;\to\; 0.
\]
By definition,
\begin{equation}\label{eq:W}
\frac{p\ell_n^M-p\ell_n^{M_0}}{n} = ( Q_n^M(\hat{\bs{\vartheta}}_{M}) - Q_n^{M_0}(\hat{\bs{\vartheta}}_{M_0}) )- \frac{ p_{n,k_M}- p_{n,k_{M_0}}}{n}.
\end{equation}
From $p_{n,k} = o(n)$ in Assumption \ref{assumption: penalty}(c),
\begin{equation}
 \frac{ p_{n,k_M}- p_{n,k_{M_0}}}{n} \rightarrow 0. \label{eq:conv_p}
 \end{equation}

By the union bound and the triangle inequality, for any $\epsilon > 0$,
\begin{align*}
\Pr\Bigl(&\left| Q_n^M(\hat{\boldsymbol\vartheta}_{M}) - Q_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0}) - \Bigl(Q^{M}({\boldsymbol\vartheta}_{M}^*) - Q^{M_0}({\boldsymbol\vartheta}_{M_0}^*)\Bigr)\right| > 4\epsilon\Bigr)
\end{align*}
is at most
\begin{align}
&\Pr\Bigl(\left|Q^M(\hat{\boldsymbol\vartheta}_{M}) - Q^{M}({\boldsymbol\vartheta}_{M}^*)\right| > \epsilon\Bigr)
+ \Pr\Bigl(\left|Q^{M_0}(\hat{\boldsymbol\vartheta}_{M_0}) - Q^{M_0}({\boldsymbol\vartheta}_{M_0}^*)\right| > \epsilon\Bigr) \label{eq:bound-1}\\[1mm]
&\quad +\, \Pr\Bigl(\left|Q_n^M(\hat{\boldsymbol\vartheta}_{M}) - Q^{M}(\hat{\boldsymbol\vartheta}_{M})\right| > \epsilon\Bigr)
+ \Pr\Bigl(\left|Q_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0}) - Q^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})\right| > \epsilon\Bigr). \label{eq:bound-2}
\end{align}

The consistency of $\hat{\boldsymbol\vartheta}_{M}$ and $\hat{\boldsymbol\vartheta}_{M_0}$, together with the Continuous Mapping Theorem, implies that the two terms in \eqref{eq:bound-1} converge to $0$ as $n\rightarrow \infty$.

For small $\delta>0$, let $B(\delta,\boldsymbol\vartheta_M^*)$ and $B(\delta,\boldsymbol\vartheta_{M_0}^*)$ be open balls in the parameter spaces $\Theta_{\boldsymbol\vartheta_M}$ and $\Theta_{\boldsymbol\vartheta_{M_0}}$, respectively. Since $\hat{\boldsymbol\vartheta}_{M}$ and $\hat{\boldsymbol\vartheta}_{M_0}$ are consistent, with probability approaching one, the two terms in \eqref{eq:bound-2} are bounded by
\[
\Pr\Bigl(\sup_{\boldsymbol\vartheta_M\in B(\delta,\boldsymbol\vartheta_M^*)}
\left|Q_n^M(\boldsymbol\vartheta_M) - Q^M(\boldsymbol\vartheta_M)\right| > \epsilon\Bigr)
\quad\text{and}\quad
\Pr\Bigl(\sup_{\boldsymbol\vartheta_{M_0}\in B(\delta,\boldsymbol\vartheta_{M_0}^*)}
\left|Q_n^{M_0}(\boldsymbol\vartheta_{M_0}) - Q^{M_0}(\boldsymbol\vartheta_{M_0})\right| > \epsilon\Bigr).
\]
By applying Lemma 2.4 of \cite{Newey1994} under Assumption \ref{assumption:Q_M}(b), and noting that $\log g_M(\bs w;\bs\vartheta_M)$ is continuous at each $\bs\vartheta_M$ and the envelope function $\sup_{\bs\vartheta_{M}\in B(\delta,\bs\vartheta_M^*)}|\log g_M(\bs w;\bs\vartheta_M)|$ has finite expectation for $M\leq M_0$, these two probabilities converge to 0 by the Uniform Law of Large Numbers. Thus, we obtain
\begin{equation}
Q_n^M(\hat{\boldsymbol\vartheta}_{M}) - Q_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})
\overset{p}{\longrightarrow} Q^M(\theta_M^*) - Q^{M_0}(\theta_{M_0}^*). \label{eq:conv_q}
\end{equation}

Therefore, from \eqref{eq:W}, \eqref{eq:conv_p}, and \eqref{eq:conv_q}, and in view of Assumptions \ref{assumption:Q_M}(f) and \ref{assumption: penalty}(c), we have
\[
\frac{p\ell_n^M - p\ell_n^{M_0}}{n}
\overset{p}{\longrightarrow}
Q^M(\theta_M^*) - Q^{M_0}(\theta_{M_0}^*)
< 0.
\]
Hence, $\Pr(p\ell_n^M > p\ell_n^{M_0}) \to 0$ for $M<M_0$, which proves that
\begin{equation}\label{eq:underestimate}
\lim_{n\rightarrow \infty} \Pr(\hat{M}_{PL} < M_0) = 0.
\end{equation}


We proceed to prove that $\lim_{n\rightarrow \infty} \Pr(\widehat{M}_{PL}>M_0)=0$ by showing that, for $M=M_0+1,...,\bar M$,
\[
\Pr(p\ell_n^M > p\ell_n^{M_0} )\rightarrow 0\quad\text{as $n\rightarrow \infty$}.
\]
By definition of $p\ell_n^M$, we have
\[
\Pr( p\ell_n^M > p\ell_n^{M_0} ) = \Pr\left(
\frac{ \ell_n^M(\hat{\boldsymbol\vartheta}_{M}) - \ell_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})}{p_{n,M_0}}
+1- \frac{p_{n,k_M}}{p_{n,k_{M_0}}}>0\right).
\]
   For any $\epsilon>0$, $\lim_{n\rightarrow \infty} \Pr\left(
\frac{ \ell_n^M(\hat{\boldsymbol\vartheta}_{M}) - \ell_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})}{p_{n,M_0}}
> \epsilon\right)=0$ because $p_{n,M_0}\rightarrow \infty$  and $\ell_n^M(\hat{\boldsymbol\vartheta}_{M}) - \ell_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})=O_p(1)$ by  Assumptions \ref{assumption: penalty}(b) and   \ref{assumption:bound}, respectively. Therefore,
\[
\frac{ \ell_n^M(\hat{\boldsymbol\vartheta}_{M}) - \ell_n^{M_0}(\hat{\boldsymbol\vartheta}_{M_0})}{p_{n,M_0}}+1
- \frac{p_{n,k_M}}{p_{n,k_{M_0}}}\overset{p}{\rightarrow} 1- \lim_{n\rightarrow\infty } \frac{p_{n,k_M}}{p_{n,k_{M_0}}},
\]
which is strictly negative by Assumption \ref{assumption: penalty}(d). Thus, $\Pr(p\ell_n^M > p\ell_n^{M_0} )\rightarrow 0\quad\text{as $n\rightarrow \infty$}$, and $\lim_{n\rightarrow \infty} \Pr(\widehat{M}_{PL}>M_0)=0$ follows.


\end{proof}


 \begin{proof}[Proof of Proposition \ref{prop:bound}]
Because \( \ell_n^{M_0}(\hat{\bs\vartheta}_{M_0}) - \ell_n^{M_0}({\bs{\vartheta}}_{M_0}^*) = O_p(1) \) under standard regularity conditions in Assumption \ref{assumption:Q_M}, Assumption \ref{assumption:bound} holds when \( \ell_{n}^{M}(\hat{\bs\vartheta}_{M}) - \ell_n^{M_0}({\bs{\vartheta}}_{M_0}^*) = O_p(1) \) in view of $\ell_{n}^M(\hat{\bs\vartheta}_{M})-\ell_n^{M_0}(\hat{\bs\vartheta}_{M_0})= ( \ell_{n}^{M}(\hat{\bs\vartheta}_{M}) - \ell_n^{M_0}({\bs{\vartheta}}_{M_0}^*) )-(\ell_n^{M_0}(\hat{\bs\vartheta}_{M_0}) - \ell_n^{M_0}({\bs{\vartheta}}_{M_0}^*) )$.
Because a consistent MLE is in $ A_{\varepsilon_n}(\eta)$ defined in Appendix \ref{app:bic}, Propositions \ref{prop:consistency} and \ref{Ln_thm2} imply that $\ell_n(\hat{\bs\psi}_{M}^j,\bs\tau^j)-\ell_n(\bs\psi_{M}^{j*},\bs\tau^j)  =O_p(1)$, and the stated result holds.
 \end{proof}



\begin{proof}[Proof of Corollary \ref{cor:bic}]
It is straightforward to verify that the penalty function $p_{n,k}=\frac{k}{2}\log(n)$ satisfies Assumption \ref{assumption: penalty}. Thus, result (a) directly follows from Proposition \ref{prop:bound}.
For (b), Assumption \ref{assumption: penalty}(c) holds for AIC penalty. Then, repeating  the argument in the proof of Proposition \ref{proposition:bic} up to (\ref{eq:underestimate}) proves that $ p\ell^{M_0}_n(\hat{\bs{\vartheta}}_{M_0}) >\max\left\{p\ell_n^{1}(\widehat{\bs{\vartheta}}_{1}),...,p\ell_n^{M_0-1}(\widehat{\bs{\vartheta}}_{M_0-1})\right\}$ holds with probability approaching one as $n\rightarrow\infty$. This implies that
\begin{align}
\lim_{n\rightarrow\infty} \Pr\left(\widehat{M}_{PL}>M_0\right) & \geq \lim_{n\rightarrow\infty}\Pr\left( p\ell^{M_0+1}_n(\hat{\bs{\vartheta}}_{M_0+1}) >\max\left\{p\ell_n^{1}(\widehat{\bs{\vartheta}}_{1}),...,p\ell_n^{M_0}(\widehat{\bs{\vartheta}}_{M_0})\right\}\right)\nonumber\\
&=  \lim_{n\rightarrow\infty}\Pr\left( p\ell^{M_0+1}_n(\hat{\bs{\vartheta}}_{M_0+1}) > p\ell_n^{M_0}(\widehat{\bs{\vartheta}}_{M_0}) \right)\nonumber\\
&=\lim_{n\rightarrow\infty}\Pr\left(2\left[ \ell^{M_0+1}_n(\hat{\bs{\vartheta}}_{M_0+1}) - \ell_n^{M_0}(\widehat{\bs{\vartheta}}_{M_0})\right] > 2(k_{M_0+1}-k_{M_0})\right),
\label{eq:cor-bic}
\end{align}
where
 $k_{M_0}$ and $k_{M_0+1}$ are the number of parameters for $M_0$ and $(M_0+1)$ components model.   Since the term $2\left[\ell^{M_0+1}_n(\hat{\bs{\vartheta}}_{M_0+1}) - \ell_n^{M_0}(\widehat{\bs{\vartheta}}_{M_0})\right]$ is $O_p(1)$ and converges in distribution as specified in Proposition \ref{prop:tm0_distribution}, and because $k_{M_0}$ and $k_{M_0+1}$ are finite, it follows  from (\ref{eq:cor-bic}) that
$\lim_{n \to \infty} \Pr\left(\widehat{M}_{PL}>M_0\right) > 0,$
and part (b) follows.
\end{proof}


 \begin{proof}[Proof of Proposition \ref{prop:h02}]
The part  (a) can be proven similar to Proposition \ref{prop:consistency}, and thus omitted.

The proof for part (b) closely follows Theorem 2(b) in \citet{andrews01em}. For each $\bs\lambda \in \Theta_{\bs\lambda}(c_1)$, we approximate the log-likelihood function $\ell_n^2(\bs\theta_2, \bs\lambda, \alpha)$ around the true parameter values $(\bs\theta^*, 0)$ using the partial derivative with respect to $\bs\theta_2$ and the right partial derivative with respect to $\alpha$ to obtain
\begin{align}
2\{\ell_n^2(\bs\theta_2, \bs\lambda, \alpha)&- \ell_n^2(\bs\theta^*, \bs\lambda,0)\} =   \bs G_n(\bs\lambda)\t \bs{\mathcal{I}}_n(\bs\lambda) \bs G_n(\bs\lambda)\nonumber\\
& -  \left[ \sqrt{n}\bs{t}(\bs\theta_2,\alpha)- \bs G_n(\bs\lambda)\right]\t \bs{\mathcal{I}}_n  \left[ \sqrt{n}\bs{t}(\bs\theta_2,\alpha)- \bs G_n(\bs\lambda)\right] + R_n(\bs\theta_2, \bs\lambda, \alpha),\label{LR22}
\end{align}
where $R_n(\bs\theta_2, \bs\lambda, \alpha)$ is a remainder term, and $\bs {\mathcal{I}}_n(\bs\lambda)$, $ \bs G_n(\bs\lambda)$, and $\bs{t}(\bs\theta_2,\alpha)$ are defined as
\begin{align*}
\bs {\mathcal{I}}_n(\bs\lambda):=n^{-1} \sum_{i=1}^n {\bs s}(\bs W_i;\bs\lambda){\bs s}(\bs W_i;\bs\lambda)\t,\
\bs G_n(\bs\lambda):=\bs{\mathcal{I}}_n(\bs\lambda)^{-1}\bs  S_n(\bs\lambda),\ \text{and}\
\bs{t}(\bs\theta_2,\alpha) :=
\begin{pmatrix}
\bs\theta_2-\bs\theta^*\\
\alpha
\end{pmatrix}
\end{align*}
with   $\bs S_n(\bs\lambda)=n^{-1/2}\sum_{i=1}^n {\bs s}(\bs W_i;\bs\lambda)$ and ${\bs s}(\bs W_i;\bs\lambda)$ defined in (\ref{eq:s_1}).  $(\theta,\pi)$ and $(B_T,D \ell_T(\theta_0,\pi),\mathcal{J}_{T \pi},Z_{T \pi})$ in \citet{andrews01em} correspond to our $((\bs\theta_2\t,\alpha)\t,\bs\lambda)$ and $(n^{1/2},n^{1/2}\bs S_n(\bs\lambda),\bs{\mathcal{I}}_n(\bs\lambda),\bs G_n(\bs\lambda))$.

We prove the stated result by applying Theorem 2(b) of \citet{andrews01em} to (\ref{LR22}). $(\beta,\delta,\pi)$ and $(B_T,G_\pi,\mathcal{J}_\pi,Z_\pi,Z_{\beta\pi})$ in \citet[pp.\ 697-699]{andrews01em} correspond to our $(\alpha,\bs\theta_2,\bs\lambda)$ and $(n^{1/2},\bs S(\bs\lambda),\bs{\mathcal{I}}( \bs\lambda),\bs G( \bs\lambda), \bs{G}_{\alpha,\bs\theta_2}(\bs\lambda))$,  where $\bs G( \bs\lambda):=\bs{\mathcal{I}}( \bs\lambda)^{-1}\bs S( \bs\lambda)$, $\bs G_{\alpha,\bs\theta_1}( \bs\lambda):=\bs{\mathcal{I}}_{\alpha,\bs\theta_2}( \bs\lambda)^{-1}\bs S_{\alpha,\bs\theta_2}( \bs\lambda)$, and $\psi$ in \citet[pp.\ 697-699]{andrews01em} does not exist in our setting. The stated result then follows because $\bs s_{\bs\theta_2}(\bs w)$ is identical to the score of the one-component model and $\hat  { \lambda}_{\beta \pi}'(H \mathcal{J}_{*\pi}^{-1}H')^{-1}\hat{ \lambda}_{\beta \pi}$ in Theorem 2(b) of \citet{andrews01em} is distributed as $(\max\{0,\bs{\mathcal{I}}_{\alpha.\bs\theta_2}( \bs\lambda)^{-1/2} \bs S_{\alpha.\bs\theta_2}( \bs\lambda)\})^2$. We proceed to verify the assumptions of Theorem 2(b) of \citet{andrews01em} (hereafter, A-Assumptions $2^{2^*}$, 3-5, 7, and 8). A-Assumption $2^{2^*}$(a)(b) follow from our Assumption \ref{assumption:h02}(a)(b). A-Assumption $2^{2^*}$(c) holds because our Assumption \ref{assumption:h02}(c)(d) and the uniform law of large numbers imply that $\sup_{ \bs\lambda\in\Theta_{ \bs\lambda}(c_1)}|| \bs{\mathcal{I}}_n( \bs\lambda) - \bs{\mathcal{I}}( \bs\lambda)|| \rightarrow_p 0$ and $\bs{\mathcal{I}}( \bs\lambda)$ is continuous.

A-Assumption 3 follows from Theorem 10.2 of \citet{pollard90book} if (i) $\widetilde\Theta_{\bs\lambda}$ is totally bounded, (ii) the finite dimensional distributions of $\bs G_n(\cdot)$ converge to those of $\bs G(\cdot)$, and (iii) $\{\bs G_n(\cdot): n\geq 1\}$ is stochastically equicontinuous. Condition (i) follows from the compactness of $\widetilde\Theta_{\bs\lambda}$ while conditions (ii) follows from Assumption \ref{assumption:h02}(b)(c) and the multivariate CLT. Condition (iii) can be verified by our Assumption \ref{assumption:h02}(b)(c) and Theorem 2 of \citet{andrews94hdbk} because $\nabla_{(\bs\theta_2\t,\alpha)\t} \log g_2(\cdot; \bs\theta_2,\bs\lambda,\alpha)$ are Lipschitz functions indexed by a finite dimensional parameter $\bs\lambda$ by Assumption  \ref{assumption:h02}(b).

A-Assumption 4 follows from Lemma 1 of \citet{andrews01em} because, for each $ \bs\lambda\in \widetilde\Theta_{ \bs\lambda}(c_1)$, $(\tilde{\bs\theta}_2( \bs\lambda),\tilde \alpha( \bs\lambda))= \arg\max_{(\bs\theta_2,\alpha)\in\Theta_{\bs\theta_2}\times[0,1/2]} \ell_n^2(\bs\theta_2, \bs\lambda, \alpha)$ converges to $(\bs\theta_2^*,0)$ in probability from the standard consistency proof. A-Assumption 5 holds because (i) the set $[0,1]$ equals a nonnegative half-line locally around $0$, and (ii) $\Theta_{\bs\theta_2}-\bs\theta_2^*$ is locally equal to ${\mathbb{R}}^{\text{dim}(\bs\theta_2)}$. A-Assumption 7(a) is not relevant for our problem. A-Assumptions 7(b) and 8 follow from our proof of A-Assumption 5.   %$\square$

\end{proof}


\begin{proof}[Proof of Proposition \ref{Ln_thm1}]
For  notational brevity, we drop the superscript $j$ from $\bs\psi_M^j$, $\bs\tau^j$, $\bs s_i^j$ and  $\bs{\mathcal{I}}^j$.
 By using the Taylor expansion of $2 \log(1+x) = 2x - x^2(1+o(1))$ for small $x$, we have uniformly $\bs\psi_M  \in \mathcal{N}_{c/\sqrt{n}}$,
\begin{equation}\label{ell_appn}
\ell_n(\bs\psi_M,\bs\tau) - \ell_n(\bs\psi_M^*,\bs\tau) = 2 \sum_{k=1}^n \log(1+h_{\bs\psi_M\bs\tau,i}) = n P_n(2h_{\bs\psi_M\bs\tau,i} - [1+o_p(1)] h_{\bs\psi_M\bs\tau,i}^2),
\end{equation}
where $h_{\bs\psi_M\bs\tau,i} := \sqrt{l_{\bs\psi_M\bs\tau,i}}-1$.
The stated result holds if we show that
\begin{align}
&  \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} \left| nP_n(h_{\bs\psi_M\bs\tau,i}^2) - n \bs t^{\top}_{\bs\psi_M\bs\tau} \bs{\mathcal{I}} \bs t_{\bs\psi_M\bs\tau}/4 \right| = o_p(1)\quad\text{and}\label{hk_appn}\\
& \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} | nP_n(h_{\bs\psi_M\bs\tau,i}) - \sqrt{n} \bs t^{\top}_{\bs\psi_M\bs\tau} \nu_n(\bs s_i)/2 + n\bs t_{\bs\psi_M\bs\tau} \bs{\mathcal{I}} \bs t^{\top}_{\bs\psi_M\bs\tau}/8 | = o_p(1),\label{hk_appn2}
\end{align}
because then the right-hand side of (\ref{ell_appn}) is equal to $\sqrt{n} \bs t^{\top}_{\bs\psi_M\bs\tau} \nu_n (\bs s_i) - \bs t_{\bs\psi_M\bs\tau} \bs{\mathcal{I}} \bs t^{\top}_{\bs\psi_M\bs\tau}/2 + o_p(1)$ uniformly in   $ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}$.

We first show (\ref{hk_appn}). Let \[
m_{ \bs\psi_M \bs\tau i} :=l_{\bs\psi_M\bs\tau,i} -1= \bs t^{\top}_{\bs\psi_M\bs\tau} \bs s_i +  r_{ \bs\psi_M \bs\tau,i}. \] Observe that
\begin{equation} \label{B2}
\max_{1\leq i \leq n} \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} |m_{ \bs\psi_M \bs\tau i}| = \max_{1\leq i \leq n} \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} |\bs t^{\top}_{\bs\psi_M\bs\tau} \bs s_i +  r_{ \bs\psi_M \bs\tau,i}| = o_p(1),
\end{equation}
from Assumptions \ref{assumption:BIC}(a) and (c) and Lemma \ref{max_bound}. Write $4P_n ( h_{\bs\psi_M\bs\tau,i}^2)$ as
\begin{equation}\label{B0}
4P_n ( h_{\bs\psi_M\bs\tau,i}^2) = P_n \left(\frac{4(l_{\bs\psi_M\bs\tau,i}-1)^2}{(\sqrt{l_{\bs\psi_M\bs\tau,i}} + 1)^2}\right) = P_n(l_{\bs\psi_M\bs\tau,i}-1)^2 - P_n \left( (l_{\bs\psi_M\bs\tau,i}-1)^3 \frac{(\sqrt{l_{\bs\psi_M\bs\tau,i}}+3)}{(\sqrt{l_{\bs\psi_M\bs\tau,i}} + 1)^3}\right).
\end{equation}
From (\ref{density-ratio}),
\begin{equation} \label{lk_lln}
\begin{aligned}
P_n(l_{\bs\psi_M\bs\tau,i}-1)^2 %&= \bs t^{\top}_{\bs\psi_M\bs\tau}P_n(\bs s_i\bs s_i')\bs t_{\bs\psi_M\bs\tau} + 2 \bs t^{\top}_{\bs\psi_M\bs\tau} P_n[\bs s_i  r_{ \bs\psi_M \bs\tau,i}  ] + P_n( r_{ \bs\psi_M \bs\tau,i}  )^2 \\
&= \bs t^{\top}_{\bs\psi_M\bs\tau}P_n(\bs s_i\bs s_i')\bs t_{\bs\psi_M\bs\tau} +   \zeta_{ \bs\psi_M \bs\tau n  },
\end{aligned}
\end{equation}
where $ \zeta_{ \bs\psi_M \bs\tau n  }:=2 \bs t^{\top}_{\bs\psi_M\bs\tau} P_n[\bs s_i  r_{ \bs\psi_M \bs\tau,i}  ] + P_n( r_{ \bs\psi_M \bs\tau,i}  )^2$. It follows from Assumptions \ref{assumption:BIC}(a)(b)(c) and $(E|XY|)^2 \leq E|X|^2E|Y|^2$ that, uniformly in $ \bs\psi_M \in \mathcal{N}_\varepsilon$,
\begin{equation}\label{zeta}
 |  \zeta_{ \bs\psi_M \bs\tau n  }|=O_p(||\bs t_{\bs\psi_M\bs\tau}||^2||\bs\psi_M-\bs\psi_M^*||)+O_p(n^{-1}||\bs t_{\bs\psi_M\bs\tau}||||\bs\psi_M-\bs\psi_M^*||) + O_p(n^{-1}||\bs\psi_M-\bs\psi_M^*||^2).
 \end{equation} Then, (\ref{hk_appn}) holds because $ || P_n(\bs s_i\bs s_i') - \bs{\mathcal{I}}|| = o_p(1)$ and the second term on the right-hand side of (\ref{B0}) is bounded by
\begin{align*}
& \mathcal{C}  \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} P_n \left[ |m_{ \bs\psi_M \bs\tau i}|^3   \right]    \leq o_p(1)  \sup_{ \bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}} P_n \left[ m_{ \bs\psi_M \bs\tau i}^2  \right]  = o_p(n^{-1}),
\end{align*}
from $\sup_{\bs\psi_M \in \mathcal{N}_{c/\sqrt{n}}}\frac{(\sqrt{l_{\bs\psi_M\bs\tau,i}}+3)}{(\sqrt{l_{\bs\psi_M\bs\tau,i}} + 1)^3}\leq  \mathcal{C}$,  (\ref{B2}), and  $P_n( m_{ \bs\psi_M \bs\tau i}^2) = \bs t^{\top}_{\bs\psi_M\bs\tau}\bs{\mathcal{I}} \bs t_{\bs\psi_M\bs\tau} + o_p(||\bs t_{\bs\psi_M\bs\tau}||^2)$.

We proceed to show (\ref{hk_appn2}). Consider the following expansion of $h_{\bs\psi_M\bs\tau,i}$:
\begin{equation} \label{hk_1}
h_{\bs\psi_M\bs\tau,i} = (l_{\bs\psi_M\bs\tau,i}-1)/2 - h_{\bs\psi_M\bs\tau,i}^2/2 = (\bs t^{\top}_{\bs\psi_M\bs\tau} \bs s_i +  r_{ \bs\psi_M \bs\tau,i} )/2 - h_{\bs\psi_M\bs\tau,i}^2/2.
\end{equation}
Then, (\ref{hk_appn2}) follows from (\ref{hk_appn}), (\ref{hk_1}), and Assumptions \ref{assumption:BIC}(d), and the stated result follows.
\end{proof}





\begin{proof}[Proof of Proposition \ref{Ln_thm2}]
For  brevity, we drop the superscript $M$ from $\bs s_i^M$ and  $\bs{\mathcal{I}}^M$.
Define $h_{\bs\psi_M\bs\alpha,i} := \sqrt{l_{\bs\psi_M\bs\alpha,i}}-1$.
For part (a), it follows from $\log(1+x) \leq x$ and $h_{\bs\psi_M\bs\alpha,i} = (l_{\bs\psi_M\bs\alpha,i}-1)/2 - h_{\bs\psi_M\bs\alpha,i}^2/2$ (see (\ref{hk_1})) that
\begin{equation} \label{Ln_ineq}
\ell_n(\bs\psi_M,\bs\alpha)-\ell_n(\bs\psi_M^*,\bs\alpha) = 2 \sum_{k=1}^n \log(1+h_{\bs\psi_M\bs\alpha,i}) \leq 2 n P_n(h_{\bs\psi_M\bs\alpha,i}) = \sqrt{n} \nu_n(l_{\bs\psi_M\bs\alpha,i}-1) - n P_n(h_{\bs\psi_M\bs\alpha,i}^2).
\end{equation}
Observe that $h_{\bs\psi_M\bs\alpha,i}^2 =(l_{\bs\psi_M\bs\alpha,i}-1)^2/(\sqrt{l_{\bs\psi_M\bs\alpha,i}} + 1)^2 \geq \mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} \leq \kappa \} (l_{\bs\psi_M\bs\alpha,i}-1)^2/ (\sqrt{\kappa}+1)^2$ for any $\kappa>0$. Therefore, \begin{equation}\label{pn_lower}
P_n (h_{\bs\psi_M\bs\alpha,i}^2)\geq (\sqrt{\kappa}+1)^{-2}P_n \left( \mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} \leq \kappa\} (l_{\bs\psi_M\bs\alpha,i}-1)^2\right).
\end{equation}
In view of (\ref{lk_lln}), (\ref{pn_lower}) is rewritten as
\begin{align} \label{pn_lower_2}
P_n (h_{\bs\psi_M\bs\alpha,i}^2)& \geq (\sqrt{\kappa}+1)^{-2} \left\{\bs t^{\top}_{\bs\psi_M\bs\alpha} \left[ P_n(\bs s_{i}\bs s_{i}') - P_n(\mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\}\bs s_{i}\bs s_{i}') \right] \bs t_{\bs\psi_M\bs\alpha} + \tilde \zeta_{ \bs\psi_M \bs\alpha n  }\right\},
\end{align}
where $\tilde \zeta_{ \bs\psi_M \bs\alpha n  }$ satisfies the bound similar to  (\ref{zeta}).
From H\"older's inequality, we have $P_n(\mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\}||\bs s_{i}||^2 ) \leq [P_n(\mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\} )]^{\delta/(2+\delta)} [ P_n(||\bs s_{i}||^{2+\delta}) ]^{2/(2+\delta)}$, where the right-hand side is no larger than $\kappa^{-\delta/(2+\delta)} O_p(1)$ uniformly in  $\bs\psi_M \in \mathcal{N}_{\varepsilon_n}$ because (i) it follows from $\kappa \mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\} \leq l_{\bs\psi_M\bs\alpha,i}$ that $P_n(\mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\} ) \leq \kappa^{-1} P_n(l_{\bs\psi_M\bs\alpha,i})$ and $  \sup_{ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}}|P_n(l_{\bs\psi_M\bs\alpha,i})-1| = o_p(1)$ from Assumptions \ref{assumption:BIC}(d)(e), and (ii) $P_n( ||\bs s_{i}||^{2+\delta})=O_p(1)$ from Assumption \ref{assumption:BIC}(a). Consequently, $\mathbb{P}(   \sup_{ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}}P_n(\mathbb{I}\{l_{\bs\psi_M\bs\alpha,i} > \kappa\}||\bs s_{i}||^2 ) \geq \lambda_{\min}/4 ) \to 0$ as $\kappa \to \infty$, where $\lambda_{\min}$ is  the smallest eigenvalue of $\bs{\mathcal{I}}$. Hence,  we can write (\ref{pn_lower_2}) as $P_n (h_{\bs\psi_M\bs\alpha,i}^2) \geq \frac{\tau}{2} (1+o_p(1)) \bs t^{\top}_{\bs\psi_M\bs\alpha} \bs{\mathcal{I}} \bs t_{\bs\psi_M\bs\alpha} + \frac{\tau}{2}  \tilde\zeta_{ \bs\psi_M \bs\alpha n  }$ for $\tau:=2(\sqrt{\kappa}+1)^{-2}>0$ by taking $\kappa$ sufficiently large. Because $\sqrt{n} \nu_n(l_{\bs\psi_M\bs\alpha,i}-1) = \sqrt{n} \bs t^{\top}_{\bs\psi_M\bs\alpha}\nu_n (\bs s_{i}) + O_p(\sqrt{n}||{\bs t}_{\bs\psi_M\bs\alpha}||||\bs\psi_M-\bs\psi_M^*||)$ from Assumptions \ref{assumption:BIC}(d) and because $\tilde \zeta_{ \bs\psi_M \bs\alpha n  }$ satisfies the bound analogous to (\ref{zeta}), it follows from (\ref{Ln_ineq}) that, uniformly in $ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}$,
\begin{align}
-\eta & \leq \ell_n(\bs\psi_M,\bs\alpha)-\ell_n(\bs\psi_M^*,\bs\alpha) \nonumber\\
&\leq  \sqrt{n} \bs t^{\top}_{\bs\psi_M\bs\alpha} \nu_n (\bs s_{i}) - \frac{\tau}{2} (1+o_p(1)) n \bs t^{\top}_{\bs\psi_M\bs\alpha} \bs{\mathcal{I}} \bs t_{\bs\psi_M\bs\alpha} + O_p(\sqrt{n}||{\bs t}_{\bs\psi_M\bs\alpha}||||\bs\psi_M-\bs\psi_M^*||) \nonumber\\
&\quad +O_p(n||\bs t_{\bs\psi_M\bs\alpha}||^2||\bs\psi_M-\bs\psi_M^*||)+O_p(||\bs t_{\bs\psi_M\bs\alpha}||||\bs\psi_M-\bs\psi_M^*||) + O_p(||\bs\psi_M-\bs\psi_M^*||^2).\label{rk_lower2}
\end{align}
Let $\bs T_n:= \bs{\mathcal{I}}^{1/2}\sqrt{n} \bs t_{\bs\psi_M\bs\alpha}$. From (\ref{rk_lower2}), Assumptions \ref{assumption:BIC}(b) and (e), and the fact $||\bs\psi_M-\bs\psi_M^*|| \to 0$ if $\bs t_{\bs\psi_M\bs\alpha} \to 0$, we obtain
\[
-\eta \leq \ell_n(\bs\psi_M,\bs\alpha)-\ell_n(\bs\psi_M^*,\bs\alpha) \leq
||\bs T_n|| O_p(1)-\frac{\tau}{2}||T_n||^2+o_p(||T_n||^2)+o_p(||T_n||) +o_p(1),
\]
uniformly in $ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}$. By  rearranging the inequality  and choosing a sufficiently large constant $C$, we have $ ||\bs T_n|| C - (\tau/2) ||\bs T_n||^2 + C  \geq 0$ with an arbitrarily high probability. Namely,  for any $\delta>0$, there exist $C$, $n_0<\infty$ such that
\begin{equation}
\mathbb{P}\left( \inf_{ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}} | |\bs T_n|| C - (\tau/2) ||\bs T_n||^2 + C  \geq 0 \right) \geq 1-\delta,\ \text{ for all }\ n > n_0.
\end{equation}
Rearranging the terms inside $\mathbb{P}(\cdot)$ gives $  \sup_{ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}} (||\bs T_n||-(C/\tau))^2 \leq 2B/\tau+(C/\tau)^2$. Taking its square root gives $\mathbb{P}(  \sup_{ \bs\psi_M \in \mathcal{N}_{\varepsilon_n}}||\bs T_n|| \leq C_1) \geq 1-\delta$ for a constant $C_1$, and part (a) follows. Part (b) follows from part (a) and Proposition \ref{Ln_thm1}.
\end{proof}



