\begin{lemma}\label{lemma:unbounded_likelihood}
For any $M<\infty$, $ \Pr\left( -\log n + \ell(\bs W_{i^*};\bar Y_{i^*},s_{i^*}^2) < M\right) =\exp(-C_T n^{1/T})$  as $n\rightarrow \infty$, where $C_T$ for $T=2,3,..$ are some positive constant that depends on $M$ and $T$.\end{lemma}
\begin{proof}[Proof of Lemma \ref{lemma:unbounded_likelihood}]
Because $\sum_{t=1}^T \frac{\left(Y_{it}-\mu \right)^2}{s_{i^*}^2}= T-1$ when $i=i^*$, we have
\begin{align}
-\log n+\ell(\bs W_{i^*};\bar Y_{i^*},s_{i^*}^2)
&= -\log n - \frac{T}{2} \log s_{i^*}^2 -\frac{T}{2}\log(2\pi) - \frac{T-1}{2} \nonumber\\
&=-\log\left( B n  \left(\chi_{i^*,T-1}^2 \right)^{T/2} \right)
% \label{bound}
\end{align}
with  $B:=\left(\frac{2\pi\sigma^{*2}}{T-1}\right)^{T/2}\exp(\frac{T-1}{2})>0$ and
\[
\chi_{i^*,T-1}^2 := \frac{(T-1)s_{i^*}^2}{\sigma^{*2}}.
\]



Therefore, to prove the stated result, it suffices to show that for any $\epsilon=\exp(-M)/B>0$, $\Pr\left(n \left(\chi_{i^*,T-1}^2\right)^{T/2} >\epsilon\right)=\Pr\left(\chi_{i^*,T-1}^2 >\left({\epsilon}/{n}\right)^{2/T}\right)\rightarrow 0$ as $n\rightarrow\infty$. Given the property of the first-order statistic, the distribution  function of $\chi_{i^*,T-1}^2$ is given by $1-[1-F_{{T-1}}(t)]^n$, where $F_{{k}}(t)$ is the cumulative distribution function for chi-squared variables with  $k$ degree of freedom. It follows that
