\begin{lemma}\label{lemma:bic}
For any $M<\infty$, $ \Pr\left( -4\log n + \ell(\bs W_{i^*};\bar Y_{i^*},s_{i^*}^2) < M\right) \rightarrow 1$ as $n\rightarrow \infty$.

\end{lemma}

 \begin{proof}
Following the proof of Lemma \ref{lemma:unbounded_likelihood}, because $-4\log n+\ell(\bs W_{i^*};\bar Y_{i^*},s_{i^*}^2) =-\log\left( B n^4  \left(\chi_{i^*,T-1}^2 \right)^{T/2} \right)$, it suffices to show that, for any $\epsilon>0$, $\Pr\left(\chi_{i^*,T-1}^2 >\left({\epsilon}/{n^4}\right)^{2/T}\right)=\Big[1-F_{{T-1}}\big( (\epsilon/n^4)^{2/T} \big) \Big]^n\rightarrow 1$ as $n\rightarrow\infty$. For any finite $T\geq 2$,    write
\begin{equation}\label{eq-lemma-bic}
\Big[1-F_{{T-1}}\big( (\epsilon/n^4)^{2/T} \big) \Big]^n =  \Big\{ \Big[1-F_{{T-1}}\big( (\epsilon/n^4)^{2/T} \big) \Big]^{\frac{1}{  F_{{T-1}}( (\epsilon/n^4)^{2/ T} )} }\Big\}^{ n F_{{T-1}}( (\epsilon/n^4)^{2/T} )  }.
\end{equation}
Then, because  $(1 - F)^{\frac{1}{F}} \to \frac{1}{e}$ when $ F \to 0 $, the stated result follows from (\ref{eq-lemma-bic}) if we can show  $\frac{  F_{{T-1}}( (\epsilon x^4)^{2/T} )}{x} \to 0\text{ as }  x \to 0$ for $x=1/n$. By applying L'Hôpital's rule, we have
\[\begin{split}
\lim_{x \to 0} \frac{  F_{{T-1}}( (\epsilon x^4 )^{2/T} )}{x } = \lim_{x \to 0}  f_{T-1}( (\epsilon x^4 )^{2/T} ) \epsilon^{2/T} (8/T) x^{8/T-1}
= \lim_{x \to 0} \tilde C_{T,\epsilon} e^{- ((\epsilon x^4 )^{2/T} )/2} x^{ 3-\frac{4}{T}} =0,
\end{split}\]
where $\tilde C_{T,\epsilon} = \frac{\epsilon^{(T-1)/T}(8/T)}{2^{(T-1)/2} \Gamma((T-1)/2)} $ because $e^{- ((\epsilon x^4 )^{2/T} )/2}\to 1$  and $x^{ 3-\frac{4}{T}} \to 0$ as $x \to 0$ for any finite $T\geq 2$.
 \end{proof}


\begin{lemma}\label{lemma:expansion}
Suppose that Assumptions  \ref{assumption:K}, \ref{assumption:consistency}, and \ref{assumption:LRT1} hold. Then, under $H_0: M=1$, for $\alpha\in [c_1,1-c_1]$, (a) for any $\delta>0$, $\lim\sup_{n\rightarrow \infty} \Pr(\sup_{\bs\psi \in \Theta_{\bs\psi}: ||\bs\psi-\bs\psi^*||\leq \kappa} |R_n(\bs\psi,\alpha)| > \delta (1+||n\bs t(\bs\psi,\alpha)||^2)) \rightarrow 0$ as $\kappa\rightarrow 0$, (b) $ \bs S_n \overset{d}{\to} \bs S\sim N(0,\bs{\mathcal{I}})$, and (c) $\bs{\mathcal{I}}_n \overset{p}{\to} \bs{\mathcal{I}}$, where $\bs{\mathcal{I}}$ is finite and non-singular, and (d) $\bs t(\hat{\bs{\psi}}_\alpha,\alpha)=O_p(n^{-1/2})$ for any $\alpha\in [c_1,1-c_1]$.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lemma:expansion}]
The proof follows that of Proposition 2 in \cite{Kasahara2012}.
For a vector $\bs{x}$ and a function $f(\bs{x})$, let $\nabla_{\bs{x}^k}f(\bs{x})$ denote its $k$-th derivative with respect to $\bs{x}$, which can be a multidimensional array. Observe that for any finite $k$ and for a neighborhood $\mathcal{N}$ of $\bs{\psi}^*$, we obtain
\begin{equation}
\begin{aligned}
&E|| \nabla_{\bs{\psi}^k} g(\bs{W}_i;\bs{\psi}^*,\alpha)/ g(\bs{W}_i;\bs{\psi}^*,\alpha)||^2<\infty, \\
&E||\sup_{\bs{\psi}\in\Theta_{\bs{\psi}} \cap \mathcal{N}}\nabla_{\bs{\psi}^k} \log g(\bs{W}_i;\bs{\psi},\alpha)||^2<\infty
\end{aligned} \label{nabla_0}
\end{equation}
because each element of $\nabla_{\bs{\psi}^k} \log g(y|\bs{x},\bs{z};\bs{\psi},\alpha)$ is written as a sum of products of Hermite polynomials.
 Note also that  the following holds:
\begin{align}
& \nabla_{\eta \lambda_j }L_n(\bs\psi^*,\alpha)=0, \quad \nabla_{\lambda_i \lambda_j\lambda_k } L_n(\bs\psi^*,\alpha)=O_p(n^{1/2}), \label{nabla_1} \\
& \nabla_{\eta\eta \lambda_i }L_n(\bs\psi^*,\alpha) =O_p(n), \quad \nabla_{\eta\eta\eta}L_n(\bs\psi^*,\alpha)=O_p(n), \label{nabla_2}
\end{align}
where equation (\ref{nabla_1}) follows from Proposition \ref{lemma:KS2018_lemma7}{(a) and (c)} and (\ref{nabla_0}) and equation (\ref{nabla_2}) is a simple consequence of (\ref{nabla_0}).
Furthermore, for a neighborhood $\mathcal{N}$ of $\bs\psi^*$,
\begin{align}
& \sup_{\bs\psi\in\Theta_{\bs\psi} \cap \mathcal{N}} \left| n^{-1}\nabla^{(4)} L_n(\bs\psi ,\alpha)- E\nabla^{(4)}  \log g(\bs W_i;\bs\psi ,\alpha) \right| = o_p(1), \label{nabla_3}\\
& E\nabla^{(4)} g(\bs W_i;\bs\psi,\alpha) \text{ is continuous in }\psi  {\in \Theta_{\bs\psi} \cap \mathcal{N}}. \label{nabla_4}
\end{align}
  Equations (\ref{nabla_3}) and (\ref{nabla_4})
follow  from Lemma 2.4 of \cite{Newey1994} and the fact that $\nabla_{\bs{\psi}^k} \log g(\bs{w};\bs{\psi},\alpha)$ is written as a sum of products of Hermite polynomials.

Taking a fourth-order Taylor expansion of $L_n(\bs{\psi},\alpha)$ around $\bs{\psi}^*$ and using (\ref{nabla_0}) and (\ref{nabla_1}), we can write $L_n(\bs{\psi},{\alpha}) -L_n(\bs{\psi}^*,\alpha)$ as the sum of the relevant terms and the remainder term as follows:
\begin{align}
\lefteqn{ L_n(\bs{\psi},{\alpha}) -L_n(\bs{\psi}^*,\alpha) = } \nonumber\\
& \quad \nabla_{\bs{\eta}}L_n^* (\bs{\eta} - \bs{\eta}^*) + \frac{1}{2!} (\bs{\eta} - \bs{\eta}^*)^{\top}\nabla_{\bs{\eta} \bs{\eta}^{\top}}L_n^*(\bs{\eta} - \bs{\eta}^*) +\frac{1}{2!}  \sum_{i=1}^{q}\sum_{j=1}^{q} \nabla_{\lambda_i\lambda_j }L_n^*\lambda_i\lambda_j \label{LR0-score0} \\
&\quad + \frac{3}{3!} \sum_{i=1}^{q} \sum_{j=1}^{q} (\bs{\eta} - \bs{\eta}^*)\t\nabla_{\bs\eta \lambda_i\lambda_j} L_n^* \lambda_i\lambda_j    \label{LR0-hessian0} \\
 &\quad + \frac{1}{4!}  \sum_{i=1}^{q}\sum_{j=1}^{q}\sum_{k=1}^{q} \sum_{\ell=1}^{q} \nabla_{\lambda_i\lambda_j\lambda_k\lambda_\ell}L_n^*\lambda_i\lambda_j\lambda_k\lambda_\ell + R_{n}(\bs{\psi},\alpha), \label{LR0-hessian1}   \end{align}
where $\nabla L_n^*$ denotes the derivative of $L_n(\bs{\psi},\alpha)$ evaluated at $(\bs{\psi}^*,\alpha)$. In view of (\ref{nabla_1}) and (\ref{nabla_2}), the remainder term is written as
\begin{align}
\lefteqn{ R_n(\bs\psi,\alpha) =  O_p(n^{1/2}) \sum_{i=1}^{q}\sum_{j=1}^{q}\sum_{k=1}^{q} \lambda_i\lambda_j \lambda_k + O_p(n) \left(  \sum_{i=1}^{q} ||\bs{\eta}-\bs{\eta}^*||^2 \lambda_i +  ||\bs{\eta}-\bs{\eta}^*||^3 \right)} \label{Rn_2} \\
& +O_p(n)\sum_{i=1}^{q}\sum_{j=1}^{q}\sum_{k=1}^{q}\left( ||\bs{\eta}-\bs{\eta}^*||^4 + ||\bs{\eta}-\bs{\eta}^*||^3 |\lambda_i|+ ||\bs{\eta}-\bs{\eta}^*||^2 |\lambda_i \lambda_j| + ||\bs{\eta}-\bs{\eta}^*|| |\lambda_i \lambda_j \lambda_k| \right) \qquad \label{Rn_3} \\
& + \frac{1}{4!}  \sum_{i=1}^{q}\sum_{j=1}^{q}\sum_{k=1}^{q}\sum_{\ell=1}^{q}  \{\nabla_{\lambda_i \lambda_j \lambda_k \lambda_\ell} L_n(\bs{\psi}^\dag,\alpha) - \nabla_{\lambda_i \lambda_j \lambda_k \lambda_\ell} L_n(\bs{\psi}^*,\alpha) \} \lambda_i \lambda_j \lambda_k \lambda_\ell
\label{Rn_4}
\end{align}
with $\bs{\psi}^\dag$ being between $\bs{\psi}$ and $\bs{\psi}^*$. Because $||\sqrt{n}t(\bs{\psi},\alpha)||^2 = n||\bs{\eta} - \bs{\eta}^*||^2 + n \sum_{i=1}^{q}\sum_{j=1}^i \alpha^2(1-\alpha)^2 |\lambda_i\lambda_j|^2$, the right-hand side of (\ref{Rn_2}) and the terms in (\ref{Rn_3}) are bounded by $O_p(1)(||\sqrt{n}t(\bs{\psi},\alpha)||+||\sqrt{n}t(\bs{\psi},\alpha)||^2)(||\bs{\eta}-\bs\eta^*||+||\lambda||)$. In view of (\ref{nabla_3}) and (\ref{nabla_4}), (\ref{Rn_4}) is bounded by  $||\sqrt{n}t(\bs{\psi},\alpha)||^2[d(\bs{\psi}^\dagger)+o_p(1)]$ with $d(\bs{\psi}^\dagger)\rightarrow 0$ as $\bs{\psi}^\dagger \rightarrow \bs{\psi}^*$, where a function $d(\bs{\psi}^\dagger)$ corresponds to $n^{-1}\E[\nabla_{\lambda_i \lambda_j \lambda_k \lambda_\ell}L_n(\bs{\psi}^\dagger,\alpha) - \nabla_{\lambda_i \lambda_j \lambda_k \lambda_\ell}L_n(\bs{\psi}^*,\alpha)]$. Therefore, $R_n(\bs{\psi},\alpha)=(1+||\sqrt{n}t(\bs{\psi},\alpha)||)^2[d(\bs{\psi}^\dagger)+o_p(1)  + O_p(||\bs{\psi}-\bs{\psi}^*||)]$, and part (a) follows.

Part (b) follows from  Lemma \ref{lemma:KS2018_lemma7}(c) and (d), the Lindeberg--Levy central limit theorem, and the finiteness of $\bs{\mathcal{I}}$ in part (c).

For part (c), we first provide the formula of $\bs{\mathcal{I}}_n$. Partition $\bs{\mathcal{I}}_n$ as
\[
\bs{\mathcal{I}}_n = \left( \begin{array}{cc}
\bs{\mathcal{I}}_{\bs\eta n} & \bs{\mathcal{I}}_{\bs\eta\bs\lambda n}\\
\bs{\mathcal{I}}_{\bs\eta\bs\lambda n}\t & \bs{\mathcal{I}}_{\bs\lambda n}
\end{array}\right), \quad \bs{\mathcal{I}}_{\bs\eta n}: q\times q, \quad \bs{\mathcal{I}}_{\bs\eta\bs\lambda n}: q\times q_\lambda, \quad \bs{\mathcal{I}}_{\bs\lambda n}: q_\lambda \times q_\lambda,
\]
where $q_\lambda=q(q+1)/2$.
$\bs{\mathcal{I}}_{\bs\eta n}$ is given by $\bs{\mathcal{I}}_{\bs\eta n} = - n^{-1}\nabla_{\bs\eta\bs\eta\t}L_n(\psi^*,\alpha)$. For $\bs{\mathcal{I}}_{\bs\eta\bs\lambda n}$, let $A_{ij} = n^{-1}\nabla_{\bs\eta \lambda_i \lambda_j} L_n(\psi^*,\alpha)$  and write the  term in (\ref{LR0-hessian0})   as   $(n/2) \sum_{i=1}^{q} \sum_{j=1}^{q} (\bs\eta -\bs\eta^*)\t A_{ij} \lambda_i \lambda_j= n \sum_{i=1}^{q} \sum_{j=1}^i (\bs\eta -\bs\eta^*)\t A_{ij} c_{ij}  \lambda_i \lambda_j$, where $c_{ij}=1/2$ if $i=j$, and $c_{ij}=1$ if $i\neq j$. Then, by defining  $\bs{\mathcal{I}}_{\bs\eta\bs\lambda n} = -(A_{11}, \ldots,  A_{qq},  A_{12}, \ldots,  A_{q-1,q}) /\alpha(1-\alpha)$, the  term in (\ref{LR0-hessian0}) equals $- n(\bs\eta -\bs\eta^*)\t \bs{\mathcal{I}}_{\bs\eta\bs\lambda n}[\alpha(1-\alpha)v(\bs\lambda)]$. For $\bs{\mathcal{I}}_{\bs\lambda n}$, define $B_{ijk\ell} = n^{-1}(8/4!)\nabla_{\lambda_i \lambda_j\lambda_k \lambda_\ell} L_n(\bs\psi^*,\alpha)$ so that the first term in (\ref{LR0-hessian1}) is written as $(n/8)\sum_{i=1}^{q} \sum_{j=1}^{q} \sum_{k=1}^{q} \sum_{\ell=1}^{q} B_{ijk\ell} \lambda_i \lambda_j \lambda_k \lambda_\ell= (n/2) \sum_{i=1}^{q} \sum_{j=1}^i \sum_{k=1}^{q} \sum_{\ell=1}^k c_{ij}c_{k\ell}B_{ijk\ell}\lambda_i \lambda_j \lambda_k \lambda_\ell$. Define $\bs{\mathcal{I}}_{\bs\lambda n}$ such that the $(ij,k\ell)$ element of $\bs{\mathcal{I}}_{\bs\lambda n}$ is $-c_{ij}c_{k\ell} B_{ijk\ell}/\alpha^2(1-\alpha)^2$, where the values of $ij$ run over $\{(1,1),\ldots,(q,q),(1,2),\ldots,(q-1,q)\}$. Then,  the first term in (\ref{LR0-hessian1}) equals $-(n/2) [\alpha(1-\alpha)v(\bs\lambda)]'\bs{\mathcal{I}}_{\bs\lambda n}[\alpha(1-\alpha)v(\bs\lambda)]$. With this definition of $\bs{\mathcal{I}}_n$, the expansion (\ref{LR0-score0})-(\ref{LR0-hessian1}) is written as (\ref{eq:LR0}) in terms of $\sqrt{n}t(\psi,\alpha)$.

We now show that $\bs{\mathcal{I}}_n \rightarrow_p \bs{\mathcal{I}}$. $\bs{\mathcal{I}}_{\bs\eta n} \rightarrow_p \bs{\mathcal{I}}_{\eta}$ holds trivially. For $\bs{\mathcal{I}}_{\bs\eta\bs\lambda n}$, it follows from Lemma \ref{lemma:KS2018_lemma7}(c) and the law of large numbers that $A_{ij} \rightarrow_p -\E[\nabla_{\bs\eta} l(\bs W;\psi^*,\alpha) \nabla_{\lambda_i\lambda_j}l(\bs W;\psi^*,\alpha)]$, giving $\bs{\mathcal{I}}_{\bs\eta\bs\lambda n} \rightarrow_p E\left[\bs s_{\bs\eta} \bs s_{\bs\lambda\bs\lambda}\t/\alpha(1-\alpha)\right]=\bs{\mathcal{I}}_{\bs\eta \bs \lambda}$. For $\bs{\mathcal{I}}_{\bs\lambda n}$, Lemma \ref{lemma:KS2018_lemma7}(d) and the law of large numbers imply that  $\sum_{i=1}^{q} \sum_{j=1}^{q} \sum_{k=1}^{q} \sum_{\ell=1}^{q} B_{ijk\ell} \lambda_i \lambda_j \lambda_k \lambda_\ell \rightarrow_p \\ - \sum_{i=1}^{q} \sum_{j=1}^{q} \sum_{k=1}^{q} \sum_{\ell=1}^{q} E[\nabla_{\lambda_i \lambda_j}l(\bs W;\psi^*,\alpha)\nabla_{\lambda_k \lambda_\ell}l(\bs W;\psi^*,\alpha)]\lambda_i \lambda_j \lambda_k \lambda_\ell$, where the factor $(8/4!)=1/3$ in $B_{ijk\ell}$ and the three derivatives on the right-hand side of Lemma \ref{lemma:KS2018_lemma7}(d) cancel each other out. Therefore, we have  $\bs{\mathcal{I}}_{\bs\lambda n} \rightarrow_p E\left[\bs s_{\bs\lambda\bs\lambda}\bs s_{\bs\lambda\bs\lambda}\t  /\alpha^2(1-\alpha)^2\right]=\bs{\mathcal{I}}_{\bs\lambda}$, and $\bs{\mathcal{I}}_n \rightarrow_p \bs{\mathcal{I}}$ follows.


We complete the proof of part (c) by showing that $\bs{\mathcal{I}} = E[\bs{s}(\bs{W}) \bs{s}(\bs{W})\t]$ is finite and non-singular.
Note that $\bs s(\bs W) $ can be expressed in Hermite polynomials as in (\ref{eq:s_1_hermite}). Then, the finiteness of $\bs{\mathcal{I}}$ follows from  Assumption \ref{assumption:LRT1}(a) and the definition of Hermite polynomials.

To show that $\bs{\mathcal{I}}$ is positive definite, it suffices to show that there exists no multicollinearity in $\bs s(\bs w)$. Suppose, to the contrary, that $\bs {s}(\bs w)$ is multicollinear and that there exists a non-zero vector $\bs a$ that solves the  equation $\bs a\t \bs s(\bs w) = 0$ for all values of $\bs w $. Partition $ s(\bs w)$ as $\bs s(\bs w)=(\bs s_{(\mu)} \t, \bs s_{(\beta)}\t )\t$  with $\bs s_{(\mu)} = (s_{\mu},s_{\sigma},s_{\lambda_{\mu \mu }} ,s_{\lambda_{\mu \sigma }} ,s_{\lambda_{\sigma \sigma }})\t$  and $\bs s_{(\beta)} = (\bs s_{\bs\beta }\t, \bs s_{\lambda_{\mu\bs \beta }}\t,\bs s_{\lambda_{\sigma\bs \beta }}\t,\bs s_{\lambda_{\bs \beta \bs \beta }}\t)\t$,
where $\bs s(\bs w) $ is defined in (\ref{eq:s_1}) and  (\ref{eq:s_1_hermite}).
Similarly, partition $\bs a$ as $\bs a = (\bs a_{(\mu)}\t, \bs a_{(\beta)}\t )\t$ so that
\begin{equation}\label{eq:as}
\bs a\t \bs s(\bs w) = \bs a_{(\mu)}\t \bs s_{(\mu)} + \bs a_{(\beta)}\t \bs s_{(\beta)}.
\end{equation}
By Assumption \ref{assumption:LRT1}(b) and the property of Hermite polynomials, if $\bs a\t \bs s(\bs w) = \bs 0$ for all $\bs w$, then $\bs a_{(\beta)} = \bs 0$.

Then, in view of (\ref{eq:as}), the stated result follows if we can show that $\bs a_{(\mu)}\t  \bs s_{(\mu)} = \bs 0$ for all $\bs w$ implies $\bs a_{(\mu)}=0$.
Suppose that
\begin{align*}
	\bs a_{(\mu)}\t  \bs s_{(\mu)} & = a_{\mu } \sum_{t=1}^T  H^{1*}_{t} +  (a_{\sigma } + a_{\lambda_{\mu \mu }}) \sum_{t=1}^T  H^{2*}_{t} +    \frac{a_{\lambda_{\mu \mu }}}{2} \sum_{t=1}^T \sum_{s \neq t} H^{1*}_{t} H^{1*}_{ is}  \\
	& + a_{\lambda_{\mu \sigma }} \sum_{t=1}^T H^{3*}_{t} + a_{\lambda_{\mu \sigma }} \sum_{t=1}^T \sum_{s \neq t} H^{1*}_{t} H^{2*}_{ is} +
	3  a_{\lambda_{\sigma \sigma }}\sum_{t=1}^T H^{4*}_{t} +  \frac{a_{\lambda_{\sigma \sigma }}}{2} \sum_{t=1}^T \sum_{s \neq t} H^{2*}_{t} H^{2*}_{ is}  = 0
\end{align*}
for all $\bs w$,
where $H^{j*}_{t}$ for $j=1,2,3$ is defined in (\ref{eq:Hermite_polynomial})  in Appendix \ref{sec:appendix_score_1}.

Because the above equation holds for all values of $\bs w$, with the property of the Hermite polynomials, we have $a_{\mu } = 0, (a_{\sigma } + a_{\lambda_{\mu \mu }}) = 0, a_{\lambda_{\mu \mu }} = 0, a_{\lambda_{\mu \sigma }} = 0, a_{\lambda_{\sigma \sigma }} = 0$. This implies that $\bs a_{(\mu)}=0$.
Therefore,  no multicollinearity exists in $\bs s(\bs w)$ and $\bs{\mathcal{I}}$ is non-singular, proving part (c). %$\square$


The proof of part (d) closely follows the proof of Theorem 1 of \cite{Andrews1999}. Let $\boldsymbol{T}_{n}: = \boldsymbol{\mathcal{I}}_{n}^{1/2}\sqrt{n}\bs{t}(\hat{\bs\psi}_\alpha,\alpha)$. Then, in view of (\ref{eq:LR0}), we have
\begin{align*}
o_p(1)&\leq L_n(\hat{\boldsymbol{\psi}}_\alpha,\alpha) - L_n(\boldsymbol{\psi}^*,\alpha)\\
 &= \boldsymbol{T}_{n}' \boldsymbol{\mathcal{I}}_{n}^{-1/2} \boldsymbol{S}_{n} - \frac{1}{2} ||\boldsymbol{T}_{n}||^2 + R_n(\hat{\boldsymbol{\psi}}_\alpha,\alpha)\\
 &= O_p(||\boldsymbol{T}_{n}||) - \frac{1}{2} ||\boldsymbol{T}_{n}||^2 + (1 + || \boldsymbol{\mathcal{I}}_{n}^{-1/2} \boldsymbol{T}_{n}||)^2 o_p(1)\\
 &= ||\boldsymbol{T}_{n}||O_p(1) - \frac{1}{2} ||\boldsymbol{T}_{n}||^2 + o_p(||\boldsymbol{T}_{n}||) + o_p(||\boldsymbol{T}_{n}||^2) + o_p(1),
\end{align*}
where the third equality holds because $\boldsymbol{\mathcal{I}}_{n}^{-1/2} \boldsymbol{S}_{n} = O_p(1)$ and $R_n(\hat{\boldsymbol{\psi}}_\alpha,\alpha) = o_p((1 + ||\boldsymbol{\mathcal{I}}_{n}^{-1/2}\boldsymbol{T}_{n}||)^2)$ from Proposition \ref {lemma:expansion}. Rearranging this equation yields $||\boldsymbol{T}_n||^2 \leq 2 ||\boldsymbol{T}_n|| O_p(1)+o_p(1)$. Denote the $O_p(1)$ term by $\varsigma_{n}$. Then, $(||\boldsymbol{T}_{n}||-\varsigma_{n})^2\leq \varsigma_{n}^2 + o_p(1) = O_p(1)$; taking its square root gives $||\boldsymbol{T}_{n}|| \leq O_p(1)$. In conjunction with $\boldsymbol{\mathcal{I}}_{n} \rightarrow_p \boldsymbol{\mathcal{I}}$, we obtain $\sqrt{n}\bs{t}(\hat{\bs\psi}_\alpha,\alpha) = O_p(1)$, and part (d) follows.


\end{proof}



\begin{lemma}\label{lemma: sht}
Suppose that the assumptions in Proposition \ref{prop:sht} hold. If  $-n^{-1}\log q_n=o(1)$, then  $n^{-1} c^M_{1-q_n}=o(1)$.

\end{lemma}
\begin{proof}
For brevity of notation,
write $c_n=c^{M}_{1-q_n}$.
By Theorem 2.1 of \cite{Foutz77as}, $PLR_n(M)\overset{d}{\rightarrow} \sum_{j=1}^K b_j \chi_j^2$ for $0<b_j<\infty$ and $K$ is finite, where $\chi_1^2$, ..., $\chi_K^2$ are independent chi-square random variables with one degree of freedom.
Then, we have
\begin{align*}\label{eq:q_n}
q_n&= \Pr\left( \sum_{j=1}^K b_j \chi_j^2 \geq c_n\right)\leq \sum_{j=1}^K  \Pr\left(  \chi_j^2 \geq \frac{c_n}{ b_j}\right)\leq  \frac{K}{\sqrt{1-2t}}\exp\left(-t \frac{c_n}{ b^*}\right)\quad\text{for $0<t<\frac{1}{2}$}
\end{align*}
with $b^*=\arg\max\{b_1,...,b_K\}$, where the last inequality follows from a Chernoff bound: $\Pr\left(  \chi_j^2 \geq \frac{c_n}{ b^*}\right)\leq \frac{\E[\exp(t(\chi_j^2-1))]}{\exp(t(\frac{c_n}{ b^* }-1))}=\frac{1}{\sqrt{1-2t}}\exp\left(-t \frac{c_n}{ b^*}\right)$ for $0<t<\frac{1}{2}$. Therefore,
$-\frac{\log q_n}{n} \geq - \frac{1}{n}\log\left(\frac{K}{\sqrt{1-2t}}\right) +\frac{1}{2b_j^*} \frac{c_n}{n}$,
and the stated result follows.

\end{proof}




\begin{lemma}\label{lemma:KS2018_lemma7}
    Suppose that $g(\bs{w};\bs{\psi},\alpha)$ is defined as (\ref{eq:repar}), where $\bs{\psi} = (\bs{\eta}^\top,\bs{\lambda}^\top)^\top$. Let $g^*$, $\nabla g^*$, and $\nabla\log g^*$ denote $g(\bs{W};\bs{\psi},\alpha)$, $\nabla g(\bs{W};\bs{\psi},\alpha)$,  and $\nabla \log g(\bs{W};\bs{\psi},\alpha)$ evaluated at $(\bs{\psi}^*,\alpha)$, respectively. Let $\nabla f^*$ denote $\nabla f(\bs{W};\bs{\theta}^*)$.
    The following statements hold.
    \begin{enumerate}[label=(\alph*)]
        \item  For $l = 0,1,\ldots, \nabla_{ (\bs{\lambda} \otimes \bs{\eta}^{\otimes l})\t}g^* = 0$;
        \item $\nabla_{(\bs{\lambda}^{\otimes 2})\t } g^*  = \alpha (1 - \alpha) \nabla_{(\bs{\theta}^{\otimes 2})\t } f^*$;
\item $\nabla_{(\bs{\lambda}^{\otimes 2})\t } \log g^*  =  \alpha (1 - \alpha) \nabla_{(\bs{\theta}^{\otimes 2})\t } f^*/f^*$;
        \item $\E[\nabla_{\lambda_i\lambda_j}\log g^*]=0$, $\E[\nabla_{\lambda_i\lambda_j\lambda_k}\log g^*]=0$,
and  $\E[\nabla_{\eta\lambda_i\lambda_j }\log g^*]=-\E[\nabla_{\eta}\log g^*\nabla_{\lambda_i\lambda_j}\log g^*]$;
 \item $\E[\nabla_{\lambda_i\lambda_j\lambda_k\lambda_\ell}\log g^*]=
-\E[\nabla_{\lambda_i\lambda_j}\log g^*\nabla_{\lambda_k\lambda_\ell}\log g^*+\nabla_{\lambda_i\lambda_k}\log g^*\nabla_{\lambda_j\lambda_\ell}\log g^*+\nabla_{\lambda_i\lambda_\ell}\log g^*\nabla_{\lambda_j\lambda_k}\log g^*]$.    \end{enumerate}
\end{lemma}

