\begin{proof}[Proof of Lemma \ref{lemma:KS2018_lemma7}]
    Recall that $$g(\bs{w};\bs{\psi},\alpha)  = \alpha f(\bs{w};\bs{\nu}  + (1 - \alpha) \bs{\lambda}) + (1 - \alpha)  f(\bs{w};\bs{\nu} - \alpha \bs{\lambda}). $$
    First, we show that for $l=0$ holds for (a),
    $\nabla_{\bs{\lambda}} g^* = \alpha ( 1 - \alpha) \nabla_{\bs{\theta}} f^* -  \alpha  ( 1 - \alpha) \nabla_{\bs{\theta}} f^*  = 0 $.
    For $l > 0$, by Fubini's theorem, we have
    \[
    \begin{split}
    \nabla_{ (\bs{\lambda} \otimes \bs{\eta}^{\otimes l})\t} g & = \left. \nabla_{\bs{\lambda}}\Big( \alpha \nabla_{ (\bs{\eta}^{\otimes l})\t} f(\bs{w};\bs{\nu}  + (1 - \alpha)  \bs{\lambda}) + (1 - \alpha) \nabla_{ (\bs{\eta}^{\otimes l})\t}f(\bs{w};\bs{\nu} - \alpha \bs{\lambda}) \right|_{\bs{\nu} = \bs{\theta}^*, \bs{\lambda} = \bs{0} } \Big) \\
    & = \left. \Big( \alpha ( 1- \alpha)\nabla_{ (\bs{\lambda} \otimes\bs{\eta}^{\otimes l})\t}f(\bs{w};\bs{\nu}  + (1 - \alpha)  \bs{\lambda}) - \alpha (1 - \alpha) \nabla_{ (\bs{\lambda} \otimes\bs{\eta}^{\otimes l})\t}f(\bs{w};\bs{\nu} - \alpha \bs{\lambda}) \right|_{\bs{\nu} = \bs{\theta}^*, \bs{\lambda} = \bs{0} } \Big) \\
    & = 0.
    \end{split}
    \]
    To show part $(b)$, note that \begin{equation*}
    \begin{split}
    \nabla_{(\bs{\lambda}^{\otimes 2})\t } g & =  \nabla_{\bs{\lambda}} \Big( \alpha ( 1 - \alpha) \nabla_{\bs{\lambda}^\top } f(\bs{w};\bs{\nu}  - \alpha (1 - \alpha)  \bs{\lambda})
    -\alpha (1 - \alpha) \nabla_{\bs{\lambda}^\top} f(\bs{w};\bs{\nu} - \alpha \bs{\lambda}) \Big) \\
    & = \left.   \alpha ( 1 - \alpha)^2 \nabla_{(\bs{\lambda}^{\otimes 2})\t } f(\bs{w};\bs{\nu}  - (1 - \alpha)  \bs{\lambda})
    + \alpha^2(1 - \alpha) \nabla_{(\bs{\lambda}^{\otimes 2})\t } f(\bs{w};\bs{\nu} - \alpha \bs{\lambda}) \right|_{\bs{\nu} = \bs{\theta}^*, \bs{\lambda} = \bs{0} } \\
    & = \nabla_{(\bs{\lambda}^{\otimes 2})\t } f^*.
    \end{split}
    \end{equation*}

    For part (c),  $\nabla_{\bs{\lambda}\bs{\lambda} \t } \log g^*  =  \nabla_{\bs{\lambda}\bs{\lambda} \t } g^*/g^* -( \nabla_{\bs\lambda } \log g^* )( \nabla_{\bs\lambda } \log g^*)=\alpha(1-\alpha)\nabla_{\bs{\lambda}\bs{\lambda} \t } f^*/f^*$ because $\nabla_{\bs{\lambda}\bs{\lambda} \t } g^*/g^*=\alpha(1-\alpha)\nabla_{\bs{\theta}\bs{\theta} \t } f^*/f^*$  from part (a) and $ \nabla_{\bs\lambda } \log g^* =\nabla_{\bs\lambda } g^* /g^*=0$ from part (b).

 For  parts (d) and (e), observe that $\int  \nabla_{\lambda_i}  \log g(\bs w;\psi,\alpha)g(\bs w;\psi,\alpha)dx=0$ holds for any $\psi$ in the interior of $\Theta_\psi$, and differentiating this equation w.r.t.\ $\lambda_j$ gives
\begin{equation}
\int \{ \nabla_{\lambda_i\lambda_j} \log g(\bs w;\psi,\alpha)  +  \nabla_{\lambda_i} \log g(\bs w;\psi,\alpha)  \nabla_{\lambda_j} \log g(\bs w;\psi,\alpha) \} g(\bs w;\psi,\alpha) dx=0.\label{IME}
\end{equation}
Evaluating (\ref{IME}) at $\psi=\psi^*$ in conjunction with  part (a) gives the first equation in  part (d). Differentiating (\ref{IME}) w.r.t.\ $\lambda_k$ or $\eta$ and evaluating  at $\psi=\psi^*$ gives the latter two equations in part (d).  Part (e) follows from differentiating (\ref{IME}) w.r.t.\ $\lambda_k$ and $\lambda_\ell$ and evaluating at $\psi=\psi^*$ in conjunction with  parts (a) and (d).

\end{proof}

