\begin{lemma}\label{max_bound}[Lemma 2.1 of \cite{liushao03as}]
Suppose $X_1, \ldots, X_n$ are i.i.d. random variables with $\max_{1 \leq i \leq n} \mathbb{E}|X_i|^{q+\delta} < C$ for some $\delta>0$, $q > 0$,  and $C \in (0,\infty)$. Then, $\max_{1 \leq i \leq n} |X_i| = o_p(n^{1/q})$.
\end{lemma}

\begin{proof}
For any $\varepsilon > 0$, we have
\begin{align*}
P\left(\max_{1 \leq i \leq n} |X_i| > \varepsilon n^{1/q}\right) &\leq \sum_{1 \leq i \leq n} P(|X_i| > \varepsilon n^{1/q})\leq \varepsilon^{-q} \mathbb{E}(|X_1|^q\mathbb{I}{\{|X_1|>\varepsilon n^{1/q}\}})
\end{align*}
by a version of the Markov inequality and the i.i.d. assumption. As $n \to \infty$, the right-hand side tends to $0$ by the dominated convergence theorem.
\end{proof}



\subsection{Score function for testing $H_0:m = 1$ against $H_A:m=2$}\label{sec:appendix_score_1}
$H^j(\cdot)$ is defined as the $j$-th order Hermite polynomial. $H^1(t) = t$, $H^2(t) = t^2 - 1$ , $H^3(t) = t^3 - 3t$, and $H^4(t) = t^4 - 6t^2 + 3$.
As shown in the supplementary material of \cite{kasaharashimotsu15jasa}, the derivative of $\{ \frac{1}{\sigma} \phi(\frac{t}{\sigma}) \}$ is  $$\frac{\nabla_{\mu^m}\nabla_{ (\sigma^2)^{\ell}} \{ \frac{1}{\sigma} \phi(\frac{t}{\sigma}) \} }{\{ \frac{1}{\sigma} \phi(\frac{t}{\sigma}) \}}
 = \left(\frac{1}{2}\right)^\ell \left(\frac{1}{\sigma}\right)^{m+2\ell} H^{m+2\ell}\left(\frac{t}{\sigma}\right). $$
Let \( f^* = f(\bs{W}; \theta^*) = \prod_{t=1}^T f^*_t (\bs{W}; \theta^*) \), where \( f^*_t \) denotes the component density for observation \( t \), which may be either a normal or a mixture density. Let \( \nabla f^* = \nabla f(\bs{W}; \theta^*) \) denote its gradient.

Define the Hermite polynomials evaluated at \( Y_t - \bs{X}_t^\top \bs{\beta}^* - \mu^* \) as follows:
\begin{equation}\label{eq:Hermite_polynomial}
\begin{split}
  H^{j*}_{t} = \frac{1}{(\sigma^*)^j} H^{j}\left(\frac{Y_{t} - \bs{X}_{t}^\top \bs{\beta}^*  - \mu^*  }{\sigma^*} \right).
\end{split}
\end{equation}

\subsubsection{Score function for the model (\ref{eq:fm}) with normal density (\ref{eq:f1})}

Let
\(f^*_t = \frac{1}{\sigma^*} \phi\left( \frac{Y_{t} - \bs{X}_{t}^\top \bs{\beta}^*  - \mu^*  }{\sigma^*} \right) \).
Then, the first-order derivatives of the normal density function (\ref{eq:f1}) with respect to the parameters are given by:
\begin{align*}
  & \nabla_{\mu} f^*  =   f^* \sum_{t=1}^T H^{1*}_{t}, 
  & \nabla_{\sigma^2} f^*   =  f^*  \sum_{t=1}^T \frac{1}{2}  H^{2*}_{t}, \\
  & \nabla_{\bs{\beta}} f^*   =   f^*  \sum_{t=1}^T H^{1*}_{t} \bs{X}_{t}.
