\subsubsection{Score function for the model (\ref{eq:fm}) with normal mixture density (\ref{eq:f1-mixture}) when $K=2$}
For brevity, we present the score function for the model (\ref{eq:fm}) with a two-component normal mixture (\ref{eq:f1-mixture}) when there are no covariates. The score function for the model with covariates can be analogously derived. Let
\[
f^* = \prod_{t=1}^T f^*_t = \prod_{t=1}^T \left( \tau^* f^*_{1t} + (1 - \tau^*) f^*_{2t}  \right),
\]
where \( f^*_{kt} = \frac{1}{\sigma^*} \phi\left(\frac{Y_t  - \mu_k^*}{\sigma^*} \right) \) for $k = 1, 2$.
In this model, we omit the covariates \( \bs{X}_t \) and the parameter \( \bs{\beta}^* \) for simplicity. The score function with covariates can be derived similarly to the previous section.
Define the $b$-th order normalized Hermite polynomial for $k$-th component evaluated at \( Y_t - \mu_k^* \) as follows:
\begin{equation}
\begin{split}
  H^{b*}_{kt} = \frac{1}{(\sigma^*)^b} H^{b}\left(\frac{Y_{t} - \mu_k^*}{\sigma^*} \right).
\end{split}
\end{equation}
Let
\[
\begin{aligned}
\gamma_{1t}:= \frac{ \tau^* f_{1t}^* }{\tau^* f_{1t}^* + (1 - \tau^*) f_{2t}^*},\quad \gamma_{2t}:=1-\gamma_{1t}.
\end{aligned}
\]
The score function defined in (\ref{eq:s_1}) is then written as:
 \begin{equation}\label{eq:s_1_hermite-mixture}
\begin{split}
\bs s_{\bs \eta }(\bs W)  = \begin{pmatrix}
s_{\tau }\\
s_{\mu_1 } \\
s_{\mu_2 } \\
s_{\sigma }
%\\ \bs s_{\bs\beta } %\\
%\bs s_{\bs \gamma }
\end{pmatrix}= \begin{pmatrix}
 \sum_{t=1}^T \left( \frac{ \gamma_{1t} }{ \tau^* } - \frac{ \gamma_{2t} }{ 1 - \tau^* } \right) \\
 \sum_{t=1}^T \gamma_{1t} H^{1*}_{1t} \\
 \sum_{t=1}^T \gamma_{2t} H^{1*}_{2t} \\
% \sum_{t=1}^T \frac{ \gamma_{1t}  H^2(Z_{1t}) +  \gamma_{2t} H^2(Z_{2t})   }{ 2 (\sigma^*)^3 }
\sum_{t=1}^T  \gamma_{1t} H^{2*}_{1t}  + \gamma_{2t} H^{2*}_{2t} 
\end{pmatrix}\quad\text{and}\quad
%s_{\lambda_{\mu \sigma} i} =
\bs{s}_{\bs{\lambda} \bs\lambda}(\bs W) = \begin{pmatrix}
s_{\lambda_{\tau}\lambda_{\tau} }\\
s_{\lambda_{\mu_1}\lambda_{\mu_1}}\\
s_{\lambda_{\mu_2}\lambda_{\mu_2}}\\
s_{\lambda_{\mu_1}\lambda_{\mu_2}}\\
s_{\lambda_{\tau}\lambda_{\mu_1} }\\
s_{\lambda_{\tau}\lambda_{\mu_2} }\\
s_{\lambda_{\mu_1}\lambda_{\sigma}}\\
s_{\lambda_{\mu_2}\lambda_{\sigma}}\\
s_{ \lambda_{\sigma} \lambda_{\sigma}}\\
s_{ \lambda_{\tau}\lambda_{\sigma} }
  \end{pmatrix},
\end{split}
\end{equation}
where
\begin{equation}\label{eq:s-vector-mixture}
\begin{pmatrix}
s_{\lambda_{\tau}\lambda_{\tau}} \\
s_{\lambda_{\mu_1}\lambda_{\mu_1}} \\
s_{\lambda_{\mu_2}\lambda_{\mu_2}} \\
s_{\lambda_{\mu_1}\lambda_{\mu_2}} \\
s_{\lambda_{\tau}\lambda_{\mu_1}} \\
s_{\lambda_{\tau}\lambda_{\mu_2}} \\
s_{\lambda_{\mu_1}\lambda_{\sigma}} \\
s_{\lambda_{\mu_2}\lambda_{\sigma}} \\
s_{\lambda_{\sigma} \lambda_{\sigma} } \\
s_{ \lambda_{\tau}\lambda_{\sigma} }
\end{pmatrix}
=
\begin{pmatrix}
 \sum_{t=1}^T \sum_{s\neq t} \left( \frac{ \gamma_{1t} }{ \tau^* } - \frac{ \gamma_{2t} }{ 1 - \tau^* } \right) \left( \frac{ \gamma_{1s} }{ \tau^* } - \frac{ \gamma_{2s} }{ 1 - \tau^* } \right) \\
\sum_{t=1}^T \left( \gamma_{1t} H^{2*}_{1t} + \sum_{s \neq t}\gamma_{1t} \gamma_{1s} H^{1*}_{1t}  H^{1*}_{1s} \right) \\
\sum_{t=1}^T \left( \gamma_{2t} H^{2*}_{2t} + \sum_{s \neq t}\gamma_{2t} \gamma_{2s} H^{1*}_{2t}  H^{1*}_{2s} \right) \\
\sum_{t=1}^T \left(  \sum_{s \neq t} \gamma_{1t} \gamma_{2s} H^{1*}_{1t} H^{1*}_{2s} \right) \\
\sum_{t=1}^T \left( \frac{ \gamma_{1t} }{ \tau^* }  H^{1*}_{1t} + \sum_{s \neq t} \gamma_{1t} H^{1*}_{1t} \left( \frac{ \gamma_{1s} }{ \tau^* } - \frac{ \gamma_{2s} }{ 1 - \tau^* } \right) \right) \\
