\frac{1}{2} \sum_{t=1}^T \left( \left( \frac{ \gamma_{1t} }{ \tau^* } -   \frac{ \gamma_{2t} }{ 1 - \tau^* }  \right) H^{2*}_{1t}  + \sum_{s \neq t} \left( \gamma_{1t} H^{2*}_{1t}  + \gamma_{2t} H^{2*}_{2t} \right) \left( \frac{ \gamma_{1s} }{ \tau^* } - \frac{ \gamma_{2s} }{ 1 - \tau^* } \right) \right)  
\end{pmatrix}.
