\subsection{Score function for testing $H_0:m = M_0$ against $H_A:m=M_0 + 1$}
We only present score function for the model (\ref{eq:fm}) with normal density (\ref{eq:f1}). The score functions for other models can be derived analogously.
% The derivative of the reparameterized density w.r.t. $\lambda$ at $\psi^{h*}_{\tau}$ is identically zero similarly to the test of the homogeneity case.
% The values of the score function $s_{\eta i}$ contain the first-order derivatives w.r.t. the $\pi$s $\gamma$ and $\nu$ at $\psi^{h*}_{\tau}$:
% \begin{equation}
% \begin{split}
% \nabla_{\pi^j} l^h(\bs{W};\psi^{h*}_{\tau},\tau) & = \frac{f(\bs{W};\gamma^*,\theta_0^{j*}) - f(\bs{W};\gamma^*,\theta_0^{M_0 *}) }{\sum_{j=1}^{M_0} \alpha_0^{j*}  f(\bs{W};\gamma^*,\theta_0^{j*})};\\
% \nabla_{\gamma} l^h(\bs{W};\psi^{h*}_{\tau},\tau) & = \frac{  \sum_{j=1}^{M_0} \alpha_0^{j*} \nabla_{\gamma} f(\bs{W};\gamma^*,\theta_0^{j*})}{\sum_{j=1}^{M_0} \alpha_0^{j*}  f(\bs{W};\gamma^*,\theta_0^{j*})};\\
% \nabla_{\nu} l^h(\bs{W};
% \psi^{h*}_{\tau},\tau) & = \frac{\nabla_{\theta} f(\bs{W};\gamma^*,\theta_0^{h*})}{\sum_{j=1}^{M_0} \alpha_0^{j*}  f(\bs{W};\gamma^*,\theta_0^{j*})}.
% \end{split}
% \end{equation}
Let $g^* = g(\bs{W};\vartheta_{M_0}^*) = \sum_{j=1}^{M_0} \alpha_j^* f_j^*$ denote the true $M_0$-component model as in equation (\ref{eq:fm0}), where $f_j^* = f(\bs{W}; \theta_j^*) = \prod_{t=1}^T \frac{1}{\sigma_j^*} \phi\left(\frac{Y_t - \mu_j^*}{\sigma_j^*}\right)$ is the $j$-th component density. 
In this section, we omit the covariate $\bs X_{it}$ and the parameters $\beta_j^*$ for simplicity; the derivation with covariates can be done analogously to the previous section.
Define $H^{b*}_{j, it}$ as a shorthand for the $b$-th order normalized Hermite polynomial evaluated at $\frac{Y_{it} - \mu_j^*}{\sigma_j^*}$, i.e., $H^{b*}_{j,t} = \frac{1}{(\sigma_j^*)^b} H^{b}\left(\frac{Y_{t} - \mu_j^*}{\sigma_j^*}\right)$. Define the weight $w_{i}^{j*}$ as
\(
w_{j}^{*}   =  \frac{\alpha_j^{*} f_j^*}{ \sum_{l} \alpha_l^{*} f_l^* }, \quad j=1,\ldots,M_0.
\)
The score functions are
\begin{align*}
&\bs s_{\bs\alpha}(\bs W)  = \begin{pmatrix}
\frac{w_1^{*}}{\alpha_1^*} - \frac{w_{M_0}^*}{\alpha_{M_0}^*} 
  \\
\vdots \\
\frac{w_{M_0-1}^*}{\alpha_{M_0-1}^*} - \frac{w_{M_0}^*}{\alpha_{M_0}^*} 
\end{pmatrix}, 
& \bs s_{\mu }(\bs W)  = \begin{pmatrix}
w_{1}^{*} \sum_{t=1}^T  H^{1*}_{1, t} \\
\vdots \\
w_{M_0}^*  \sum_{t=1}^T  H^{1*}_{M_0, t}
\end{pmatrix}, \\
& \bs s_{\sigma }(\bs W) = \begin{pmatrix}
w_{1}^*  \sum_{t=1}^T H^{2*}_{1, t} \\
\vdots \\
w_{M_0}^*  \sum_{t=1}^T H^{2*}_{M_0, t}
\end{pmatrix}, 
& \bs s_{\bs\lambda\bs\lambda}(\bs W) =
\begin{pmatrix}
\bs s_{\lambda_{\mu}\lambda_{ \mu } }\\
\bs s_{\lambda_{\mu }\lambda_{ \sigma }}\\
\bs s_{\lambda_{\sigma }\lambda_{ \sigma }}
\end{pmatrix},
\end{align*}
where
\begin{align*}
\bs s_{\lambda_{\mu}\lambda_{ \mu } } &= \begin{pmatrix}
w_1^* \sum_{t=1}^T \left[ H^{2*}_{1,t} + \sum_{s \neq t} H^{1*}_{1, t} H^{1*}_{1, s} \right] \\
\vdots \\
w_{M_0}^* \sum_{t=1}^T \left[ H^{2*}_{M_0,t} + \sum_{s \neq t} H^{1*}_{M_0, t} H^{1*}_{M_0, s} \right] 
\end{pmatrix}, 
\bs s_{\lambda_{\mu }\lambda_{ \sigma }} = \begin{pmatrix}
w_1^*  \frac{1}{2} \sum_{t=1}^T \left[  H^{3*}_{1,t} + \sum_{s \neq t} H^{1*}_{1,t} H^{2*}_{1, s} \right] \\
\vdots \\
w_{M_0}^*  \frac{1}{2} \sum_{t=1}^T \left[  H^{3*}_{M_0,t} + \sum_{s \neq t} H^{1*}_{M_0,t} H^{2*}_{M_0, s} \right] \\
\end{pmatrix}, \\[1em]
\bs s_{\lambda_{\sigma }\lambda_{ \sigma }} &= \begin{pmatrix}
w_1^* \frac{1}{4} \sum_{t=1}^T \left[ H^{4*}_{1,t} + \sum_{s \neq t} H^{2*}_{1,t} H^{2*}_{1,s} \right] \\
\vdots \\
w_{M_0}^* \frac{1}{4} \sum_{t=1}^T \left[ H^{4*}_{M_0,t} + \sum_{s \neq t} H^{2*}_{M_0,t} H^{2*}_{M_0,s} \right]
\end{pmatrix}.
\end{align*}



\subsection{EM Algorithm}\label{sec:em}
\subsubsection{EM Algorithm for the model (\ref{eq:fm}) with normal mixture density (\ref{eq:f1-mixture})}\label{sec:em-algorithm}

We introduce latent variables $D_i \in \{1,2,\ldots,M\}$ and $C_{it} \in \{1,2,\ldots,K\}$, where the top-level latent variable $D_i$ indicates which of the $M$ top-level components was chosen for observation $i$, and $C_{it}$ indicates which of the $K$ inner components was chosen for the $t$-th observation of unit $i$ under the selected top-level component. Then, the complete-data log-likelihood is given as
\[
\log L_c = \sum_{i=1}^n \sum_{j=1}^M \mathbb{I}(D_i=j)\left[\log\alpha_j + \sum_{t=1}^T \sum_{k=1}^{{\cal{K}}} \mathbb{I}(C_{it}=k)\bigl(\log \tau_{jk} + \log\phi(Z_{jk,it}) - \log \sigma_j\bigr)\right],
\]
where $Z_{jk,it}:=\frac{Y_{it}-\mu_{jk}-\bs X_{it}\t \bs\beta_j }{\sigma_j}$.

To obtain the Maximum Likelihood estimator $\hat{\bs\vartheta} = \arg\max_{\bs\vartheta} \sum_{i=1}^n \log g(\mathbf{W}_i;\bs\vartheta)$, we implment the following EM algorithm by alternating between the E-step and the M-step.

In E-step, given current estimates $(\alpha_j^{(m)},\bs\theta_j^{(m)})$, compute the posterior probabilities of the latent variables as
\begin{align*}
\pi_{i,j}^{(m)} & = P(D_i=j|\mathbf{W}_i,\{\alpha_j^{(m)},\bs\theta_j^{(m)}\})
= \frac{\alpha_j^{(m)} f(\mathbf{W}_i;\theta_j^{(m)})}{\sum_{r=1}^M \alpha_r^{(m)}f(\mathbf{W}_i;\theta_r^{(m)})}\text{ and }\\
\gamma_{jk,it}^{(m)} &= P(C_{it}=k|\mathbf{W}_i,D_i=j,\bs\theta_j^{(m)})
= \frac{\tau_{jk}^{(m)}\phi(z_{jk,it}^{(m)})}{\sum_{\ell=1}^{{\cal{K}}} \tau_{j\ell}^{(m)}\phi(z_{j\ell,it}^{(m)})}
\end{align*}
 for each $j=1,\ldots,M$ and $k=1,\dots,K$.

In M-step, we maximize  the expected complete-data log-likelihood $E[\log L_c|\mathbf{W},\alpha_j^{(m)},\bs\theta_j^{(m)}]$ as follows: for $j=1,...,M$,
\begin{enumerate}
\item  Update $\alpha_j$ as
\[
\alpha_j^{(m+1)} = \frac{\sum_{i=1}^n \pi_{i,j}^{(m)}}{n}, \quad \text{with } \sum_{j=1}^M \alpha_j^{(m+1)}=1.
\]
\item  Update $\tau_{jk}$ as
\[
\tau_{jk}^{(m+1)} = \frac{\sum_{i=1}^n \pi_{i,j}^{(m)}\sum_{t=1}^T \gamma_{jk,it}^{(m)}}{\sum_{i=1}^n \pi_{i,j}^{(m)} T}\quad\text{for $k=1,...,{\cal{K}}$}.
\]
%and ensure $\sum_{k=1}^{{\cal{K}}} \tau_{jk}^{(m+1)}=1$ by defining $\tau_{jK}^{(m+1)}=1-\sum_{\ell=1}^{K-1}\tau_{j\ell}^{(m+1)}$.
\item   Update $\bs\mu_{j}$ as
   \[
   \mu_{jk}^{(m+1)} = \frac{\sum_{i,t} \pi_{i,j}^{(m)}\gamma_{jk,it}^{(m)}(Y_{it}-\bs{X}_{it}^\top \beta_j^{(m)})}{\sum_{i,t} \pi_{i,j}^{(m)}\gamma_{jk,it}^{(m)}}\quad\text{   for $k=1,...,K$.}
   \]


\item  Given  $\bs\mu_{j}^{(m+1)}$, update $\bs\beta_j$ as
\[
\bs\beta_j^{(m+1)}=\arg\min_{\bs\beta_j} \sum_{j=1}^M \sum_{k=1}^{{\cal{K}}} \sum_{i=1}^n \sum_{t=1}^T \pi_{i,j}^{(m)}\gamma_{jk,it}^{(m)} (Y_{it}-\mu_{jk}^{(m+1)}-\bs X_{it}\t \bs\beta_j )^2.
\]

\item Update $\sigma_{j}^2$
\[
\sigma_j^{(m+1)2} = \frac{\sum_{i=1}^n \pi_{i,j}^{(m)}\sum_{t=1}^T \sum_{k=1}^{{\cal{K}}} \gamma_{jk,it}^{(m)}(Y_{it}-\mu_{jk}^{(m+1)}-\bs X_{it}\t \bs\beta_j )^2}{\sum_{i=1}^n \pi_{i,j}^{(m)}T}.
\]
\end{enumerate}

We iterate between the E-step and the M-step until convergence.


\subsubsection{EM Algorithm for the model (\ref{eq:fm-dynamic}) with normal mixture density (\ref{eq:f1-dynamic-mixture})}\label{sec:em-algorithm-dynamic}

In a similar manner as above section, we denote latent variables $D_i \in \{1,2,\ldots,M\}$ and $C_{it} \in \{1,2,\ldots,K\}$, where the top-level latent variable $D_i$ indicates which of the $M$ top-level components was chosen for observation $i$, and $C_{it}$ indicates which of the $K$ inner components was chosen for the $t$-th observation of unit $i$ under the selected top-level component. Then, the complete-data log-likelihood is given as
\[
\begin{aligned}
\log L_c = \sum_{i=1}^n \sum_{j=1}^M \mathbb{I}(D_i = j) \Bigg[ \log\alpha_j
+  \Big(
& \sum_{k=1}^{\mathcal{K}} \mathbb{I}(C_{i1} = k) \big(  \log \tau_{jk} + \log\phi(Z_{jk,i1}) - \log \sigma_{1,j} \big) \\
& + \sum_{t=2}^T \sum_{k=1}^{\mathcal{K}} \mathbb{I}(C_{it} = k) \big( \log \tau_{jk} + \log\phi(Z_{jk,it}) - \log \sigma_j \big)
\Big) \Bigg]
\end{aligned}
\]
where $Z_{jk,it}:=\frac{Y_{it} - \rho Y_{i,t-1} - (1 - \rho) \mu_{jk}-\bs X_{it}\t \bs\beta_j +  \bs X_{i,t-1}\t \bs\beta_j \rho_j  }{\sigma_j}$ and $Z_{jk,i1} = \frac{Y_{i1} - \mu_{1,jk} - \bs X_{i1}\t \bs\beta_{1,j}}{\sigma_{1,j}}$.

To obtain the Maximum Likelihood estimator $\hat{\bs\vartheta} = \arg\max_{\bs\vartheta} \sum_{i=1}^n \log g(\mathbf{W}_i;\bs\vartheta)$, we implment the following EM algorithm by alternating between the E-step and the M-step.

In E-step, given current estimates $(\alpha_j^{(m)},\bs\theta_j^{(m)})$, compute the posterior probabilities of the latent variables as
\[
\pi_{i,j}^{(m)} = P(D_i=j|\mathbf{W}_i,\{\alpha_j^{(m)},\bs\theta_j^{(m)}\})
= \frac{\alpha_j^{(m)} f(\mathbf{W}_i;\theta_j^{(m)})}{\sum_{r=1}^M \alpha_r^{(m)}f(\mathbf{W}_i;\theta_r^{(m)})}
\]
\[
\gamma_{jk,it}^{(m)} = P(C_{it}=k|\mathbf{W}_i,D_i=j,\bs\theta_j^{(m)})
= \frac{\tau_{jk}^{(m)}\phi(Z_{jk,it}^{(m)})}{\sum_{\ell=1}^{{\cal{K}}} \tau_{j\ell}^{(m)}\phi(Z_{j\ell,it}^{(m)})} \qquad \text{for } T > 1,
\]
\[
\gamma_{jki,1}^{(m)} = P(C_{i1}=k|\mathbf{W}_i,D_i=j,\bs\theta_j^{(m)})
= \frac{\tau_{jk}^{(m)}\phi(Z_{jki,1}^{(m)})}{\sum_{\ell=1}^{{\cal{K}}} \tau_{j\ell}^{(m)}\phi(Z_{j\ell,i1}^{(m)})} \qquad \text{for } T = 1,
\]
for each $j=1,\ldots,M$ and $k=1,\dots,K$.

In M-step, we maximize the expected complete-data log-likelihood $E[\log L_c|\mathbf{W},\alpha_j^{(m)},\bs\theta_j^{(m)}]$ as follows: for $j=1,...,M$,
\begin{enumerate}
\item  Update $\alpha_j$ as
\[
\alpha_j^{(m+1)} = \frac{\sum_{i=1}^n \pi_{i,j}^{(m)}}{n}, \quad \text{with } \sum_{j=1}^M \alpha_j^{(m+1)}=1.
\]
\item  Update $\tau_{jk}$ as
\[
\tau_{jk}^{(m+1)} = \frac{\sum_{i=1}^n \pi_{i,j}^{(m)}\sum_{t=1}^T \gamma_{jk,it}^{(m)}}{\sum_{i=1}^n \pi_{i,j}^{(m)} T}\quad\text{for $k=1,...,{\cal{K}}$}.
\]
%and ensure $\sum_{k=1}^{{\cal{K}}} \tau_{jk}^{(m+1)}=1$ by defining $\tau_{jK}^{(m+1)}=1-\sum_{\ell=1}^{K-1}\tau_{j\ell}^{(m+1)}$.
\item   Update $\bs\mu_{j}$ and $\bs\mu_{1,j}$ as
   \[
   \mu_{jk}^{(m+1)} = \frac{\sum_{i,t} \pi_{i,j}^{(m)}\gamma_{jk,it}^{(m)}( Y_{it} - \rho^{(m)} Y_{i,t-1} - \bs X_{it}\t \bs\beta_j^{(m)} +  \bs X_{i,t-1}\t \bs\beta_j^{(m)} \rho_j^{(m)}  )}{\sum_{i,t} \pi_{i,j}^{(m)}\gamma_{jk,it}^{(m)} (1 - \rho_j^{(m)}) }\quad\text{   for $k=1,...,K$.}
   \]
   and 
  \[
   \mu_{1,jk}^{(m+1)} = \frac{\sum_{i} \pi_{i,j}^{(m)}\gamma_{jk,i1}^{(m)}( Y_{i1} - \bs X_{i1}\t \bs\beta_{1,j}^{(m)}  )}{\sum_{i,t} \pi_{i,j}^{(m)}\gamma_{jk,i1}^{(m)}}\quad\text{   for $k=1,...,K$.}
   \]

\item  Given  $\bs\mu_{j}^{(m+1)}$, $\mu_{1,jk}^{(m+1)}$ and $\rho_{j}^{(m)}$, update $\bs\beta_j$ and $\bs\beta_{1,j}$ as
\begin{align*}
\bs\beta_j^{(m+1)} = \arg\min_{\bs\beta_j} \sum_{j=1}^M \sum_{k=1}^{\mathcal{K}} & \sum_{i=1}^n \sum_{t=2}^T 
\pi_{i,j}^{(m)} \gamma_{jk,it}^{(m)} \\
& \times
\Big[
 Y_{it} - \rho_{j}^{(m)} Y_{i,t-1} - (1 - \rho_{j}^{(m)}) \mu_{jk}^{(m+1)} - \left( \bs X_{it}^\top - \rho_j^{(m)} \bs X_{i,t-1}^\top \right) \bs\beta_j
\Big]^2
\end{align*}

and
\[
\bs\beta_{1,j}^{(m+1)} = \arg\min_{\bs\beta_{1,j}} \sum_{j=1}^M \sum_{k=1}^{\mathcal{K}} \sum_{i=1}^n 
\pi_{i,j}^{(m)} \gamma_{jk,i1}^{(m)} 
\left( Y_{i1} - \mu_{1,jk}^{(m+1)} - \bs X_{i1}^\top \bs\beta_{1,j} \right)^2.
\]

\item Given $\bs\beta_j^{(m+1)}$ and $\mu_{jk}^{(m+1)}$, update $\rho_j$ 
\begin{align*}
&\rho_j^{(m+1)} =  \arg\min_{\rho_j} \sum_{j=1}^M \sum_{k=1}^{\mathcal{K}} \sum_{i=1}^n \sum_{t=2}^T 
\pi_{i,j}^{(m)} \gamma_{jk,it}^{(m)} \\
&\qquad \times \left[
 \big(Y_{it} - \mu_{jk}^{(m+1)} - \bs X_{it}^\top  \bs\beta_j^{(m+1)}\big) - \rho_j \big(Y_{it-1} - \mu_{jk}^{(m+1)} - \bs X_{it-1}^\top  \bs\beta_j^{(m+1)}\big)
\right]^2.
\end{align*}

\item Update $\sigma_{j}^2$ and $\sigma_{1,j}^2$ As

\scalebox{0.85}{%
\parbox{\linewidth}{%
\begin{align*}
\sigma_j^{(m+1)2} =  
  \frac{
  \sum_{i=1}^n \sum_{t=2}^T \sum_{k=1}^{\mathcal{K}} \pi_{i,j}^{(m)} \gamma_{jk,it}^{(m)}
  \left(
    Y_{it} - Y_{i,t-1}\rho_j^{(m+1)}
    - \mu_{jk}^{(m+1)} (1 - \rho_j^{(m+1)})
    - \bs X_{it}^\top \bs\beta_j^{(m+1)} + \bs X_{i,t-1}^\top \bs\beta_j^{(m+1)} \rho_j^{(m+1)}
  \right)^2
  }{
  \sum_{i=1}^n \pi_{i,j}^{(m)} (T-1)
  }
\end{align*}
}%
}
and 
\[ \sigma_{1,j}^{(m+1)2} =  
  \frac{
  \displaystyle
  \sum_{i=1}^n \sum_{k=1}^{\mathcal{K}} \pi_{i,j}^{(m)} \gamma_{jk,i1}^{(m)}
  \left(
    Y_{i1} - \mu_{1,jk}^{(m+1)}
    - \bs X_{i1}^\top \bs\beta_{1,j}^{(m+1)}
  \right)^2
  }{
  \displaystyle
  \sum_{i=1}^n \sum_{k=1}^{\mathcal{K}} \pi_{i,j}^{(m)}
  }
\]
\end{enumerate}

We iterate between the E-step and the M-step until convergence.

