	\begin{algorithm}[!t]
		\caption{Speech Synthesis based on QHARMA-GAN.}
		\begin{algorithmic}
			\STATE {\textbf{Step 1: Preprocessing and Setting}\\
				Extract the $\hat{f}_k$ and mel-spectrogram from speech $x(t)$;
				set sampling rate $f_s$, harmonic number $K$ and frame-shift $\Delta t$; 
				obtain $a^l_{j,p}$ and $b^l_{j,q}$ from DNN;}

			\STATE {\textbf{Step 2: Instantaneous amplitude and phase}\\
				Get framewise amplitude and phase delay by Eq. (\ref{eq22})-(\ref{eq23});\\
				Compute unwrapped framewise phase $\hat{\varphi}_k(t_l)$ by Eq. (\ref{eq17});\\
				Cubically interpolate $\hat{\varphi}_k(t_l)$ into $\hat{\varphi}_k(t)$;\\
				Linearly interpolate $\hat{A}_k(t_l)$ into $\hat{A}_k(t)$;\\
			}
			\STATE {\textbf{Step 3: Generation}\\
				\STATE $\hat{x}(t) \leftarrow \sum_{k=-K}^{K}\hat{A}_k(t)e^{i\hat{\varphi}_k(t)}$;
			}
			\STATE {\textbf{Output:} $\hat{x}(t)$}
		\end{algorithmic}

		\label{alg1_1}
	\end{algorithm}



