\section{Derivation of the nonlinear sigma model}\label{app:derive_NLSM}
A Hamiltonian $H$ with chiral symmetry, $\sigma_z H \sigma_z = - H$, is given by a two-by-two block off-diagonal form, $H=(h_0+V)\sigma_{+} + (h^\dagger_0+V^\dagger)\sigma_{-}$, where $h_0$ and $V$ are $M\times M$ non-Hermitian matrices. $h_0$ is a disorder-free tight-binding matrix. $V$ is a diagonal matrix whose diagonal elements $V_r$ are random complex numbers obeying the Gaussian distribution function with $\langle V_{r}\rangle_{\rm dis}=0$ and $\langle V_{r}^*V_{r^\prime}\rangle_{\rm dis}=\gamma^2\delta_{rr^\prime}$. A Green's function $G(z;r,r^{\prime})=\langle r|(z-H)^{-1}|r^{\prime}\rangle$ and its products are generated from a partition function,
\begin{equation}
    {\cal Z}=\int \mathrm{d}[\psi]\,\exp\left[-\psi^\dagger(z-H)\psi\right]
    =\int \mathrm{d}[\psi]\,\exp\left[-\psi^\dagger(z-H)\sigma_x\psi\right],
\end{equation}
with $\psi \equiv (\psi_{+},\psi_{-})^T$ and $\psi^{\dagger}\equiv (\psi^{\dagger}_{+},\psi^{\dagger}_{-})$. Here $\pm$ is the chiral index associated with the two-by-two block-off diagonal structure~\cite{altlandTopologyAndersonLocalization2015,konigMetalinsulatorTransitionTwodimensional2012,zhaoTopologicalEffectAnderson2024c}. The right-hand side is due to $\det\sigma_x=1$. The Green's function and its product are obtained from derivatives of the partition function $\cal Z$ with respect to a source field $J$, e.g. 
\begin{equation}
    G(z;r,r^{\prime})=\frac{\partial\ln {\cal Z}}{\partial J_{r,r^{\prime}}}.
\end{equation}
As the derivatives and the disorder average commute with each other, we have only to calculate $\langle \ln  {\cal Z}\rangle_{\rm dis}$. To calculate $\langle \ln{\cal Z}\rangle_{\rm dis}$, we use the replica trick,  
\begin{equation}
    \ln {\cal Z}=\lim_{N\to 0}\frac{{\cal Z}^N-1}{N},
\end{equation}
where ${\cal Z}^N$ is a partition function of $N$ replicated fermion field $\psi_m\equiv (\psi_{m,+},\psi_{m,-})^T$ ($m=1,\cdots,N$). The Gaussian average of ${\cal Z}^N$ induces an attractive interaction among the replicated $\psi$-fields, 
\begin{equation}
    \braket{{\cal Z}^N}_{\text{dis}}=\int \mathrm{d}[\psi]\,\exp\left[-\sum^N_{n=1}\psi_n^\dagger(z-H_0)\sigma_x\psi_n+\frac{\gamma^2}{2}\sum^N_{m,n=1} \sum^M_{r=1} \psi_{m,+,r}^*\psi_{m,+,r}\psi_{n,-,r}^*\psi_{n,-,r}\right],
\end{equation}
with $H_0  =  h_0\sigma_{+} + h^\dagger_0\sigma_{-}$. $H_0$ is diagonal in the replica index ($n$) and independent of the replica index $n$.  

\subsection{Self-consistent Born approximation}
The attractive interaction is further decomposed by the use of the Hubbard-Stratonovich (HS) transformation,
\begin{align}\label{eq:6}
&\exp\left[\frac{\gamma^2}{2}\sum_{m,n,r}\psi_{m,+,r}^*\psi_{m,+,r}\psi_{n,-,r}^*\psi_{n,-,r}\right] \nonumber \\
  & = \int \mathrm{d}[Q]\,\exp\left[-\frac{1}{2\gamma^2}\Tr (Q^\dagger Q)+i\left(\psi^\dagger_{+}Q \psi_{-}+\psi^\dagger_{-}Q^\dagger \psi_{+}\right)\right].
\end{align}
Here, the HS field ($Q$ field) takes the form of an $N$ by $N$ matrix. The $Q$ field is diagonal in the lattice-site index $r$, while it is dependent on $r$. The partition function of the $N$ replicated fields is given by 
\begin{equation}
    \braket{{\cal Z}^N}_{\text{dis}}=\int \mathrm{D}[Q,\psi]\,\exp\left[-\frac{1}{2\gamma^2}\Tr \left(Q^\dagger Q\right)-\psi^\dagger
    \begin{pmatrix}
        z-iQ & -h_0 \\
        -h^\dagger_0 & z-iQ^\dagger
    \end{pmatrix}
    \sigma_x\psi
    \right].
\end{equation}
An integration of the fermion $\psi$-field yields the partition function for the auxiliary $Q$ field,
\begin{align}
    \braket{{\cal Z}^N}_{\text{dis}} &=\int \mathrm{D}[Q]\,\exp\left[-\frac{1}{2\gamma^2}
    \Tr \left(Q^\dagger Q\right)+\Tr \ln
    \begin{pmatrix}
        z-iQ & -h_0 \\
        -h^\dagger_0 & z-iQ^\dagger
    \end{pmatrix}
    \right], \nonumber \\
    & \equiv\int \mathrm{D}[Q] \exp \left[-S[Q,z]\right]. 
\end{align}
Here, the trace on the right-hand side is taken over the chiral index ($\pm$), replica index ($m,n$), and the lattice site index  ($r$).

Self-consistent Born solution is a saddle-point solution $Q$ of the action $S[Q,z]$. For simplicity, we will not explore general structures of the saddle-point solutions of specific tight-binding Hamiltonians $h_0$ in the chiral unitary class. Instead, we assume a (commonly used) {\it ansatz} $Q=\lambda \!\ 1_{N\times N}$. Real and imaginary parts of $\lambda$ physically mean an inverse of the mean free time and energy renormalization of diffusive particles, respectively. With periodic boundary conditions for $h_0$, the action in the momentum space may become
\begin{equation}
    S[\lambda 1_{N\times N},z]=-\frac{N M}{2\gamma^2}\lambda^* \lambda+M \sum_{k} \!\ \Tr \ln
    \begin{pmatrix}
        z-i\lambda & -h_0(\bm{k}) \\
        -h^{*}_0(\bm{k}) & z-i\lambda^*
    \end{pmatrix}. \label{eq:scb-action}
\end{equation}
Here we assume that the eigenvalues of an $M$ by $M$ non-Hermitian matrix $h_0$ are given by complex values $h_0(\bm{k})$, where $k$ takes $M$ discrete values from the periodic boundary condition.  The trace ($\operatorname{Tr}$) on the right-hand side is taken over the chiral index. The stationary point is determined by 
\begin{equation}
    0=\frac{\partial S}{\partial \lambda^*}=-\frac{N M}{2\gamma^2}\lambda+N\!\ \sum_{k} 
    \Tr \left[\begin{pmatrix}
        z-i\lambda & -h_0(\bm{k}) \\
        -h^{*}_0(\bm{k}) & z-i\lambda^*
    \end{pmatrix}^{-1}
    \begin{pmatrix}
        0 & 0 \\
        0 & -i
    \end{pmatrix}
    \right].
\end{equation}
The trace can be calculated as   
\begin{equation}
    \Tr \left[\begin{pmatrix}
        z-i\lambda & -h_0(\bm{k}) \\
        -h^*_0(\bm{k}) & z-i\lambda^*
    \end{pmatrix}^{-1}
    \begin{pmatrix}
        0 & 0 \\
        0 & -i
    \end{pmatrix}
    \right]=\sum_{\bm{k}}\frac{-i(z-i\lambda)}{(z-i\lambda)(z-i\lambda^*)-\epsilon_{k}^2},
\end{equation}
with $\epsilon^2_{k}=|h_{0}(\bm{k})|^2 \ge 0$. The saddle-point equation reduces to
\begin{equation}
    \lambda=-\frac{2i\gamma^2}{M}\sum_{k}\frac{z-i\lambda}{(z-i\lambda)(z-i\lambda^*)-\epsilon_{k}^2}.
\end{equation}
In the thermodynamic limit, we may replace the $k$-sum by an energy integral with a density of states  $\rho(\epsilon)  \equiv \frac{1}{M}\sum_k \delta(\epsilon-\epsilon_k)$,
\begin{equation}
    \lambda=-2i\gamma^2 \int_0^{\infty}d\epsilon\,\rho(\epsilon)\frac{z-i\lambda}{(z-i\lambda)(z-i\lambda^*)-\epsilon^2}. 
\end{equation}
Here, we set $z=0$, because the chiral symmetry is respected exclusively by zero-energy eigenstates of $H$, and the Anderson transition in chiral symmetry class depends solely on the zero-energy Green's function $G(z=0)$. The gap equation at $z=0$ suggests either $\lambda=0$ solution or $\lambda\ne 0$ solution that satisfies,
\begin{align}
1 = 2\gamma^2 \int^{\infty}_{0} d\epsilon \!\ \frac{\rho(\epsilon)}{|\lambda|^2+\epsilon^2}.  
\end{align}
When $\rho(\epsilon)\simeq \epsilon^\alpha$ for  $\epsilon\simeq 0$ and $\alpha\ge 1$,  the gap equation for small $\gamma$  has only $\lambda=0$ solution (a solution of ballistic transport)~\cite{fradkin1986,syzranovHighDimensionalDisorderDrivenPhenomena2018}. Otherwise, the gap equation generally has a $\lambda\ne 0$ solution (a solution of diffusive transport). 

\subsection{Nonlinear sigma model}
     The action at $z=0$ has a continuous symmetry, and the $\lambda \ne 0$ solution has a degeneracy; 
\begin{equation}
    \braket{{\cal Z}^N}_{\text{dis}}=\int \mathrm{d}[Q]\,\exp\left[-\frac{1}{2\gamma^2}\Tr \left(Q^\dagger Q\right)+\Tr \ln
    \begin{pmatrix}
        -iQ & -h_0 \\
        -h^\dagger_0 & -iQ^\dagger
    \end{pmatrix}
    \right]. 
\end{equation}
The action is invariant under the continuous transformation $Q\to U_1 Q U_2^\dagger$, with two $N$ by $N$ unitary matrices $U_1$ and $U_2$ that are independent of the spatial coordinate $r$. The symmetry dictates that the self-consistent Born (SCB) solution $Q=\lambda 1_{N\times N}$ must have degeneracy with $Q=\lambda U_1U_2^\dagger$. For $U_1=U_2$, they are identical. Thus, the degenerate SCB solutions form a manifold defined by a matrix group $\mathrm{U}(N)\times\mathrm{U}(N)/\mathrm{U}(N)\cong\mathrm{U}(N)$. The matrix group is called the Goldstone manifold. The group $\mathrm{U}(N)\times\mathrm{U}(N)$ in the numerator is called the symmetry group, while the group $\mathrm{U}(N)$ in the denominator is called the stabilizer group.

Since the SCB solution breaks the continuous symmetry, the solution is accompanied by gapless Goldstone modes -- diffusion mode. To describe the diffusion mode, let us take $Q=\lambda U$, where a $N$ by $N$ matrix $U$ is diagonal in $r$ but slowly varying in $r$. The partition function of the replicated fermion fields reduces to
\begin{align}
\braket{{\cal Z}^N}_{\text{dis}}
    &=\int \mathrm{d}[U]\,\exp\left[-\frac{|\lambda|^2 M N}{2\gamma^2} + \Tr \ln
    \begin{pmatrix}
        -i\lambda & -U^\dagger h_0 U \\
        -h^\dagger_0 & -i\lambda^*
    \end{pmatrix}\right].
\end{align}
On the right-hand side, the $r$-dependent $U$ does not commute with $h_0$, while the $r$-independent $U$ yields the SCB action, Eq.~(\ref{eq:scb-action}). To extract energy cost from the $r$-dependency in $U$, one can exercise a gradient expansion around the SCB Green's function $G^{-1}_0$, 
\begin{align}
\braket{{\cal Z}^N}_{\text{dis}}
    &= \exp [-S_{\rm scb}] \int \mathrm{d}[U] \exp \left[\Tr \ln \left[1 + G_0 \begin{pmatrix} 
         0 & \Delta_{U} h_0 \\
         0 &  0
    \end{pmatrix}\right]\right] \nonumber \\
    & = \exp [-S_{\rm scb}] \int \mathrm{d}[U] \exp \left[ \Tr  \left[G_0 \begin{pmatrix} 
         0 & \Delta_{U} h_0 \\
         0 &  0
    \end{pmatrix}\right] - \frac{1}{2} \Tr  \left[\!\ G_0 \begin{pmatrix} 
         0 & \Delta_{U} h_0 \\
         0 &  0
    \end{pmatrix} G_0 \begin{pmatrix} 
         0 & \Delta_{U} h_0 \\
         0 &  0
    \end{pmatrix} \right] + \cdots \right] \nonumber \\
    & \equiv \exp [-S_{\rm scb}] \int \mathrm{d}[U] \exp [-S_{\rm NSLM}[U]],
\end{align}
with $S_{\rm scb} \equiv S [\lambda \!\ 1_{N\times N},z=0]$ and $\Delta_{U} h_0 \equiv -U^\dagger h_0 U + h_0$. The SCB Green's function $G_0$ at the zero energy ($z=0$) is given by,
\begin{align}
G^{-1}_0 = \begin{pmatrix} 
         -i\lambda &  - h_0\\
         -h^{\dagger}_0 &  -i\lambda^*
    \end{pmatrix}.
\end{align}

In the following, we deduce the form of $S_{\rm NLSM}[U]$ based on symmetry arguments. Since $\Delta_U h_0=0$ for the $r$-independent $U$, $\Delta_U h_0$ must reduce to a linear combination of $U^{-1}\nabla_{\mu} U$ in the continuum limit ($\mu=x,y,\cdots$). Possible scalar quantities one can construct out of $U^{-1}\nabla_{\mu} U$ and their products are $\Tr [U^{-1}\nabla_{\mu} U]$, $\Tr [U^{-1}\nabla_{\mu} U\cdot U^{-1}\nabla_{\nu} U]$,  $\Tr [U^{-1}\nabla_{\mu} U]\! \ \Tr [U^{-1}\nabla_{\nu} U]$,  and higher-order gradient terms~\cite{gadeReplicaLimitUnSOn1991,gadeAndersonLocalizationSublattice1993}. Suppose that a disordered system considered here has (statistical) mirror symmetries with respect to spatial directions except for $z$, e.g., $(x,y,z) \rightarrow (-x,y,z)$ or $(x,-y,z)$.  The mirror symmetries forbid cross terms ($\mu\ne \nu$) in  
$\Tr [U^{-1}\nabla_{\mu}U \cdot U^{-1}\nabla_{\nu}U]$ and $\Tr [U^{-1}\nabla_{\mu}U]\Tr [U^{-1}\nabla_{\nu}U]$. The symmetries also forbid $\Tr [U^{-1}\nabla_{\mu} U]$ with $\mu=x,y$. Thus, up to the second order in the expansion, the symmetry-allowed form of $S_{\rm NLSM}$ is given by 
\begin{align}
    S_{\rm NLSM}[U]=-\int\frac{\mathrm{d}^d r}{8\pi}\,\sum_{\mu}\left[\sigma_\mu\Tr \left(U^{-1}\nabla_\mu U\right)^2+c_\mu\Tr ^2\left(U^{-1}\nabla_\mu U\right)-\chi \!\  \Tr \left(U^{-1}\nabla_z U\right)\right].
\end{align}
Notably, $\sigma_{\mu}$ and $c_{\mu}$ must be positive and $\chi$ must be real. Otherwise, the spatially uniform saddle-point solution $Q=\lambda 1_{N\times N}$ cannot be a local energy minimum of the action $S[Q,z]$. In the absence of any other statistical symmetries that change the sign of $z$, e.g. $(x,y,z)\rightarrow (x,y,-z)$, real-valued $\chi$ is generally finite. 

\section{Saddle-point equation of the nonlinear sigma model}\label{app:saddle_point}
In this Appendix, we derive a set of saddle-point equations of the chiral NLSM, Eqs~(\ref{eq:action_with_Ansatz},\ref{eq:saddle-point_equation1},\ref{eq:saddle-point-equation2}), as well as Eq.~(\ref{eq:field-strength}). We also discuss a general feature of $P(\bm{r}) \equiv |p(\bm{r})\rangle \langle p(\bm{r})|$ that satisfies the saddle-point equations, and how the Poisson equation for $\phi(\bm{r})$ can be obtained from them. The derivation can be applied to all three chiral symmetry classes. $Q(\bm{r})$ in the chiral classes has unit complex numbers $e^{i\phi_n(\bm{r})}$ as its eigenvalues, 
\begin{equation}
    Q(\bm{r})=\sum_{n=1}^{N}e^{i\phi_n(\bm{r})}\ket{p_n(\bm{r})}\bra{p_n(\bm{r})}. \nonumber 
\end{equation}
$|p_n(\bm{r})\rangle$ is a corresponding eigenvector. General saddle-point solutions of the NLSM could be obtained from its derivatives with respect to all eigenvalues and eigenvectors of the $Q$ field. In saddle-point solutions thus obtained, each eigenvalue $e^{i\phi_n(\bm{r})}$ could have multiple vortex excitations separately. When such vortex excitations have no spatial overlap with one another, however, one may utilize an $r$-dependent basis change in such a way that only one eigenvalue $e^{i\phi(\bm{r})}$ has all the vortex excitations, while the others do not. To introduce such a generic $Q$ configuration as the saddle-point solution, we may use the following ansatz; 
\begin{align}
    Q(\bm{r})&=e^{i\psi(\bm{r})}+\left[e^{i\phi(\bm{r})}-e^{i\psi(\bm{r})}\right]|p(\bm{r})\rangle\langle p(\bm{r})| \nonumber \\
             &= e^{i\psi(\bm{r})} \left(1+ \left[e^{i\phi(\bm{r})-i\psi(\bm{r})}-1\right]|p(\bm{r})\rangle\langle p(\bm{r})|\right).
    \label{Eq:B-1}
\end{align}
In the ansatz, only one eigenvalue $e^{i\phi({\bm r})}$, which an eigenstate $|p(\bm{r})\rangle$ belongs to, has vortex excitations, while the other eigenvalues $e^{i\psi(\bm{r})}$ are degenerate, and do not have any vortices.  Since the overall factor $e^{i\psi(\bm{r})}$ in the right hand side can be absorbed into the spin-wave part of the $Q$ field, we may also use Eq.~(\ref{eq:Ansatz}) by replacing  $e^{i\phi(\bm{r})-i\psi(\bm{r})}$ by $e^{i\phi(\bm{r})}$.  From Eq.~(\ref{eq:Ansatz}) with $P(\bm{r}) \equiv \ket{p(\bm{r})}\bra{p(\bm{r})}$, we obtain
\begin{align}
    \nabla_\mu Q &=i\nabla_\mu \phi\, \  e^{i\phi}P+\left(e^{i\phi}-1\right)\nabla_\mu P, \nonumber \\
    Q^{-1}\nabla_\mu Q&=i\nabla_\mu \phi P+2(1-\cos\phi)P\nabla_\mu P+(e^{i\phi}-1)\nabla_\mu P. \label{Eq:B-1a}
\end{align}
With the use of $ \Tr (P)=1$,  $\Tr (\nabla_\mu P)=\nabla_\mu \Tr (P)=0$, $\Tr (P\nabla_\mu P)=\Tr (\nabla_\mu P P)=\frac{1}{2}\Tr (\nabla_\mu P)=0$, $P^2=P$, $\nabla_\mu PP+P\nabla_\mu P=\nabla_\mu P$, and 
\begin{align}
    &\Tr (P\nabla_\mu P)^2=\Tr (\nabla_\mu P P\nabla_\mu P)-\Tr (\nabla_\mu P P^2\nabla_\mu P)=0,  \nonumber \\
    &\Tr (\nabla_{\mu} P)^2 = 2 \Tr (P\nabla_{\mu} P \nabla_{\mu} P), \nonumber 
\end{align}
we obtain the following formulas, 
\begin{align}
    &\Tr \left(Q^{-1}\nabla_\mu Q\right)=i\nabla_\mu\phi,  \nonumber \\
    &\Tr \left(Q^{-1}\nabla_\mu Q\right)^2=-(\nabla_\mu \phi)^2-2(1-\cos\phi)\Tr (\nabla_{\mu} P)^2. 
    \nonumber 
\end{align}
Thus, the action with the saddle-point ansatz, Eq.~(\ref{eq:Ansatz}), is given by
\begin{equation}
    S=\int\frac{\mathrm{d}^3r}{8\pi}\,\sum_{\mu}\left[(\sigma_\mu+c_\mu)(\nabla_\mu \phi)^2+2\sigma_\mu(1-\cos\phi)\Tr (\nabla_\mu P)^2+i\chi_\mu\nabla_\mu \phi\right]. \label{Eq:B0}
\end{equation}
Derivatives of Eq.~(\ref{Eq:B0}) with respect to the U(1) phase $\phi(\bm{r})$ and matrix elements of $P(\bm{r})$ give 
\begin{equation}
    \sum_{\mu}(\sigma_{\mu}+c_{\mu})\nabla^2_{\mu}\phi-\sum_{\mu}\sigma_{\mu} \sin\phi \Tr (\nabla_{\mu} P)^2=0, \label{Eq:B1}
\end{equation}
and 
\begin{equation}
   \sum_{\mu} \sigma_{\mu}(1-\cos\phi)\nabla^2_{\mu} P+\sum_{\mu}\sigma_{\mu} \sin\phi \nabla_{\mu}\phi\nabla_{\mu} P=0, \label{Eq:B2}
\end{equation}
respectively. By multiplying \cref{Eq:B2} by $P$ and taking the trace, we can also have
\begin{equation}
   \sum_{\mu} \sigma_{\mu}(1-\cos\phi) \!\ \Tr (P\nabla^2_{\mu} P)+ \sum_{\mu} \sigma_{\mu}\sin\phi \!\ \nabla_{\mu}\phi \!\ \Tr (P\nabla_{\mu} P)=0. \label{Eq:B3}
\end{equation}
As $\Tr (P\nabla_{\nu} P)=0$, and $\Tr (P\nabla^2_{\nu} P)=\nabla_{\nu}\Tr (P\nabla_{\nu} P)-\Tr (\nabla_{\nu} P)^2=-\Tr (\nabla_{\nu} P)^2$, Eq.~(\ref{Eq:B3}) means either $\sum_{\mu}\sigma_{\mu}\Tr (\nabla_{\mu} P)^2=0$ or $\phi=2\pi \mathbb{Z}$. For $\phi=2\pi \mathbb{Z}$,  $Q$ in Eq.~(\ref{eq:Ansatz}) becomes independent of $P(\bm{r})$, where we can choose $P(\bm{r})$ freely. Note that $P(\bm{r})$ that satisfies $\sum_{\mu}\sigma_{\mu}\Tr (\nabla_{\mu} P)^2=0$ becomes independent of $r$; $P(\bm{r})=P_0$. This is because as $\sigma_{\mu}\ge 0$, $\sum_{\mu}\sigma_{\mu}\Tr (\nabla_{\mu} P)^2=\sum_{\mu}\sum^N_{i,j=1} \sigma_{\mu} |\nabla_{\mu} P_{ij}({\bm r})|^2=0$ requires that $P(\bm{r})$ is independent of $\bm{r}$. For $\phi=2\pi \mathbb{Z}$, we choose $P(\bm{r})=P_0$, so that $\sum_{\mu}\sigma_{\mu}\Tr (\nabla_{\mu} P)^2=0$ is satisfied entirely. Then, Eq.~\eqref{Eq:B1} reduces to a Poisson equation, 
\begin{equation}
    (\sigma_{\mu}+c_{\mu})\nabla^2_{\mu}\phi=0.
\end{equation}
 Note also that when $\phi$ is indefinite such as in vortex cores, Eqs.~(\ref{Eq:B2},\ref{Eq:B3}) do not have to be satisfied, where $P(\bm{r})$ is not specified: $P(\bm{r})$ can depend on $r$ along vortex loops. From Eq.~(\ref{Eq:B-1a}), the field strength $F_{\mu}\equiv \epsilon_{\mu\nu\lambda}\nabla_{\nu}h_{\lambda}+ i\epsilon_{\mu\nu\lambda}h_{\nu}h_{\lambda}$ with  $h_{\lambda} \equiv -iQ^{-1}\nabla_{\lambda} Q$ can be calculated,
\begin{align}
F_{\mu}(\bm{r}) \equiv \epsilon_{\mu\nu\lambda} 
\nabla_{\nu}\nabla_{\mu} \phi(\bm{r}) \!\ P(\bm{r}).  
\end{align} 

\section{Variational study of $\mathrm{U}(N)$ type-II superconductor model}\label{app:variational_method}
In this Appendix, we elaborate the variational analysis of the superconducting (Meissner) phase in the $\mathrm{U}(N)$ type-II superconductor model for $\chi=0$ case, Eqs.~(\ref{eq:dual_discretized},\ref{eq:dual_discretized_u1},\ref{eq:dual_discretized_suN},\ref{eq:dual_discretized_Sy}). In the superconducting phase, the $\psi$ field assumes a spatially uniform value, and the spin-wave fluctuation around the uniform configuration can be absorbed into the U(1) gauge field. The action thus obtained takes the following form in the continuum limit, 
\begin{equation}
    S=2\pi\int \mathrm{d}^3r\,\left[\frac{\left(\bm{\nabla}\times\bm{\theta}^0
    %-\frac{\sqrt{N}}{8\pi}\chi
    \right)^2}{\sigma+Nc}+\sum_{a}\frac{\left(\bm{\nabla}\times\bm{\theta}^a\right)^2}{\sigma}\right]-2t\sum_{\mu}\int \mathrm{d}^3 r \int \mathrm{d}|p(\bm{r})\rangle \cos\Tr (2\pi\Theta_\mu P).
\end{equation}
Thanks to the $|p(\bm{r})\rangle$ integral, the U(1) and $\mathrm{SU}(N)$ gauge fields are decoupled from one another at the quadratic level in the Taylor expansion of the $\cos$ term. Thus, the Meissner phase can be described by the following mean-field action with finite $m$,
\begin{align}
\overline{S} =  2\pi\int \mathrm{d}^3r\left\{\left[\frac{\left(\bm{\nabla}\times\bm{\theta}^0\right)^2}{\sigma+Nc}+m^2\left(\bm{\theta}^0\right)^2\right]+\sum_{a=1}^{N^2-1}\left[\frac{\left(\bm{\nabla}\times\bm{\theta}^a\right)^2}{\sigma}+m^2\left(\bm{\theta}^a\right)^2\right]\right\}.
\end{align}
Here we assume the same mass $m$ for the U(1) and S$\mathrm{U}(N)$ gauge field (see the replica limit of Eq.~(\ref{eq:action_for_SC})). To obtain a gap equation for $m$, we exercise a variational principle which states that a trial free energy $F(m)$ defined below must be always greater than the true free energy $F_{\rm true}\equiv -\ln Z \equiv \int \mathrm{D}[\Theta] \exp\left[-S\right]$,    
\begin{align}
&F(m) \equiv  -\ln \overline{Z} + \langle S - \overline{S}\rangle_{\overline{S}}, 
\end{align}
and 
\begin{align}
\langle \cdots \rangle_{\overline{S}} &\equiv \frac{1}{\overline{Z}} \int \mathrm{D}[\Theta] 
\cdots \exp \left[-\overline{S}\right], \nonumber \\
\overline{Z} &\equiv \int \mathrm{D}[\Theta] 
 \exp \left[-\overline{S}\right].  
\end{align}
The variational principle (Bogoliubov inequality) is rooted in the convex nature of the exponential function, which implies that an optimal value of $m$ can be obtained by minimizing $F(m)$ with respect to $m$\cite{chaikin_lubensky1995,nagaosa1999,herbutModernApproachCritical2007}. 

Notably, $F(m)$ reaches zero in the replica limit[see below], and so does $F_{\rm true}$ by the inequality. Since $F_{\rm true}=-\ln \langle {\cal Z}^N\rangle_{\rm dis}$ in Eq.~(\ref{eq:replica}), $\lim_{N\rightarrow 0} F_{\rm true}=0$ allows us to express the disorder-averaged free energy by $-\langle \ln {\cal Z }\rangle_{\rm dis} = \lim_{N\rightarrow 0}F_{\rm true}/N$.  Correspondingly, we regard $\lim_{N\rightarrow 0}F(m)/N$ as a trial function of the disorder-averaged free energy and minimize this trial function with respect to $m$. The following Green's functions, as well as their trace and determinant, facilitate an evaluation of $F(m)$,
\begin{align}
    G_{\mu\nu}^a(\bm{r}-\bm{r}') 
    &\equiv \int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\langle \tilde{\theta}^a_\mu(-\bm{k})\tilde{\theta}^a_\nu(\bm{k})\rangle_{\overline{S}} \!\ \!\ e^{i\bm{k}\cdot(\bm{r}-\bm{r}')}\nonumber \\
    &\equiv\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\tilde{G}_{\mu\nu}^a(\bm{k}) \!\ \!\ e^{i\bm{k}\cdot(\bm{r}-\bm{r}')},
\end{align}
with $a=0,1,\cdots, N^2-1$. The Fourier transforms $\tilde{G}^a_{\mu\nu}({\bm k})$ of the Green's function are given by   
\begin{equation}
    \tilde{G}^0_{\mu\nu}(\bm{k})=\frac{1}{4\pi}\frac{1}{k^2+(\sigma+Nc)m^2}\left[(\sigma+Nc)\delta_{\mu\nu}+\frac{k_\mu k_\nu}{m^2}\right],
\end{equation}
\begin{equation}
    \tilde{G}^{a\ne 0}_{\mu\nu}(\bm{k})=\frac{1}{4\pi}\frac{1}{k^2+\sigma m^2}\left(\sigma\delta_{\mu\nu}+\frac{k_\mu k_\nu}{m^2}\right). 
\end{equation}
The trace and determinant of these 3 by 3 matrices are as follows, e.g.  
\begin{align}
        \Tr  \tilde{G}^{a\ne 0}(\bm{k})&=\frac{1}{4\pi}\frac{k^2+3\sigma m^2}{m^2(k^2+\sigma m^2)}, \nonumber \\
        \det\tilde{G}^{a\ne 0}(\bm{k}) &=\frac{\sigma^2}{64\pi^3}\frac{1}{m^2(k^2+\sigma m^2)^2}.
\end{align}

We calculate the density of the trial free energy $F(m)$ in the replica limit, 
\begin{equation}
    f(m)=\lim_{N\to 0}\frac{F(m)}{NV} = -\lim_{N\rightarrow 0}\frac{\ln \overline{Z}}{NV} + \lim_{N\rightarrow 0}\frac{\langle S-\overline{S}\rangle_{\overline{S}}}{NV}
\end{equation}
where the $m$-dependent part of $\ln \overline{Z}/V$ is given by the determinant of the Green's function, 
\begin{align}
    & \frac{1}{V}\ln \overline{Z}=\frac{1}{2}\sum_{a=0}^{N^2-1}\int\frac{ \mathrm{d}^3k}{(2\pi)^3}\,\ln\det \tilde{G}^a(\bm{k}) \nonumber \\
    & =-\int\frac{ \mathrm{d}^3 k}{(2\pi)^3}\,\ln\frac{k^2+(\sigma+Nc)m^2}{k^2+\sigma m^2}-N^2\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\left[\ln m+\ln (k^2+\sigma m^2)\right],
\end{align}
In the replica limit, it becomes
\begin{align}
    \lim_{N\to 0}\frac{1}{NV}\ln \overline{Z} &=-\lim_{N\to 0}\frac{2}{N}\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\,\ln\frac{k^2+(\sigma+Nc)m^2}{k^2+\sigma m^2} \nonumber \\
& =-\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\,\frac{2cm^2}{k^2+\sigma m^2}.
\end{align}

$\langle S-\overline{S}\rangle_{\overline{S}}$ is given by 
\begin{align}
    \langle S-S_0 \rangle_{\overline{S}} =-2t\sum_{\mu}\int \mathrm{d}^3r \int \mathrm{d}|p(\bm{r})\rangle \langle \!\ \cos\Tr (2\pi\Theta_\mu P)\rangle_{\overline{S}}-2\pi m^2 \sum^{N^2-1}_{a=0} \sum_{\mu=x,y,z}
    \int \mathrm{d}^3 r \!\ \langle \theta^a_{\mu}(\bm{r}) \theta^a_{\mu}(\bm{r})\rangle_{\overline{S}}, \label{eq:20}
\end{align}
where
\begin{equation}
    \sum_{\mu}\langle \theta^0_{\mu}(\bm{r})\theta^0_{\mu}(\bm{r})\rangle_{\overline{S}}=\int\frac{\mathrm{d}^3k}{(2\pi)^3}
    \Tr \tilde{G}^0(\bm{k})=\frac{1}{4\pi}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\frac{k^2+3(\sigma+Nc) m^2}{m^2[k^2+(\sigma+Nc) m^2]},
\end{equation}
\begin{equation}
     \sum_{\mu}\langle \theta^{a\ne 0}_{\mu}(\bm{r})\theta^{a\ne 0}_{\mu}(\bm{r})\rangle_{\overline{S}}=\int\frac{\mathrm{d}^3k}{(2\pi)^3}
    \Tr \tilde{G}^{a\ne 0}(\bm{k})=\frac{1}{4\pi}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\frac{k^2+3\sigma m^2}{m^2(k^2+\sigma m^2)}.
\end{equation}

The first term in Eq.~(\ref{eq:20}) for general $N$ is given by 
\begin{align}
    \langle \cos\Tr (2\pi\Theta_\mu(\bm{r}) P)\rangle_{\overline{S}}&=\left\langle \cos\left[2\pi\frac{\theta_\mu^0(\bm{r})}{\sqrt{N}}+2\pi\sum^{N^2-1}_{a=1}\theta_\mu^a(\bm{r})\Tr (T^a P)\right]\right\rangle \\
    &=\exp\left[-\frac{2\pi^2}{N}\int\frac{\mathrm{d}^3k}{(2\pi)^3} \tilde{G}_{\mu\mu}^0(\bm{k})-2\pi^2\sum^{N^2-1}_{a=1}\Tr ^2(T^aP)\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\tilde{G}_{\mu\mu}^a(\bm{k})\right].
\end{align}
Using
\begin{align}
    \sum^{N^2-1}_{a=1}\Tr ^2(T^aP)=\sum^{N^2-1}_{a=1}T^a_{ij}P_{ji}T^a_{kl}P_{lk}=\left(\delta_{il}\delta_{jk}-\frac{1}{N}\delta_{ij}\delta_{kl}\right)P_{ji}P_{lk}=\Tr  P^2-\frac{1}{N}\Tr ^2P=1-\frac{1}{N},
\end{align}
we can express this by 
\begin{align}
     \langle \cos\Tr (2\pi\Theta_\mu(\bm{r}) P)\rangle_{\overline{S}}&=\exp\left\{-2\pi^2\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\left[\frac{1}{N}\tilde{G}^0_{\mu\mu}(\bm{k})+\left(1-\frac{1}{N}\right)\tilde{G}^{a\ne 0}_{\mu\mu}(\bm{k})\right]\right\}.
\end{align}
For a spherical integral region of $k$ (the region will be specified later), we can also rewrite this by
\begin{align}
  \langle \cos\Tr (2\pi\Theta_\mu(\bm{r}) P)\rangle_{\overline{S}}& =\exp\left\{-\frac{2\pi^2}{3}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\left[\frac{1}{N}\Tr \tilde{G}^0(\bm{k})+\left(1-\frac{1}{N}\right)\Tr \tilde{G}^{a\ne 0}(\bm{k})\right]\right\}. \label{eq:21}
\end{align}
In the limit of $N\rightarrow 0$, the integrand of Eq.~(\ref{eq:21}) remains a finite function of $k$
\begin{align}
\lim_{N\to 0}\left[\frac{1}{N}\Tr \tilde{G}^0(\bm{k})+\left(1-\frac{1}{N}\right)\Tr \tilde{G}^{a\ne 0}(\bm{k})\right]=\frac{1}{4\pi}\frac{k^4+2(2\sigma+c)m^2k^2+3\sigma^2m^4}{m^2(k^2+\sigma m^2)^2}.
\end{align}


The second term of Eq.~(\ref{eq:20}) for general $N$ is given by
\begin{align}
   \frac{2\pi m^2}{V}\int \mathrm{d}^3r \sum_{a=0}^{N^2-1}\langle \left[\theta^a(\bm{r})\right]^2\rangle_{\overline{S}} =\frac{1}{2}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\left[\frac{k^2+3(\sigma+Nc) m^2}{k^2+(\sigma+Nc) m^2}-\frac{k^2+3\sigma m^2}{k^2+\sigma m^2}\right]+\frac{N^2}{2}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\frac{k^2+3\sigma m^2}{k^2+\sigma m^2}.
\end{align}
which vanishes in the replica limit. Thus, we obtain
\begin{equation}
    \lim_{N\to 0}\frac{2\pi m^2}{NV}\int \mathrm{d}^3r \sum_{a=0}^{N^2-1}\langle \left(\theta^a(\bm{r})\right)^2\rangle_{\overline{S}}=\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\frac{ cm^2 k^2}{(k^2+\sigma m^2)^2}.
\end{equation}

To summarize, we obtain $F(m)/V$ for  general $N$ as follows,
\begin{align}
    \frac{F(m)}{V}=&-\frac{6t\pi^{N-1}}{\Gamma(N)}\exp\left\{-\frac{2\pi^2}{3}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\left[\frac{1}{N}\Tr \tilde{G}^0(\bm{k})+\left(1-\frac{1}{N}\right)\Tr \tilde{G}^a(\bm{k})\right]\right\}\\
    &-\frac{1}{2}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\left[\frac{k^2+3(\sigma+Nc) m^2}{k^2+(\sigma+Nc) m^2}-\frac{k^2+3\sigma m^2}{k^2+\sigma m^2}\right]-\frac{N^2}{2}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\frac{k^2+3\sigma m^2}{k^2+\sigma m^2}\\
   &+\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\,\ln\frac{k^2+(\sigma+Nc)m^2}{k^2+\sigma m^2}+N^2\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\left[\ln m+\ln (k^2+\sigma m^2)\right],
\end{align}
where we use $\int \mathrm{d}|p(\bm{r})\rangle = \pi^{N-1}/\Gamma(N)$. This quantity vanishes linearly in $N$ in the replica limit with 
\begin{align}
    f(m) \equiv \lim_{N\to 0}\frac{F(m)}{NV}=&-\frac{6y}{\pi}\exp\left[-\frac{\pi}{6}\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\frac{k^4+2(2\sigma+c)m^2k^2+3\sigma^2m^4}{m^2(k^2+\sigma m^2)^2}\right] \nonumber \\
    &-\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\frac{ cm^2 k^2}{(k^2+\sigma m^2)^2}+\int\frac{\mathrm{d}^3 k}{(2\pi)^3}\,\frac{cm^2}{k^2+\sigma m^2}.
\end{align}
Note that all three $k$-integrals on the right-hand side need the ultraviolet (UV) cutoff. Here, we use the following soft-cutoff function,
\begin{align}
    \Psi(\bm{k})=\frac{\Lambda^4}{(k^2+\Lambda^2)^2},
\end{align}
and replace the $k$-integrals by integrals with the cutoff function, i.e.
\begin{align}\label{eq:soft_cutoff}
    \int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\cdots \to \int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\Psi(\bm{k})\cdots.
\end{align}
The $k$-integrals are calculated as follows, 
\begin{align}
        &\int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\frac{\Lambda^4}{(k^2+\Lambda^2)^2}\frac{k^4+2(2\sigma+c)m^2k^2+3\sigma^2m^4}{m^2(k^2+\sigma m^2)^2} \nonumber \\
        &=\frac{\Lambda^3}{8\pi}\frac{\Lambda^3+|m|\left[3\sqrt{\sigma}\Lambda^2+|m|\left(2c\Lambda+5\sigma\Lambda+3m\sigma^{3/2}\right)\right]}{m^2\left(\Lambda+\sqrt{\sigma}|m|\right)^3}, \end{align}
\begin{align}
    \int\frac{\mathrm{d}^3k}{(2\pi)^3}\,\frac{\Lambda^4}{(k^2+\Lambda^2)^2}\frac{ cm^2 k^2}{(k^2+\sigma m^2)^2}=\frac{1}{8\pi}\frac{cm^2 \Lambda^4}{\left(\Lambda+m\sqrt{\sigma}\right)^3},
\end{align}
\begin{align}
    \int\frac{\mathrm{d}^3 k}{(2\pi)^3}\,\frac{\Lambda^4}{(k^2+\Lambda^2)^2}\,\frac{cm^2}{k^2+\sigma m^2}=\frac{1}{8\pi}\frac{cm^2 \Lambda^3}{\left(\Lambda+m\sqrt{\sigma}\right)^2}.
\end{align}
Thus, we finally obtain,
\begin{equation}
    f=-\frac{6t}{\pi}\exp\left\{-\frac{\Lambda^3}{48}\frac{\Lambda^3+|m|\left[3\sqrt{\sigma}\Lambda^2+|m|\left(2c\Lambda+5\sigma\Lambda+3m\sigma^{3/2}\right)\right]}{m^2\left(\Lambda+\sqrt{\sigma}|m|\right)^3}\right\}+\frac{1}{8\pi}\frac{c\sqrt{\sigma}m^3 \Lambda^3}{\left(\Lambda+m\sqrt{\sigma}\right)^3}.
\end{equation}



