    \item for code content extraction

    \texttt{re.findall(r'\textless{}code\textgreater{}(.*?)\textless{}/code\textgreater{}', str(text), re.DOTALL)} 

    \item for image element identification

    \texttt{lambda x: 1 if re.search(r'\textbackslash{}img\textbackslash{}s+ [\textasciicircum{}>\textbackslash{}]*src=', str(x)) else 0} 
\end{itemize}

