  \tr\Big[ 
  \mathbb{W}^{L-l}_t
  \mathbb{B}_{{\rm L},\beta,t}^{(\pm)}
  \left.
  \mathbb{W}_{\beta,t}^{(\pm)}\right.^{l}
  \mathbb{B}_{{\rm R},\beta,t}^{(\pm)}
  \Big],
\end{eqnarray}
where $\mathbb{B}_{{\rm L/R},\beta,t}^{(\pm)}$ act as identity on both $\mathbb{V}_t$,
and as boundary vectors
$\begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \vLine{0.5}{0}{0}{0}
    \vBmps{0.5}{0}{colObsLines}
\end{tikzpicture}$,
$\begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \vLine{-0.5}{0}{0}{0}
    \vBmps{-0.5}{0}{colObsLines}
\end{tikzpicture}$
on the auxiliary degree of freedom (see Fig.~\ref{fig:Z1beta}).

