\end{tikzpicture}$, are diagonal matrices in the auxiliary space,
\begin{eqnarray}\label{eq:defPentagon}\fl
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \mpsWire{0}{-0.5}{0}{0.5}
    \mpsAux{0}{0}{colMPSBeta}
  \end{tikzpicture}=
  \left[\matrix{
    1 & 0 & 0 \cr
    0 & \gamma & 0 \cr
    0 & 0 & \gamma
    }\right],\qquad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
      \wedgeL{0}{0}
    \end{tikzpicture}=
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
    \end{tikzpicture}\right|_{\gamma\to e^{-i\beta}},\qquad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
      \wedgeR{0}{0}
    \end{tikzpicture}=
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
    \end{tikzpicture}\right|_{\gamma\to e^{i\beta}},\qquad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}=
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{-0.5}{0}{0.5}
      \mpsAux{0}{0}{colMPSBeta}
    \end{tikzpicture}\right|_{\gamma\to e^{i\beta}\Lambda_{\beta}^{(+)}}.
\end{eqnarray}
Note that the bulk tensors in $\sbra{l_{\beta,t}^{(-)}}$ and 
$\sket{r_{\beta,t}^{(-)}}$ are related to each other through a flip of sign of $\beta$.
The remaining tensors and boundary vectors are reported in~\ref{sec:tensorsOther}.
The corresponding eigenvalues are determined as (see \ref{sec:uniquenessFPs}),
\begin{eqnarray}
  \log \Lambda_{\beta}^{(\pm)}=
  \lim_{L\to\infty}
  \frac{1}{L}\log \mel{\Psi_0}{e^{i\beta Q^{(\pm)}}}{\Psi_0},
\end{eqnarray}
and are
\begin{eqnarray}\label{eq:defLambda}
  \Lambda_{\beta}^{(+)}=1-\vartheta+\vartheta e^{2i\beta},\qquad
  \Lambda_{\beta}^{(-)}=1.
\end{eqnarray}

Finally, we note that the fixed points are for convenience \emph{not} normalized, but rather
we keep the overlap between the right and left eigenvectors to be 
\begin{eqnarray}\label{eq:FPnorm}
  \sbraket{l_{\beta,t}^{(+)}}{r_{\beta,t}^{(+)}}=\left.\Lambda_{\beta}^{(+)}\right.^{2t},
  \qquad
  \sbraket{l_{\beta,t}^{(-)}}{r_{\beta,t}^{(-)}}=1=\left.\Lambda_{\beta}^{(-)}\right.^{2t}.
\end{eqnarray}
See~\ref{sec:FPnormalization} for details.

\section{Asymptotics of charged moments}\label{sec:asymptotics}
When the subsystem size $l$ and the system size $L$ are sufficiently large
compared to the time $t$ (in particular, when $l,L>2t+1$) the charged moments
factorize into the two contributions corresponding to the edges of the
subsystem,
\begin{eqnarray}
  \lim_{l,L\to\infty} \frac{Z_{\alpha,\vec{\beta}}^{(\pm)}(l,t)}
  {\prod_{j=1}^{\alpha}
  \left.\Lambda_{\beta_{j}}^{(\pm)}\right.^{l}}
  =
  \frac{z_{\alpha,\vec{\beta}}^{{\rm L}\,(\pm)}(t)\,
  z_{\alpha,\vec{\beta}}^{{\rm R}\,(\pm)}(t)}
  {\prod_{j=1}^{\alpha}
  \left.\Lambda_{\beta_{j}}^{(\pm)}\right.^{2t}},
\end{eqnarray}
where $z_{\alpha,\vec{\beta}}^{{\rm L/R}\, (\pm)}$ are the contributions
given by the (un-normalized) leading eigenvectors,
\begin{eqnarray}\fl
  \eqalign{
    z_{\alpha,\vec{\beta}}^{{\rm L}\, (\pm)}=
    \sbra{l_{t}}^{\otimes \alpha}\,
    \mathbb{P}_{\alpha,t}
    \left(
    \mathbb{B}_{{\rm L},\beta_1,t}^{(\pm)}\sket{r_{\beta_1,t}^{(\pm)}}
    \otimes
    \mathbb{B}_{{\rm L},\beta_2,t}^{(\pm)}\sket{r_{\beta_2,t}^{(\pm)}}
    \otimes
    \cdots
    \otimes
    \mathbb{B}_{{\rm L},\beta_{\alpha},t}^{(\pm)}\sket{r_{\beta_{\alpha},t}^{(\pm)}}\right),\\
    z_{\alpha,\vec{\beta}}^{{\rm R}\, (\pm)}=
    \left(
    \sbra{l_{\beta_1,t}^{(\pm)}}\mathbb{B}_{{\rm R},\beta_1,t}^{(\pm)}
    \otimes
    \sbra{l_{\beta_2,t}^{(\pm)}}\mathbb{B}_{{\rm R},\beta_2,t}^{(\pm)}
    \otimes
    \cdots
    \otimes
    \sbra{l_{\beta_{\alpha},t}^{(\pm)}}\mathbb{B}_{{\rm R},\beta_{\alpha},t}^{(\pm)}
    \right)\,
    \mathbb{P}_{\alpha,t}^{\dagger}
    \sket{r_{t}}^{\otimes \alpha}.
    }
\end{eqnarray}
In terms of the fixed-point tensors, these expressions take form of
$2t\times 2\alpha$ tensor networks,
\begin{eqnarray} \label{eq:defTNOneEdgeContrib}
  z_{\alpha,\vec{\beta}}^{{\rm L}\, (-)}(t)
  =
  \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
    \foreach \t in {1,...,4}{
      \gridLine{0.4}{\t}{6.6}{\t}
      \gridLine{0.4}{\t-0.4}{6.6}{\t-0.4}
      \leftHook{0.4}{\t}
      \rightHook{6.6}{\t}
    }
    \foreach \x in {1,...,6}{\mpsWire{\x}{0}{\x}{5}}
    \foreach \x in {2,4,6}{
      \foreach \t in {1,3}{
        %\draw[white,fill=white] (\x,{\t+0.45}) circle (0.3);
