      \wedgeR{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{0.625}
      \mpsBvecW{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{0.625}
      \mpsBvecW{0}{0}{colMPS}
    \end{tikzpicture}=
    \left[\matrix{
      1 \cr 0 \cr 0
    }\right]\mkern-6mu.
  \end{eqnarray}
  On the other hand, the top boundary vectors act on both the auxiliary space of
  the MPO describing $e^{i\beta Q^{(\pm)}}$, and the auxiliary space of the fixed-point MPO,
  and therefore must obtain the dependence on the charge in question and the value of $\beta$.
  In particular, the top boundary vector in the absence of the charge is
  \begin{eqnarray}\label{eq:topNoCharge}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \node at (-0.75,0) {\scalebox{0.8}{$\phantom{s}$}};
      \mpsWire{0}{0}{0}{-0.625}
      \mpsBvec{0}{0}
    \end{tikzpicture}=\left[\matrix{1&1&0}\right],
  \end{eqnarray}
  while the top boundary vector included in $\sbra{l_{\beta,t}^{(-)}}$ is
  \begin{eqnarray}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \mpsBvecV{0}{0}{colMPSBeta}
      \wedgeL{0}{0}
      \node at (0.875,0) {\scalebox{0.8}{$x$}};
    \end{tikzpicture}\mkern-8mu=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \mpsBvecW{0}{0}{colMPSBeta}
      \wedgeL{0}{0}
      \node at (0.875,0) {\scalebox{0.8}{$x$}};
    \end{tikzpicture}\mkern-8mu=
    \left[\matrix{
      \delta_{x,1} & \delta_{x,2} & 0
    }\right].
  \end{eqnarray}
  Unlike the bulk tensors (cf.\ \eref{eq:newFixedPointTensors}) the top boundary
  vectors of $\sket{r_{\beta,t}^{(-)}}$ are not obtained just by the flip of the
  sign $\beta\mapsto -\beta$, but take a completely different form,
  \begin{eqnarray}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \mpsBvecV{0}{0}{colMPSBeta}
      \wedgeR{0}{0}
      \node at (-0.875,0) {\scalebox{0.8}{$x$}};
    \end{tikzpicture}=
    \left[\matrix{
      1 & \delta_{x,1} + e^{i\beta} \delta_{x,2}& 0
    }\right],\qquad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \mpsBvecW{0}{0}{colMPSBeta}
      \wedgeR{0}{0}
      \node at (-0.875,0) {\scalebox{0.8}{$x$}};
    \end{tikzpicture}=
    \left[\matrix{
      1 & \delta_{x,1} + e^{-i\beta} \delta_{x,2} & 0
    }\right].
  \end{eqnarray}
  We note that the overlap between the top boundary vectors
  of fixed-points and the boundary vectors from~\eref{eq:boundaryMPO} reduce to the
  top boundary vector of the fixed-point $\sbra{l_t}$,
  \begin{eqnarray}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \vLine{-0.625}{-0.25}{-0.625}{0.25}
      \mpsBvecV{0}{0}{colMPSBeta}
      \wedgeR{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \vLine{-0.625}{-0.25}{-0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \wedgeR{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecV{0}{0}{colMPSBeta}
      \wedgeL{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \wedgeL{0}{0}
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \mpsBvec{0}{0}
    \end{tikzpicture}.
  \end{eqnarray}

  In the case of $Q^{(+)}$, the top boundary vectors take the following form,
  \begin{eqnarray}\fl
    \eqalign{
      &\mkern-11mu
      \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
        \mpsWire{0}{0}{0}{-0.625}
        \vLine{0}{0}{-0.625}{0}
        \mpsBvecW{0}{0}{colMPSBeta}
        \plus{0}{0}
        \node at (-0.875,0) {\scalebox{0.8}{$x$}};
      \end{tikzpicture}=
      \left[\matrix{
        \delta_{x,1}+e^{2i\beta}\delta_{x,2}+\delta_{x,3}\cr
        \delta_{x,1}+\frac{e^{2i\beta}}{\gamma_{+}}(\delta_{x,2}+\delta_{x,3})\cr
        \left(\frac{e^{3i\beta}}{\gamma_{+}}-1\right)\delta_{x,1}
      }\right]^{T}\mkern-10mu,\\
      &\begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
        \mpsWire{0}{0}{0}{-0.625}
        \vLine{0}{0}{0.625}{0}
        \mpsBvecW{0}{0}{colMPSBeta}
        \plus{0}{0}
        \node at (0.875,0) {\scalebox{0.8}{$x$}};
      \end{tikzpicture}\mkern-8mu=
      \left[\matrix{
        \frac{e^{i\beta}}{\gamma_{+}} \delta_{x,1}\cr 
        \frac{e^{2i\beta}(1-\vartheta)}{\gamma_{+}^2} \left(\frac{\vartheta}{1-\vartheta}\delta_{x,2}+\delta_{x,3}\right)\cr 
        \frac{e^{2i\beta}(1-\vartheta)}{\gamma_{+}^2}\left(\delta_{x,2}-\delta_{x,3}\right)
      }\right]^{T}\mkern-10mu,}
      \qquad
      \eqalign{
        &\mkern-4mu
        \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
          \mpsWire{0}{0}{0}{-0.625}
          \vLine{0}{0}{-0.625}{0}
          \mpsBvecV{0}{0}{colMPSBeta}
          \plus{0}{0}
          \node at (-0.875,0) {\scalebox{0.8}{$x$}};
        \end{tikzpicture}=
        \left[\matrix{
          \delta_{x,1}+e^{2i\beta}\delta_{x,2}+\delta_{x,3}\cr
          e^{2i\beta}\delta_{x,1}+\gamma_{+}(\delta_{x,2}+\delta_{x,3})\cr
          \left(e^{3i\beta}-\gamma_{+}\right)(\delta_{x,2}+\delta_{x,3})
        }\right]^T\mkern-10mu,\\ 
        &\begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
          \mpsWire{0}{0}{0}{-0.625}
          \vLine{0}{0}{0.625}{0}
          \mpsBvecV{0}{0}{colMPSBeta}
          \plus{0}{0}
          \node at (0.875,0) {\scalebox{0.8}{$x$}};
        \end{tikzpicture}\mkern-8mu=
        \left[\matrix{
          \frac{e^{i\beta}}{\gamma_{+}} \delta_{x,1}\cr 
          \frac{e^{i\beta}(1-\vartheta)}{\gamma_{+}} 
          \left(\delta_{x,2}+\frac{\vartheta e^{2i\beta}}{1-\vartheta}\delta_{x,3}\right)\cr 
          \frac{e^{i\beta}(1-\vartheta)}{\gamma_{+}} 
          \left(-\delta_{x,2}+e^{2i\beta}\delta_{x,3}\right)
        }\right]^T\mkern-10mu,}
  \end{eqnarray}
  where 
  \begin{eqnarray}
    \gamma_{+}=e^{i\beta}\Lambda_{\beta}^{(+)},
  \end{eqnarray}
  and $\Lambda_{\beta}^{(+)}$ is given in Eq.~\eref{eq:defLambda}. The two overlaps
  between these vectors and the boundary vectors of the $Q^{(+)}$ MPO that are needed
  to evaluate Eq.~\eref{eq:defTNOneEdgeContrib} are given as
  \begin{eqnarray}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}=
    \left[\matrix{
      \frac{e^{i\beta}}{\gamma_{+}}\cr
      \frac{e^{i\beta}(1-\vartheta+\vartheta e^{i\beta})}{\gamma_{+}^2}\cr
      -\frac{e^{i\beta}(1-e^{i\beta})(1-\vartheta)}{\gamma_{+}^2}
    }\right]^{T},\qquad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \vLine{-0.625}{-0.25}{-0.625}{0.25}
      \mpsBvecV{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}=
    \left[\matrix{
      1\cr
      \gamma_{+} e^{-i\beta}\cr
      e^{2 i\beta}-\gamma_{+} e^{-i\beta}
    }\right]^{T}.
  \end{eqnarray}
  Note that in the limit of $\beta\to 0$ all of the overlaps reduce to
  \begin{eqnarray}
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecV{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}\right|_{\beta\to 0}
    =
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}\right|_{\beta\to 0}
    =
    \left.
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{-0.625}{0}
      \vLine{-0.625}{-0.25}{-0.625}{0.25}
      \mpsBvecV{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}\right|_{\beta\to0}
    =
    \begin{tikzpicture}[baseline={([yshift=-0.2ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-1}
      \vLine{0}{0}{-0.625}{0}
      \vLine{-0.625}{-0.25}{-0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \plus{0}{0}
      \mpsAux{0}{-0.625}{colMPSBeta}
      \plus{0}{-0.625}
    \end{tikzpicture}
    \mkern-4mu
    \left.
    \vphantom{
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \vLine{0}{0}{0.625}{0}
      \vLine{0.625}{-0.25}{0.625}{0.25}
      \mpsBvecW{0}{0}{colMPSBeta}
      \plus{0}{0}
    \end{tikzpicture}}\right|_{\beta\to 0}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{0}{0}{-0.625}
      \mpsBvec{0}{0}
    \end{tikzpicture}.
  \end{eqnarray}
  \subsection{Normalization}\label{sec:FPnormalization}
  The normalization of boundary vectors above was chosen so that the following holds,
  \begin{eqnarray}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2}{0}{3}
      \mpsWire{1}{2}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \mpsBvecW{0}{2}{colMPS}
      \mpsBvecV{1}{2}{colMPS}
      \foreach \x in {3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2}{0}{3}
      \mpsWire{1}{2}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \mpsBvecV{0}{2}{colMPS}
      \mpsBvecW{1}{2}{colMPS}
      \foreach \x in {3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2}{0}{3}
      \mpsWire{1}{2}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \mpsBvecW{0}{2}{colMPS}
      \mpsBvecV{1}{2}{colMPS}
      \foreach \x in {3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2}{0}{3}
      \mpsWire{1}{2}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \mpsBvecV{0}{2}{colMPS}
      \mpsBvecW{1}{2}{colMPS}
      \foreach \x in {3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture}=1,
  \end{eqnarray}
  which together with 
  \begin{eqnarray}\fl
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \draw[thick,colLines,rounded corners] (0,2) -- (-0.75,2) -- (-0.75,3.5) -- (1.75,3.5) -- (1.75,2) -- cycle;
      \mpsWire{0}{1.5}{0}{3}
      \mpsWire{1}{1.5}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsB{0}{2}{colMPSBeta}
      \mpsA{1}{2}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \foreach \x in {2,3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture}=\Lambda_{\beta}^{(+)}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2.25}{0}{3}
      \mpsWire{1}{2.25}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \foreach \x in {3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture},\quad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \draw[thick,colLines,rounded corners] (0,2) -- (-0.75,2) -- (-0.75,3.5) -- (1.75,3.5) -- (1.75,2) -- cycle;
      \mpsWire{0}{1.5}{0}{3}
      \mpsWire{1}{1.5}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsA{0}{2}{colMPSBeta}
      \mpsB{1}{2}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \foreach \x in {2,3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture}=\Lambda_{\beta}^{(+)}
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2.25}{0}{3}
      \mpsWire{1}{2.25}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \foreach \x in {3}{
        \plus{0}{\x}
        \plus{1}{\x}
      }
    \end{tikzpicture},\quad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \draw[thick,colLines,rounded corners] (0,2) -- (-0.75,2) -- (-0.75,3.5) -- (1.75,3.5) -- (1.75,2) -- cycle;
      \mpsWire{0}{1.5}{0}{3}
      \mpsWire{1}{1.5}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsB{0}{2}{colMPSBeta}
      \mpsA{1}{2}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \foreach \x in {2,3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2.25}{0}{3}
      \mpsWire{1}{2.25}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \foreach \x in {3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture},\quad
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \draw[thick,colLines,rounded corners] (0,2) -- (-0.75,2) -- (-0.75,3.5) -- (1.75,3.5) -- (1.75,2) -- cycle;
      \mpsWire{0}{1.5}{0}{3}
      \mpsWire{1}{1.5}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecV{0}{3}{colMPSBeta}
      \mpsA{0}{2}{colMPSBeta}
      \mpsB{1}{2}{colMPSBeta}
      \mpsBvecW{1}{3}{colMPSBeta}
      \foreach \x in {2,3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture}=
    \begin{tikzpicture}[baseline={([yshift=-0.6ex]current bounding box.center)},scale=0.5]
      \mpsWire{0}{2.25}{0}{3}
      \mpsWire{1}{2.25}{1}{3}
      \vLine{0}{3}{1}{3}
      \mpsBvecW{0}{3}{colMPSBeta}
      \mpsBvecV{1}{3}{colMPSBeta}
      \foreach \x in {3}{
        \wedgeL{0}{\x}
        \wedgeR{1}{\x}
      }
    \end{tikzpicture},
  \end{eqnarray}
  implies
  \begin{eqnarray}
    \sbraket{l_{\beta,t}^{(+)}}{r_{\beta,t}^{(+)}}=\left.\Lambda_{\beta}^{(+)}\right.^{2t},
    \qquad
    \sbraket{l_{\beta,t}^{(-)}}{r_{\beta,t}^{(-)}}=1.
  \end{eqnarray}

